INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('fefb6ce8-d380-407e-af03-709d3fe462d8', 'paracetamol', 'Paracetamol', 'Paracetamol (Acetaminophen)', 'Paracetamol', 'Paracetamol', NULL, 'A widely used analgesic and antipyretic with weak anti-inflammatory activity.', 'Pain & Fever', ARRAY['500 mg', '650 mg', '125 mg/5 mL']::text[], ARRAY['Tablet', 'Syrup', 'Suppository', 'IV infusion']::text[], ARRAY['Oral', 'Rectal', 'Intravenous']::text[], 'Mainly central inhibition of prostaglandin synthesis (COX pathway) and action on descending serotonergic pathways; exact mechanism not fully established.', 'Analgesic and antipyretic at therapeutic doses; minimal peripheral anti-inflammatory effect and no significant antiplatelet action.', 'Rapid and near-complete absorption from the small intestine after oral dosing.', 'Distributed widely into most body tissues and fluids.', 'Hepatic conjugation (glucuronidation, sulfation); a small fraction via CYP2E1 to the toxic metabolite NAPQI, normally detoxified by glutathione.', 'Renal excretion of conjugated metabolites.', 'Approximately 60-90% orally', 'About 2-3 hours in adults with normal hepatic function', 'Low (about 10-25%)', NULL, NULL, 'Around 30-60 minutes orally', '4-6 hours', ARRAY['Mild to moderate pain', 'Fever']::text[], ARRAY['Known hypersensitivity to paracetamol', 'Severe hepatocellular insufficiency']::text[], ARRAY['Hepatotoxicity in overdose or with chronic excessive intake', 'Take care with multiple combination products that also contain paracetamol', 'Increased risk with chronic alcohol use or malnutrition']::text[], NULL, ARRAY['Generally well tolerated at therapeutic doses', 'Nausea (uncommon)']::text[], ARRAY['Acute liver failure in overdose', 'Rare severe skin reactions']::text[], ARRAY['Warfarin (possible INR increase with sustained high-dose use)', 'Alcohol (increased hepatotoxicity risk)', 'Enzyme-inducing drugs']::text[], NULL, ARRAY['Total daily dose from all sources', 'Liver function in prolonged or high-dose use']::text[], NULL, NULL, 'Commonly regarded as the analgesic/antipyretic of choice in pregnancy at the lowest effective dose for the shortest time; use under medical advice.', 'Considered compatible with breastfeeding in usual therapeutic doses.', 'Widely used in children with weight-based dosing determined by a clinician.', 'Usually well tolerated; consider hepatic status and total daily dose.', 'Dose interval may need extension in severe renal impairment.', 'Caution and dose reduction in hepatic impairment; avoid in severe hepatic disease.', ARRAY['Well tolerated at therapeutic doses', 'Suitable when NSAIDs are unsuitable', 'Available in many formulations']::text[], ARRAY['Narrow safety margin in overdose', 'Little anti-inflammatory effect']::text[], ARRAY['Antidote for overdose is N-acetylcysteine', 'Check combination cold/flu products for hidden paracetamol']::text[], '"Para-SEE-ta-mol: pain and fever, but no swelling."', '', 'pa-ra-SEE-ta-mol', 'पैरा-सी-टा-मोल', NULL, 'active', 'verified', '2026-08-18', '1.0', '2026-08-18T16:51:42.755036+00:00', '2026-08-18T16:51:42.755036+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('cdfddd11-5b2b-42e1-ad39-ba09eeecf21b', 'ibuprofen', 'Ibuprofen', 'Ibuprofen', 'Ibuprofen', 'Ibuprofen', NULL, 'A propionic acid NSAID with analgesic, antipyretic and anti-inflammatory activity.', 'Pain & Fever', ARRAY['200 mg', '400 mg', '600 mg', '100 mg/5 mL']::text[], ARRAY['Tablet', 'Suspension', 'Gel']::text[], ARRAY['Oral', 'Topical']::text[], 'Non-selective reversible inhibition of COX-1 and COX-2, reducing prostaglandin synthesis.', 'Analgesic, antipyretic and anti-inflammatory; reversible inhibition of platelet aggregation.', 'Rapidly absorbed orally; food may delay peak concentration.', 'Extensively bound to plasma proteins; distributes into synovial fluid.', 'Hepatic oxidation (CYP2C9) and conjugation.', 'Renal excretion of metabolites.', 'High (over 80%)', 'About 2 hours', 'Approximately 99%', NULL, NULL, '30-60 minutes', '4-6 hours', ARRAY['Pain', 'Fever', 'Inflammatory conditions', 'Dysmenorrhoea']::text[], ARRAY['Active peptic ulcer or GI bleeding', 'Severe heart failure', 'Severe renal impairment', 'NSAID or aspirin hypersensitivity', 'Third trimester of pregnancy']::text[], ARRAY['Gastrointestinal bleeding and ulceration risk', 'Cardiovascular thrombotic risk with prolonged high-dose use', 'Renal impairment risk in dehydration']::text[], NULL, ARRAY['Dyspepsia', 'Nausea', 'Abdominal discomfort', 'Dizziness']::text[], ARRAY['Gastrointestinal bleeding', 'Acute kidney injury', 'Bronchospasm in susceptible asthmatics']::text[], ARRAY['Anticoagulants (bleeding risk)', 'Other NSAIDs', 'ACE inhibitors/ARBs plus diuretics (triple whammy renal risk)', 'Lithium', 'Methotrexate']::text[], NULL, ARRAY['Renal function', 'Blood pressure', 'Signs of GI bleeding']::text[], NULL, NULL, 'Avoid, particularly after 20 weeks and in the third trimester; use only under medical direction.', 'Small amounts pass into milk; generally considered compatible short term under medical advice.', 'Used in children with weight-based dosing determined by a clinician.', 'Higher risk of GI and renal adverse effects; use lowest effective dose.', 'Avoid in significant renal impairment.', 'Use with caution; avoid in severe hepatic impairment.', ARRAY['Anti-inflammatory in addition to analgesic effect', 'Effective for musculoskeletal pain']::text[], ARRAY['Gastric irritation', 'Renal and cardiovascular cautions']::text[], ARRAY['Take with or after food', 'Avoid combining with other NSAIDs']::text[], '"-profen → NSAID family."', '-profen', 'eye-byoo-PROH-fen', 'आई-बू-प्रो-फेन', NULL, 'active', 'verified', '2026-08-18', '1.0', '2026-08-18T16:51:42.755036+00:00', '2026-08-18T16:51:42.755036+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('1625e7cb-00f6-4875-95c5-4c9f25e49dbb', 'diclofenac', 'Diclofenac', 'Diclofenac', 'Diclofenac', 'Diclofenac sodium / potassium', NULL, 'A potent NSAID used for musculoskeletal and inflammatory pain.', 'Pain & Fever', ARRAY['50 mg', '75 mg', '100 mg SR', '1% gel']::text[], ARRAY['Tablet', 'SR tablet', 'Injection', 'Gel']::text[], ARRAY['Oral', 'Topical', 'Intramuscular']::text[], 'Preferential inhibition of cyclo-oxygenase enzymes, reducing prostaglandin synthesis.', 'Marked anti-inflammatory and analgesic activity.', 'Well absorbed orally; significant first-pass metabolism.', 'Highly protein bound; penetrates synovial fluid.', 'Hepatic metabolism (CYP2C9) with conjugation.', 'Renal and biliary excretion of metabolites.', 'Approximately 50% orally due to first-pass effect', 'About 1-2 hours', 'Over 99%', NULL, NULL, 'About 30 minutes (immediate release)', '6-8 hours (formulation dependent)', ARRAY['Musculoskeletal pain', 'Arthritis', 'Post-operative pain']::text[], ARRAY['Active peptic ulcer', 'Ischaemic heart disease and cerebrovascular disease', 'Severe heart failure', 'Severe renal impairment', 'NSAID hypersensitivity']::text[], ARRAY['Higher cardiovascular thrombotic risk than some other NSAIDs', 'Gastrointestinal bleeding risk', 'Hepatotoxicity reported']::text[], NULL, ARRAY['Dyspepsia', 'Nausea', 'Headache', 'Injection site pain']::text[], ARRAY['GI bleeding', 'Myocardial infarction and stroke risk', 'Serious hepatic reactions']::text[], ARRAY['Anticoagulants', 'Other NSAIDs', 'Corticosteroids', 'ACE inhibitors/ARBs and diuretics']::text[], NULL, ARRAY['Liver function', 'Renal function', 'Blood pressure']::text[], NULL, NULL, 'Avoid, especially in the third trimester.', 'Generally avoided; seek medical advice.', 'Not generally recommended in young children.', 'Use with caution; prefer topical formulations where appropriate.', 'Avoid in significant renal impairment.', 'Avoid in hepatic impairment.', ARRAY['Potent anti-inflammatory effect', 'Topical option reduces systemic exposure']::text[], ARRAY['Cardiovascular and GI risk', 'Hepatic monitoring may be needed']::text[], ARRAY['Use lowest effective dose for shortest duration', 'Topical gel useful for localised pain']::text[], '"-fenac → NSAID."', '-fenac', 'dy-KLOE-fen-ak', 'डाइ-क्लो-फे-नैक', NULL, 'active', 'verified', '2026-08-18', '1.0', '2026-08-18T16:51:42.755036+00:00', '2026-08-18T16:51:42.755036+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('2ab01c08-1cd3-408a-94dc-0c351c27926a', 'naproxen', 'Naproxen', 'Naproxen', 'Naproxen', 'Naproxen sodium', NULL, 'A longer-acting propionic acid NSAID.', 'Pain & Fever', ARRAY['250 mg', '500 mg']::text[], ARRAY['Tablet', 'Suspension']::text[], ARRAY['Oral']::text[], 'Non-selective inhibition of COX-1 and COX-2.', 'Analgesic, antipyretic and anti-inflammatory with a longer duration than ibuprofen.', 'Well absorbed orally.', 'Highly protein bound.', 'Hepatic metabolism with demethylation and conjugation.', 'Predominantly renal.', 'Approximately 95%', 'About 12-17 hours', 'Over 99%', NULL, NULL, 'About 1 hour', 'Up to 12 hours', ARRAY['Arthritis', 'Musculoskeletal pain', 'Dysmenorrhoea', 'Acute gout']::text[], ARRAY['Active peptic ulcer', 'Severe renal impairment', 'Severe heart failure', 'NSAID hypersensitivity']::text[], ARRAY['GI bleeding risk', 'Fluid retention', 'Renal effects']::text[], NULL, ARRAY['Dyspepsia', 'Heartburn', 'Headache', 'Dizziness']::text[], ARRAY['GI bleeding', 'Renal impairment']::text[], ARRAY['Anticoagulants', 'Other NSAIDs', 'Lithium', 'Methotrexate']::text[], NULL, ARRAY['Renal function', 'Blood pressure', 'GI symptoms']::text[], NULL, NULL, 'Avoid, particularly in the third trimester.', 'Seek medical advice; generally other agents preferred.', 'Restricted use in children under medical supervision.', 'Use with caution due to long half-life.', 'Avoid in significant renal impairment.', 'Caution in hepatic impairment.', ARRAY['Twice-daily dosing', 'Long duration of action']::text[], ARRAY['Long half-life increases exposure in the elderly']::text[], ARRAY['Useful when longer NSAID cover is needed']::text[], '"Naproxen = the long-acting -profen cousin."', '-proxen', 'na-PROX-en', 'ना-प्रॉक-सेन', NULL, 'active', 'verified', '2026-08-18', '1.0', '2026-08-18T16:51:42.755036+00:00', '2026-08-18T16:51:42.755036+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('ea5d3a22-d1eb-42f5-bc3c-89fff47ad381', 'amoxicillin', 'Amoxicillin', 'Amoxicillin', 'Amoxicillin', 'Amoxicillin trihydrate', NULL, 'An aminopenicillin beta-lactam antibiotic with broad activity.', 'Antibiotics', ARRAY['250 mg', '500 mg', '125 mg/5 mL']::text[], ARRAY['Capsule', 'Tablet', 'Dry syrup']::text[], ARRAY['Oral']::text[], 'Inhibits bacterial cell wall synthesis by binding penicillin-binding proteins and blocking peptidoglycan cross-linking.', 'Time-dependent bactericidal activity.', 'Well absorbed orally and largely unaffected by food.', 'Distributes into most body fluids; poor CSF penetration unless meninges inflamed.', 'Limited hepatic metabolism.', 'Mainly renal excretion of unchanged drug.', 'Approximately 70-90%', 'About 1-1.5 hours', 'Approximately 20%', NULL, NULL, 'Within 1-2 hours', 'Dose-interval dependent (usually 8 hourly)', ARRAY['Respiratory tract infections', 'Otitis media', 'Urinary tract infection', 'Part of H. pylori eradication regimens']::text[], ARRAY['Penicillin hypersensitivity']::text[], ARRAY['Anaphylaxis risk in penicillin allergy', 'Rash if given in infectious mononucleosis', 'Antibiotic-associated diarrhoea and C. difficile risk']::text[], NULL, ARRAY['Diarrhoea', 'Nausea', 'Rash']::text[], ARRAY['Anaphylaxis', 'C. difficile colitis', 'Severe cutaneous reactions']::text[], ARRAY['Methotrexate', 'Probenecid', 'Oral typhoid vaccine']::text[], NULL, ARRAY['Signs of hypersensitivity', 'Renal function in prolonged therapy']::text[], NULL, NULL, 'Generally considered acceptable when clinically indicated; use under medical direction.', 'Considered compatible with breastfeeding.', 'Widely used in children with weight-based dosing.', 'Adjust dose in reduced renal function.', 'Dose reduction required in significant renal impairment.', 'No routine adjustment; monitor in hepatic disease.', ARRAY['Good oral absorption', 'Well established in children']::text[], ARRAY['Inactivated by beta-lactamase producing organisms', 'Allergy risk']::text[], ARRAY['Complete the prescribed course as directed', 'Not effective against viral illness']::text[], '"-cillin → penicillin family, cell wall attack."', '-cillin', 'a-mox-i-SIL-in', 'अमॉक्सी-सि-लिन', NULL, 'active', 'verified', '2026-08-18', '1.0', '2026-08-18T16:51:42.755036+00:00', '2026-08-18T16:51:42.755036+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('d643f589-932f-4e10-9ba9-62ecc9dbc960', 'amoxicillin-clavulanic-acid', 'Amoxicillin + Clavulanic Acid', 'Amoxicillin + Clavulanic Acid (Co-amoxiclav)', 'Amoxicillin, Clavulanic acid', 'Amoxicillin trihydrate + Potassium clavulanate', NULL, 'A fixed combination of amoxicillin with a beta-lactamase inhibitor.', 'Antibiotics', ARRAY['500 mg + 125 mg', '875 mg + 125 mg', '200 mg + 28.5 mg/5 mL']::text[], ARRAY['Tablet', 'Dry syrup', 'Injection']::text[], ARRAY['Oral', 'Intravenous']::text[], 'Amoxicillin inhibits cell wall synthesis while clavulanic acid irreversibly inhibits many bacterial beta-lactamases, protecting amoxicillin from degradation.', 'Extends the antibacterial spectrum to many beta-lactamase producing organisms.', 'Both components are well absorbed orally; taking with food improves tolerance.', 'Distributes into body fluids similarly to amoxicillin.', 'Clavulanic acid undergoes more extensive metabolism than amoxicillin.', 'Predominantly renal.', 'Amoxicillin approximately 70-90%; clavulanate somewhat lower', 'About 1 hour for both components', 'Low for both components', NULL, NULL, 'Within 1-2 hours', '8-12 hourly dosing depending on formulation', ARRAY['Respiratory infections with suspected resistant organisms', 'Sinusitis', 'Otitis media', 'Skin and soft tissue infection', 'Animal bite prophylaxis']::text[], ARRAY['Penicillin hypersensitivity', 'Previous co-amoxiclav associated jaundice or hepatic dysfunction']::text[], ARRAY['Cholestatic jaundice risk, more common in older adults and prolonged courses', 'Diarrhoea more frequent than with amoxicillin alone']::text[], NULL, ARRAY['Diarrhoea', 'Nausea', 'Rash']::text[], ARRAY['Cholestatic hepatitis', 'Anaphylaxis', 'C. difficile colitis']::text[], ARRAY['Methotrexate', 'Warfarin (INR changes reported)', 'Probenecid']::text[], NULL, ARRAY['Liver function in prolonged courses', 'Signs of hypersensitivity']::text[], NULL, NULL, 'Use only when clearly indicated under medical direction.', 'Considered compatible; monitor infant for GI upset.', 'Used in children with weight-based dosing.', 'Higher risk of hepatic adverse effects; use with care.', 'Dose adjustment in renal impairment.', 'Avoid in previous co-amoxiclav related hepatic injury.', ARRAY['Covers many beta-lactamase producing bacteria']::text[], ARRAY['More GI upset than plain amoxicillin', 'Cholestatic jaundice risk']::text[], ARRAY['Take with food to reduce GI upset', 'Reserve for situations where the broader cover is needed']::text[], '"Clavulanic acid = the bodyguard protecting amoxicillin."', '-cillin', 'a-mox-i-SIL-in plus klav-yoo-LAN-ik', 'अमॉक्सी-सि-लिन + क्लैवु-लैनिक ऐसिड', NULL, 'active', 'verified', '2026-08-18', '1.0', '2026-08-18T16:51:42.755036+00:00', '2026-08-18T16:51:42.755036+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('18227fbe-9276-4d36-abac-ae6a2ca962d2', 'azithromycin', 'Azithromycin', 'Azithromycin', 'Azithromycin', 'Azithromycin dihydrate', NULL, 'A macrolide (azalide) antibiotic with a long tissue half-life.', 'Antibiotics', ARRAY['250 mg', '500 mg', '200 mg/5 mL']::text[], ARRAY['Tablet', 'Dry syrup', 'Injection']::text[], ARRAY['Oral', 'Intravenous']::text[], 'Binds the 50S bacterial ribosomal subunit and inhibits protein synthesis.', 'Predominantly bacteriostatic with extensive tissue accumulation.', 'Absorbed orally; food reduces absorption of some formulations.', 'Very large volume of distribution with high intracellular and tissue concentrations.', 'Limited hepatic metabolism.', 'Mainly biliary excretion with a small renal component.', 'Approximately 37%', 'Terminal half-life about 68 hours', 'Variable, low to moderate', NULL, NULL, 'Within hours', 'Sustained tissue levels allow short courses', ARRAY['Community-acquired pneumonia', 'Pharyngitis in penicillin allergy', 'Certain sexually transmitted infections', 'Enteric fever (as directed)']::text[], ARRAY['Macrolide hypersensitivity', 'History of cholestatic jaundice with azithromycin']::text[], ARRAY['QT interval prolongation risk', 'Hepatic dysfunction reported', 'Antimicrobial resistance with inappropriate use']::text[], NULL, ARRAY['Nausea', 'Abdominal pain', 'Diarrhoea']::text[], ARRAY['QT prolongation and arrhythmia', 'Severe hepatic reactions', 'Severe cutaneous reactions']::text[], ARRAY['Other QT-prolonging drugs', 'Antacids (reduce absorption of some forms)', 'Warfarin (monitor INR)']::text[], NULL, ARRAY['ECG in patients at QT risk', 'Liver function if prolonged use']::text[], NULL, NULL, 'Use only when clearly indicated under medical direction.', 'Considered compatible under medical advice.', 'Used in children with weight-based dosing.', 'Consider cardiac comorbidity and QT risk.', 'No routine adjustment in mild impairment; caution in severe.', 'Avoid in significant hepatic impairment.', ARRAY['Short courses due to long tissue half-life', 'Alternative in penicillin allergy']::text[], ARRAY['Growing resistance', 'QT prolongation risk']::text[], ARRAY['Do not use for ordinary viral colds', 'Complete the prescribed course as directed']::text[], '"-thromycin → macrolide, 50S ribosome."', '-thromycin', 'az-ith-roe-MY-sin', 'अज़िथ्रो-माय-सिन', NULL, 'active', 'verified', '2026-08-18', '1.0', '2026-08-18T16:51:42.755036+00:00', '2026-08-18T16:51:42.755036+00:00') ON CONFLICT (slug) DO NOTHING;
