persensitivity']::text[], NULL, NULL, 'Use only when clearly indicated under medical direction.', 'Considered compatible under medical advice.', 'Widely used in children with weight-based dosing.', 'Adjust for renal function.', 'Dose reduction in significant renal impairment.', 'No routine adjustment.', ARRAY['Oral third-generation cephalosporin', 'Convenient dosing']::text[], ARRAY['Overuse contributes to resistance']::text[], ARRAY['Reserve for appropriate indications']::text[], '"Cef- → cephalosporin, a beta-lactam."', 'cef-', 'se-FIX-eem', 'सी-फिक्-सीम', NULL, 'active', 'verified', '2026-08-18', '1.0', '2026-08-18T16:51:42.755036+00:00', '2026-08-18T16:51:42.755036+00:00') ON CONFLICT (slug) DO NOTHING;
