t[], NULL, ARRAY['Injection site reactions', 'Diarrhoea', 'Rash']::text[], ARRAY['Anaphylaxis', 'Haemolytic anaemia (rare)', 'C. difficile colitis']::text[], ARRAY['Calcium-containing IV solutions', 'Anticoagulants']::text[], NULL, ARRAY['Renal and hepatic function', 'Signs of hypersensitivity']::text[], NULL, NULL, 'Used when clearly indicated under medical direction.', 'Considered compatible under medical advice.', 'Used in children including neonates with specific restrictions.', 'Generally well tolerated; monitor renal function.', 'Adjust in combined severe renal and hepatic impairment.', 'Adjust in combined severe renal and hepatic impairment.', ARRAY['Once-daily dosing', 'Good CSF penetration']::text[], ARRAY['Parenteral only', 'Biliary sludging']::text[], ARRAY['Hospital and clinic use under supervision']::text[], '"Ceftriaxone = once-daily heavyweight cephalosporin."', 'cef-', 'sef-try-AX-one', 'सेफ्-ट्राइ-ऐक्-सोन', NULL, 'active', 'verified', '2026-08-18', '1.0', '2026-08-18T16:51:42.755036+00:00', '2026-08-18T16:51:42.755036+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('b71dfafe-8abe-4cf8-ac40-7162b69890e4', 'metronidazole', 'Metronidazole', 'Metronidazole', 'Metronidazole', 'Metronidazole', NULL, 'A nitroimidazole active against anaerobic bacteria and several protozoa.', 'Antibiotics', ARRAY['200 mg', '400 mg', '500 mg IV']::text[], ARRAY['Tablet', 'Suspension', 'Injection', 'Gel']::text[], ARRAY['Oral', 'Intravenous', 'Topical']::text[], 'Reduced within anaerobic organisms to reactive intermediates that damage microbial DNA.', 'Bactericidal against anaerobes and amoebicidal.', 'Well absorbed orally.', 'Widely distributed including CSF, bone and abscesses.', 'Hepatic metabolism.', 'Mainly renal excretion of metabolites.', 'Approximately 90-100% orally', 'About 8 hours', 'Under 20%', NULL, NULL, 'Within 1-2 hours', '8-12 hourly dosing', ARRAY['Amoebiasis', 'Giardiasis', 'Bacterial vaginosis', 'Anaerobic bacterial infections']::text[], ARRAY['Known hypersensitivity', 'First trimester of pregnancy for high-dose regimens (as advised)']::text[], ARRAY['Avoid alcohol during and for at least 48 hours after therapy (disulfiram-like reaction)', 'Peripheral neuropathy with prolonged use']::text[], NULL, ARRAY['Metallic taste', 'Nausea', 'Dark urine', 'Headache']::text[], ARRAY['Peripheral neuropathy', 'Seizures (rare)', 'Encephalopathy (rare)']::text[], ARRAY['Alcohol', 'Warfarin', 'Lithium', 'Phenytoin']::text[], NULL, ARRAY['Neurological symptoms in prolonged courses', 'Full blood count in long therapy']::text[], NULL, NULL, 'Use only when clearly indicated; follow medical advice regarding trimester and dose.', 'Seek medical advice; high single doses may require temporary interruption.', 'Used in children with weight-based dosing.', 'Generally well tolerated.', 'No routine adjustment in mild impairment.', 'Dose reduction in severe hepatic impairment.', ARRAY['Excellent anaerobic and protozoal cover', 'Good tissue penetration']::text[], ARRAY['Alcohol interaction', 'Taste disturbance']::text[], ARRAY['Strictly avoid alcohol', 'Complete the course as directed']::text[], '"-nidazole → anaerobes and amoebae; no alcohol."', '-nidazole', 'met-roe-NYE-da-zole', 'मेट्रो-नाइ-डा-ज़ोल', NULL, 'active', 'verified', '2026-08-18', '1.0', '2026-08-18T16:51:42.755036+00:00', '2026-08-18T16:51:42.755036+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('74ef0987-9f92-49c9-8645-fbb4599876ed', 'omeprazole', 'Omeprazole', 'Omeprazole', 'Omeprazole', 'Omeprazole', NULL, 'A proton pump inhibitor that suppresses gastric acid secretion.', 'Acidity & GERD', ARRAY['20 mg', '40 mg']::text[], ARRAY['Capsule', 'Tablet', 'Injection']::text[], ARRAY['Oral', 'Intravenous']::text[], 'Irreversibly inhibits the gastric H+/K+-ATPase (proton pump) in parietal cells.', 'Profound and prolonged suppression of both basal and stimulated acid secretion.', 'Acid-labile; given as enteric-coated formulation, absorbed in the small intestine.', 'Highly protein bound; concentrates in parietal cells.', 'Hepatic metabolism via CYP2C19 and CYP3A4.', 'Mainly renal excretion of metabolites.', 'Approximately 35-60%, increasing with repeated dosing', 'About 0.5-1 hour in plasma, but effect lasts far longer', 'Approximately 95%', NULL, NULL, 'Within 1 hour', 'Acid suppression persists up to 72 hours', ARRAY['GERD', 'Peptic ulcer disease', 'H. pylori eradication regimens', 'NSAID ulcer prophylaxis']::text[], ARRAY['Hypersensitivity to PPIs', 'Concomitant use with certain antiretrovirals']::text[], ARRAY['May mask symptoms of gastric malignancy', 'Long-term use associated with hypomagnesaemia, B12 deficiency and fracture risk', 'Reduces clopidogrel activation via CYP2C19']::text[], NULL, ARRAY['Headache', 'Diarrhoea', 'Abdominal pain', 'Nausea']::text[], ARRAY['C. difficile associated diarrhoea', 'Severe hypomagnesaemia', 'Acute interstitial nephritis (rare)']::text[], ARRAY['Clopidogrel', 'Ketoconazole and itraconazole', 'Methotrexate', 'Digoxin']::text[], NULL, ARRAY['Magnesium and B12 in long-term therapy', 'Ongoing need for therapy']::text[], NULL, NULL, 'Use when clearly indicated under medical direction.', 'Considered compatible under medical advice.', 'Used in children under specialist direction.', 'Reassess long-term need regularly.', 'No routine adjustment.', 'Dose reduction in severe hepatic impairment.', ARRAY['Potent, long-lasting acid suppression', 'Once-daily dosing']::text[], ARRAY['CYP2C19 interactions including clopidogrel', 'Long-term use risks']::text[], ARRAY['Take 30-60 minutes before food', 'Review long-term need periodically']::text[], '"-prazole → proton pump inhibitor."', '-prazole', 'oh-MEP-ra-zole', 'ओ-मेप्रा-ज़ोल', NULL, 'active', 'verified', '2026-08-18', '1.0', '2026-08-18T16:51:42.755036+00:00', '2026-08-18T16:51:42.755036+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('8ef23cad-842d-4c7e-8418-02ad4e3383ce', 'pantoprazole', 'Pantoprazole', 'Pantoprazole', 'Pantoprazole', 'Pantoprazole sodium', NULL, 'A proton pump inhibitor with fewer CYP-mediated interactions than omeprazole.', 'Acidity & GERD', ARRAY['20 mg', '40 mg']::text[], ARRAY['Tablet', 'Injection']::text[], ARRAY['Oral', 'Intravenous']::text[], 'Irreversibly inhibits the gastric H+/K+-ATPase in parietal cells.', 'Sustained suppression of gastric acid secretion.', 'Enteric-coated for absorption in the small intestine.', 'Highly protein bound.', 'Hepatic metabolism via CYP2C19 with sulfate conjugation.', 'Renal excretion of metabolites.', 'Approximately 77%', 'About 1 hour in plasma with far longer pharmacological effect', 'Approximately 98%', NULL, NULL, 'Within 1 hour', '24 hours of acid control with regular dosing', ARRAY['GERD', 'Erosive oesophagitis', 'Peptic ulcer', 'Stress ulcer prophylaxis (as directed)']::text[], ARRAY['Hypersensitivity to PPIs']::text[], ARRAY['May mask gastric malignancy', 'Long-term use risks similar to other PPIs']::text[], NULL, ARRAY['Headache', 'Diarrhoea', 'Nausea', 'Flatulence']::text[], ARRAY['Severe hypomagnesaemia', 'Acute interstitial nephritis (rare)']::text[], ARRAY['Methotrexate', 'Atazanavir', 'Ketoconazole']::text[], NULL, ARRAY['Magnesium in long-term therapy', 'Ongoing need']::text[], NULL, NULL, 'Use when clearly indicated under medical direction.', 'Considered compatible under medical advice.', 'Used in children under specialist direction.', 'Generally well tolerated.', 'No routine adjustment.', 'Reduce dose in severe hepatic impairment.', ARRAY['Fewer significant CYP interactions than omeprazole', 'IV option available']::text[], ARRAY['Same long-term PPI considerations']::text[], ARRAY['Take before breakfast']::text[], '"-prazole → pump blocker; pantoprazole = fewer interactions."', '-prazole', 'pan-TOE-pra-zole', 'पैन्टो-प्रा-ज़ोल', NULL, 'active', 'verified', '2026-08-18', '1.0', '2026-08-18T16:51:42.755036+00:00', '2026-08-18T16:51:42.755036+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('4d6b410b-0c2c-4044-bb74-3e034f0c685a', 'ondansetron', 'Ondansetron', 'Ondansetron', 'Ondansetron', 'Ondansetron hydrochloride', NULL, 'A selective 5-HT3 receptor antagonist antiemetic.', 'Vomiting & Nausea', ARRAY['4 mg', '8 mg']::text[], ARRAY['Tablet', 'Mouth dissolving tablet', 'Injection', 'Syrup']::text[], ARRAY['Oral', 'Intravenous', 'Intramuscular']::text[], 'Selectively blocks serotonin 5-HT3 receptors peripherally on vagal afferents and centrally in the chemoreceptor trigger zone.', 'Prevents and treats nausea and vomiting without significant dopaminergic effects.', 'Well absorbed orally with first-pass metabolism.', 'Moderate volume of distribution.', 'Extensive hepatic metabolism (CYP3A4, CYP2D6, CYP1A2).', 'Renal excretion of metabolites.', 'Approximately 60%', 'About 3-6 hours', 'Approximately 70-76%', NULL, NULL, 'Within 30 minutes', 'Around 8-12 hours', ARRAY['Chemotherapy-induced nausea and vomiting', 'Radiotherapy-induced vomiting', 'Post-operative nausea and vomiting']::text[], ARRAY['Concomitant apomorphine', 'Known hypersensitivity', 'Congenital long QT syndrome']::text[], ARRAY['Dose-dependent QT prolongation', 'Serotonin syndrome when combined with other serotonergic drugs', 'Constipation']::text[], NULL, ARRAY['Headache', 'Constipation', 'Fatigue']::text[], ARRAY['QT prolongation and torsades de pointes', 'Serotonin syndrome']::text[], ARRAY['Apomorphine', 'Other QT-prolonging drugs', 'SSRIs and SNRIs', 'Tramadol']::text[], NULL, ARRAY['ECG in cardiac risk patients', 'Electrolytes']::text[], NULL, NULL, 'Use only when clearly indicated under medical direction.', 'Seek medical advice.', 'Used in children under medical supervision.', 'Consider cardiac status and QT risk.', 'No routine adjustment.', 'Maximum daily dose reduced in severe hepatic impairment.', ARRAY['Highly effective antiemetic', 'Mouth-dissolving option']::text[], ARRAY['QT prolongation', 'Constipation']::text[], ARRAY['Not a treatment for the underlying cause of vomiting']::text[], '"-setron → 5-HT3 blocker."', '-setron', 'on-DAN-se-tron', 'ऑन-डैन-सी-ट्रॉन', NULL, 'active', 'verified', '2026-08-18', '1.0', '2026-08-18T16:51:42.755036+00:00', '2026-08-18T16:51:42.755036+00:00') ON CONFLICT (slug) DO NOTHING;
