ol', 'CNS depressants', 'Theophylline (minor)']::text[], NULL, ARRAY['Symptom control', 'Sedation level']::text[], NULL, NULL, 'Use only if clearly needed under medical advice.', 'Passes into breast milk; seek medical advice.', 'Used in children with age-appropriate dosing.', 'Reduce dose with reduced renal function.', 'Dose reduction in renal impairment.', 'Caution in hepatic impairment.', ARRAY['Once-daily dosing', 'Less sedating than first-generation agents']::text[], ARRAY['Can still cause drowsiness in some people']::text[], ARRAY['Take in the evening if drowsiness occurs']::text[], '"Cetirizine = allergy once a day."', '-zine', 'se-TEER-i-zeen', 'सेटी-रि-ज़ीन', NULL, 'active', 'verified', '2026-08-18', '1.0', '2026-08-18T16:51:42.755036+00:00', '2026-08-18T16:51:42.755036+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('dd667454-6407-4557-bd7b-c5e9b6c8d1e1', 'loratadine', 'Loratadine', 'Loratadine', 'Loratadine', 'Loratadine', NULL, 'A non-sedating second-generation H1 antihistamine.', 'Allergy', ARRAY['10 mg', '5 mg/5 mL']::text[], ARRAY['Tablet', 'Syrup']::text[], ARRAY['Oral']::text[], 'Selective peripheral H1 receptor antagonism.', 'Long-acting antihistamine effect with minimal sedation at usual doses.', 'Rapidly absorbed orally.', 'Highly protein bound; poor CNS penetration.', 'Extensive hepatic metabolism (CYP3A4/CYP2D6) to active desloratadine.', 'Renal and biliary excretion.', 'High but subject to first-pass metabolism', 'About 8-11 hours (active metabolite longer)', 'Approximately 97%', NULL, NULL, '1-3 hours', '24 hours', ARRAY['Allergic rhinitis', 'Chronic urticaria']::text[], ARRAY['Known hypersensitivity']::text[], ARRAY['Caution in severe hepatic impairment', 'Rarely sedating but individual variation exists']::text[], NULL, ARRAY['Headache', 'Dry mouth', 'Fatigue']::text[], ARRAY['Rare hypersensitivity reactions']::text[], ARRAY['Ketoconazole', 'Erythromycin', 'Cimetidine']::text[], NULL, ARRAY['Symptom control']::text[], NULL, NULL, 'Use only if clearly needed under medical advice.', 'Seek medical advice.', 'Used in children with age-appropriate dosing.', 'Generally well tolerated.', 'Extend dosing interval in significant renal impairment.', 'Reduce dose in hepatic impairment.', ARRAY['Minimal sedation', 'Once-daily dosing']::text[], ARRAY['Slower onset than some alternatives']::text[], ARRAY['Preferred where daytime alertness is important']::text[], '"-tadine → antihistamine."', '-tadine', 'lor-AT-a-deen', 'लॉरा-टा-डीन', NULL, 'active', 'verified', '2026-08-18', '1.0', '2026-08-18T16:51:42.755036+00:00', '2026-08-18T16:51:42.755036+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('1b863c01-ed09-4f6f-b66d-3aab15cc6552', 'salbutamol', 'Salbutamol', 'Salbutamol (Albuterol)', 'Salbutamol', 'Salbutamol sulphate', NULL, 'A short-acting beta-2 agonist bronchodilator.', 'Asthma & COPD', ARRAY['100 mcg/puff', '2 mg', '2.5 mg respule']::text[], ARRAY['Inhaler', 'Nebuliser solution', 'Tablet', 'Syrup']::text[], ARRAY['Inhalation', 'Oral', 'Intravenous']::text[], 'Selectively stimulates beta-2 adrenoceptors, increasing intracellular cAMP and relaxing bronchial smooth muscle.', 'Rapid bronchodilation; higher doses may cause beta-1 effects such as tachycardia.', 'Rapid onset after inhalation; oral absorption slower with first-pass metabolism.', 'Limited systemic distribution after inhalation.', 'Hepatic metabolism by sulfation.', 'Renal excretion.', 'Inhaled route delivers a small fraction to the lungs with high local effect', 'About 4-6 hours', 'Approximately 10%', NULL, NULL, 'Within 5 minutes when inhaled', '4-6 hours', ARRAY['Acute bronchospasm in asthma', 'COPD symptom relief', 'Exercise-induced bronchospasm']::text[], ARRAY['Known hypersensitivity']::text[], ARRAY['Increasing reliever use indicates poorly controlled asthma', 'Hypokalaemia with high doses', 'Caution in cardiac disease and thyrotoxicosis']::text[], NULL, ARRAY['Tremor', 'Palpitations', 'Headache', 'Muscle cramps']::text[], ARRAY['Severe hypokalaemia', 'Paradoxical bronchospasm', 'Cardiac arrhythmia at high doses']::text[], ARRAY['Non-selective beta blockers (antagonism)', 'Diuretics (hypokalaemia)', 'Digoxin']::text[], NULL, ARRAY['Inhaler technique', 'Frequency of reliever use', 'Serum potassium with high-dose therapy']::text[], NULL, NULL, 'Considered acceptable when needed for asthma control under medical direction.', 'Considered compatible with breastfeeding.', 'Widely used in children with spacer devices.', 'Caution with cardiac comorbidity.', 'No routine adjustment.', 'No routine adjustment.', ARRAY['Rapid symptom relief', 'Inhaled route limits systemic effects']::text[], ARRAY['No anti-inflammatory action', 'Overuse masks deteriorating control']::text[], ARRAY['Use a spacer for better lung delivery', 'Frequent use should prompt medical review']::text[], '"-terol / salbutamol → beta-2 opens the airways."', '-terol', 'sal-BYOO-ta-mol', 'सैल्-ब्यू-टा-मोल', NULL, 'active', 'verified', '2026-08-18', '1.0', '2026-08-18T16:51:42.755036+00:00', '2026-08-18T16:51:42.755036+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('9b9c4665-37b7-4d8f-829d-bfc0a0ed183a', 'metformin', 'Metformin', 'Metformin', 'Metformin', 'Metformin hydrochloride', NULL, 'A biguanide and usual first-line oral therapy for type 2 diabetes.', 'Diabetes', ARRAY['500 mg', '850 mg', '1000 mg', '500 mg SR']::text[], ARRAY['Tablet', 'SR tablet']::text[], ARRAY['Oral']::text[], 'Reduces hepatic gluconeogenesis, decreases intestinal glucose absorption and improves peripheral insulin sensitivity, partly through AMP-activated protein kinase pathways.', 'Lowers fasting and postprandial glucose without stimulating insulin secretion, so it does not intrinsically cause hypoglycaemia.', 'Slow and incomplete absorption from the small intestine.', 'Low protein binding; accumulates in intestinal wall and erythrocytes.', 'Not metabolised.', 'Excreted unchanged by the kidneys via tubular secretion.', 'Approximately 50-60%', 'About 4-9 hours (plasma)', 'Negligible', NULL, NULL, 'Days for full glycaemic effect', 'Depends on formulation; SR is once daily', ARRAY['Type 2 diabetes mellitus', 'Polycystic ovary syndrome (as directed)', 'Prediabetes in selected patients']::text[], ARRAY['eGFR below 30 mL/min/1.73 m2', 'Acute metabolic acidosis', 'Severe dehydration or hypoxic states']::text[], ARRAY['Rare but serious lactic acidosis, mainly with renal impairment', 'Withhold around iodinated contrast procedures and major surgery', 'Long-term use may reduce vitamin B12']::text[], NULL, ARRAY['Nausea', 'Diarrhoea', 'Metallic taste', 'Abdominal discomfort']::text[], ARRAY['Lactic acidosis (rare)', 'Symptomatic B12 deficiency']::text[], ARRAY['Iodinated contrast media', 'Alcohol', 'Diuretics and NSAIDs during dehydration', 'Cimetidine']::text[], NULL, ARRAY['Renal function at least annually', 'HbA1c', 'Vitamin B12 in long-term use']::text[], NULL, NULL, 'Often continued or used in pregnancy under specialist direction; follow medical advice.', 'Considered compatible under medical advice.', 'Used in older children with type 2 diabetes under specialist care.', 'Check renal function before and during therapy.', 'Dose limited below eGFR 45; contraindicated below 30.', 'Avoid in significant hepatic impairment due to lactic acidosis risk.', ARRAY['Weight neutral', 'No intrinsic hypoglycaemia', 'Strong long-term evidence', 'Low cost']::text[], ARRAY['GI intolerance at start', 'Renal restrictions']::text[], ARRAY['Start low and increase slowly with food', 'SR formulation improves GI tolerance']::text[], '"Metformin = first-line, no hypo by itself."', '', 'met-FOR-min', 'मेट-फॉर-मिन', NULL, 'active', 'verified', '2026-08-18', '1.0', '2026-08-18T16:51:42.755036+00:00', '2026-08-18T16:51:42.755036+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('0d75ccc4-37a6-4bb6-87c1-3c29d9edfefd', 'glimepiride', 'Glimepiride', 'Glimepiride', 'Glimepiride', 'Glimepiride', NULL, 'A second-generation sulfonylurea insulin secretagogue.', 'Diabetes', ARRAY['1 mg', '2 mg', '3 mg', '4 mg']::text[], ARRAY['Tablet']::text[], ARRAY['Oral']::text[], 'Closes ATP-sensitive potassium channels on pancreatic beta cells, causing depolarisation, calcium entry and insulin release.', 'Lowers blood glucose by increasing endogenous insulin secretion; requires functioning beta cells.', 'Completely absorbed orally.', 'Small volume of distribution; highly protein bound.', 'Hepatic metabolism via CYP2C9 to metabolites with some activity.', 'Renal and faecal excretion.', 'Essentially complete', 'About 5-8 hours', 'Over 99%', NULL, NULL, 'Within 1 hour', 'Up to 24 hours', ARRAY['Type 2 diabetes mellitus when metformin alone is insufficient']::text[], ARRAY['Type 1 diabetes', 'Diabetic ketoacidosis', 'Severe hepatic or renal impairment', 'Sulfonylurea hypersensitivity']::text[], ARRAY['Hypoglycaemia risk, particularly if meals are missed', 'Weight gain', 'Caution in the elderly and in renal impairment']::text[], NULL, ARRAY['Hypoglycaemia', 'Weight gain', 'Nausea']::text[], ARRAY['Severe prolonged hypoglycaemia']::text[], ARRAY['Other glucose-lowering drugs', 'Beta blockers (mask hypoglycaemia)', 'Fluconazole', 'Alcohol']::text[], NULL, ARRAY['Blood glucose', 'HbA1c', 'Hypoglycaemia symptoms', 'Weight']::text[], NULL, NULL, 'Generally avoided; insulin is usually preferred in pregnancy.', 'Generally avoided.', 'Not usually used in children.', 'Higher hypoglycaemia risk; start at the lowest dose.', 'Reduce dose; avoid in severe impairment.', 'Avoid in significant hepatic impairment.', ARRAY['Effective glucose lowering', 'Once-daily dosing', 'Low cost']::text[], ARRAY['Hypoglycaemia', 'Weight gain']::text[], ARRAY['Take with breakfast', 'Never skip meals while on therapy']::text[], '"gli- → sulfonylurea; can cause hypos."', 'gli-', 'glye-MEP-i-ride', 'ग्लाइ-मे-पि-राइड', NULL, 'active', 'verified', '2026-08-18', '1.0', '2026-08-18T16:51:42.755036+00:00', '2026-08-18T16:51:42.755036+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('e3aa7b24-c39c-4af2-ae98-8c50729fa971', 'amlodipine', 'Amlodipine', 'Amlodipine', 'Amlodipine', 'Amlodipine besylate', NULL, 'A long-acting dihydropyridine calcium channel blocker.', 'Blood Pressure', ARRAY['2.5 mg', '5 mg', '10 mg']::text[], ARRAY['Tablet']::text[], ARRAY['Oral']::text[], 'Blocks L-type calcium channels in vascular smooth muscle, causing peripheral arterial vasodilation.', 'Reduces peripheral vascular resistance and blood pressure with minimal negative inotropic effect at usual doses.', 'Slowly and well absorbed orally, unaffected by food.', 'Large volume of distribution; highly protein bound.', 'Extensive hepatic metabolism via CYP3A4.', 'Renal excretion of metabolites.', 'Approximately 64-90%', 'About 30-50 hours', 'Approximately 93%', NULL, NULL, 'Gradual over 6-12 hours', 'Over 24 hours', ARRAY['Hypertension', 'Chronic stable angina', 'Vasospastic angina']::text[], ARRAY['Cardiogenic shock', 'Severe aortic stenosis', 'Known hypersensitivity']::text[], ARRAY['Dose-dependent ankle oedema', 'Caution in severe hepatic impairment', 'Reflex tachycardia is uncommon due to slow onset']::text[], NULL, ARRAY['Ankle oedema', 'Flushing', 'Headache', 'Palpitations']::text[], ARRAY['Severe hypotension', 'Rarely worsening angina on initiation']::text[], ARRAY['Simvastatin (dose limit)', 'CYP3A4 inhibitors such as clarithromycin', 'Grapefruit juice']::text[], NULL, ARRAY['Blood pressure', 'Ankle oedema', 'Heart rate']::text[], NULL, NULL, 'Not first choice; use only under specialist direction.', 'Seek medical advice.', 'Used in children under specialist direction.', 'Effective and generally well tolerated; start low.', 'No routine adjustment.', 'Start low and titrate slowly in hepatic impairment.', ARRAY['Once-daily dosing', 'Smooth 24-hour blood pressure control', 'Effective in many Indian patients']::text[], ARRAY['Ankle oedema is a common reason for discontinuation']::text[], ARRAY['Oedema is dose related and not usually due to fluid overload']::text[], '"-dipine → dihydropyridine CCB, ankle oedema clue."', '-dipine', 'am-LOE-di-peen', 'ऐम्-लो-डि-पीन', NULL, 'active', 'verified', '2026-08-18', '1.0', '2026-08-18T16:51:42.755036+00:00', '2026-08-18T16:51:42.755036+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('f0eae62e-dd32-4c3c-9413-7b86dcb24f5d', 'losartan', 'Losartan', 'Losartan', 'Losartan', 'Losartan potassium', NULL, 'The first angiotensin II receptor blocker in clinical use.', 'Blood Pressure', ARRAY['25 mg', '50 mg', '100 mg']::text[], ARRAY['Tablet']::text[], ARRAY['Oral']::text[], 'Selectively blocks the angiotensin II type 1 (AT1) receptor, preventing angiotensin II mediated vasoconstriction and aldosterone release.', 'Lowers blood pressure and reduces intraglomerular pressure; also has a mild uricosuric effect.', 'Well absorbed orally with significant first-pass metabolism.', 'Highly protein bound; does not readily cross the blood-brain barrier.', 'Hepatic metabolism via CYP2C9 and CYP3A4 to the more potent active metabolite E-3174.', 'Renal and biliary excretion.', 'Approximately 33%', 'Losartan about 2 hours; active metabolite 6-9 hours', 'Over 98%', NULL, NULL, 'Within 6 hours', '24 hours', ARRAY['Hypertension', 'Diabetic nephropathy with proteinuria', 'Left ventricular hypertrophy risk reduction']::text[], ARRAY['Pregnancy', 'Bilateral renal artery stenosis', 'Concomitant aliskiren in diabetes']::text[], ARRAY['Hyperkalaemia', 'Renal function decline in volume depletion', 'Symptomatic hypotension after the first dose in volume-depleted patients']::text[], NULL, ARRAY['Dizziness', 'Fatigue', 'Hyperkalaemia']::text[], ARRAY['Angioedema (rare)', 'Acute kidney injury', 'Severe hyperkalaemia']::text[], ARRAY['Potassium supplements and potassium-sparing diuretics', 'NSAIDs', 'Lithium', 'ACE inhibitors (avoid dual blockade)']::text[], NULL, ARRAY['Serum potassium', 'Renal function', 'Blood pressure']::text[], NULL, NULL, 'Contraindicated in pregnancy due to fetal renal toxicity.', 'Generally avoided; alternatives preferred.', 'Used in children over 6 years under specialist direction.', 'Effective; monitor renal function and potassium.', 'Monitor closely; avoid in bilateral renal artery stenosis.', 'Reduce initial dose in hepatic impairment.', ARRAY['Well tolerated', 'No ACE inhibitor cough', 'Mild uricosuric effect']::text[], ARRAY['Contraindicated in pregnancy', 'Hyperkalaemia risk']::text[], ARRAY['Check potassium and creatinine after initiation', 'Do not combine with an ACE inhibitor']::text[], '"-sartan → ARB; -pril → ACE inhibitor."', '-sartan', 'loe-SAR-tan', 'लो-सार्-टन', NULL, 'active', 'verified', '2026-08-18', '1.0', '2026-08-18T16:51:42.755036+00:00', '2026-08-18T16:51:42.755036+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('97ee4bde-7a9d-43a7-9286-0bcab5809e2b', 'telmisartan', 'Telmisartan', 'Telmisartan', 'Telmisartan', 'Telmisartan', NULL, 'A long-acting angiotensin II receptor blocker.', 'Blood Pressure', ARRAY['20 mg', '40 mg', '80 mg']::text[], ARRAY['Tablet']::text[], ARRAY['Oral']::text[], 'Selective AT1 receptor antagonism with partial PPAR-gamma agonist activity.', 'Provides sustained 24-hour blood pressure reduction.', 'Absorbed rapidly with variable bioavailability.', 'Very high protein binding and a large volume of distribution.', 'Minimal metabolism; conjugated to an inactive glucuronide.', 'Almost entirely faecal (biliary) excretion.', 'Approximately 42-58%', 'About 24 hours', 'Over 99%', NULL, NULL, 'Within a few hours; full effect over weeks', 'Beyond 24 hours', ARRAY['Hypertension', 'Cardiovascular risk reduction in selected patients']::text[], ARRAY['Pregnancy', 'Biliary obstruction', 'Severe hepatic impairment']::text[], ARRAY['Hyperkalaemia', 'Hypotension in volume depletion', 'Renal function changes']::text[], NULL, ARRAY['Dizziness', 'Back pain', 'Sinus symptoms']::text[], ARRAY['Angioedema (rare)', 'Acute kidney injury', 'Hyperkalaemia']::text[], ARRAY['Potassium-sparing agents', 'NSAIDs', 'Digoxin', 'Lithium']::text[], NULL, ARRAY['Potassium', 'Renal function', 'Blood pressure']::text[], NULL, NULL, 'Contraindicated in pregnancy.', 'Generally avoided.', 'Not recommended in children.', 'Effective and generally well tolerated.', 'No routine adjustment in mild to moderate impairment.', 'Contraindicated in severe hepatic impairment and biliary obstruction.', ARRAY['Longest half-life among ARBs', 'Good early-morning blood pressure control']::text[], ARRAY['Contraindicated in pregnancy and biliary obstruction']::text[], ARRAY['Eliminated mainly by the liver, unlike losartan']::text[], '"Telmisartan = the longest-acting -sartan."', '-sartan', 'tel-mi-SAR-tan', 'टेल्-मि-सार्-टन', NULL, 'active', 'verified', '2026-08-18', '1.0', '2026-08-18T16:51:42.755036+00:00', '2026-08-18T16:51:42.755036+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('4a842194-44d2-4153-abe9-8540a8d5f61c', 'atorvastatin', 'Atorvastatin', 'Atorvastatin', 'Atorvastatin', 'Atorvastatin calcium', NULL, 'A potent HMG-CoA reductase inhibitor.', 'Cholesterol', ARRAY['10 mg', '20 mg', '40 mg', '80 mg']::text[], ARRAY['Tablet']::text[], ARRAY['Oral']::text[], 'Competitively inhibits HMG-CoA reductase, the rate-limiting enzyme of hepatic cholesterol synthesis, upregulating LDL receptors.', 'Lowers LDL cholesterol and triglycerides, modestly raises HDL, and has plaque-stabilising effects.', 'Rapidly absorbed with extensive first-pass metabolism.', 'Highly protein bound; hepatoselective.', 'Extensive hepatic metabolism via CYP3A4 to active metabolites.', 'Mainly biliary excretion.', 'Approximately 14% systemically but high hepatic extraction', 'Parent drug about 14 hours; active metabolites longer', 'Over 98%', NULL, NULL, 'Lipid effects over 2 weeks', 'Suitable for once-daily dosing at any time of day', ARRAY['Primary and secondary prevention of cardiovascular disease', 'Hypercholesterolaemia', 'Mixed dyslipidaemia']::text[], ARRAY['Active liver disease', 'Unexplained persistent transaminase elevation', 'Pregnancy and breastfeeding']::text[], ARRAY['Myopathy and rarely rhabdomyolysis', 'Interaction with strong CYP3A4 inhibitors', 'Small increase in new-onset diabetes']::text[], NULL, ARRAY['Myalgia', 'Headache', 'Gastrointestinal upset', 'Raised transaminases']::text[], ARRAY['Rhabdomyolysis', 'Immune-mediated necrotising myopathy (rare)', 'Severe hepatic injury (rare)']::text[], ARRAY['Clarithromycin and other strong CYP3A4 inhibitors', 'Fibrates (especially gemfibrozil)', 'Ciclosporin', 'Grapefruit juice in large amounts']::text[], NULL, ARRAY['Lipid profile', 'Liver enzymes at baseline', 'Creatine kinase if muscle symptoms occur']::text[], NULL, NULL, 'Contraindicated in pregnancy.', 'Contraindicated during breastfeeding.', 'Used in familial hypercholesterolaemia under specialist care.', 'Effective; monitor for muscle symptoms.', 'No routine adjustment.', 'Contraindicated in active liver disease.', ARRAY['Strong outcome evidence', 'Flexible dosing time', 'Potent LDL reduction']::text[], ARRAY['Muscle symptoms in some patients', 'CYP3A4 interactions']::text[], ARRAY['Report unexplained muscle pain promptly', 'Diet and exercise remain essential']::text[], '"-statin → HMG-CoA reductase inhibitor."', '-statin', 'a-TOR-va-sta-tin', 'अटोर्-वा-स्टै-टिन', NULL, 'active', 'verified', '2026-08-18', '1.0', '2026-08-18T16:51:42.755036+00:00', '2026-08-18T16:51:42.755036+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('e070830f-d3f3-4a7a-adb9-bb365c607346', 'rosuvastatin', 'Rosuvastatin', 'Rosuvastatin', 'Rosuvastatin', 'Rosuvastatin calcium', NULL, 'A high-intensity statin with limited CYP3A4 metabolism.', 'Cholesterol', ARRAY['5 mg', '10 mg', '20 mg', '40 mg']::text[], ARRAY['Tablet']::text[], ARRAY['Oral']::text[], 'Competitive inhibition of HMG-CoA reductase in the liver.', 'Produces the greatest LDL reduction per milligram among commonly used statins.', 'Absorbed with low systemic bioavailability but high hepatic uptake via OATP1B1.', 'Highly protein bound and hepatoselective.', 'Minimal metabolism, partly via CYP2C9.', 'Mainly faecal excretion.', 'Approximately 20%', 'About 19 hours', 'Approximately 88%', NULL, NULL, 'Lipid effects over 2-4 weeks', 'Once-daily dosing', ARRAY['Hypercholesterolaemia', 'Cardiovascular risk reduction']::text[], ARRAY['Active liver disease', 'Pregnancy and breastfeeding', 'Severe renal impairment at higher doses']::text[], ARRAY['Myopathy risk, higher at 40 mg', 'Proteinuria and haematuria reported at high doses', 'Asian patients may need lower starting doses']::text[], NULL, ARRAY['Myalgia', 'Headache', 'Nausea', 'Constipation']::text[], ARRAY['Rhabdomyolysis', 'Severe hepatic injury (rare)']::text[], ARRAY['Ciclosporin', 'Gemfibrozil', 'Some antiretrovirals', 'Warfarin (monitor INR)']::text[], NULL, ARRAY['Lipid profile', 'Liver enzymes at baseline', 'Creatine kinase if muscle symptoms occur']::text[], NULL, NULL, 'Contraindicated in pregnancy.', 'Contraindicated during breastfeeding.', 'Used in specific paediatric lipid disorders under specialist care.', 'Start at a lower dose.', 'Avoid higher doses in significant renal impairment.', 'Contraindicated in active liver disease.', ARRAY['High-intensity LDL lowering', 'Fewer CYP3A4 interactions than atorvastatin']::text[], ARRAY['Dose caution in Asian patients and renal impairment']::text[], ARRAY['Lower starting doses are often appropriate in Indian patients']::text[], '"Rosuvastatin = strongest LDL drop per mg."', '-statin', 'roe-soo-va-STA-tin', 'रोसू-वा-स्टै-टिन', NULL, 'active', 'verified', '2026-08-18', '1.0', '2026-08-18T16:51:42.755036+00:00', '2026-08-18T16:51:42.755036+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('bf45cfb8-eeaf-4df1-bbea-a751e72c3bcd', 'levothyroxine', 'Levothyroxine', 'Levothyroxine', 'Levothyroxine', 'Levothyroxine sodium', NULL, 'Synthetic thyroxine (T4) used as thyroid hormone replacement.', 'Thyroid', ARRAY['25 mcg', '50 mcg', '75 mcg', '100 mcg']::text[], ARRAY['Tablet']::text[], ARRAY['Oral']::text[], 'Provides exogenous T4 which is deiodinated peripherally to the active hormone T3, restoring normal metabolic function.', 'Restores euthyroid state; excessive dosing produces features of thyrotoxicosis.', 'Absorbed mainly from the jejunum and ileum; absorption reduced by food, calcium, iron and coffee.', 'Highly protein bound to thyroxine-binding globulin.', 'Peripheral deiodination in liver, kidney and other tissues.', 'Renal and faecal elimination of metabolites.', 'Approximately 40-80%, best on an empty stomach', 'About 7 days in euthyroid adults', 'Over 99%', NULL, NULL, 'Clinical effect over 1-3 weeks', 'Long, allowing once-daily dosing', ARRAY['Hypothyroidism', 'Post-thyroidectomy replacement', 'TSH suppression in selected thyroid cancers']::text[], ARRAY['Untreated adrenal insufficiency', 'Untreated thyrotoxicosis', 'Acute myocardial infarction (caution)']::text[], ARRAY['Start low in the elderly and in cardiac disease', 'Over-replacement risks atrial fibrillation and bone loss', 'Separate from calcium and iron by at least 4 hours']::text[], NULL, ARRAY['Usually none at correct dose', 'Palpitations, tremor, weight loss and anxiety indicate over-replacement']::text[], ARRAY['Atrial fibrillation and angina with over-replacement', 'Osteoporosis with prolonged over-replacement']::text[], ARRAY['Calcium and iron salts', 'Proton pump inhibitors', 'Soya products', 'Warfarin (enhanced effect)']::text[], NULL, ARRAY['TSH 6-8 weeks after any dose change, then periodically', 'Symptoms of over or under-replacement']::text[], NULL, NULL, 'Requirements usually increase in pregnancy; therapy must be continued with close monitoring.', 'Compatible with breastfeeding.', 'Used in congenital hypothyroidism; prompt treatment is critical.', 'Start at a lower dose and titrate slowly.', 'No routine adjustment.', 'No routine adjustment.', ARRAY['Inexpensive and highly effective', 'Once-daily dosing']::text[], ARRAY['Absorption is easily disturbed by food and other drugs', 'Needs regular monitoring']::text[], ARRAY['Take on an empty stomach, 30-60 minutes before breakfast', 'Keep to the same brand where possible']::text[], '"Levothyroxine = empty stomach, morning, wait before food."', '', 'lee-voe-thy-ROX-een', 'लीवो-थाइ-रॉक्-सीन', NULL, 'active', 'verified', '2026-08-18', '1.0', '2026-08-18T16:51:42.755036+00:00', '2026-08-18T16:51:42.755036+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('ac5fbe3d-07b5-4768-bc11-60a4b530fd25', 'furosemide', 'Furosemide', 'Furosemide (Frusemide)', 'Furosemide', 'Furosemide', NULL, 'A potent loop diuretic.', 'Heart', ARRAY['20 mg', '40 mg', '10 mg/mL injection']::text[], ARRAY['Tablet', 'Injection']::text[], ARRAY['Oral', 'Intravenous', 'Intramuscular']::text[], 'Inhibits the Na-K-2Cl co-transporter in the thick ascending limb of the loop of Henle, producing marked natriuresis and diuresis.', 'Rapid, potent diuresis with reduction of preload and oedema.', 'Variable oral absorption, reduced in decompensated heart failure.', 'Highly protein bound.', 'Partly metabolised by glucuronidation.', 'Mainly renal excretion.', 'Approximately 50-70% orally, variable', 'About 1-2 hours (prolonged in renal impairment)', 'Over 95%', NULL, NULL, 'Within 30-60 minutes orally, 5 minutes IV', '6-8 hours orally', ARRAY['Oedema in heart failure', 'Pulmonary oedema', 'Oedema in renal or hepatic disease', 'Resistant hypertension']::text[], ARRAY['Anuria', 'Severe electrolyte depletion', 'Hypersensitivity']::text[], ARRAY['Hypokalaemia and other electrolyte disturbances', 'Dehydration and hypotension', 'Ototoxicity with rapid high-dose IV administration']::text[], NULL, ARRAY['Increased urination', 'Hypokalaemia', 'Hyponatraemia', 'Dizziness']::text[], ARRAY['Severe electrolyte disturbance', 'Acute kidney injury from over-diuresis', 'Ototoxicity']::text[], ARRAY['Aminoglycosides (ototoxicity)', 'NSAIDs (reduced effect)', 'Digoxin (hypokalaemia risk)', 'Lithium']::text[], NULL, ARRAY['Electrolytes especially potassium and sodium', 'Renal function', 'Weight and fluid balance', 'Blood pressure']::text[], NULL, NULL, 'Use only when clearly indicated under medical direction.', 'Seek medical advice; may reduce milk production.', 'Used in children under specialist direction.', 'Higher risk of dehydration, falls and electrolyte disturbance.', 'Higher doses may be required; monitor closely.', 'Caution; risk of hepatic encephalopathy with electrolyte shifts.', ARRAY['Rapid and potent diuresis', 'Oral and IV routes']::text[], ARRAY['Electrolyte disturbance', 'Frequent urination affects daily routine']::text[], ARRAY['Take in the morning to avoid night-time urination', 'Monitor potassium']::text[], '"Furosemide = strong loop diuretic; watch potassium."', '', 'fyoor-OH-se-mide', 'फ्यूरो-सी-माइड', NULL, 'active', 'verified', '2026-08-18', '1.0', '2026-08-18T16:51:42.755036+00:00', '2026-08-18T16:51:42.755036+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('956bb130-891a-48c7-98ca-260b286d84c4', 'aspirin', 'Aspirin', 'Aspirin (Acetylsalicylic Acid)', 'Acetylsalicylic acid', 'Acetylsalicylic acid', NULL, 'A salicylate used at low dose as an antiplatelet and at higher dose as an analgesic.', 'Heart', ARRAY['75 mg', '150 mg', '325 mg']::text[], ARRAY['Tablet', 'Dispersible tablet', 'Enteric-coated tablet']::text[], ARRAY['Oral']::text[], 'Irreversibly acetylates cyclo-oxygenase-1 in platelets, blocking thromboxane A2 synthesis for the platelet lifespan; higher doses also inhibit COX-2 mediated prostaglandin synthesis.', 'Low dose gives antiplatelet effect; higher doses provide analgesic, antipyretic and anti-inflammatory effects.', 'Rapidly absorbed from the stomach and upper small intestine.', 'Widely distributed; salicylate is highly protein bound.', 'Hydrolysed to salicylic acid then conjugated in the liver; elimination becomes saturable at high doses.', 'Renal excretion, increased in alkaline urine.', 'Approximately 50-75%', 'Aspirin 15-20 minutes; salicylate 2-3 hours at low dose and longer at high dose', 'Salicylate 80-90%', NULL, NULL, 'Antiplatelet effect within 1 hour of a chewed dose', 'Antiplatelet effect lasts 7-10 days (platelet lifespan)', ARRAY['Secondary prevention of myocardial infarction and ischaemic stroke', 'Acute coronary syndrome', 'Pain and fever at higher doses']::text[], ARRAY['Active peptic ulcer or bleeding', 'Children and adolescents with viral illness (Reye syndrome risk)', 'Aspirin-exacerbated respiratory disease', 'Severe bleeding disorders']::text[], ARRAY['Gastrointestinal bleeding', 'Reye syndrome in children', 'Bleeding risk before surgery', 'Caution in asthma']::text[], NULL, ARRAY['Dyspepsia', 'Bruising', 'Minor bleeding', 'Nausea']::text[], ARRAY['Major gastrointestinal or intracranial bleeding', 'Anaphylactoid reactions', 'Salicylate toxicity in overdose']::text[], ARRAY['Anticoagulants', 'Other NSAIDs (including ibuprofen, which can blunt the antiplatelet effect)', 'Methotrexate', 'Alcohol']::text[], NULL, ARRAY['Signs of bleeding', 'Haemoglobin in long-term use', 'Blood pressure']::text[], NULL, NULL, 'Low-dose aspirin is used in specific obstetric indications under specialist direction; avoid high dose especially in the third trimester.', 'Low doses generally considered acceptable; avoid high doses.', 'Avoid in children and adolescents with febrile viral illness because of Reye syndrome.', 'Bleeding risk increases; consider gastroprotection.', 'Avoid in severe renal impairment.', 'Avoid in severe hepatic impairment.', ARRAY['Inexpensive with strong cardiovascular evidence', 'Irreversible platelet effect']::text[], ARRAY['Bleeding and gastric irritation', 'Not for routine paediatric fever']::text[], ARRAY['Chew the tablet in suspected heart attack for faster action', 'Take after food to reduce gastric irritation']::text[], '"Aspirin = irreversible COX-1, effect lasts the platelet''s life."', '', 'ASS-pi-rin', 'ऐस्-पि-रिन', NULL, 'active', 'verified', '2026-08-18', '1.0', '2026-08-18T16:51:42.755036+00:00', '2026-08-18T16:51:42.755036+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('bb0c1209-dd6b-4496-903c-3d3b11d21667', 'clopidogrel', 'Clopidogrel', 'Clopidogrel', 'Clopidogrel', 'Clopidogrel bisulphate', NULL, 'A thienopyridine P2Y12 receptor antagonist antiplatelet prodrug.', 'Heart', ARRAY['75 mg', '150 mg']::text[], ARRAY['Tablet']::text[], ARRAY['Oral']::text[], 'A prodrug converted by hepatic CYP enzymes, chiefly CYP2C19, to an active metabolite that irreversibly blocks the platelet P2Y12 ADP receptor.', 'Inhibits ADP-mediated platelet aggregation for the lifespan of the platelet.', 'Rapidly absorbed orally.', 'Highly protein bound.', 'Hepatic activation via CYP2C19 with extensive esterase inactivation of most of the dose.', 'Renal and faecal excretion.', 'Approximately 50% absorbed, with only a small fraction converted to active metabolite', 'Active metabolite about 30 minutes; effect far longer', 'Approximately 94-98%', NULL, NULL, 'Within 2 hours with a loading dose', 'Antiplatelet effect lasts 7-10 days', ARRAY['Acute coronary syndrome', 'After coronary stenting', 'Secondary prevention of ischaemic stroke and peripheral arterial disease']::text[], ARRAY['Active pathological bleeding', 'Severe hepatic impairment', 'Hypersensitivity']::text[], ARRAY['Bleeding risk, increased with dual antiplatelet therapy', 'Reduced effectiveness in CYP2C19 poor metabolisers', 'Stop before elective surgery as advised']::text[], NULL, ARRAY['Bruising', 'Minor bleeding', 'Diarrhoea', 'Rash']::text[], ARRAY['Major bleeding', 'Thrombotic thrombocytopenic purpura (very rare)']::text[], ARRAY['Omeprazole and esomeprazole (reduced activation)', 'Anticoagulants', 'NSAIDs', 'SSRIs']::text[], NULL, ARRAY['Signs of bleeding', 'Full blood count as clinically indicated']::text[], NULL, NULL, 'Use only when clearly indicated under specialist direction.', 'Generally avoided.', 'Not usually used in children.', 'Bleeding risk increases with age.', 'No routine adjustment.', 'Avoid in severe hepatic impairment.', ARRAY['Effective alternative or addition to aspirin', 'Once-daily dosing']::text[], ARRAY['Variable response due to CYP2C19 genetics', 'Bleeding risk']::text[], ARRAY['Do not stop abruptly after stenting without cardiology advice', 'Prefer pantoprazole if a PPI is needed']::text[], '"-grel → P2Y12 antiplatelet."', '-grel', 'kloe-PID-oh-grel', 'क्लो-पिडो-ग्रेल', NULL, 'active', 'verified', '2026-08-18', '1.0', '2026-08-18T16:51:42.755036+00:00', '2026-08-18T16:51:42.755036+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('c9cc0ec9-dd2c-44cc-87f9-1394df0ab771', 'aceclofenac', 'Aceclofenac', 'Aceclofenac', 'Aceclofenac', 'Aceclofenac', NULL, 'A non-steroidal anti-inflammatory drug widely used in India for musculoskeletal pain.', 'Pain & Fever', ARRAY['100 mg', '200 mg SR']::text[], ARRAY['Tablet', 'Gel']::text[], ARRAY['Oral', 'Topical']::text[], 'Inhibits cyclo-oxygenase, reducing prostaglandin synthesis; partly acts through its metabolite diclofenac.', 'Analgesic, anti-inflammatory and antipyretic effects with relative preference for COX-2.', 'Rapid and almost complete oral absorption.', 'Highly protein bound; penetrates synovial fluid.', 'Hepatic metabolism, including conversion to 4-hydroxyaceclofenac and diclofenac.', 'Mainly renal excretion of metabolites.', 'High after oral dosing', 'About 4 hours', 'Over 99%', NULL, NULL, 'Within 1-2 hours', '8-12 hours (immediate release)', ARRAY['Osteoarthritis', 'Rheumatoid arthritis', 'Ankylosing spondylitis', 'Acute musculoskeletal pain']::text[], ARRAY['Active peptic ulcer or GI bleeding', 'Severe heart failure', 'Severe renal impairment', 'NSAID-induced asthma or urticaria']::text[], ARRAY['Gastrointestinal bleeding risk', 'Cardiovascular thrombotic risk', 'Use the lowest effective dose for the shortest time']::text[], NULL, ARRAY['Dyspepsia', 'Abdominal pain', 'Nausea', 'Dizziness']::text[], ARRAY['GI bleeding or perforation', 'Hepatotoxicity', 'Acute kidney injury']::text[], ARRAY['Anticoagulants', 'Other NSAIDs', 'ACE inhibitors and diuretics (triple whammy)', 'Methotrexate']::text[], NULL, ARRAY['Renal function', 'Blood pressure', 'Signs of GI bleeding']::text[], NULL, NULL, 'Avoid, especially in the third trimester.', 'Seek medical advice before use.', 'Not generally recommended in young children.', 'Increased GI and renal risk; use cautiously.', 'Avoid in severe renal impairment.', 'Avoid in severe hepatic impairment.', ARRAY['Good anti-inflammatory efficacy', 'Twice-daily dosing']::text[], ARRAY['NSAID gastrointestinal and cardiovascular risks']::text[], ARRAY['Often combined with paracetamol in Indian practice — check total NSAID load']::text[], 'Aceclofenac = "diclofenac''s cousin" — same NSAID cautions.', '-fenac', 'ay-see-KLOE-fen-ak', 'ऐ-सी-क्लो-फे-नैक', NULL, 'active', 'under_review', NULL, '1.0', '2026-08-18T16:59:55.28058+00:00', '2026-08-18T16:59:55.28058+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('9c235b52-8c0a-43be-94a8-2fbbbdc4e235', 'mefenamic-acid', 'Mefenamic acid', 'Mefenamic acid', 'Mefenamic acid', 'Mefenamic acid', NULL, 'A fenamate NSAID commonly used for period pain and fever in children.', 'Pain & Fever', ARRAY['250 mg', '500 mg', '100 mg/5 mL']::text[], ARRAY['Tablet', 'Capsule', 'Suspension']::text[], ARRAY['Oral']::text[], 'Non-selective inhibition of COX-1 and COX-2 with some prostaglandin receptor antagonism.', 'Analgesic, anti-inflammatory and antipyretic; particularly useful in dysmenorrhoea.', 'Rapidly absorbed orally; peak levels in 2-4 hours.', 'Highly protein bound.', 'Hepatic metabolism, mainly via CYP2C9, then glucuronidation.', 'Renal and faecal excretion of metabolites.', 'Well absorbed orally', 'About 2-4 hours', 'Over 90%', NULL, NULL, 'Within 1-2 hours', 'About 6 hours', ARRAY['Dysmenorrhoea', 'Mild to moderate pain', 'Fever']::text[], ARRAY['Active peptic ulcer', 'Inflammatory bowel disease', 'Severe renal impairment', 'NSAID hypersensitivity']::text[], ARRAY['Diarrhoea may indicate colitis and requires stopping the drug', 'Seizures reported in overdose', 'Not for prolonged use']::text[], NULL, ARRAY['Diarrhoea', 'Dyspepsia', 'Nausea', 'Rash']::text[], ARRAY['GI bleeding', 'Haemolytic anaemia', 'Acute kidney injury']::text[], ARRAY['Anticoagulants', 'Other NSAIDs', 'Lithium', 'Methotrexate']::text[], NULL, ARRAY['Bowel symptoms', 'Renal function']::text[], NULL, NULL, 'Avoid, particularly in the third trimester.', 'Seek medical advice before use.', 'Used short term in children under medical advice.', 'Avoid prolonged use due to GI and renal risks.', 'Avoid in significant renal impairment.', 'Caution in hepatic impairment.', ARRAY['Effective in dysmenorrhoea']::text[], ARRAY['Diarrhoea is a characteristic adverse effect', 'Not suitable for long-term therapy']::text[], ARRAY['Stop if diarrhoea develops — a class-specific warning']::text[], 'Mefenamic → "Mef for menstrual pain, but Motions (diarrhoea) warn you".', '-fenamic', 'me-fe-NAM-ik', 'मे-फे-ना-मिक', NULL, 'active', 'under_review', NULL, '1.0', '2026-08-18T16:59:55.28058+00:00', '2026-08-18T16:59:55.28058+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('a6baee01-b44f-4a3d-ae8a-9c8dc39f1d02', 'etoricoxib', 'Etoricoxib', 'Etoricoxib', 'Etoricoxib', 'Etoricoxib', NULL, 'A selective COX-2 inhibitor used for arthritis and acute gout pain.', 'Pain & Fever', ARRAY['60 mg', '90 mg', '120 mg']::text[], ARRAY['Tablet']::text[], ARRAY['Oral']::text[], 'Selectively inhibits cyclo-oxygenase-2, reducing inflammatory prostaglandins with relative sparing of gastric COX-1.', 'Anti-inflammatory and analgesic with less platelet inhibition than non-selective NSAIDs.', 'Well absorbed orally.', 'Widely distributed; highly protein bound.', 'Hepatic metabolism, mainly via CYP3A4.', 'Renal excretion of metabolites.', 'Approximately 100%', 'About 22 hours', 'Around 92%', NULL, NULL, 'Within about 1 hour', 'Up to 24 hours', ARRAY['Osteoarthritis', 'Rheumatoid arthritis', 'Ankylosing spondylitis', 'Acute gouty arthritis']::text[], ARRAY['Uncontrolled hypertension', 'Ischaemic heart disease', 'Cerebrovascular disease', 'Severe heart failure', 'Active peptic ulcer']::text[], ARRAY['Blood pressure can rise significantly', 'Cardiovascular thrombotic risk is dose related']::text[], NULL, ARRAY['Hypertension', 'Oedema', 'Dyspepsia', 'Headache']::text[], ARRAY['Myocardial infarction', 'Stroke', 'Serious skin reactions']::text[], ARRAY['Antihypertensives', 'Anticoagulants', 'Methotrexate', 'Rifampicin']::text[], NULL, ARRAY['Blood pressure', 'Renal function', 'Liver enzymes with prolonged use']::text[], NULL, NULL, 'Avoid in pregnancy.', 'Avoid; seek medical advice.', 'Not recommended under 16 years.', 'Use lowest dose; monitor blood pressure closely.', 'Avoid in severe renal impairment.', 'Reduce dose in moderate hepatic impairment; avoid if severe.', ARRAY['Once-daily dosing', 'Lower GI ulcer risk than non-selective NSAIDs']::text[], ARRAY['Raises blood pressure', 'Cardiovascular risk limits use']::text[], ARRAY['Check blood pressure before and during therapy']::text[], '"-coxib" → COX-2 inhibitor: stomach kinder, heart stricter.', '-coxib', 'et-or-i-KOX-ib', 'ए-टो-रि-कॉक्स-इब', NULL, 'active', 'under_review', NULL, '1.0', '2026-08-18T16:59:55.28058+00:00', '2026-08-18T16:59:55.28058+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('586688f3-612a-4ecf-bc6c-754511430ee9', 'tramadol', 'Tramadol', 'Tramadol', 'Tramadol', 'Tramadol hydrochloride', NULL, 'A centrally acting weak opioid analgesic for moderate pain.', 'Pain & Fever', ARRAY['50 mg', '100 mg', '100 mg/2 mL injection']::text[], ARRAY['Capsule', 'Tablet', 'Injection']::text[], ARRAY['Oral', 'Intravenous', 'Intramuscular']::text[], 'Weak mu-opioid receptor agonism plus inhibition of noradrenaline and serotonin reuptake.', 'Analgesia with less respiratory depression than strong opioids at usual doses; lowers seizure threshold.', 'Rapid oral absorption.', 'Widely distributed; low protein binding.', 'Hepatic metabolism via CYP2D6 to the active O-desmethyl metabolite and via CYP3A4.', 'Mainly renal excretion.', 'About 70% orally (rises with repeat dosing)', 'About 6 hours', 'Around 20%', NULL, NULL, 'Within 1 hour orally', '4-6 hours', ARRAY['Moderate to moderately severe pain', 'Post-operative pain']::text[], ARRAY['Acute intoxication with alcohol or CNS depressants', 'Uncontrolled epilepsy', 'Concurrent MAO inhibitors', 'Severe respiratory depression']::text[], ARRAY['Seizure risk, especially with SSRIs or in overdose', 'Serotonin syndrome risk', 'Dependence with prolonged use']::text[], NULL, ARRAY['Nausea', 'Vomiting', 'Dizziness', 'Constipation', 'Drowsiness']::text[], ARRAY['Seizures', 'Serotonin syndrome', 'Respiratory depression']::text[], ARRAY['SSRIs and SNRIs', 'MAO inhibitors', 'Carbamazepine', 'Warfarin']::text[], NULL, ARRAY['Pain score', 'Sedation level', 'Bowel function']::text[], NULL, NULL, 'Avoid unless clearly necessary.', 'Avoid; passes into breast milk.', 'Not recommended in young children.', 'Reduce dose and extend interval.', 'Reduce dose in renal impairment.', 'Reduce dose in hepatic impairment.', ARRAY['Useful step between NSAIDs and strong opioids']::text[], ARRAY['Nausea limits use', 'CYP2D6 variability alters response', 'Dependence potential']::text[], ARRAY['Avoid combining with other serotonergic drugs where possible']::text[], 'Tramadol = "tram" between NSAIDs and morphine — mind seizures and serotonin.', '—', 'TRAM-a-dol', 'ट्रा-मा-डोल', NULL, 'active', 'under_review', NULL, '1.0', '2026-08-18T16:59:55.28058+00:00', '2026-08-18T16:59:55.28058+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('9f01c151-f46d-46fb-a72f-a9b1b92ca358', 'morphine', 'Morphine', 'Morphine', 'Morphine', 'Morphine sulphate', NULL, 'The reference strong opioid analgesic for severe pain.', 'Pain & Fever', ARRAY['10 mg/mL injection', '10 mg tablet', '2 mg/mL oral solution']::text[], ARRAY['Injection', 'Tablet', 'Oral solution']::text[], ARRAY['Oral', 'Intravenous', 'Subcutaneous', 'Intramuscular']::text[], 'Agonist at mu-opioid receptors in the brain and spinal cord, reducing pain transmission and perception.', 'Potent analgesia, sedation, euphoria, respiratory depression and reduced gut motility.', 'Oral absorption good but with extensive first-pass metabolism.', 'Widely distributed; crosses the placenta.', 'Hepatic glucuronidation to morphine-6-glucuronide (active) and morphine-3-glucuronide.', 'Renal excretion of glucuronides; accumulation in renal impairment.', 'About 20-40% orally', '2-4 hours (longer for active metabolites)', 'About 30-35%', NULL, NULL, 'Within 5-10 minutes IV', '3-5 hours', ARRAY['Severe acute pain', 'Cancer pain', 'Myocardial infarction pain', 'Palliative breathlessness']::text[], ARRAY['Acute respiratory depression', 'Paralytic ileus', 'Raised intracranial pressure with head injury', 'Acute severe asthma']::text[], ARRAY['Respiratory depression risk', 'Controlled drug under the NDPS framework in India', 'Dependence and tolerance with prolonged use']::text[], NULL, ARRAY['Constipation', 'Nausea', 'Drowsiness', 'Pruritus', 'Miosis']::text[], ARRAY['Respiratory depression', 'Hypotension', 'Dependence']::text[], ARRAY['Benzodiazepines', 'Alcohol', 'Other CNS depressants', 'MAO inhibitors']::text[], NULL, ARRAY['Respiratory rate', 'Sedation score', 'Pain score', 'Bowel function']::text[], NULL, NULL, 'Use only when essential; neonatal withdrawal possible with prolonged use.', 'Small amounts pass into milk; specialist advice needed.', 'Specialist dosing only.', 'Start low and titrate; increased sensitivity.', 'Reduce dose; active metabolites accumulate.', 'Reduce dose in hepatic impairment.', ARRAY['Highly effective in severe pain', 'Multiple routes and formulations']::text[], ARRAY['Respiratory depression', 'Constipation', 'Dependence and regulatory controls']::text[], ARRAY['Always co-prescribe a laxative', 'Naloxone reverses respiratory depression']::text[], 'Morphine → the yardstick opioid; every other opioid is compared with it.', '—', 'MOR-feen', 'मॉर्-फीन', NULL, 'active', 'under_review', NULL, '1.0', '2026-08-18T16:59:55.28058+00:00', '2026-08-18T16:59:55.28058+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('4939b3d5-6c6f-4696-80da-328c8078b480', 'ampicillin', 'Ampicillin', 'Ampicillin', 'Ampicillin', 'Ampicillin sodium / trihydrate', NULL, 'An aminopenicillin used mainly by injection for susceptible infections.', 'Antibiotics', ARRAY['250 mg', '500 mg', '500 mg injection', '1 g injection']::text[], ARRAY['Capsule', 'Injection']::text[], ARRAY['Oral', 'Intravenous', 'Intramuscular']::text[], 'Inhibits bacterial cell wall synthesis by binding penicillin-binding proteins.', 'Bactericidal, time-dependent killing against susceptible Gram-positive and some Gram-negative organisms.', 'Oral absorption incomplete and reduced by food.', 'Distributes into most tissues; poor CSF entry unless meninges inflamed.', 'Limited hepatic metabolism.', 'Mainly renal excretion of unchanged drug.', 'About 30-40% orally', 'About 1-1.5 hours', 'Around 20%', NULL, NULL, 'Rapid after IV dosing', '6-8 hours dosing interval', ARRAY['Listeria infection', 'Enterococcal infection', 'Susceptible respiratory and urinary infections']::text[], ARRAY['Penicillin hypersensitivity']::text[], ARRAY['Rash is common when given in glandular fever', 'Anaphylaxis risk in penicillin allergy']::text[], NULL, ARRAY['Diarrhoea', 'Rash', 'Nausea']::text[], ARRAY['Anaphylaxis', 'Clostridioides difficile colitis']::text[], ARRAY['Allopurinol (rash risk)', 'Methotrexate', 'Oral typhoid vaccine']::text[], NULL, ARRAY['Signs of hypersensitivity', 'Renal function on prolonged high-dose therapy']::text[], NULL, NULL, 'Considered acceptable when indicated.', 'Considered compatible; observe the infant for loose stools.', 'Widely used in children with weight-based dosing.', 'Adjust dose for renal function.', 'Extend dosing interval in renal impairment.', 'No routine adjustment.', ARRAY['Covers Listeria and enterococci', 'Inexpensive']::text[], ARRAY['Poor oral bioavailability', 'Beta-lactamase susceptible']::text[], ARRAY['Amoxicillin is preferred for oral therapy because absorption is better']::text[], 'Ampicillin → "A for ampicillin, A for Listeria cover".', '-cillin', 'am-pi-SIL-in', 'ऐम्-पि-सि-लिन', NULL, 'active', 'under_review', NULL, '1.0', '2026-08-18T16:59:55.28058+00:00', '2026-08-18T16:59:55.28058+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('6704fc06-667f-4034-9462-6db9c0caf0a1', 'cefalexin', 'Cefalexin', 'Cefalexin (Cephalexin)', 'Cefalexin', 'Cefalexin monohydrate', NULL, 'A first-generation oral cephalosporin used for skin and urinary infections.', 'Antibiotics', ARRAY['250 mg', '500 mg', '125 mg/5 mL']::text[], ARRAY['Capsule', 'Tablet', 'Suspension']::text[], ARRAY['Oral']::text[], 'Inhibits bacterial cell wall synthesis by binding penicillin-binding proteins.', 'Bactericidal against streptococci, methicillin-sensitive staphylococci and some Gram-negative organisms.', 'Well absorbed orally; absorption largely unaffected by food.', 'Distributes into skin, bone and urine.', 'Minimal metabolism.', 'Mainly renal excretion of unchanged drug.', 'Approximately 90%', 'About 1 hour', 'Around 10-15%', NULL, NULL, 'Within 1 hour', '6-8 hours dosing interval', ARRAY['Skin and soft tissue infection', 'Uncomplicated urinary tract infection', 'Streptococcal pharyngitis']::text[], ARRAY['Cephalosporin hypersensitivity', 'Severe penicillin anaphylaxis (caution)']::text[], ARRAY['Cross-reactivity with penicillins is uncommon but possible', 'Complete the prescribed course']::text[], NULL, ARRAY['Diarrhoea', 'Nausea', 'Rash']::text[], ARRAY['Anaphylaxis', 'Clostridioides difficile colitis']::text[], ARRAY['Probenecid', 'Metformin (increased levels)']::text[], NULL, ARRAY['Clinical response', 'Renal function in impairment']::text[], NULL, NULL, 'Generally considered acceptable when indicated.', 'Considered compatible with breastfeeding.', 'Commonly used with weight-based dosing.', 'Adjust for reduced renal function.', 'Reduce dose in significant renal impairment.', 'No routine adjustment.', ARRAY['Reliable oral absorption', 'Good Gram-positive skin cover']::text[], ARRAY['No activity against MRSA or Pseudomonas']::text[], ARRAY['A practical oral option for cellulitis when MRSA is not suspected']::text[], '"cef-" at the start → cephalosporin family.', 'cef-', 'sef-a-LEX-in', 'से-फ़ा-लेक्-सिन', NULL, 'active', 'under_review', NULL, '1.0', '2026-08-18T16:59:55.28058+00:00', '2026-08-18T16:59:55.28058+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('aa41237e-290e-418c-ba18-785a65d219d2', 'cefuroxime', 'Cefuroxime', 'Cefuroxime', 'Cefuroxime', 'Cefuroxime axetil (oral) / sodium (injection)', NULL, 'A second-generation cephalosporin used for respiratory and urinary infections.', 'Antibiotics', ARRAY['250 mg', '500 mg', '750 mg injection', '1.5 g injection']::text[], ARRAY['Tablet', 'Injection']::text[], ARRAY['Oral', 'Intravenous', 'Intramuscular']::text[], 'Inhibits bacterial cell wall synthesis via penicillin-binding proteins; more stable to some beta-lactamases than first-generation agents.', 'Bactericidal with extended Gram-negative activity compared with first-generation cephalosporins.', 'Oral cefuroxime axetil absorption improves when taken after food.', 'Distributes into tissues and pleural fluid.', 'Ester hydrolysis of the axetil prodrug; minimal further metabolism.', 'Mainly renal excretion.', 'About 35-50% with food (oral)', 'About 1-2 hours', 'Around 33-50%', NULL, NULL, 'Within 2-3 hours orally', '8-12 hours dosing interval', ARRAY['Community-acquired pneumonia', 'Sinusitis and otitis media', 'Urinary tract infection', 'Surgical prophylaxis']::text[], ARRAY['Cephalosporin hypersensitivity']::text[], ARRAY['Take the oral form after food for adequate absorption', 'Cross-reactivity in severe penicillin allergy']::text[], NULL, ARRAY['Diarrhoea', 'Nausea', 'Rash']::text[], ARRAY['Clostridioides difficile colitis', 'Anaphylaxis']::text[], ARRAY['Probenecid', 'Antacids and H2 blockers reduce oral absorption']::text[], NULL, ARRAY['Clinical response', 'Renal function']::text[], NULL, NULL, 'Considered acceptable when indicated.', 'Considered compatible with breastfeeding.', 'Used with weight-based dosing.', 'Adjust for renal function.', 'Reduce frequency in renal impairment.', 'No routine adjustment.', ARRAY['Broader Gram-negative cover than first-generation agents', 'Oral and injectable forms']::text[], ARRAY['Food dependence for oral absorption', 'Promotes resistance if overused']::text[], ARRAY['Oral cefuroxime axetil must be taken after food']::text[], 'Cefuroxime = second generation: "one step further into Gram-negative territory".', 'cef-', 'sef-yoor-OX-eem', 'से-फ़्यू-रॉक्-सीम', NULL, 'active', 'under_review', NULL, '1.0', '2026-08-18T16:59:55.28058+00:00', '2026-08-18T16:59:55.28058+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('f76613b7-0da0-44ea-abe8-7d00a82a594e', 'clarithromycin', 'Clarithromycin', 'Clarithromycin', 'Clarithromycin', 'Clarithromycin', NULL, 'A macrolide antibiotic used in respiratory infection and H. pylori eradication.', 'Antibiotics', ARRAY['250 mg', '500 mg', '500 mg SR']::text[], ARRAY['Tablet', 'Suspension']::text[], ARRAY['Oral']::text[], 'Binds the bacterial 50S ribosomal subunit and inhibits protein synthesis.', 'Bacteriostatic to bactericidal against atypical organisms, streptococci and H. pylori.', 'Well absorbed orally; food delays but does not reduce absorption.', 'Good tissue penetration, especially lung tissue.', 'Hepatic metabolism via CYP3A4 to the active 14-hydroxy metabolite; potent CYP3A4 inhibitor.', 'Renal and biliary excretion.', 'About 50%', '3-4 hours', 'Around 70%', NULL, NULL, 'Within 2-3 hours', '12 hours dosing interval', ARRAY['Community-acquired pneumonia', 'Atypical respiratory infection', 'Helicobacter pylori eradication']::text[], ARRAY['Concurrent ergot alkaloids', 'QT prolongation or history of torsades', 'Severe hepatic impairment with renal impairment']::text[], ARRAY['QT prolongation risk', 'Potent CYP3A4 inhibitor — check every co-prescription']::text[], NULL, ARRAY['Metallic taste', 'Nausea', 'Abdominal pain', 'Diarrhoea']::text[], ARRAY['QT prolongation and arrhythmia', 'Hepatotoxicity', 'C. difficile colitis']::text[], ARRAY['Statins (especially simvastatin)', 'Warfarin', 'Colchicine', 'Amiodarone']::text[], NULL, ARRAY['ECG when other QT-prolonging drugs are used', 'Liver function on prolonged therapy']::text[], NULL, NULL, 'Avoid in the first trimester unless essential.', 'Small amounts in milk; usually considered acceptable.', 'Used with weight-based dosing.', 'Watch for interactions and QT risk.', 'Reduce dose in severe renal impairment.', 'Caution in hepatic impairment.', ARRAY['Excellent lung penetration', 'Key part of H. pylori regimens']::text[], ARRAY['Major CYP3A4 interactions', 'Metallic taste affects adherence']::text[], ARRAY['Stop or dose-reduce simvastatin during a clarithromycin course']::text[], '"-thromycin" → macrolide; think interactions and QT.', '-thromycin', 'kla-RITH-roe-mye-sin', 'क्ला-रिथ्-रो-मा-इ-सिन', NULL, 'active', 'under_review', NULL, '1.0', '2026-08-18T16:59:55.28058+00:00', '2026-08-18T16:59:55.28058+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('9594349a-d382-4d43-bb0a-76a57cdb261d', 'ciprofloxacin', 'Ciprofloxacin', 'Ciprofloxacin', 'Ciprofloxacin', 'Ciprofloxacin hydrochloride', NULL, 'A fluoroquinolone antibiotic with strong Gram-negative activity.', 'Antibiotics', ARRAY['250 mg', '500 mg', '750 mg', '200 mg/100 mL infusion']::text[], ARRAY['Tablet', 'Infusion', 'Eye drops']::text[], ARRAY['Oral', 'Intravenous', 'Ophthalmic']::text[], 'Inhibits bacterial DNA gyrase and topoisomerase IV, blocking DNA replication.', 'Concentration-dependent bactericidal activity, particularly against Gram-negative bacilli including Pseudomonas.', 'Well absorbed orally; absorption markedly reduced by divalent and trivalent cations.', 'Wide tissue distribution including prostate and urine.', 'Partial hepatic metabolism; inhibits CYP1A2.', 'Mainly renal excretion of unchanged drug.', 'About 70%', 'About 4 hours', 'Around 20-40%', NULL, NULL, 'Within 1-2 hours', '12 hours dosing interval', ARRAY['Complicated urinary tract infection', 'Enteric fever (where susceptible)', 'Intra-abdominal infection with metronidazole', 'Pseudomonal infection']::text[], ARRAY['Known fluoroquinolone hypersensitivity', 'Tendon disorders with previous quinolone use', 'Concurrent tizanidine']::text[], ARRAY['Tendinitis and tendon rupture, especially with steroids and in the elderly', 'Aortic aneurysm risk', 'QT prolongation', 'Avoid within 2 hours of calcium, iron, zinc or antacids']::text[], NULL, ARRAY['Nausea', 'Diarrhoea', 'Headache', 'Dizziness']::text[], ARRAY['Tendon rupture', 'Peripheral neuropathy', 'Seizures', 'C. difficile colitis']::text[], ARRAY['Antacids and mineral supplements', 'Theophylline', 'Warfarin', 'Tizanidine']::text[], NULL, ARRAY['Tendon pain', 'Neurological symptoms', 'Renal function']::text[], NULL, NULL, 'Avoid unless no safer alternative.', 'Usually avoided; seek medical advice.', 'Restricted use in children; specialist decision.', 'Higher tendon and CNS risk; use cautiously.', 'Reduce dose in renal impairment.', 'No routine adjustment.', ARRAY['Excellent oral bioavailability', 'Strong Gram-negative cover']::text[], ARRAY['Tendon, neurological and cardiac safety concerns', 'High resistance rates in enteric fever in India']::text[], ARRAY['Separate from milk, antacids and iron by at least 2 hours']::text[], '"-floxacin" → fluoroquinolone: tendons, tummy upset, and metal-ion binding.', '-floxacin', 'sip-roe-FLOX-a-sin', 'सिप्-रो-फ्लॉक्-सा-सिन', NULL, 'active', 'under_review', NULL, '1.0', '2026-08-18T16:59:55.28058+00:00', '2026-08-18T16:59:55.28058+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('f916a56f-9026-4fe6-b4e2-8224e0b8b3f5', 'levofloxacin', 'Levofloxacin', 'Levofloxacin', 'Levofloxacin', 'Levofloxacin hemihydrate', NULL, 'A respiratory fluoroquinolone active against pneumococci and atypical organisms.', 'Antibiotics', ARRAY['250 mg', '500 mg', '750 mg', '500 mg/100 mL infusion']::text[], ARRAY['Tablet', 'Infusion', 'Eye drops']::text[], ARRAY['Oral', 'Intravenous', 'Ophthalmic']::text[], 'Inhibits bacterial DNA gyrase and topoisomerase IV.', 'Concentration-dependent bactericidal activity with good Gram-positive and atypical cover.', 'Almost complete oral absorption.', 'Excellent lung and tissue penetration.', 'Minimal metabolism.', 'Predominantly renal excretion of unchanged drug.', 'Approximately 99%', '6-8 hours', 'Around 24-38%', NULL, NULL, 'Within 1-2 hours', '24 hours dosing interval', ARRAY['Community-acquired pneumonia', 'Complicated urinary tract infection', 'Multidrug-resistant tuberculosis regimens', 'Sinusitis']::text[], ARRAY['Fluoroquinolone hypersensitivity', 'Previous quinolone tendon disorder', 'Epilepsy (caution)']::text[], ARRAY['Tendon rupture and peripheral neuropathy risk', 'QT prolongation', 'Dysglycaemia in diabetes']::text[], NULL, ARRAY['Nausea', 'Diarrhoea', 'Insomnia', 'Headache']::text[], ARRAY['Tendon rupture', 'Seizures', 'C. difficile colitis', 'Hypoglycaemia']::text[], ARRAY['Antacids, iron and calcium', 'Warfarin', 'QT-prolonging drugs', 'Sulfonylureas']::text[], NULL, ARRAY['Blood glucose in diabetes', 'Tendon symptoms', 'Renal function']::text[], NULL, NULL, 'Avoid unless essential.', 'Usually avoided during breastfeeding.', 'Restricted in children except in TB regimens.', 'Increased tendon and CNS risk.', 'Reduce dose in renal impairment.', 'No routine adjustment.', ARRAY['Once-daily dosing', 'Reliable pneumococcal cover']::text[], ARRAY['Quinolone class safety warnings', 'Contributes to resistance if overused']::text[], ARRAY['Blood glucose can swing in diabetic patients on quinolones']::text[], 'Levofloxacin = the "lung" quinolone.', '-floxacin', 'lee-voe-FLOX-a-sin', 'ले-वो-फ्लॉक्-सा-सिन', NULL, 'active', 'under_review', NULL, '1.0', '2026-08-18T16:59:55.28058+00:00', '2026-08-18T16:59:55.28058+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('925f7844-b819-40d5-b710-799e782f3eca', 'co-trimoxazole', 'Co-trimoxazole', 'Co-trimoxazole (Trimethoprim + Sulfamethoxazole)', 'Trimethoprim and sulfamethoxazole', 'Trimethoprim 80 mg + sulfamethoxazole 400 mg (standard strength)', NULL, 'A fixed-dose antibacterial combination blocking two steps of bacterial folate synthesis.', 'Antibiotics', ARRAY['80 mg + 400 mg', '160 mg + 800 mg', '40 mg + 200 mg per 5 mL']::text[], ARRAY['Tablet', 'Suspension', 'Injection']::text[], ARRAY['Oral', 'Intravenous']::text[], 'Sulfamethoxazole inhibits dihydropteroate synthase and trimethoprim inhibits dihydrofolate reductase, giving sequential blockade of folate synthesis.', 'Synergistic bactericidal activity against many Gram-positive and Gram-negative organisms and Pneumocystis jirovecii.', 'Well absorbed orally.', 'Widely distributed including lungs and prostate.', 'Hepatic acetylation and glucuronidation of sulfamethoxazole.', 'Mainly renal excretion.', 'Approximately 90-100%', 'About 10 hours (trimethoprim) and 10-12 hours (sulfamethoxazole)', 'Around 44-70%', NULL, NULL, 'Within 1-4 hours', '12 hours dosing interval', ARRAY['Pneumocystis pneumonia treatment and prophylaxis', 'Urinary tract infection', 'Nocardiosis', 'Selected skin infections']::text[], ARRAY['Sulfonamide hypersensitivity', 'Severe hepatic or renal impairment', 'Megaloblastic anaemia due to folate deficiency', 'Late pregnancy and infants under 6 weeks']::text[], ARRAY['Serious skin reactions including Stevens-Johnson syndrome', 'Hyperkalaemia, especially with ACE inhibitors', 'Maintain good hydration']::text[], NULL, ARRAY['Nausea', 'Rash', 'Headache']::text[], ARRAY['Stevens-Johnson syndrome', 'Bone marrow suppression', 'Hyperkalaemia', 'Acute kidney injury']::text[], ARRAY['Warfarin', 'Methotrexate', 'ACE inhibitors and potassium-sparing diuretics', 'Phenytoin']::text[], NULL, ARRAY['Serum potassium', 'Full blood count on prolonged therapy', 'Renal function']::text[], NULL, NULL, 'Avoid in the first trimester and near term.', 'Avoid in jaundiced or premature infants.', 'Used in children over 6 weeks with weight-based dosing.', 'Higher risk of hyperkalaemia and marrow suppression.', 'Reduce dose; avoid in severe impairment.', 'Avoid in severe hepatic disease.', ARRAY['Drug of choice for Pneumocystis pneumonia', 'Inexpensive and orally effective']::text[], ARRAY['Rash and hyperkalaemia are common reasons to stop']::text[], ARRAY['Check potassium when used with ACE inhibitors or ARBs']::text[], 'Co-trimoxazole = two drugs, two folate steps, double block.', '—', 'koe-trye-MOX-a-zole', 'को-ट्रा-इ-मॉक्-सा-ज़ोल', NULL, 'active', 'under_review', NULL, '1.0', '2026-08-18T16:59:55.28058+00:00', '2026-08-18T16:59:55.28058+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('ec284dea-21e6-4e3e-98f5-84e24f094da0', 'nitrofurantoin', 'Nitrofurantoin', 'Nitrofurantoin', 'Nitrofurantoin', 'Nitrofurantoin (macrocrystals)', NULL, 'A urinary antibacterial used for uncomplicated bladder infection.', 'Antibiotics', ARRAY['50 mg', '100 mg']::text[], ARRAY['Capsule', 'Tablet', 'Suspension']::text[], ARRAY['Oral']::text[], 'Reduced by bacterial nitroreductases to reactive intermediates that damage bacterial DNA, ribosomes and other macromolecules.', 'Bactericidal in urine; systemic tissue concentrations remain low.', 'Well absorbed orally; absorption improved with food.', 'Poor tissue distribution; concentrates in urine.', 'Partial tissue metabolism.', 'Rapid renal excretion producing high urinary levels.', 'Well absorbed orally', 'About 20-60 minutes in plasma', 'Around 60-90%', NULL, NULL, 'Urinary levels within 1-2 hours', '6-8 hours dosing interval', ARRAY['Uncomplicated lower urinary tract infection', 'Recurrent UTI prophylaxis']::text[], ARRAY['Creatinine clearance below about 30-45 mL/min', 'Term pregnancy (38-42 weeks)', 'Infants under 3 months', 'G6PD deficiency']::text[], ARRAY['Not effective for pyelonephritis or systemic infection', 'Pulmonary and hepatic reactions with long-term use', 'Urine may turn dark yellow or brown']::text[], NULL, ARRAY['Nausea', 'Headache', 'Urine discolouration']::text[], ARRAY['Acute and chronic pulmonary reactions', 'Peripheral neuropathy', 'Hepatitis', 'Haemolysis in G6PD deficiency']::text[], ARRAY['Magnesium trisilicate antacids', 'Probenecid', 'Quinolones (antagonism)']::text[], NULL, ARRAY['Respiratory symptoms on long-term use', 'Liver function on prolonged therapy']::text[], NULL, NULL, 'Acceptable in early pregnancy; avoid at term.', 'Avoid in infants under 1 month and in G6PD deficiency.', 'Not for infants under 3 months.', 'Avoid if renal function is reduced.', 'Contraindicated when clearance is low.', 'Caution; stop if hepatitis is suspected.', ARRAY['Low resistance rates in cystitis', 'Minimal effect on gut flora']::text[], ARRAY['Only useful for bladder infection', 'Pulmonary toxicity with prolonged use']::text[], ARRAY['Take with food to improve absorption and reduce nausea']::text[], 'Nitrofurantoin = "bladder-only antibiotic".', '—', 'nye-troe-fyoor-AN-toyn', 'ना-इ-ट्रो-फ्यू-रैन्-टॉ-इन', NULL, 'active', 'under_review', NULL, '1.0', '2026-08-18T16:59:55.28058+00:00', '2026-08-18T16:59:55.28058+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('e8e69821-fcb5-4aae-aa37-9622c4acddb6', 'rifampicin', 'Rifampicin', 'Rifampicin (Rifampin)', 'Rifampicin', 'Rifampicin', NULL, 'A cornerstone antitubercular antibiotic and potent enzyme inducer.', 'Antibiotics', ARRAY['150 mg', '300 mg', '450 mg', '600 mg']::text[], ARRAY['Capsule', 'Tablet', 'Suspension', 'Injection']::text[], ARRAY['Oral', 'Intravenous']::text[], 'Inhibits bacterial DNA-dependent RNA polymerase, blocking RNA synthesis.', 'Bactericidal against Mycobacterium tuberculosis including semi-dormant organisms; sterilising activity.', 'Well absorbed on an empty stomach; food reduces absorption.', 'Widely distributed including CSF when meninges are inflamed.', 'Hepatic deacetylation; strong inducer of CYP3A4 and other enzymes.', 'Biliary and renal excretion.', 'Good when taken fasting', '2-5 hours', 'Around 80%', NULL, NULL, 'Within 2-4 hours', '24 hours dosing interval in TB regimens', ARRAY['Tuberculosis (all forms, in combination)', 'Leprosy regimens', 'Meningococcal prophylaxis', 'Staphylococcal prosthetic infection (combination)']::text[], ARRAY['Jaundice', 'Known hypersensitivity', 'Concurrent use with several protease inhibitors']::text[], ARRAY['Turns urine, tears and sweat orange-red', 'Powerful enzyme inducer — oral contraceptives fail', 'Hepatotoxicity risk increases with isoniazid']::text[], NULL, ARRAY['Orange discolouration of body fluids', 'Nausea', 'Rash']::text[], ARRAY['Hepatitis', 'Thrombocytopenia', 'Flu-like syndrome with intermittent dosing']::text[], ARRAY['Oral contraceptives', 'Warfarin', 'Antiretrovirals', 'Oral hypoglycaemics']::text[], NULL, ARRAY['Liver function tests', 'Full blood count', 'Adherence']::text[], NULL, NULL, 'Used in TB during pregnancy under supervision; vitamin K may be given near delivery.', 'Considered compatible with breastfeeding.', 'Weight-based dosing in paediatric TB regimens.', 'Monitor liver function closely.', 'No routine adjustment.', 'Avoid or reduce dose in significant liver disease.', ARRAY['Essential sterilising drug in TB therapy']::text[], ARRAY['Massive drug interaction potential', 'Hepatotoxicity']::text[], ARRAY['Warn every patient about orange urine and contraceptive failure']::text[], 'Rifampicin = "Red-orange fluids and Rapid enzyme induction".', '—', 'rif-AM-pi-sin', 'रि-फैम्-पि-सिन', NULL, 'active', 'under_review', NULL, '1.0', '2026-08-18T16:59:55.28058+00:00', '2026-08-18T16:59:55.28058+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('c3eec6c5-ba64-4772-9580-434e4e688bac', 'isoniazid', 'Isoniazid', 'Isoniazid', 'Isoniazid', 'Isoniazid', NULL, 'A first-line antitubercular drug given with pyridoxine to prevent neuropathy.', 'Antibiotics', ARRAY['100 mg', '300 mg']::text[], ARRAY['Tablet', 'Syrup', 'Injection']::text[], ARRAY['Oral', 'Intramuscular']::text[], 'Inhibits mycolic acid synthesis in the mycobacterial cell wall after activation by catalase-peroxidase (KatG).', 'Bactericidal against rapidly dividing Mycobacterium tuberculosis.', 'Rapidly absorbed orally; food and antacids reduce absorption.', 'Distributed widely including CSF.', 'Hepatic acetylation by N-acetyltransferase 2 — fast and slow acetylator phenotypes.', 'Mainly renal excretion of metabolites.', 'High when taken fasting', '1-4 hours (acetylator dependent)', 'Low (under 10%)', NULL, NULL, 'Within 1-2 hours', '24 hours dosing interval', ARRAY['Tuberculosis treatment (in combination)', 'Latent tuberculosis infection']::text[], ARRAY['Active hepatitis', 'Previous isoniazid-induced liver injury', 'Known hypersensitivity']::text[], ARRAY['Peripheral neuropathy — give pyridoxine 10-25 mg daily', 'Hepatitis risk increases with age and alcohol', 'Report nausea, vomiting or dark urine urgently']::text[], NULL, ARRAY['Nausea', 'Raised transaminases', 'Numbness or tingling']::text[], ARRAY['Hepatitis', 'Peripheral neuropathy', 'Optic neuritis', 'Lupus-like syndrome']::text[], ARRAY['Phenytoin', 'Carbamazepine', 'Alcohol', 'Antacids']::text[], NULL, ARRAY['Liver function tests', 'Neuropathy symptoms', 'Adherence']::text[], NULL, NULL, 'Used in TB during pregnancy with pyridoxine cover.', 'Considered compatible; give the infant pyridoxine if indicated.', 'Weight-based dosing with pyridoxine.', 'Higher hepatitis risk; monitor closely.', 'No routine adjustment.', 'Avoid in active liver disease.', ARRAY['Highly effective and inexpensive', 'Key drug in latent TB therapy']::text[], ARRAY['Hepatotoxicity', 'Peripheral neuropathy without pyridoxine']::text[], ARRAY['Always pair isoniazid with pyridoxine in Indian practice']::text[], 'Isoniazid = "I Numb" — neuropathy unless pyridoxine is added.', '—', 'eye-soe-NYE-a-zid', 'आ-इ-सो-ना-इ-ज़िड', NULL, 'active', 'under_review', NULL, '1.0', '2026-08-18T16:59:55.28058+00:00', '2026-08-18T16:59:55.28058+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('a6dcb300-35ce-48af-859d-e8702ce350a7', 'gentamicin', 'Gentamicin', 'Gentamicin', 'Gentamicin', 'Gentamicin sulphate', NULL, 'An injectable aminoglycoside for serious Gram-negative infection.', 'Antibiotics', ARRAY['40 mg/mL injection', '80 mg injection', '0.3% eye drops']::text[], ARRAY['Injection', 'Eye drops', 'Cream']::text[], ARRAY['Intravenous', 'Intramuscular', 'Ophthalmic', 'Topical']::text[], 'Binds irreversibly to the bacterial 30S ribosomal subunit causing mRNA misreading and cell death.', 'Concentration-dependent bactericidal activity with a post-antibiotic effect.', 'Not absorbed orally; given parenterally.', 'Distributes into extracellular fluid; poor CSF penetration.', 'Not metabolised.', 'Renal excretion of unchanged drug by glomerular filtration.', 'Negligible orally', 'About 2-3 hours with normal renal function', 'Low (under 30%)', NULL, NULL, 'Rapid after IV dosing', 'Once-daily dosing in most regimens', ARRAY['Severe Gram-negative sepsis', 'Pyelonephritis', 'Endocarditis (synergy)', 'Neonatal sepsis']::text[], ARRAY['Myasthenia gravis', 'Known aminoglycoside hypersensitivity']::text[], ARRAY['Nephrotoxicity and ototoxicity are dose and duration related', 'Therapeutic drug monitoring is required', 'Avoid concurrent nephrotoxins where possible']::text[], NULL, ARRAY['Rise in serum creatinine', 'Vestibular disturbance']::text[], ARRAY['Acute kidney injury', 'Irreversible ototoxicity', 'Neuromuscular blockade']::text[], ARRAY['Loop diuretics', 'Vancomycin', 'NSAIDs', 'Neuromuscular blockers']::text[], NULL, ARRAY['Serum gentamicin levels', 'Serum creatinine', 'Hearing and balance symptoms']::text[], NULL, NULL, 'Avoid unless essential; fetal ototoxicity risk.', 'Minimal oral absorption by the infant; usually acceptable.', 'Neonatal and paediatric dosing is weight and age based.', 'Higher toxicity risk; adjust and monitor closely.', 'Extend interval and monitor levels.', 'No routine adjustment.', ARRAY['Rapid bactericidal action', 'Synergy with beta-lactams']::text[], ARRAY['Narrow therapeutic index', 'Requires level monitoring']::text[], ARRAY['Trough levels matter most for toxicity; peak levels for efficacy']::text[], 'Aminoglycosides → "Ears and kidneys pay the price".', '-micin', 'jen-ta-MYE-sin', 'जेन्-टा-मा-इ-सिन', NULL, 'active', 'under_review', NULL, '1.0', '2026-08-18T16:59:55.28058+00:00', '2026-08-18T16:59:55.28058+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('e9f7e395-0d0e-474a-86bd-55b40491dfb7', 'tinidazole', 'Tinidazole', 'Tinidazole', 'Tinidazole', 'Tinidazole', NULL, 'A nitroimidazole used for amoebiasis, giardiasis and anaerobic infection.', 'Antibiotics', ARRAY['300 mg', '500 mg', '1 g']::text[], ARRAY['Tablet', 'Suspension', 'Infusion']::text[], ARRAY['Oral', 'Intravenous']::text[], 'Reduced within anaerobic organisms to reactive nitro radicals that damage microbial DNA.', 'Amoebicidal, giardicidal and active against anaerobic bacteria; longer acting than metronidazole.', 'Rapid and complete oral absorption.', 'Widely distributed including bile and CSF.', 'Hepatic metabolism via CYP3A4.', 'Renal and faecal excretion.', 'Approximately 100%', '12-14 hours', 'Around 12%', NULL, NULL, 'Within 2 hours', '24 hours dosing interval', ARRAY['Amoebiasis', 'Giardiasis', 'Trichomoniasis', 'Bacterial vaginosis', 'Anaerobic infection']::text[], ARRAY['First trimester of pregnancy', 'Blood dyscrasias', 'Neurological disease', 'Known nitroimidazole hypersensitivity']::text[], ARRAY['Avoid alcohol during and for 3 days after therapy (disulfiram-like reaction)', 'Metallic taste is common']::text[], NULL, ARRAY['Metallic taste', 'Nausea', 'Anorexia', 'Dark urine']::text[], ARRAY['Peripheral neuropathy with prolonged use', 'Seizures (rare)']::text[], ARRAY['Alcohol', 'Warfarin', 'Phenytoin', 'Lithium']::text[], NULL, ARRAY['Symptom resolution', 'Neurological symptoms on prolonged use']::text[], NULL, NULL, 'Avoid in the first trimester.', 'Avoid breastfeeding for 3 days after a single high dose.', 'Weight-based dosing in children.', 'No specific adjustment; watch for neuropathy.', 'No routine adjustment.', 'Reduce dose in severe hepatic impairment.', ARRAY['Once-daily and short-course therapy', 'Better tolerated than metronidazole for many patients']::text[], ARRAY['Alcohol interaction', 'Metallic taste']::text[], ARRAY['Single-dose regimens are common for giardiasis and trichomoniasis']::text[], '"-nidazole" → no alcohol.', '-nidazole', 'tin-ID-a-zole', 'टि-नि-डा-ज़ोल', NULL, 'active', 'under_review', NULL, '1.0', '2026-08-18T16:59:55.28058+00:00', '2026-08-18T16:59:55.28058+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('b5a7f93d-82b5-46e6-9700-db4e25a7172a', 'albendazole', 'Albendazole', 'Albendazole', 'Albendazole', 'Albendazole', NULL, 'A broad-spectrum anthelmintic used in national deworming programmes.', 'Deworming', ARRAY['400 mg', '200 mg/5 mL']::text[], ARRAY['Tablet', 'Suspension']::text[], ARRAY['Oral']::text[], 'Binds parasite beta-tubulin, inhibiting microtubule polymerisation and glucose uptake by the worm.', 'Larvicidal, ovicidal and vermicidal against common intestinal helminths.', 'Poorly absorbed; absorption increases substantially with a fatty meal.', 'The active sulphoxide metabolite distributes into tissues and cysts.', 'Extensive first-pass hepatic metabolism to albendazole sulphoxide.', 'Mainly biliary excretion.', 'Low and variable orally', 'About 8-12 hours (sulphoxide)', 'Around 70%', NULL, NULL, 'Within 2-5 hours', 'Single dose for most intestinal worms', ARRAY['Roundworm, hookworm, whipworm and pinworm infestation', 'Neurocysticercosis', 'Hydatid disease']::text[], ARRAY['First trimester of pregnancy', 'Known hypersensitivity']::text[], ARRAY['Prolonged high-dose therapy requires blood count and liver monitoring', 'Take with fatty food for tissue infections']::text[], NULL, ARRAY['Abdominal pain', 'Nausea', 'Headache']::text[], ARRAY['Bone marrow suppression with prolonged therapy', 'Hepatotoxicity', 'Raised intracranial pressure in neurocysticercosis']::text[], ARRAY['Dexamethasone', 'Praziquantel', 'Cimetidine']::text[], NULL, ARRAY['Full blood count and liver function on prolonged therapy']::text[], NULL, NULL, 'Avoid in the first trimester; used in programmes after the first trimester.', 'Considered compatible with breastfeeding.', 'Widely used from 1-2 years of age in deworming programmes.', 'No specific adjustment.', 'No routine adjustment.', 'Caution in hepatic impairment.', ARRAY['Single-dose therapy for common worms', 'Very low cost']::text[], ARRAY['Reinfection is common without sanitation measures']::text[], ARRAY['Take with a fatty meal when treating tissue cysts, on an empty stomach for gut worms']::text[], '"-bendazole" → binds tubulin, banishes worms.', '-bendazole', 'al-BEN-da-zole', 'ऐल्-बेन्-डा-ज़ोल', NULL, 'active', 'under_review', NULL, '1.0', '2026-08-18T16:59:55.28058+00:00', '2026-08-18T16:59:55.28058+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('156b0311-c968-4339-93b8-365d7ce721e0', 'ivermectin', 'Ivermectin', 'Ivermectin', 'Ivermectin', 'Ivermectin', NULL, 'An antiparasitic used for strongyloidiasis, scabies and filarial programmes.', 'Deworming', ARRAY['3 mg', '6 mg', '12 mg']::text[], ARRAY['Tablet', 'Lotion']::text[], ARRAY['Oral', 'Topical']::text[], 'Binds glutamate-gated chloride channels in invertebrate nerve and muscle cells, causing paralysis of the parasite.', 'Microfilaricidal and active against several ectoparasites; mammalian CNS is protected by the blood-brain barrier.', 'Absorbed orally; absorption increases with food.', 'Widely distributed; does not readily cross an intact blood-brain barrier.', 'Hepatic metabolism via CYP3A4.', 'Mainly faecal excretion.', 'Good oral absorption', 'About 18 hours', 'Around 93%', NULL, NULL, 'Within 4-5 hours', 'Single dose, often repeated after 1-2 weeks', ARRAY['Strongyloidiasis', 'Scabies', 'Lymphatic filariasis mass drug administration', 'Head lice']::text[], ARRAY['Known hypersensitivity', 'Caution in Loa loa co-infection']::text[], ARRAY['Not approved as a treatment for COVID-19', 'Mazzotti-type reactions can occur when microfilarial load is high']::text[], NULL, ARRAY['Pruritus', 'Rash', 'Dizziness', 'Nausea']::text[], ARRAY['Severe hypersensitivity reactions', 'Encephalopathy in heavy Loa loa infection']::text[], ARRAY['Warfarin', 'Strong CYP3A4 inhibitors']::text[], NULL, ARRAY['Symptom response', 'Signs of hypersensitivity']::text[], NULL, NULL, 'Generally avoided; specialist advice needed.', 'Small amounts in milk; specialist advice needed.', 'Usually reserved for children above 15 kg.', 'No specific adjustment.', 'No routine adjustment.', 'Caution in hepatic impairment.', ARRAY['Single-dose oral therapy for scabies and strongyloidiasis']::text[], ARRAY['Repeat dosing often needed', 'Widely misused for unapproved indications']::text[], ARRAY['Treat all household contacts simultaneously in scabies']::text[], 'Ivermectin → paralyses parasites, not people.', '—', 'eye-ver-MEK-tin', 'आ-इ-वर्-मेक्-टिन', NULL, 'active', 'under_review', NULL, '1.0', '2026-08-18T17:03:05.494031+00:00', '2026-08-18T17:03:05.494031+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('2774cf88-9230-424d-84ba-eca4da702224', 'hydroxychloroquine', 'Hydroxychloroquine', 'Hydroxychloroquine', 'Hydroxychloroquine', 'Hydroxychloroquine sulphate', NULL, 'A 4-aminoquinoline used mainly as a disease-modifying drug in lupus and rheumatoid arthritis.', 'Immunity & Autoimmune', ARRAY['200 mg', '300 mg', '400 mg']::text[], ARRAY['Tablet']::text[], ARRAY['Oral']::text[], 'Accumulates in lysosomes, raising intracellular pH and interfering with antigen processing and toll-like receptor signalling; in malaria it interferes with haem detoxification.', 'Immunomodulatory effect develops slowly over weeks to months.', 'Well absorbed orally.', 'Extensive tissue distribution with a very large volume of distribution.', 'Hepatic metabolism to active metabolites.', 'Renal excretion over a prolonged period.', 'About 70-80%', 'Around 40 days (terminal)', 'Around 40-50%', NULL, NULL, 'Weeks for immunomodulatory effect', 'Long — steady state takes months', ARRAY['Systemic lupus erythematosus', 'Rheumatoid arthritis', 'Malaria in selected settings']::text[], ARRAY['Pre-existing maculopathy', 'Known 4-aminoquinoline hypersensitivity']::text[], ARRAY['Annual retinal screening is required with long-term use', 'QT prolongation risk', 'Overdose is dangerous, particularly in children']::text[], NULL, ARRAY['Nausea', 'Abdominal discomfort', 'Headache', 'Skin pigmentation']::text[], ARRAY['Irreversible retinopathy', 'Cardiomyopathy', 'QT prolongation', 'Severe hypoglycaemia']::text[], ARRAY['Digoxin', 'QT-prolonging drugs', 'Insulin and sulfonylureas', 'Antacids (spacing needed)']::text[], NULL, ARRAY['Baseline and annual eye examination', 'Blood glucose', 'ECG when combined with QT-prolonging drugs']::text[], NULL, NULL, 'Considered acceptable in lupus under specialist supervision.', 'Considered compatible with breastfeeding.', 'Specialist supervision; overdose is highly toxic in children.', 'Monitor renal function and eye health.', 'Reduce dose in significant renal impairment.', 'Caution in hepatic impairment.', ARRAY['Steroid-sparing in lupus', 'Long clinical experience']::text[], ARRAY['Slow onset', 'Retinal toxicity requires monitoring']::text[], ARRAY['Not an evidence-based treatment for COVID-19']::text[], 'HCQ → "eyes need yearly checks".', '—', 'hye-drox-ee-KLOR-oh-kwin', 'हा-इ-ड्रॉक्-सी-क्लो-रो-क्विन', NULL, 'active', 'under_review', NULL, '1.0', '2026-08-18T17:03:05.494031+00:00', '2026-08-18T17:03:05.494031+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('f9a7cc7c-1bb6-44fb-a8d0-e547d67d0b81', 'fluconazole', 'Fluconazole', 'Fluconazole', 'Fluconazole', 'Fluconazole', NULL, 'A triazole antifungal widely used for candidiasis and dermatophyte infection.', 'Fungal Infections', ARRAY['50 mg', '150 mg', '200 mg', '400 mg', '2 mg/mL infusion']::text[], ARRAY['Tablet', 'Capsule', 'Infusion']::text[], ARRAY['Oral', 'Intravenous']::text[], 'Inhibits fungal cytochrome P450 14-alpha-demethylase, blocking conversion of lanosterol to ergosterol and disrupting the fungal cell membrane.', 'Fungistatic against most Candida species; excellent penetration into body fluids including CSF.', 'Almost complete oral absorption unaffected by food or gastric pH.', 'Wide distribution including CSF, saliva and vaginal tissue.', 'Minimal metabolism; inhibits CYP2C9, CYP2C19 and CYP3A4.', 'Mainly renal excretion of unchanged drug.', 'Over 90%', 'About 30 hours', 'Around 11-12%', NULL, NULL, 'Within 1-2 hours', '24 hours dosing interval', ARRAY['Vulvovaginal candidiasis', 'Oropharyngeal and oesophageal candidiasis', 'Cryptococcal meningitis (maintenance)', 'Dermatophyte infection']::text[], ARRAY['Concurrent terfenadine or cisapride', 'Known azole hypersensitivity', 'High-dose use in pregnancy']::text[], ARRAY['QT prolongation risk', 'Hepatotoxicity', 'High doses in the first trimester are teratogenic']::text[], NULL, ARRAY['Nausea', 'Headache', 'Abdominal pain', 'Rash']::text[], ARRAY['Hepatotoxicity', 'QT prolongation and torsades', 'Stevens-Johnson syndrome']::text[], ARRAY['Warfarin', 'Phenytoin', 'Statins', 'Sulfonylureas', 'QT-prolonging drugs']::text[], NULL, ARRAY['Liver function on prolonged therapy', 'ECG when other QT drugs are used']::text[], NULL, NULL, 'Single low doses may be acceptable; avoid high-dose or repeated courses.', 'Considered compatible with breastfeeding.', 'Weight-based dosing in children.', 'Adjust for renal function.', 'Reduce maintenance dose in renal impairment.', 'Caution and monitor liver function.', ARRAY['Excellent oral bioavailability', 'Single-dose therapy for vaginal candidiasis']::text[], ARRAY['Significant CYP interactions', 'Resistance in some non-albicans Candida']::text[], ARRAY['A single 150 mg dose treats uncomplicated vaginal candidiasis']::text[], '"-azole" → antifungal; think liver and interactions.', '-azole', 'floo-KON-a-zole', 'फ्लू-को-ना-ज़ोल', NULL, 'active', 'under_review', NULL, '1.0', '2026-08-18T17:03:05.494031+00:00', '2026-08-18T17:03:05.494031+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('d280122b-2ed8-4f4b-85fe-b9ffb3ab0885', 'acyclovir', 'Aciclovir', 'Aciclovir (Acyclovir)', 'Aciclovir', 'Aciclovir sodium (injection)', NULL, 'An antiviral for herpes simplex and varicella zoster infections.', 'Viral Infections', ARRAY['200 mg', '400 mg', '800 mg', '250 mg injection', '5% cream']::text[], ARRAY['Tablet', 'Cream', 'Injection', 'Eye ointment']::text[], ARRAY['Oral', 'Intravenous', 'Topical']::text[], 'Phosphorylated by viral thymidine kinase then cellular kinases to aciclovir triphosphate, which inhibits viral DNA polymerase and terminates the DNA chain.', 'Selective for virus-infected cells; reduces duration and severity when started early.', 'Poor and variable oral absorption.', 'Widely distributed including CSF at about 50% of plasma levels.', 'Minimal hepatic metabolism.', 'Mainly renal excretion by filtration and tubular secretion.', 'About 15-30% orally', '2-3 hours with normal renal function', 'Around 9-33%', NULL, NULL, 'Within 1.5-2 hours', '5 times daily oral dosing for treatment', ARRAY['Herpes simplex infection', 'Herpes zoster (shingles)', 'Chickenpox in at-risk patients', 'Herpes encephalitis (IV)']::text[], ARRAY['Known hypersensitivity to aciclovir or valaciclovir']::text[], ARRAY['Maintain hydration with IV therapy to avoid crystal nephropathy', 'Start within 72 hours of rash onset for best effect']::text[], NULL, ARRAY['Nausea', 'Headache', 'Diarrhoea', 'Local burning with topical use']::text[], ARRAY['Acute kidney injury with rapid IV infusion', 'Neurotoxicity in renal impairment']::text[], ARRAY['Probenecid', 'Nephrotoxic drugs', 'Mycophenolate']::text[], NULL, ARRAY['Renal function during IV therapy', 'Hydration status']::text[], NULL, NULL, 'Considered acceptable when clearly indicated.', 'Considered compatible with breastfeeding.', 'Weight-based dosing in children.', 'Reduce dose for age-related renal decline.', 'Dose reduction essential in renal impairment.', 'No routine adjustment.', ARRAY['Well tolerated', 'Long safety record']::text[], ARRAY['Frequent dosing due to short half-life', 'Poor oral bioavailability']::text[], ARRAY['Give plenty of fluids, especially with intravenous therapy']::text[], '"-vir" → antiviral; aciclovir needs viral thymidine kinase to switch on.', '-vir', 'ay-SYE-kloe-veer', 'ए-सा-इ-क्लो-वीर', NULL, 'active', 'under_review', NULL, '1.0', '2026-08-18T17:03:05.494031+00:00', '2026-08-18T17:03:05.494031+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('3e88302b-47aa-4714-9d1d-8d99d7bcb671', 'oseltamivir', 'Oseltamivir', 'Oseltamivir', 'Oseltamivir', 'Oseltamivir phosphate', NULL, 'An oral neuraminidase inhibitor used for influenza.', 'Viral Infections', ARRAY['30 mg', '45 mg', '75 mg']::text[], ARRAY['Capsule', 'Suspension']::text[], ARRAY['Oral']::text[], 'Its active metabolite inhibits influenza neuraminidase, preventing release of new virions from infected cells.', 'Reduces duration of influenza symptoms when started within 48 hours; used for prophylaxis in outbreaks.', 'Well absorbed orally as a prodrug.', 'Distributes to respiratory tissues.', 'Hepatic ester hydrolysis to oseltamivir carboxylate.', 'Renal excretion of the active metabolite.', 'About 75% as active metabolite', '6-10 hours (active metabolite)', 'Low (about 3%)', NULL, NULL, 'Symptom benefit within 1-2 days', '12 hours dosing interval', ARRAY['Influenza A and B treatment', 'Influenza post-exposure prophylaxis']::text[], ARRAY['Known hypersensitivity']::text[], ARRAY['Most effective when started within 48 hours of symptom onset', 'Neuropsychiatric events reported, mainly in children']::text[], NULL, ARRAY['Nausea', 'Vomiting', 'Headache']::text[], ARRAY['Serious skin reactions', 'Neuropsychiatric events']::text[], ARRAY['Live attenuated influenza vaccine', 'Probenecid']::text[], NULL, ARRAY['Symptom course', 'Renal function in impairment']::text[], NULL, NULL, 'Used in pregnancy when influenza risk is significant.', 'Considered compatible with breastfeeding.', 'Weight-based dosing including infants.', 'Adjust for renal function.', 'Reduce dose in renal impairment.', 'No routine adjustment in mild to moderate impairment.', ARRAY['Oral therapy for influenza', 'Useful in high-risk groups']::text[], ARRAY['Narrow treatment window', 'Nausea is common']::text[], ARRAY['Take with food to reduce nausea']::text[], 'Oseltamivir → "neuraminidase blocker: virus cannot leave the cell".', '-mivir', 'oh-sel-TAM-i-veer', 'ओ-सेल्-टै-मि-वीर', NULL, 'active', 'under_review', NULL, '1.0', '2026-08-18T17:03:05.494031+00:00', '2026-08-18T17:03:05.494031+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('9348496a-b555-45a6-b4f9-06c1634128ee', 'famotidine', 'Famotidine', 'Famotidine', 'Famotidine', 'Famotidine', NULL, 'An H2 receptor blocker that reduces gastric acid secretion.', 'Acidity & GERD', ARRAY['20 mg', '40 mg', '20 mg/2 mL injection']::text[], ARRAY['Tablet', 'Injection']::text[], ARRAY['Oral', 'Intravenous']::text[], 'Competitively blocks histamine H2 receptors on gastric parietal cells, reducing acid secretion.', 'Reduces basal and nocturnal acid output; less potent than proton pump inhibitors.', 'Incompletely absorbed orally.', 'Distributed widely; crosses the placenta.', 'Limited hepatic metabolism.', 'Mainly renal excretion of unchanged drug.', 'About 40-45%', '2.5-3.5 hours', 'Around 15-20%', NULL, NULL, 'Within 1 hour', '10-12 hours', ARRAY['Gastro-oesophageal reflux disease', 'Peptic ulcer', 'Dyspepsia', 'Stress ulcer prophylaxis']::text[], ARRAY['Known hypersensitivity to H2 blockers']::text[], ARRAY['May mask symptoms of gastric malignancy', 'Confusion possible in elderly patients with renal impairment']::text[], NULL, ARRAY['Headache', 'Constipation', 'Diarrhoea', 'Dizziness']::text[], ARRAY['Thrombocytopenia (rare)', 'Confusion in renal impairment']::text[], ARRAY['Atazanavir', 'Ketoconazole and itraconazole', 'Dasatinib']::text[], NULL, ARRAY['Symptom relief', 'Renal function in the elderly']::text[], NULL, NULL, 'Considered one of the safer acid-suppressing options in pregnancy.', 'Considered compatible with breastfeeding.', 'Weight-based dosing in children.', 'Reduce dose if renal function is reduced.', 'Halve the dose in significant renal impairment.', 'No routine adjustment.', ARRAY['Rapid onset for on-demand relief', 'Fewer interactions than cimetidine']::text[], ARRAY['Less potent than PPIs', 'Tolerance can develop with regular use']::text[], ARRAY['Useful at night when PPIs alone do not control nocturnal acid']::text[], '"-tidine" → H2 blocker.', '-tidine', 'fa-MOE-ti-deen', 'फ़ै-मो-टि-डीन', NULL, 'active', 'under_review', NULL, '1.0', '2026-08-18T17:03:05.494031+00:00', '2026-08-18T17:03:05.494031+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('049bde27-5ea1-4ff9-a4ac-7632af8ee5f0', 'rabeprazole', 'Rabeprazole', 'Rabeprazole', 'Rabeprazole', 'Rabeprazole sodium', NULL, 'A proton pump inhibitor with rapid onset used in acid-related disorders.', 'Acidity & GERD', ARRAY['10 mg', '20 mg']::text[], ARRAY['Enteric-coated tablet', 'Capsule (with domperidone in combinations)']::text[], ARRAY['Oral']::text[], 'Irreversibly inhibits the gastric H+/K+-ATPase proton pump in parietal cells.', 'Profound and prolonged suppression of gastric acid secretion.', 'Enteric coated to survive gastric acid; absorbed in the small intestine.', 'Highly protein bound.', 'Hepatic metabolism, largely non-enzymatic with some CYP2C19 and CYP3A4 involvement.', 'Mainly renal excretion of metabolites.', 'About 52%', 'About 1-2 hours (effect far outlasts plasma levels)', 'Around 96%', NULL, NULL, 'Acid suppression within hours', 'Up to 24 hours', ARRAY['Gastro-oesophageal reflux disease', 'Peptic ulcer', 'Helicobacter pylori eradication', 'Zollinger-Ellison syndrome']::text[], ARRAY['Known hypersensitivity to substituted benzimidazoles', 'Concurrent rilpivirine']::text[], ARRAY['Long-term use is associated with hypomagnesaemia, B12 deficiency and fracture risk', 'May mask gastric cancer symptoms']::text[], NULL, ARRAY['Headache', 'Diarrhoea', 'Abdominal pain', 'Flatulence']::text[], ARRAY['Clostridioides difficile infection', 'Hypomagnesaemia', 'Acute interstitial nephritis']::text[], ARRAY['Clopidogrel (less than omeprazole)', 'Ketoconazole and itraconazole', 'Methotrexate', 'Digoxin']::text[], NULL, ARRAY['Magnesium on long-term therapy', 'Symptom control and need for continued therapy']::text[], NULL, NULL, 'Use only if clearly needed.', 'Limited data; seek medical advice.', 'Used in children under specialist advice.', 'Review the need for long-term therapy.', 'No routine adjustment.', 'Reduce dose in severe hepatic impairment.', ARRAY['Less CYP2C19 dependence than omeprazole', 'Rapid acid control']::text[], ARRAY['Long-term risks with indefinite use']::text[], ARRAY['Take 30-60 minutes before the first meal of the day']::text[], '"-prazole" → proton pump inhibitor; take before food.', '-prazole', 'ra-BEP-ra-zole', 'रै-बे-प्रा-ज़ोल', NULL, 'active', 'under_review', NULL, '1.0', '2026-08-18T17:03:05.494031+00:00', '2026-08-18T17:03:05.494031+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('d3f3984a-8772-4987-adce-df4c7623d363', 'domperidone', 'Domperidone', 'Domperidone', 'Domperidone', 'Domperidone maleate', NULL, 'A prokinetic antiemetic that does not readily cross the blood-brain barrier.', 'Vomiting & Nausea', ARRAY['10 mg', '1 mg/mL suspension']::text[], ARRAY['Tablet', 'Suspension']::text[], ARRAY['Oral']::text[], 'Blocks dopamine D2 receptors in the gut and in the chemoreceptor trigger zone, which lies outside the blood-brain barrier.', 'Increases gastric emptying and lower oesophageal tone with a low risk of extrapyramidal effects.', 'Rapidly absorbed but with extensive first-pass metabolism.', 'Poor penetration into the central nervous system.', 'Extensive hepatic metabolism via CYP3A4.', 'Faecal and renal excretion of metabolites.', 'About 15% orally', 'About 7-9 hours', 'Around 91-93%', NULL, NULL, 'Within 30-60 minutes', 'About 8 hours', ARRAY['Nausea and vomiting', 'Gastroparesis', 'Bloating and early satiety']::text[], ARRAY['Prolactinoma', 'Significant QT prolongation', 'GI haemorrhage or obstruction', 'Moderate to severe hepatic impairment']::text[], ARRAY['Use the lowest effective dose for up to one week where possible', 'QT prolongation and sudden cardiac death risk at higher doses']::text[], NULL, ARRAY['Dry mouth', 'Headache', 'Galactorrhoea']::text[], ARRAY['QT prolongation and serious arrhythmia', 'Hyperprolactinaemia']::text[], ARRAY['CYP3A4 inhibitors such as ketoconazole and clarithromycin', 'QT-prolonging drugs']::text[], NULL, ARRAY['ECG when risk factors are present', 'Duration of therapy']::text[], NULL, NULL, 'Avoid unless clearly necessary.', 'Small amounts pass into milk; medical advice needed.', 'Restricted in children; specialist decision.', 'Higher cardiac risk; keep doses low and courses short.', 'Reduce frequency in renal impairment.', 'Avoid in moderate to severe hepatic impairment.', ARRAY['Prokinetic without significant extrapyramidal effects']::text[], ARRAY['QT prolongation limits dose and duration']::text[], ARRAY['Prefer short courses at the lowest effective dose']::text[], 'Domperidone stays outside the brain — gut relief without dystonia.', '—', 'dom-PER-i-done', 'डॉम्-पे-रि-डोन', NULL, 'active', 'under_review', NULL, '1.0', '2026-08-18T17:03:05.494031+00:00', '2026-08-18T17:03:05.494031+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('7564376d-d6ad-4e54-8e0c-fce5cde539dd', 'metoclopramide', 'Metoclopramide', 'Metoclopramide', 'Metoclopramide', 'Metoclopramide hydrochloride', NULL, 'A dopamine antagonist antiemetic and prokinetic.', 'Vomiting & Nausea', ARRAY['10 mg', '5 mg/mL injection']::text[], ARRAY['Tablet', 'Injection', 'Syrup']::text[], ARRAY['Oral', 'Intravenous', 'Intramuscular']::text[], 'Blocks central and peripheral dopamine D2 receptors and, at higher doses, 5-HT3 receptors; also has 5-HT4 agonist prokinetic activity.', 'Antiemetic and prokinetic; crosses the blood-brain barrier so extrapyramidal effects can occur.', 'Rapidly absorbed orally.', 'Widely distributed including the CNS.', 'Hepatic metabolism.', 'Mainly renal excretion.', 'About 80% orally', '5-6 hours', 'Around 30%', NULL, NULL, 'Within 30-60 minutes orally, 1-3 minutes IV', '1-2 hours per dose', ARRAY['Nausea and vomiting', 'Migraine-associated nausea', 'Gastroparesis', 'Aid to intubation of the small bowel']::text[], ARRAY['GI obstruction, perforation or haemorrhage', 'Phaeochromocytoma', 'Epilepsy', 'Parkinson disease']::text[], ARRAY['Restrict to a maximum of 5 days where possible', 'Acute dystonic reactions are more common in young women and children', 'Tardive dyskinesia with prolonged use']::text[], NULL, ARRAY['Drowsiness', 'Restlessness', 'Diarrhoea']::text[], ARRAY['Acute dystonia', 'Tardive dyskinesia', 'Neuroleptic malignant syndrome']::text[], ARRAY['Antipsychotics', 'Levodopa', 'Opioids', 'Digoxin']::text[], NULL, ARRAY['Movement disorders', 'Duration of therapy']::text[], NULL, NULL, 'Used when benefit outweighs risk; commonly used for hyperemesis under supervision.', 'Small amounts in milk; short-term use usually acceptable.', 'Restricted; higher risk of dystonia in children.', 'Higher risk of tardive dyskinesia.', 'Reduce dose in renal impairment.', 'Reduce dose in hepatic impairment.', ARRAY['Effective antiemetic with prokinetic action', 'Available orally and by injection']::text[], ARRAY['Extrapyramidal reactions', 'Duration limits']::text[], ARRAY['Treat acute dystonia promptly with an anticholinergic such as promethazine or benztropine']::text[], 'Metoclopramide crosses into the brain — dystonia is the price.', '—', 'met-oh-kloe-PRA-mide', 'मे-टो-क्लो-प्रा-माइड', NULL, 'active', 'under_review', NULL, '1.0', '2026-08-18T17:03:05.494031+00:00', '2026-08-18T17:03:05.494031+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('c8733feb-3f01-4509-86d4-ba2c6f197fc3', 'loperamide', 'Loperamide', 'Loperamide', 'Loperamide', 'Loperamide hydrochloride', NULL, 'An antimotility agent for symptomatic control of non-infective diarrhoea.', 'Diarrhoea', ARRAY['2 mg']::text[], ARRAY['Capsule', 'Tablet']::text[], ARRAY['Oral']::text[], 'Agonist at peripheral mu-opioid receptors in the intestinal wall, slowing transit and increasing water absorption.', 'Antidiarrhoeal without central opioid effects at normal doses because of P-glycoprotein efflux at the blood-brain barrier.', 'Poorly absorbed systemically.', 'Acts locally in the gut; minimal CNS penetration at therapeutic doses.', 'Extensive first-pass hepatic metabolism via CYP3A4 and CYP2C8.', 'Mainly faecal excretion.', 'Low systemic bioavailability (about 0.3%)', 'About 9-14 hours', 'Around 95%', NULL, NULL, 'Within 1-3 hours', 'Symptomatic control while dosing continues', ARRAY['Acute non-infective diarrhoea', 'Chronic diarrhoea in inflammatory bowel disease under supervision', 'High-output stoma']::text[], ARRAY['Bloody diarrhoea with fever', 'Suspected dysentery or C. difficile colitis', 'Children under 4 years', 'Acute ulcerative colitis flare']::text[], ARRAY['Do not use in dysentery', 'High doses cause serious cardiac arrhythmias', 'Oral rehydration remains the priority in acute diarrhoea']::text[], NULL, ARRAY['Constipation', 'Abdominal cramps', 'Nausea', 'Dizziness']::text[], ARRAY['Paralytic ileus', 'Toxic megacolon', 'QT prolongation and cardiac arrest in overdose']::text[], ARRAY['CYP3A4 inhibitors', 'Quinidine', 'P-glycoprotein inhibitors']::text[], NULL, ARRAY['Stool frequency', 'Hydration status', 'Abdominal distension']::text[], NULL, NULL, 'Avoid in the first trimester unless essential.', 'Small amounts in milk; short-term use usually acceptable.', 'Not for children under 4 years.', 'Watch for constipation and ileus.', 'No routine adjustment.', 'Caution in hepatic impairment.', ARRAY['Rapid symptom control', 'Available over the counter']::text[], ARRAY['Dangerous in invasive diarrhoea', 'Cardiotoxic in overdose']::text[], ARRAY['Fluid and electrolyte replacement matters more than stopping the stools']::text[], 'Loperamide = "lock the pipe" — never in bloody diarrhoea.', '—', 'loe-PER-a-mide', 'लो-पे-रा-माइड', NULL, 'active', 'under_review', NULL, '1.0', '2026-08-18T17:03:05.494031+00:00', '2026-08-18T17:03:05.494031+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('85c7e34c-5c16-4523-a67c-1f5ee1d37a3c', 'lactulose', 'Lactulose', 'Lactulose', 'Lactulose', 'Lactulose', NULL, 'An osmotic laxative also used in hepatic encephalopathy.', 'Constipation', ARRAY['10 g/15 mL solution']::text[], ARRAY['Oral solution']::text[], ARRAY['Oral', 'Rectal']::text[], 'A non-absorbed disaccharide fermented by colonic bacteria into organic acids that draw water into the bowel and acidify colonic contents.', 'Softens stool and increases frequency; traps ammonia as ammonium in hepatic encephalopathy.', 'Not absorbed from the gut.', 'Remains within the intestinal lumen.', 'Metabolised by colonic bacteria to lactic and acetic acid.', 'Excreted in faeces.', 'Negligible systemic absorption', 'Not applicable (acts locally)', 'Not applicable', NULL, NULL, '24-48 hours for constipation', 'Continues while dosing is maintained', ARRAY['Constipation', 'Hepatic encephalopathy']::text[], ARRAY['Galactosaemia', 'Intestinal obstruction']::text[], ARRAY['Flatulence and cramps are common in the first days', 'Titrate to 2-3 soft stools daily in hepatic encephalopathy']::text[], NULL, ARRAY['Flatulence', 'Abdominal cramps', 'Nausea']::text[], ARRAY['Electrolyte disturbance with excessive dosing', 'Dehydration']::text[], ARRAY['Other laxatives', 'Antacids (reduced colonic acidification)']::text[], NULL, ARRAY['Stool frequency and consistency', 'Electrolytes with high-dose therapy']::text[], NULL, NULL, 'Considered safe in pregnancy.', 'Considered safe during breastfeeding.', 'Used in children with weight-based dosing.', 'Useful and generally well tolerated.', 'No routine adjustment.', 'Used therapeutically in liver disease.', ARRAY['Safe in pregnancy', 'Dual role in liver disease']::text[], ARRAY['Slow onset', 'Bloating and sweet taste']::text[], ARRAY['In hepatic encephalopathy the dose is titrated to stool frequency, not to a fixed number']::text[], 'Lactulose = "sugar the gut bacteria eat" — acid traps ammonia.', '—', 'LAK-tyoo-lose', 'लैक्-टु-लोज़', NULL, 'active', 'under_review', NULL, '1.0', '2026-08-18T17:03:05.494031+00:00', '2026-08-18T17:03:05.494031+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('6383bbd4-6442-4ea3-82af-9911f3c5983f', 'sucralfate', 'Sucralfate', 'Sucralfate', 'Sucralfate', 'Sucralfate (aluminium sucrose sulphate)', NULL, 'A mucosal protectant that coats ulcer bases.', 'Acidity & GERD', ARRAY['1 g', '1 g/10 mL suspension']::text[], ARRAY['Tablet', 'Suspension']::text[], ARRAY['Oral']::text[], 'In acidic conditions it polymerises and binds to proteins at the ulcer base, forming a protective barrier; also stimulates prostaglandin and mucus production.', 'Local cytoprotection without significant acid suppression.', 'Minimal systemic absorption.', 'Acts locally on the gastric and duodenal mucosa.', 'Not appreciably metabolised.', 'Excreted mainly in faeces; small amounts of aluminium absorbed.', 'Minimal (under 5%)', 'Not clinically relevant (local action)', 'Not applicable', NULL, NULL, 'Within 1-2 hours of dosing', 'About 6 hours of mucosal coating', ARRAY['Peptic ulcer', 'Stress ulcer prophylaxis', 'Oral and oesophageal mucositis (off-label rinse)']::text[], ARRAY['Severe renal impairment (aluminium accumulation)']::text[], ARRAY['Take on an empty stomach, 1 hour before meals', 'Separate from other medicines by at least 2 hours']::text[], NULL, ARRAY['Constipation', 'Dry mouth', 'Nausea']::text[], ARRAY['Aluminium toxicity in renal failure', 'Bezoar formation (rare)']::text[], ARRAY['Fluoroquinolones', 'Levothyroxine', 'Phenytoin', 'Digoxin']::text[], NULL, ARRAY['Symptom relief', 'Serum aluminium in dialysis patients']::text[], NULL, NULL, 'Considered low risk; minimal absorption.', 'Considered compatible with breastfeeding.', 'Used in children under medical advice.', 'Watch for constipation.', 'Avoid in severe renal impairment.', 'No routine adjustment.', ARRAY['Acts locally with minimal systemic effect']::text[], ARRAY['Frequent dosing', 'Binds many other drugs']::text[], ARRAY['Space all other oral medicines away from sucralfate']::text[], 'Sucralfate = a bandage for the ulcer, needs acid to stick.', '—', 'soo-KRAL-fate', 'सु-क्रैल्-फ़ेट', NULL, 'active', 'under_review', NULL, '1.0', '2026-08-18T17:03:05.494031+00:00', '2026-08-18T17:03:05.494031+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('22e2de13-c1a2-4fbd-8f3b-935352f32417', 'levocetirizine', 'Levocetirizine', 'Levocetirizine', 'Levocetirizine', 'Levocetirizine dihydrochloride', NULL, 'The active enantiomer of cetirizine, a second-generation antihistamine.', 'Allergy', ARRAY['5 mg', '2.5 mg/5 mL syrup']::text[], ARRAY['Tablet', 'Syrup']::text[], ARRAY['Oral']::text[], 'Selective peripheral histamine H1 receptor inverse agonist.', 'Relieves allergic symptoms with less sedation than first-generation agents, though some drowsiness occurs.', 'Rapid and near-complete oral absorption.', 'Limited CNS penetration; small volume of distribution.', 'Minimal metabolism.', 'Mainly renal excretion of unchanged drug.', 'Approximately 100%', 'About 8-9 hours', 'Around 90%', NULL, NULL, 'Within 1 hour', '24 hours', ARRAY['Allergic rhinitis', 'Chronic urticaria', 'Allergic conjunctivitis']::text[], ARRAY['End-stage renal disease', 'Known hypersensitivity to cetirizine or hydroxyzine']::text[], ARRAY['Can still cause drowsiness — caution when driving', 'Avoid alcohol']::text[], NULL, ARRAY['Drowsiness', 'Dry mouth', 'Fatigue', 'Headache']::text[], ARRAY['Angioedema (rare)', 'Hypersensitivity reactions']::text[], ARRAY['Alcohol', 'CNS depressants', 'Ritonavir']::text[], NULL, ARRAY['Symptom relief', 'Daytime sedation']::text[], NULL, NULL, 'Use only when clearly needed.', 'Small amounts in milk; medical advice needed.', 'Approved for children with age-based dosing.', 'Reduce dose if renal function is reduced.', 'Reduce dose or interval in renal impairment.', 'No routine adjustment unless renal function is also impaired.', ARRAY['Once-daily dosing', 'Effective in chronic urticaria']::text[], ARRAY['More sedating than fexofenadine or loratadine']::text[], ARRAY['Chronic urticaria may need higher specialist-directed doses']::text[], 'Levocetirizine = the "left-handed" half of cetirizine.', '-zine', 'lee-voe-se-TEER-i-zeen', 'ले-वो-से-टि-रि-ज़ीन', NULL, 'active', 'under_review', NULL, '1.0', '2026-08-18T17:03:05.494031+00:00', '2026-08-18T17:03:05.494031+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('3754597c-21fe-426f-be37-b8b8f876b1fc', 'fexofenadine', 'Fexofenadine', 'Fexofenadine', 'Fexofenadine', 'Fexofenadine hydrochloride', NULL, 'A non-sedating second-generation antihistamine.', 'Allergy', ARRAY['30 mg', '120 mg', '180 mg']::text[], ARRAY['Tablet', 'Suspension']::text[], ARRAY['Oral']::text[], 'Selective peripheral H1 receptor antagonist that does not readily cross the blood-brain barrier.', 'Relieves allergic symptoms with essentially no sedation at usual doses.', 'Rapidly absorbed; fruit juices markedly reduce absorption.', 'Poor CNS penetration; P-glycoprotein substrate.', 'Minimal metabolism (about 5%).', 'Mainly faecal excretion with some renal excretion.', 'About 30%', 'About 14 hours', 'Around 60-70%', NULL, NULL, 'Within 1-2 hours', '24 hours', ARRAY['Allergic rhinitis', 'Chronic idiopathic urticaria']::text[], ARRAY['Known hypersensitivity']::text[], ARRAY['Avoid taking with grapefruit, orange or apple juice', 'Separate from aluminium and magnesium antacids by 2 hours']::text[], NULL, ARRAY['Headache', 'Nausea', 'Drowsiness (uncommon)']::text[], ARRAY['Hypersensitivity reactions (rare)']::text[], ARRAY['Fruit juices', 'Aluminium and magnesium antacids', 'Erythromycin and ketoconazole (raised levels)']::text[], NULL, ARRAY['Symptom relief']::text[], NULL, NULL, 'Use only when clearly needed.', 'Limited data; medical advice needed.', 'Approved for children with age-based dosing.', 'Well tolerated; adjust for renal function.', 'Reduce dose in renal impairment.', 'No routine adjustment.', ARRAY['Least sedating of the common antihistamines', 'Suitable for drivers and students']::text[], ARRAY['Absorption reduced by fruit juice and antacids']::text[], ARRAY['Take with water, not with fruit juice']::text[], 'Fexofenadine = "fewer effects on the brain".', '—', 'fex-oh-FEN-a-deen', 'फ़ेक्-सो-फ़े-ना-डीन', NULL, 'active', 'under_review', NULL, '1.0', '2026-08-18T17:03:05.494031+00:00', '2026-08-18T17:03:05.494031+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('c8221e81-57c2-4435-9b53-a9526df59053', 'chlorpheniramine', 'Chlorpheniramine', 'Chlorpheniramine maleate', 'Chlorpheniramine', 'Chlorpheniramine maleate', NULL, 'A first-generation sedating antihistamine widely used in cold and allergy preparations.', 'Allergy', ARRAY['4 mg', '2 mg/5 mL syrup', '10 mg/mL injection']::text[], ARRAY['Tablet', 'Syrup', 'Injection']::text[], ARRAY['Oral', 'Intramuscular', 'Intravenous']::text[], 'Competitive H1 receptor antagonist with additional antimuscarinic activity; crosses the blood-brain barrier.', 'Relieves allergic symptoms and causes sedation and drying of secretions.', 'Well absorbed orally.', 'Crosses the blood-brain barrier and the placenta.', 'Extensive hepatic metabolism.', 'Renal excretion of metabolites.', 'About 25-45% (first-pass metabolism)', '14-24 hours', 'Around 70%', NULL, NULL, 'Within 30 minutes', '4-6 hours per dose', ARRAY['Allergic rhinitis', 'Urticaria', 'Adjunct in anaphylaxis after adrenaline', 'Common cold symptom relief']::text[], ARRAY['Narrow-angle glaucoma', 'Bladder outflow obstruction', 'Neonates and premature infants', 'Concurrent MAO inhibitors']::text[], ARRAY['Marked sedation — avoid driving or operating machinery', 'Anticholinergic effects are troublesome in the elderly']::text[], NULL, ARRAY['Drowsiness', 'Dry mouth', 'Blurred vision', 'Urinary retention']::text[], ARRAY['Confusion and falls in the elderly', 'Convulsions in overdose in children']::text[], ARRAY['Alcohol', 'Benzodiazepines and opioids', 'MAO inhibitors', 'Tricyclic antidepressants']::text[], NULL, ARRAY['Sedation', 'Anticholinergic effects in the elderly']::text[], NULL, NULL, 'Used when needed; discuss with a clinician.', 'Can cause infant drowsiness; seek medical advice.', 'Avoid in infants; caution in young children.', 'Avoid where possible — falls and confusion risk.', 'No routine adjustment.', 'Caution in hepatic impairment.', ARRAY['Rapid relief', 'Very inexpensive', 'Injectable form available']::text[], ARRAY['Sedation and anticholinergic burden']::text[], ARRAY['Adrenaline, not an antihistamine, is the first-line treatment for anaphylaxis']::text[], 'First-generation antihistamines = "sleepy and dry".', '—', 'klor-fen-EER-a-meen', 'क्लोर्-फ़े-नि-रा-मीन', NULL, 'active', 'under_review', NULL, '1.0', '2026-08-18T17:03:05.494031+00:00', '2026-08-18T17:03:05.494031+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('1912866c-a9f4-4d3c-8cd6-67a85c205927', 'montelukast', 'Montelukast', 'Montelukast', 'Montelukast', 'Montelukast sodium', NULL, 'An oral leukotriene receptor antagonist used as add-on asthma therapy.', 'Asthma & COPD', ARRAY['4 mg', '5 mg', '10 mg']::text[], ARRAY['Tablet', 'Chewable tablet', 'Granules']::text[], ARRAY['Oral']::text[], 'Selectively blocks the cysteinyl leukotriene CysLT1 receptor, reducing bronchoconstriction, mucus secretion and eosinophilic inflammation.', 'Modest bronchodilation and anti-inflammatory effect; useful in exercise-induced and allergic asthma.', 'Rapidly absorbed orally.', 'Highly protein bound.', 'Extensive hepatic metabolism via CYP2C8, CYP3A4 and CYP2C9.', 'Almost entirely biliary excretion.', 'About 64%', '2.7-5.5 hours', 'Over 99%', NULL, NULL, 'Within 3-4 hours', '24 hours', ARRAY['Asthma maintenance (add-on)', 'Exercise-induced bronchoconstriction', 'Allergic rhinitis']::text[], ARRAY['Known hypersensitivity']::text[], ARRAY['Neuropsychiatric events including mood change, nightmares and suicidal thinking have been reported', 'Not for acute asthma attacks']::text[], NULL, ARRAY['Headache', 'Abdominal pain', 'Sleep disturbance']::text[], ARRAY['Neuropsychiatric reactions', 'Eosinophilic granulomatosis with polyangiitis (rare)']::text[], ARRAY['Phenobarbital', 'Rifampicin', 'Gemfibrozil']::text[], NULL, ARRAY['Mood and behaviour', 'Asthma control and reliever use']::text[], NULL, NULL, 'Considered acceptable when needed for asthma control.', 'Considered compatible with breastfeeding.', 'Approved from 6 months with age-based dosing.', 'No specific adjustment.', 'No routine adjustment.', 'Caution in moderate to severe hepatic impairment.', ARRAY['Oral once-daily controller', 'Useful when inhaler technique is poor']::text[], ARRAY['Less effective than inhaled corticosteroids', 'Neuropsychiatric warnings']::text[], ARRAY['Take in the evening; stop and seek advice if mood or sleep changes']::text[], '"-lukast" → leukotriene blocker.', '-lukast', 'mon-te-LOO-kast', 'मॉन्-टे-लू-कास्ट', NULL, 'active', 'under_review', NULL, '1.0', '2026-08-18T17:03:05.494031+00:00', '2026-08-18T17:03:05.494031+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('a2a1c21c-4fca-4777-a316-072ff9e08b80', 'budesonide', 'Budesonide', 'Budesonide', 'Budesonide', 'Budesonide', NULL, 'An inhaled corticosteroid used as controller therapy in asthma.', 'Asthma & COPD', ARRAY['100 mcg', '200 mcg', '400 mcg', '0.5 mg/2 mL respule']::text[], ARRAY['Inhaler', 'Rotacaps', 'Nebuliser suspension']::text[], ARRAY['Inhalation', 'Nebulisation']::text[], 'Binds glucocorticoid receptors in airway cells, suppressing transcription of inflammatory mediators.', 'Reduces airway inflammation, hyper-responsiveness and exacerbation rate over days to weeks.', 'Deposited in the airway; a swallowed fraction is absorbed from the gut.', 'Distributes to airway tissue; high first-pass metabolism limits systemic exposure.', 'Extensive first-pass hepatic metabolism via CYP3A4.', 'Renal and faecal excretion of metabolites.', 'About 10-15% of an inhaled dose reaches the systemic circulation', '2-3 hours', 'Around 85-90%', NULL, NULL, 'Days for full clinical effect', '12-24 hours dosing interval', ARRAY['Asthma maintenance therapy', 'Croup (nebulised)', 'COPD in combination therapy']::text[], ARRAY['Known hypersensitivity', 'Untreated respiratory infection (caution)']::text[], ARRAY['Not a reliever — it does not relieve an acute attack', 'Rinse the mouth after each dose to prevent oral thrush']::text[], NULL, ARRAY['Oral candidiasis', 'Hoarseness', 'Throat irritation', 'Cough']::text[], ARRAY['Adrenal suppression with high doses', 'Reduced growth velocity in children with high doses']::text[], ARRAY['Strong CYP3A4 inhibitors such as ketoconazole and ritonavir']::text[], NULL, ARRAY['Asthma control', 'Growth in children', 'Oral hygiene']::text[], NULL, NULL, 'Inhaled corticosteroids are generally continued in pregnancy.', 'Considered compatible with breastfeeding.', 'Used in children with age-appropriate devices and spacers.', 'Effective; watch for local side effects.', 'No routine adjustment.', 'Systemic exposure rises in severe hepatic impairment.', ARRAY['Cornerstone controller therapy', 'Low systemic exposure']::text[], ARRAY['Local thrush and dysphonia', 'Requires correct inhaler technique']::text[], ARRAY['Use a spacer and rinse the mouth to reduce candidiasis']::text[], 'Inhaled steroid = "prevent, not rescue" — rinse after use.', '—', 'byoo-DES-oh-nide', 'ब्यू-डे-सो-नाइड', NULL, 'active', 'under_review', NULL, '1.0', '2026-08-18T17:03:05.494031+00:00', '2026-08-18T17:03:05.494031+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('37c140cb-4123-4545-9442-86b59870e4b5', 'ipratropium', 'Ipratropium bromide', 'Ipratropium bromide', 'Ipratropium bromide', 'Ipratropium bromide', NULL, 'A short-acting inhaled anticholinergic bronchodilator.', 'Asthma & COPD', ARRAY['20 mcg/actuation', '250 mcg/mL respule', '500 mcg/2 mL respule']::text[], ARRAY['Inhaler', 'Nebuliser solution']::text[], ARRAY['Inhalation', 'Nebulisation']::text[], 'Blocks muscarinic M3 receptors on airway smooth muscle, reducing vagally mediated bronchoconstriction and mucus secretion.', 'Bronchodilation with slower onset but longer duration than salbutamol; minimal systemic absorption.', 'Poorly absorbed from the airway and gut.', 'Acts locally in the airways; quaternary structure limits systemic distribution.', 'Partial hepatic metabolism of absorbed drug.', 'Faecal and renal excretion.', 'Low systemic bioavailability', 'About 1.6 hours', 'Low (0-9%)', NULL, NULL, '15-30 minutes', '4-6 hours', ARRAY['COPD maintenance and exacerbations', 'Acute severe asthma (with salbutamol)', 'Rhinorrhoea (nasal spray)']::text[], ARRAY['Known hypersensitivity to atropine derivatives']::text[], ARRAY['Avoid contact with the eyes — nebulised drug can precipitate acute glaucoma', 'Caution in bladder outflow obstruction']::text[], NULL, ARRAY['Dry mouth', 'Cough', 'Bitter taste', 'Headache']::text[], ARRAY['Paradoxical bronchospasm', 'Acute angle-closure glaucoma with eye exposure']::text[], ARRAY['Other anticholinergics', 'Tiotropium (avoid duplication)']::text[], NULL, ARRAY['Symptom relief', 'Eye symptoms during nebulisation']::text[], NULL, NULL, 'Considered acceptable when needed.', 'Considered compatible with breastfeeding.', 'Used in children with weight and age-based dosing.', 'Useful in COPD; watch anticholinergic effects.', 'No routine adjustment.', 'No routine adjustment.', ARRAY['Adds benefit to salbutamol in acute severe asthma and COPD']::text[], ARRAY['Slower onset than beta-2 agonists', 'Dry mouth']::text[], ARRAY['Use a well-fitting mask or mouthpiece to keep the drug out of the eyes']::text[], 'Ipratropium = "atropine for the airways".', '—', 'ip-ra-TROE-pee-um', 'इप्-रा-ट्रो-पि-अम', NULL, 'active', 'under_review', NULL, '1.0', '2026-08-18T17:03:05.494031+00:00', '2026-08-18T17:03:05.494031+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('2ed12fbc-f7a3-4f19-b499-cc8d46ed90c1', 'dextromethorphan', 'Dextromethorphan', 'Dextromethorphan', 'Dextromethorphan', 'Dextromethorphan hydrobromide', NULL, 'A central cough suppressant used for dry, non-productive cough.', 'Cough & Cold', ARRAY['10 mg/5 mL', '15 mg']::text[], ARRAY['Syrup', 'Lozenge', 'Tablet']::text[], ARRAY['Oral']::text[], 'Acts on the medullary cough centre, raising the threshold for the cough reflex; it is a sigma-1 agonist and NMDA antagonist without opioid analgesic activity.', 'Suppresses dry cough within about 30 minutes; no analgesic or significant dependence liability at therapeutic doses.', 'Rapidly absorbed orally.', 'Widely distributed including the CNS.', 'Hepatic metabolism via CYP2D6 to dextrorphan; poor metabolisers have higher levels.', 'Renal excretion of metabolites.', 'Variable, CYP2D6 dependent', '2-4 hours (longer in poor metabolisers)', 'Moderate', NULL, NULL, 'Within 15-30 minutes', '3-6 hours', ARRAY['Dry irritating cough']::text[], ARRAY['Children under 4 years', 'Concurrent or recent MAO inhibitor use', 'Productive cough needing expectoration']::text[], ARRAY['Abuse potential at high doses', 'Serotonin syndrome risk with SSRIs', 'Do not use for cough with copious sputum']::text[], NULL, ARRAY['Drowsiness', 'Dizziness', 'Nausea']::text[], ARRAY['Serotonin syndrome', 'Hallucinations and dissociation in overdose']::text[], ARRAY['SSRIs and SNRIs', 'MAO inhibitors', 'CYP2D6 inhibitors such as fluoxetine and quinidine']::text[], NULL, ARRAY['Cough pattern', 'Excessive sedation']::text[], NULL, NULL, 'Use only if clearly needed.', 'Short-term use usually considered acceptable; seek advice.', 'Not for children under 4 years.', 'Watch for confusion and sedation.', 'Caution in renal impairment.', 'Caution in hepatic impairment.', ARRAY['Non-opioid cough suppression', 'Widely available']::text[], ARRAY['Limited evidence of benefit', 'Misuse potential']::text[], ARRAY['Never suppress a wet, productive cough']::text[], 'Dextromethorphan = "DM" on cough syrup labels — dry cough only.', '—', 'dex-troe-meth-OR-fan', 'डेक्-स्ट्रो-मे-थॉर्-फ़न', NULL, 'active', 'under_review', NULL, '1.0', '2026-08-19T05:55:43.559291+00:00', '2026-08-19T05:55:43.559291+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('04999c0c-3b86-4c2d-9c5a-596e01d65096', 'gliclazide', 'Gliclazide', 'Gliclazide', 'Gliclazide', 'Gliclazide', NULL, 'A second-generation sulfonylurea used in type 2 diabetes.', 'Diabetes', ARRAY['40 mg', '80 mg', '30 mg MR', '60 mg MR']::text[], ARRAY['Tablet', 'Modified-release tablet']::text[], ARRAY['Oral']::text[], 'Binds the SUR1 subunit of pancreatic beta-cell KATP channels, causing depolarisation, calcium influx and insulin release.', 'Lowers blood glucose by stimulating endogenous insulin secretion; effect depends on residual beta-cell function.', 'Well absorbed orally; the modified-release form gives a smoother profile.', 'Highly protein bound.', 'Extensive hepatic metabolism to inactive metabolites.', 'Mainly renal excretion of metabolites.', 'Well absorbed', '10-12 hours (immediate release)', 'Around 94%', NULL, NULL, 'Within 1-2 hours', '12-24 hours depending on formulation', ARRAY['Type 2 diabetes mellitus']::text[], ARRAY['Type 1 diabetes', 'Diabetic ketoacidosis', 'Severe renal or hepatic impairment', 'Known sulfonylurea hypersensitivity']::text[], ARRAY['Hypoglycaemia risk, especially if meals are skipped or during fasting such as Ramadan', 'Weight gain is common']::text[], NULL, ARRAY['Hypoglycaemia', 'Weight gain', 'Nausea', 'Rash']::text[], ARRAY['Severe prolonged hypoglycaemia', 'Blood dyscrasias (rare)', 'Cholestatic jaundice (rare)']::text[], ARRAY['Beta blockers (mask hypoglycaemia)', 'Fluconazole', 'Sulfonamides', 'Alcohol']::text[], NULL, ARRAY['Blood glucose and HbA1c', 'Weight', 'Hypoglycaemia episodes']::text[], NULL, NULL, 'Usually switched to insulin during pregnancy.', 'Not recommended; risk of infant hypoglycaemia.', 'Not used in children.', 'Prefer the lowest dose; high hypoglycaemia risk.', 'Avoid in severe renal impairment.', 'Avoid in severe hepatic impairment.', ARRAY['Effective and inexpensive', 'Lower hypoglycaemia risk than glibenclamide']::text[], ARRAY['Hypoglycaemia and weight gain', 'Loses effect as beta-cell function declines']::text[], ARRAY['Advise patients on sick-day and fasting rules']::text[], '"-ide" sulfonylureas → squeeze insulin out of the pancreas.', '-zide (sulfonylurea)', 'GLIK-la-zide', 'ग्लि-क्ला-ज़ाइड', NULL, 'active', 'under_review', NULL, '1.0', '2026-08-19T05:55:43.559291+00:00', '2026-08-19T05:55:43.559291+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('06151f46-f8f2-47a0-a2c7-affd85d61cfd', 'sitagliptin', 'Sitagliptin', 'Sitagliptin', 'Sitagliptin', 'Sitagliptin phosphate', NULL, 'A DPP-4 inhibitor that raises incretin levels in type 2 diabetes.', 'Diabetes', ARRAY['25 mg', '50 mg', '100 mg']::text[], ARRAY['Tablet']::text[], ARRAY['Oral']::text[], 'Inhibits dipeptidyl peptidase-4, preventing breakdown of GLP-1 and GIP, which increases glucose-dependent insulin release and lowers glucagon.', 'Modest HbA1c reduction with a low intrinsic risk of hypoglycaemia and a neutral effect on weight.', 'Rapidly absorbed; food has no clinically important effect.', 'Moderate volume of distribution.', 'Minimal metabolism; mostly excreted unchanged.', 'Mainly renal excretion of unchanged drug.', 'About 87%', 'About 12 hours', 'Around 38%', NULL, NULL, 'Within 1-4 hours', '24 hours', ARRAY['Type 2 diabetes mellitus']::text[], ARRAY['Type 1 diabetes', 'Diabetic ketoacidosis', 'Known hypersensitivity']::text[], ARRAY['Rare reports of acute pancreatitis', 'Severe joint pain has been reported', 'Dose reduction needed in renal impairment']::text[], NULL, ARRAY['Nasopharyngitis', 'Headache', 'Upper respiratory infection']::text[], ARRAY['Acute pancreatitis', 'Bullous pemphigoid', 'Severe arthralgia']::text[], ARRAY['Sulfonylureas (added hypoglycaemia risk)', 'Insulin', 'Digoxin (mild)']::text[], NULL, ARRAY['HbA1c', 'Renal function', 'Symptoms of pancreatitis']::text[], NULL, NULL, 'Insulin is preferred in pregnancy.', 'Not recommended.', 'Not established in children.', 'Well tolerated; adjust for renal function.', 'Reduce dose in moderate to severe renal impairment.', 'No routine adjustment in mild to moderate impairment.', ARRAY['Weight neutral', 'Low hypoglycaemia risk when used alone', 'Once daily']::text[], ARRAY['Modest glucose lowering', 'Cost']::text[], ARRAY['Stop and investigate if severe persistent abdominal pain occurs']::text[], '"-gliptin" → DPP-4 inhibitor, incretin helper.', '-gliptin', 'sit-a-GLIP-tin', 'सि-टा-ग्लिप्-टिन', NULL, 'active', 'under_review', NULL, '1.0', '2026-08-19T05:55:43.559291+00:00', '2026-08-19T05:55:43.559291+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('4548342d-fabb-4d70-aceb-d5806059976f', 'dapagliflozin', 'Dapagliflozin', 'Dapagliflozin', 'Dapagliflozin', 'Dapagliflozin propanediol', NULL, 'An SGLT2 inhibitor with benefits in diabetes, heart failure and kidney disease.', 'Diabetes', ARRAY['5 mg', '10 mg']::text[], ARRAY['Tablet']::text[], ARRAY['Oral']::text[], 'Inhibits the sodium-glucose co-transporter 2 in the proximal renal tubule, reducing glucose reabsorption and increasing urinary glucose excretion.', 'Lowers glucose independently of insulin; produces mild diuresis, weight loss and blood pressure reduction with cardiorenal benefit.', 'Rapidly absorbed; food slightly delays absorption.', 'Moderately distributed; highly protein bound.', 'Mainly glucuronidation via UGT1A9.', 'Renal and faecal excretion of metabolites.', 'About 78%', 'About 12.9 hours', 'Around 91%', NULL, NULL, 'Glucose lowering within days', '24 hours', ARRAY['Type 2 diabetes mellitus', 'Heart failure', 'Chronic kidney disease']::text[], ARRAY['Type 1 diabetes (unless specialist supervised)', 'Diabetic ketoacidosis', 'Known hypersensitivity']::text[], ARRAY['Genital mycotic infections are common — advise on hygiene', 'Euglycaemic diabetic ketoacidosis can occur; withhold during acute illness, fasting or surgery', 'Volume depletion risk with diuretics']::text[], NULL, ARRAY['Genital candidiasis', 'Urinary frequency', 'Thirst', 'Urinary tract infection']::text[], ARRAY['Euglycaemic ketoacidosis', 'Fournier gangrene (very rare)', 'Severe volume depletion']::text[], ARRAY['Loop diuretics', 'Insulin and sulfonylureas', 'Antihypertensives']::text[], NULL, ARRAY['Renal function', 'Volume status', 'Ketones during illness']::text[], NULL, NULL, 'Not recommended in pregnancy.', 'Not recommended.', 'Not established in children.', 'Watch for volume depletion and hypotension.', 'Glucose-lowering effect falls with low eGFR, but cardiorenal benefit persists.', 'Caution in severe hepatic impairment.', ARRAY['Cardiovascular and renal outcome benefits', 'Weight and blood pressure reduction']::text[], ARRAY['Genital infections', 'Ketoacidosis risk during illness or fasting']::text[], ARRAY['Sick-day rule: stop temporarily during acute illness, vomiting or fasting']::text[], '"-gliflozin" → flushes glucose out through the kidney.', '-gliflozin', 'dap-a-gli-FLOE-zin', 'डै-पा-ग्लि-फ्लो-ज़िन', NULL, 'active', 'under_review', NULL, '1.0', '2026-08-19T05:55:43.559291+00:00', '2026-08-19T05:55:43.559291+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('521475e2-31f8-465b-8533-caadedb0ffa5', 'pioglitazone', 'Pioglitazone', 'Pioglitazone', 'Pioglitazone', 'Pioglitazone hydrochloride', NULL, 'A thiazolidinedione that improves insulin sensitivity.', 'Diabetes', ARRAY['7.5 mg', '15 mg', '30 mg']::text[], ARRAY['Tablet']::text[], ARRAY['Oral']::text[], 'Activates PPAR-gamma nuclear receptors, altering transcription of genes involved in glucose and lipid metabolism and improving peripheral insulin sensitivity.', 'Durable glycaemic improvement with fluid retention and weight gain; effect develops over weeks.', 'Well absorbed orally.', 'Highly protein bound.', 'Hepatic metabolism via CYP2C8 and CYP3A4 to active metabolites.', 'Mainly biliary and faecal excretion.', 'Over 80%', '3-7 hours (16-24 hours for metabolites)', 'Over 99%', NULL, NULL, 'Weeks for full effect', '24 hours', ARRAY['Type 2 diabetes mellitus, especially with marked insulin resistance']::text[], ARRAY['Heart failure', 'Active bladder cancer or unexplained haematuria', 'Active liver disease', 'Diabetic ketoacidosis']::text[], ARRAY['Fluid retention can precipitate heart failure', 'Increased fracture risk, particularly in women', 'Weight gain is common']::text[], NULL, ARRAY['Weight gain', 'Peripheral oedema', 'Anaemia (dilutional)']::text[], ARRAY['Heart failure', 'Fractures', 'Macular oedema', 'Hepatotoxicity (rare)']::text[], ARRAY['Gemfibrozil (raises levels)', 'Rifampicin (lowers levels)', 'Insulin (oedema risk)']::text[], NULL, ARRAY['Weight and oedema', 'Liver function', 'Signs of heart failure']::text[], NULL, NULL, 'Not recommended in pregnancy.', 'Not recommended.', 'Not established in children.', 'Avoid if there is heart failure or fracture risk.', 'No dose adjustment, but avoid if on dialysis.', 'Avoid in active liver disease.', ARRAY['No hypoglycaemia when used alone', 'Durable HbA1c effect', 'Useful in fatty liver disease']::text[], ARRAY['Oedema, weight gain and heart failure risk', 'Fracture risk']::text[], ARRAY['Ask about breathlessness and ankle swelling at every review']::text[], '"-glitazone" → PPAR-gamma; think oedema and weight gain.', '-glitazone', 'pye-oh-GLI-ta-zone', 'पा-इ-ओ-ग्लि-टा-ज़ोन', NULL, 'active', 'under_review', NULL, '1.0', '2026-08-19T05:55:43.559291+00:00', '2026-08-19T05:55:43.559291+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('1ee6d0ac-594b-404d-8a8b-95de6cd77e2b', 'regular-human-insulin', 'Regular human insulin', 'Regular human insulin (soluble insulin)', 'Human insulin', 'Human insulin (rDNA origin)', NULL, 'Short-acting soluble insulin used in daily regimens and emergencies.', 'Diabetes', ARRAY['40 IU/mL', '100 IU/mL']::text[], ARRAY['Injection', 'Vial', 'Cartridge']::text[], ARRAY['Subcutaneous', 'Intravenous']::text[], 'Binds insulin receptors, promoting cellular glucose uptake, glycogen and protein synthesis, and suppressing hepatic glucose production and lipolysis.', 'Onset about 30 minutes subcutaneously with a peak at 2-3 hours; immediate action when given intravenously.', 'Absorbed from subcutaneous tissue; absorption varies with site and blood flow.', 'Distributed in extracellular fluid.', 'Degraded by insulinase in liver, kidney and muscle.', 'Renal clearance of degradation products.', 'Not applicable (injected)', 'About 1.5 hours in plasma; longer clinical action', 'Low', NULL, NULL, '30 minutes subcutaneously, minutes intravenously', '6-8 hours subcutaneously', ARRAY['Type 1 diabetes', 'Type 2 diabetes when oral therapy is insufficient', 'Diabetic ketoacidosis (IV infusion)', 'Hyperkalaemia (with dextrose)']::text[], ARRAY['Hypoglycaemia', 'Known hypersensitivity to the preparation']::text[], ARRAY['Inject 30 minutes before meals', 'Rotate injection sites to prevent lipohypertrophy', 'Never share pens or needles']::text[], NULL, ARRAY['Hypoglycaemia', 'Weight gain', 'Injection-site reactions', 'Lipohypertrophy']::text[], ARRAY['Severe hypoglycaemia', 'Hypokalaemia', 'Severe allergic reactions (rare)']::text[], ARRAY['Beta blockers (mask hypoglycaemia)', 'Corticosteroids', 'Alcohol', 'Thiazides']::text[], NULL, ARRAY['Capillary blood glucose', 'HbA1c', 'Injection sites', 'Potassium during IV use']::text[], NULL, NULL, 'Insulin is the preferred glucose-lowering therapy in pregnancy.', 'Compatible with breastfeeding; doses often need reduction.', 'Used in children with careful dose titration.', 'Simplify regimens and target less strict control.', 'Insulin requirement falls in renal impairment.', 'Requirement may change in hepatic impairment.', ARRAY['Effective in every form of diabetes', 'Rapid IV action in emergencies']::text[], ARRAY['Hypoglycaemia', 'Injections and monitoring burden', 'Cold-chain storage']::text[], ARRAY['Unopened vials go in the fridge; the in-use vial can stay at room temperature for about 28 days']::text[], 'Regular insulin = the only insulin routinely given intravenously.', '—', 'IN-su-lin', 'इन्-सु-लिन', NULL, 'active', 'under_review', NULL, '1.0', '2026-08-19T05:55:43.559291+00:00', '2026-08-19T05:55:43.559291+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('a4836ff1-8083-493d-a2df-aa4068e8a8b6', 'carbimazole', 'Carbimazole', 'Carbimazole', 'Carbimazole', 'Carbimazole', NULL, 'An antithyroid drug used to control hyperthyroidism.', 'Thyroid', ARRAY['5 mg', '10 mg', '20 mg']::text[], ARRAY['Tablet']::text[], ARRAY['Oral']::text[], 'Converted to methimazole, which inhibits thyroid peroxidase and blocks iodination and coupling of thyroglobulin tyrosine residues.', 'Reduces new thyroid hormone synthesis; clinical effect takes 2-6 weeks because stored hormone must be depleted.', 'Rapidly absorbed orally.', 'Concentrated in the thyroid gland.', 'Converted to the active metabolite methimazole in the liver.', 'Renal excretion of metabolites.', 'Well absorbed', 'About 5-6 hours (methimazole)', 'Low', NULL, NULL, '2-6 weeks for clinical effect', '24 hours dosing interval', ARRAY['Graves disease and other causes of hyperthyroidism', 'Preparation for thyroidectomy or radioiodine']::text[], ARRAY['Previous agranulocytosis or severe reaction to thionamides', 'Severe hepatic impairment']::text[], ARRAY['Report sore throat, mouth ulcers or fever immediately — possible agranulocytosis', 'Congenital malformations reported with first-trimester use']::text[], NULL, ARRAY['Rash', 'Itching', 'Nausea', 'Arthralgia']::text[], ARRAY['Agranulocytosis', 'Hepatitis', 'ANCA-associated vasculitis (rare)']::text[], ARRAY['Warfarin', 'Digoxin', 'Theophylline']::text[], NULL, ARRAY['Thyroid function tests', 'Full blood count if infection symptoms occur', 'Liver function']::text[], NULL, NULL, 'Propylthiouracil is usually preferred in the first trimester.', 'Low doses considered compatible; monitor infant thyroid function.', 'Used in children under specialist care.', 'Monitor closely for marrow and liver effects.', 'No routine adjustment.', 'Caution; avoid in severe impairment.', ARRAY['Effective medical control of hyperthyroidism', 'Once-daily dosing at maintenance']::text[], ARRAY['Slow onset', 'Agranulocytosis risk requires patient education']::text[], ARRAY['Every patient must know the sore throat and fever warning']::text[], 'Carbimazole → "Cuts hormone production; Check the throat".', '—', 'kar-BIM-a-zole', 'कार्-बि-मा-ज़ोल', NULL, 'active', 'under_review', NULL, '1.0', '2026-08-19T05:55:43.559291+00:00', '2026-08-19T05:55:43.559291+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('39a17feb-bfb3-4e15-b42d-be43d037b1f1', 'prednisolone', 'Prednisolone', 'Prednisolone', 'Prednisolone', 'Prednisolone (base or sodium phosphate)', NULL, 'A widely used oral corticosteroid with anti-inflammatory and immunosuppressive effects.', 'Immunity & Autoimmune', ARRAY['5 mg', '10 mg', '20 mg', '40 mg', '15 mg/5 mL']::text[], ARRAY['Tablet', 'Syrup', 'Eye drops']::text[], ARRAY['Oral', 'Ophthalmic']::text[], 'Binds cytoplasmic glucocorticoid receptors, altering transcription of genes controlling inflammation and immune activation.', 'Broad anti-inflammatory and immunosuppressive activity with predominantly glucocorticoid and mild mineralocorticoid effect.', 'Well absorbed orally.', 'Widely distributed; crosses the placenta poorly compared with dexamethasone.', 'Hepatic metabolism.', 'Renal excretion of metabolites.', 'Approximately 70-90%', '2-4 hours (biological effect 12-36 hours)', 'Around 70-90%', NULL, NULL, 'Within hours', '12-36 hours biological effect', ARRAY['Asthma and COPD exacerbations', 'Autoimmune and inflammatory disease', 'Allergic reactions', 'Nephrotic syndrome']::text[], ARRAY['Systemic fungal infection', 'Live vaccines during high-dose therapy', 'Known hypersensitivity']::text[], ARRAY['Do not stop abruptly after more than about 3 weeks of therapy', 'Raises blood glucose and blood pressure', 'Increases infection risk and can mask its signs']::text[], NULL, ARRAY['Increased appetite', 'Insomnia', 'Mood change', 'Raised blood glucose', 'Dyspepsia']::text[], ARRAY['Adrenal suppression', 'Osteoporosis', 'Serious infection', 'Peptic ulcer with NSAIDs', 'Steroid psychosis']::text[], ARRAY['NSAIDs', 'Live vaccines', 'Rifampicin', 'Antidiabetic agents', 'Warfarin']::text[], NULL, ARRAY['Blood pressure', 'Blood glucose', 'Weight', 'Bone health on long-term therapy']::text[], NULL, NULL, 'Used when clearly needed; prednisolone crosses the placenta less than dexamethasone.', 'Considered compatible; take the dose after a feed if possible.', 'Used in children with weight-based dosing; monitor growth.', 'Higher risk of osteoporosis, diabetes and infection.', 'No routine adjustment.', 'Prednisone conversion is impaired in liver failure, so prednisolone is preferred.', ARRAY['Rapid and powerful anti-inflammatory effect', 'Inexpensive']::text[], ARRAY['Wide-ranging adverse effects', 'Needs tapering after prolonged use']::text[], ARRAY['Take in the morning with food to mimic the natural cortisol rhythm']::text[], 'Steroids → "Sugar up, Bones down, Infection hidden".', '-solone', 'pred-NIS-oh-lone', 'प्रेड्-नि-सो-लोन', NULL, 'active', 'under_review', NULL, '1.0', '2026-08-19T05:55:43.559291+00:00', '2026-08-19T05:55:43.559291+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('f6311fcf-2c41-4381-a859-200294f6956a', 'dexamethasone', 'Dexamethasone', 'Dexamethasone', 'Dexamethasone', 'Dexamethasone sodium phosphate', NULL, 'A potent long-acting corticosteroid with negligible mineralocorticoid activity.', 'Immunity & Autoimmune', ARRAY['0.5 mg', '4 mg/mL injection', '8 mg injection']::text[], ARRAY['Tablet', 'Injection', 'Eye drops']::text[], ARRAY['Oral', 'Intravenous', 'Intramuscular', 'Ophthalmic']::text[], 'Binds glucocorticoid receptors, suppressing transcription of pro-inflammatory genes; about 25-30 times more potent than hydrocortisone.', 'Long-acting, potent anti-inflammatory action with minimal sodium retention.', 'Well absorbed orally.', 'Widely distributed; crosses the placenta readily.', 'Hepatic metabolism via CYP3A4.', 'Renal excretion of metabolites.', 'Approximately 80-90%', '3-4.5 hours (biological effect 36-54 hours)', 'Around 70-80%', NULL, NULL, 'Within hours', '36-54 hours biological effect', ARRAY['Cerebral oedema', 'Croup', 'Severe COVID-19 requiring oxygen', 'Antenatal fetal lung maturation', 'Chemotherapy-induced nausea']::text[], ARRAY['Systemic fungal infection', 'Live vaccines during high-dose therapy']::text[], ARRAY['Potent and long acting — small doses go a long way', 'Hyperglycaemia is common', 'Do not stop abruptly after prolonged courses']::text[], NULL, ARRAY['Hyperglycaemia', 'Insomnia', 'Mood change', 'Increased appetite']::text[], ARRAY['Adrenal suppression', 'Serious infection', 'Psychiatric reactions', 'Osteoporosis with prolonged use']::text[], ARRAY['CYP3A4 inducers and inhibitors', 'Antidiabetic drugs', 'NSAIDs', 'Live vaccines']::text[], NULL, ARRAY['Blood glucose', 'Blood pressure', 'Signs of infection']::text[], NULL, NULL, 'Used antenatally for fetal lung maturity; crosses the placenta readily.', 'Considered compatible for short courses.', 'Used in croup as a single oral dose.', 'Monitor glucose and infection risk closely.', 'No routine adjustment.', 'Caution in hepatic impairment.', ARRAY['Very potent', 'Minimal sodium retention', 'Long duration allows once-daily dosing']::text[], ARRAY['Marked hyperglycaemia', 'Adrenal suppression']::text[], ARRAY['Roughly 0.75 mg dexamethasone equals 5 mg prednisolone']::text[], 'Dexamethasone = strongest and longest of the common steroids, no salt retention.', '-methasone', 'dex-a-METH-a-sone', 'डेक्-सा-मे-था-सोन', NULL, 'active', 'under_review', NULL, '1.0', '2026-08-19T05:55:43.559291+00:00', '2026-08-19T05:55:43.559291+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('5ebce608-5421-49e3-b3d7-fbd73a574f76', 'enalapril', 'Enalapril', 'Enalapril', 'Enalapril', 'Enalapril maleate', NULL, 'An ACE inhibitor prodrug used in hypertension and heart failure.', 'Blood Pressure', ARRAY['2.5 mg', '5 mg', '10 mg']::text[], ARRAY['Tablet']::text[], ARRAY['Oral']::text[], 'Its active metabolite enalaprilat inhibits angiotensin-converting enzyme, reducing angiotensin II formation and aldosterone release and decreasing bradykinin breakdown.', 'Lowers blood pressure and afterload; reduces proteinuria and improves survival in heart failure.', 'About 60% absorbed orally.', 'Distributes widely; the active metabolite has low tissue binding.', 'Hepatic hydrolysis of the prodrug to enalaprilat.', 'Mainly renal excretion.', 'About 60%', 'About 11 hours (enalaprilat effective half-life)', 'Around 50-60%', NULL, NULL, 'Within 1 hour, peak at 4-6 hours', '12-24 hours', ARRAY['Hypertension', 'Heart failure', 'Left ventricular dysfunction', 'Diabetic nephropathy']::text[], ARRAY['Pregnancy', 'History of ACE inhibitor angioedema', 'Bilateral renal artery stenosis', 'Concurrent aliskiren in diabetes']::text[], ARRAY['Dry cough is common and may require a switch to an ARB', 'Angioedema can be life threatening', 'Check renal function and potassium after starting or increasing the dose']::text[], NULL, ARRAY['Dry cough', 'Dizziness', 'Headache', 'Hyperkalaemia']::text[], ARRAY['Angioedema', 'Acute kidney injury', 'Severe hyperkalaemia', 'First-dose hypotension']::text[], ARRAY['Potassium supplements and potassium-sparing diuretics', 'NSAIDs', 'Lithium', 'ARBs (avoid dual blockade)']::text[], NULL, ARRAY['Serum creatinine and potassium 1-2 weeks after initiation', 'Blood pressure']::text[], NULL, NULL, 'Contraindicated — stop before conception where possible.', 'Alternatives are preferred; seek specialist advice.', 'Used in children under specialist care.', 'Start at a low dose; monitor renal function.', 'Reduce dose in renal impairment.', 'No routine adjustment.', ARRAY['Mortality benefit in heart failure', 'Renal protection in proteinuric disease']::text[], ARRAY['Dry cough', 'Hyperkalaemia', 'Contraindicated in pregnancy']::text[], ARRAY['A rise in creatinine of up to about 30% after starting can be acceptable — recheck rather than stopping reflexively']::text[], '"-pril" → ACE inhibitor: cough, potassium, pregnancy caution.', '-pril', 'e-NAL-a-pril', 'ए-ना-ला-प्रिल', NULL, 'active', 'under_review', NULL, '1.0', '2026-08-19T05:55:43.559291+00:00', '2026-08-19T05:55:43.559291+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('21ad0c2f-060f-43e6-a944-c4ffb651e757', 'ramipril', 'Ramipril', 'Ramipril', 'Ramipril', 'Ramipril', NULL, 'A long-acting ACE inhibitor with strong cardiovascular outcome evidence.', 'Blood Pressure', ARRAY['1.25 mg', '2.5 mg', '5 mg', '10 mg']::text[], ARRAY['Capsule', 'Tablet']::text[], ARRAY['Oral']::text[], 'Hydrolysed to ramiprilat, which inhibits angiotensin-converting enzyme, lowering angiotensin II and aldosterone.', 'Reduces blood pressure, afterload and cardiovascular events in high-risk patients.', 'Rapidly absorbed; food slows but does not reduce absorption.', 'Widely distributed; extensive tissue ACE binding.', 'Hepatic conversion to active ramiprilat.', 'Mainly renal excretion.', 'About 50-60% as ramiprilat', '13-17 hours (effective)', 'About 56% (ramiprilat)', NULL, NULL, 'Within 1-2 hours', '24 hours', ARRAY['Hypertension', 'Heart failure after myocardial infarction', 'Cardiovascular risk reduction', 'Diabetic and non-diabetic nephropathy']::text[], ARRAY['Pregnancy', 'Previous ACE inhibitor angioedema', 'Bilateral renal artery stenosis']::text[], ARRAY['Persistent dry cough', 'Symptomatic hypotension after the first dose', 'Renal function and potassium must be checked after initiation']::text[], NULL, ARRAY['Dry cough', 'Dizziness', 'Fatigue', 'Hyperkalaemia']::text[], ARRAY['Angioedema', 'Acute kidney injury', 'Hyperkalaemia']::text[], ARRAY['NSAIDs', 'Potassium-sparing diuretics', 'Lithium', 'Diuretics (first-dose hypotension)']::text[], NULL, ARRAY['Creatinine and potassium', 'Blood pressure']::text[], NULL, NULL, 'Contraindicated in pregnancy.', 'Alternatives preferred.', 'Specialist use only in children.', 'Start low; monitor blood pressure standing and sitting.', 'Reduce dose in renal impairment.', 'Reduce dose in hepatic impairment.', ARRAY['Once-daily dosing', 'Strong evidence for cardiovascular protection']::text[], ARRAY['Cough', 'Contraindicated in pregnancy']::text[], ARRAY['Take the first dose at bedtime to reduce first-dose dizziness']::text[], '"-pril" → ACE inhibitor; ramipril is the outcome-trial workhorse.', '-pril', 'ra-MI-pril', 'रै-मि-प्रिल', NULL, 'active', 'under_review', NULL, '1.0', '2026-08-19T05:55:43.559291+00:00', '2026-08-19T05:55:43.559291+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('87e81f58-d7d8-4eea-a9d5-fbf6239e1c02', 'valsartan', 'Valsartan', 'Valsartan', 'Valsartan', 'Valsartan', NULL, 'An angiotensin receptor blocker used in hypertension and heart failure.', 'Blood Pressure', ARRAY['40 mg', '80 mg', '160 mg', '320 mg']::text[], ARRAY['Tablet']::text[], ARRAY['Oral']::text[], 'Selectively blocks the angiotensin II type 1 (AT1) receptor, preventing vasoconstriction and aldosterone release.', 'Lowers blood pressure without the bradykinin accumulation that causes ACE inhibitor cough.', 'Absorption is variable and reduced by food.', 'Highly protein bound; small volume of distribution.', 'Minimal metabolism.', 'Mainly biliary and faecal excretion.', 'About 23%', 'About 6 hours', 'Around 95%', NULL, NULL, 'Within 2 hours, peak effect in 4-6 weeks', '24 hours', ARRAY['Hypertension', 'Heart failure', 'Post-myocardial infarction left ventricular dysfunction']::text[], ARRAY['Pregnancy', 'Bilateral renal artery stenosis', 'Concurrent aliskiren in diabetes']::text[], ARRAY['Contraindicated in pregnancy', 'Hyperkalaemia and renal impairment risk as with ACE inhibitors', 'Do not combine with an ACE inhibitor']::text[], NULL, ARRAY['Dizziness', 'Headache', 'Fatigue', 'Hyperkalaemia']::text[], ARRAY['Angioedema (rare)', 'Acute kidney injury', 'Severe hyperkalaemia']::text[], ARRAY['Potassium-sparing diuretics', 'NSAIDs', 'Lithium', 'ACE inhibitors']::text[], NULL, ARRAY['Blood pressure', 'Creatinine and potassium']::text[], NULL, NULL, 'Contraindicated in pregnancy.', 'Alternatives preferred.', 'Used in children over 6 years under specialist care.', 'Start low and titrate.', 'Caution in severe renal impairment.', 'Reduce dose in hepatic impairment; avoid in biliary obstruction.', ARRAY['No cough', 'Well tolerated']::text[], ARRAY['Same pregnancy and potassium cautions as ACE inhibitors']::text[], ARRAY['ARBs are the usual switch when an ACE inhibitor causes cough']::text[], '"-sartan" → ARB: same benefits, no cough.', '-sartan', 'val-SAR-tan', 'वैल्-सार्-टन', NULL, 'active', 'under_review', NULL, '1.0', '2026-08-19T05:55:43.559291+00:00', '2026-08-19T05:55:43.559291+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('e4a2371c-086b-4933-8c15-412bb4b34b60', 'nifedipine', 'Nifedipine', 'Nifedipine', 'Nifedipine', 'Nifedipine', NULL, 'A dihydropyridine calcium channel blocker used in hypertension and angina.', 'Blood Pressure', ARRAY['5 mg', '10 mg', '20 mg SR', '30 mg XL']::text[], ARRAY['Capsule', 'Sustained-release tablet']::text[], ARRAY['Oral']::text[], 'Blocks L-type calcium channels in vascular smooth muscle, causing arterial vasodilation.', 'Reduces peripheral resistance and blood pressure; immediate-release forms can cause reflex tachycardia.', 'Rapidly absorbed; extensive first-pass metabolism.', 'Highly protein bound.', 'Hepatic metabolism via CYP3A4.', 'Renal excretion of inactive metabolites.', 'About 45-68% (formulation dependent)', '2 hours (immediate release); longer for modified release', 'Around 92-98%', NULL, NULL, '20 minutes (immediate release)', '4-8 hours immediate release, 24 hours for XL', ARRAY['Hypertension', 'Chronic stable angina', 'Raynaud phenomenon', 'Tocolysis in preterm labour (specialist use)']::text[], ARRAY['Cardiogenic shock', 'Unstable angina with immediate-release forms', 'Severe aortic stenosis', 'Within one month of myocardial infarction (immediate release)']::text[], ARRAY['Avoid immediate-release capsules for acute blood pressure reduction — reflex tachycardia and ischaemia can occur', 'Do not take with grapefruit juice', 'Swallow modified-release tablets whole']::text[], NULL, ARRAY['Ankle oedema', 'Flushing', 'Headache', 'Palpitations']::text[], ARRAY['Severe hypotension', 'Worsening angina', 'Reflex tachycardia']::text[], ARRAY['Grapefruit juice', 'CYP3A4 inhibitors and inducers', 'Beta blockers', 'Magnesium sulphate']::text[], NULL, ARRAY['Blood pressure', 'Heart rate', 'Ankle oedema']::text[], NULL, NULL, 'Used in pregnancy for hypertension and tocolysis under supervision.', 'Considered compatible with breastfeeding.', 'Specialist use in children.', 'Prefer modified-release forms; start low.', 'No routine adjustment.', 'Reduce dose in hepatic impairment.', ARRAY['Effective antihypertensive', 'Safe in pregnancy under supervision']::text[], ARRAY['Ankle oedema', 'Immediate-release forms cause reflex tachycardia']::text[], ARRAY['Never use sublingual nifedipine for a hypertensive crisis']::text[], '"-dipine" → dihydropyridine; ankle swelling and flushing.', '-dipine', 'nye-FED-i-peen', 'ना-इ-फ़े-डि-पीन', NULL, 'active', 'under_review', NULL, '1.0', '2026-08-19T05:55:43.559291+00:00', '2026-08-19T05:55:43.559291+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('d020926d-ff53-449a-8435-2a91f05848b7', 'atenolol', 'Atenolol', 'Atenolol', 'Atenolol', 'Atenolol', NULL, 'A cardioselective beta blocker used in hypertension and angina.', 'Blood Pressure', ARRAY['25 mg', '50 mg', '100 mg']::text[], ARRAY['Tablet']::text[], ARRAY['Oral']::text[], 'Selectively blocks beta-1 adrenoceptors, reducing heart rate, contractility and renin release.', 'Lowers heart rate and blood pressure; water soluble so limited CNS penetration.', 'Incompletely absorbed orally.', 'Low lipid solubility; minimal CNS entry.', 'Minimal hepatic metabolism.', 'Mainly renal excretion of unchanged drug.', 'About 50%', '6-7 hours (prolonged in renal impairment)', 'Low (about 3%)', NULL, NULL, 'Within 1 hour', '24 hours', ARRAY['Hypertension', 'Angina', 'Arrhythmias', 'Post-myocardial infarction']::text[], ARRAY['Severe bradycardia', 'Second or third degree heart block', 'Cardiogenic shock', 'Severe asthma']::text[], ARRAY['Do not stop abruptly — rebound angina and hypertension can occur', 'Can mask hypoglycaemia symptoms in diabetes', 'Accumulates in renal impairment']::text[], NULL, ARRAY['Fatigue', 'Cold extremities', 'Bradycardia', 'Dizziness']::text[], ARRAY['Severe bradycardia or heart block', 'Bronchospasm', 'Heart failure decompensation']::text[], ARRAY['Verapamil and diltiazem', 'Insulin and sulfonylureas', 'Clonidine', 'NSAIDs']::text[], NULL, ARRAY['Heart rate', 'Blood pressure', 'Signs of heart failure']::text[], NULL, NULL, 'Growth restriction reported; labetalol or methyldopa are usually preferred.', 'Accumulates in breast milk; monitor the infant or choose an alternative.', 'Specialist use in children.', 'Watch for bradycardia and fatigue.', 'Reduce dose in renal impairment.', 'No routine adjustment.', ARRAY['Once daily', 'Inexpensive', 'Cardioselective']::text[], ARRAY['Less effective than other agents for stroke prevention in hypertension', 'Renal accumulation']::text[], ARRAY['Never stop a beta blocker suddenly']::text[], '"-olol" → beta blocker; atenolol leaves via the kidney.', '-olol', 'a-TEN-oh-lol', 'ऐ-टे-नो-लोल', NULL, 'active', 'under_review', NULL, '1.0', '2026-08-19T05:55:43.559291+00:00', '2026-08-19T05:55:43.559291+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('b5bf353e-b38f-4750-9126-acd9341ea1c7', 'metoprolol', 'Metoprolol', 'Metoprolol', 'Metoprolol', 'Metoprolol succinate (ER) / tartrate (IR)', NULL, 'A cardioselective beta blocker with mortality benefit in heart failure.', 'Heart', ARRAY['25 mg', '50 mg', '100 mg', '25 mg ER', '50 mg ER']::text[], ARRAY['Tablet', 'Extended-release tablet', 'Injection']::text[], ARRAY['Oral', 'Intravenous']::text[], 'Selectively blocks beta-1 adrenoceptors, reducing heart rate, contractility, myocardial oxygen demand and renin release.', 'Reduces angina frequency, controls rate and improves survival in heart failure when titrated slowly.', 'Well absorbed but with significant first-pass metabolism.', 'Lipid soluble; crosses the blood-brain barrier.', 'Hepatic metabolism via CYP2D6.', 'Renal excretion of metabolites.', 'About 50% (tartrate)', '3-7 hours (tartrate); ER gives 24-hour cover', 'Around 12%', NULL, NULL, 'Within 1 hour orally', '6-12 hours (IR), 24 hours (ER)', ARRAY['Heart failure with reduced ejection fraction (succinate)', 'Angina', 'Hypertension', 'Rate control in atrial fibrillation', 'Post-myocardial infarction']::text[], ARRAY['Decompensated heart failure', 'Severe bradycardia', 'High-grade AV block', 'Cardiogenic shock', 'Severe asthma']::text[], ARRAY['Only the succinate extended-release form is licensed for heart failure', 'Start low and titrate slowly in heart failure', 'Do not stop abruptly']::text[], NULL, ARRAY['Fatigue', 'Bradycardia', 'Dizziness', 'Cold hands and feet', 'Vivid dreams']::text[], ARRAY['Heart block', 'Acute heart failure decompensation', 'Bronchospasm']::text[], ARRAY['Verapamil and diltiazem', 'CYP2D6 inhibitors such as fluoxetine and paroxetine', 'Clonidine', 'Insulin']::text[], NULL, ARRAY['Heart rate and blood pressure', 'Symptoms of heart failure', 'Exercise tolerance']::text[], NULL, NULL, 'Beta blockers may be used when needed; monitor fetal growth.', 'Small amounts in milk; usually considered acceptable.', 'Specialist use in children.', 'Start low; watch for bradycardia and falls.', 'No routine adjustment.', 'Reduce dose in hepatic impairment.', ARRAY['Survival benefit in heart failure', 'Cardioselective', 'Once-daily ER form']::text[], ARRAY['Fatigue', 'Requires slow titration in heart failure']::text[], ARRAY['Use succinate ER, not tartrate, for chronic heart failure']::text[], 'Metoprolol succinate = "Success in heart failure".', '-olol', 'me-TOE-proe-lol', 'मे-टो-प्रो-लोल', NULL, 'active', 'under_review', NULL, '1.0', '2026-08-19T05:55:43.559291+00:00', '2026-08-19T05:55:43.559291+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('2bbadd64-72ef-4365-bb25-e8b43174c162', 'propranolol', 'Propranolol', 'Propranolol', 'Propranolol', 'Propranolol hydrochloride', NULL, 'A non-selective beta blocker with many uses beyond the heart.', 'Heart', ARRAY['10 mg', '20 mg', '40 mg', '80 mg']::text[], ARRAY['Tablet', 'Injection']::text[], ARRAY['Oral', 'Intravenous']::text[], 'Non-selectively blocks beta-1 and beta-2 adrenoceptors, reducing heart rate, contractility, tremor and portal pressure.', 'Reduces sympathetic drive; lipid soluble with prominent central effects.', 'Well absorbed but with extensive first-pass metabolism.', 'Highly lipid soluble; crosses the blood-brain barrier.', 'Extensive hepatic metabolism via CYP2D6 and CYP1A2.', 'Renal excretion of metabolites.', 'About 25-30%', '3-6 hours', 'About 90%', NULL, NULL, 'Within 1-2 hours orally', '6-12 hours', ARRAY['Migraine prophylaxis', 'Essential tremor', 'Thyrotoxicosis symptom control', 'Variceal bleeding prophylaxis', 'Performance anxiety', 'Infantile haemangioma']::text[], ARRAY['Asthma', 'Severe bradycardia', 'High-grade AV block', 'Cardiogenic shock', 'Untreated phaeochromocytoma']::text[], ARRAY['Contraindicated in asthma because beta-2 blockade causes bronchospasm', 'Masks hypoglycaemia warning signs', 'Do not stop abruptly']::text[], NULL, ARRAY['Fatigue', 'Cold extremities', 'Bradycardia', 'Sleep disturbance']::text[], ARRAY['Bronchospasm', 'Severe bradycardia', 'Heart failure decompensation', 'Severe hypoglycaemia in children']::text[], ARRAY['Verapamil', 'Insulin and sulfonylureas', 'NSAIDs', 'Rizatriptan']::text[], NULL, ARRAY['Heart rate', 'Blood pressure', 'Respiratory symptoms']::text[], NULL, NULL, 'Used when needed; monitor fetal growth and neonatal glucose.', 'Small amounts in milk; usually acceptable.', 'Used for infantile haemangioma under specialist care.', 'Watch for bradycardia, falls and fatigue.', 'No routine adjustment.', 'Reduce dose in hepatic impairment.', ARRAY['Very versatile', 'Effective for tremor and migraine prophylaxis']::text[], ARRAY['Non-selective — unsafe in asthma', 'Central side effects']::text[], ARRAY['Its non-selectivity is exactly why it is useful for tremor and varices, and why it is unsafe in asthma']::text[], 'Propranolol = non-selective: "blocks both, so beware the lungs".', '-olol', 'proe-PRAN-oh-lol', 'प्रो-प्रै-नो-लोल', NULL, 'active', 'under_review', NULL, '1.0', '2026-08-19T05:55:43.559291+00:00', '2026-08-19T05:55:43.559291+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('b73a0ca1-772b-460f-93e2-0421404c3945', 'carvedilol', 'Carvedilol', 'Carvedilol', 'Carvedilol', 'Carvedilol', NULL, 'A combined alpha and beta blocker used in heart failure.', 'Heart', ARRAY['3.125 mg', '6.25 mg', '12.5 mg', '25 mg']::text[], ARRAY['Tablet']::text[], ARRAY['Oral']::text[], 'Blocks beta-1, beta-2 and alpha-1 adrenoceptors, reducing heart rate, contractility and afterload; also has antioxidant properties.', 'Improves survival and symptoms in heart failure; the alpha blockade causes vasodilation and postural hypotension.', 'Rapidly absorbed; food slows absorption and reduces the risk of postural hypotension.', 'Highly protein bound; lipophilic.', 'Extensive hepatic metabolism via CYP2D6 and CYP2C9.', 'Mainly biliary and faecal excretion.', 'About 25-35%', '7-10 hours', 'Over 98%', NULL, NULL, 'Within 1 hour', '12 hours dosing interval', ARRAY['Heart failure with reduced ejection fraction', 'Hypertension', 'Angina', 'Portal hypertension']::text[], ARRAY['Decompensated heart failure', 'Asthma', 'Severe bradycardia', 'High-grade AV block', 'Severe hepatic impairment']::text[], ARRAY['Start at a very low dose and double no faster than every 2 weeks in heart failure', 'Take with food to reduce postural hypotension', 'Not suitable in asthma']::text[], NULL, ARRAY['Dizziness', 'Fatigue', 'Postural hypotension', 'Bradycardia']::text[], ARRAY['Heart failure worsening during up-titration', 'Bronchospasm', 'Complete heart block']::text[], ARRAY['Verapamil and diltiazem', 'Digoxin (raised levels)', 'CYP2D6 inhibitors', 'Insulin']::text[], NULL, ARRAY['Weight and fluid status', 'Heart rate and blood pressure', 'Renal function']::text[], NULL, NULL, 'Limited data; specialist advice needed.', 'Not recommended.', 'Not established in children.', 'Start low; risk of postural hypotension and falls.', 'No routine adjustment.', 'Contraindicated in severe hepatic impairment.', ARRAY['Mortality benefit in heart failure', 'Vasodilating action']::text[], ARRAY['Postural hypotension', 'Slow titration required', 'Unsafe in asthma']::text[], ARRAY['Weight gain of 2 kg or more during titration suggests fluid retention, not drug failure']::text[], 'Carvedilol = beta blocker plus alpha blocker — "double block, go slow".', '-dilol', 'KAR-ve-dil-ol', 'कार्-वे-डि-लोल', NULL, 'active', 'under_review', NULL, '1.0', '2026-08-19T05:55:43.559291+00:00', '2026-08-19T05:55:43.559291+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('48958fb7-453a-453a-91f0-152af6fdee7f', 'hydrochlorothiazide', 'Hydrochlorothiazide', 'Hydrochlorothiazide', 'Hydrochlorothiazide', 'Hydrochlorothiazide', NULL, 'A thiazide diuretic used widely in hypertension, often in combinations.', 'Blood Pressure', ARRAY['12.5 mg', '25 mg']::text[], ARRAY['Tablet']::text[], ARRAY['Oral']::text[], 'Inhibits the sodium-chloride co-transporter in the distal convoluted tubule, increasing sodium, chloride and water excretion.', 'Initial diuresis followed by a sustained fall in peripheral resistance; reduces urinary calcium excretion.', 'Well absorbed orally.', 'Distributes into extracellular fluid.', 'Not appreciably metabolised.', 'Renal excretion of unchanged drug.', 'About 65-75%', '6-15 hours', 'Around 40-68%', NULL, NULL, 'Within 2 hours', '6-12 hours', ARRAY['Hypertension', 'Oedema', 'Recurrent calcium-containing kidney stones', 'Nephrogenic diabetes insipidus']::text[], ARRAY['Anuria', 'Refractory hypokalaemia or hyponatraemia', 'Sulfonamide hypersensitivity (caution)', 'Symptomatic hyperuricaemia']::text[], ARRAY['Electrolyte disturbance, particularly hyponatraemia and hypokalaemia', 'Can precipitate gout', 'Photosensitivity and increased risk of skin cancer with long-term use']::text[], NULL, ARRAY['Increased urination', 'Dizziness', 'Hypokalaemia', 'Hyperuricaemia']::text[], ARRAY['Severe hyponatraemia', 'Severe hypokalaemia with arrhythmia', 'Acute gout', 'Pancreatitis (rare)']::text[], ARRAY['Lithium', 'NSAIDs', 'Digoxin (via hypokalaemia)', 'Antidiabetic drugs']::text[], NULL, ARRAY['Serum sodium and potassium', 'Renal function', 'Uric acid', 'Blood glucose']::text[], NULL, NULL, 'Not first choice; specialist advice needed.', 'May suppress lactation; alternatives preferred.', 'Rarely used in children.', 'Higher risk of hyponatraemia and falls.', 'Ineffective when eGFR is low; a loop diuretic is preferred.', 'Caution in hepatic impairment.', ARRAY['Inexpensive first-line antihypertensive', 'Reduces stroke risk', 'Useful in calcium stone prevention']::text[], ARRAY['Electrolyte and metabolic disturbance', 'Gout']::text[], ARRAY['Check sodium and potassium 2-4 weeks after starting']::text[], 'Thiazide = "loses potassium and sodium, keeps calcium".', '-thiazide', 'hye-droe-klor-oh-THYE-a-zide', 'हा-इ-ड्रो-क्लो-रो-था-इ-ज़ाइड', NULL, 'active', 'under_review', NULL, '1.0', '2026-08-19T05:55:43.559291+00:00', '2026-08-19T05:55:43.559291+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('a57dadc1-7120-47c9-9642-aab1666c7a2e', 'spironolactone', 'Spironolactone', 'Spironolactone', 'Spironolactone', 'Spironolactone', NULL, 'A potassium-sparing aldosterone antagonist used in heart failure and ascites.', 'Heart', ARRAY['25 mg', '50 mg', '100 mg']::text[], ARRAY['Tablet']::text[], ARRAY['Oral']::text[], 'Competitively antagonises mineralocorticoid (aldosterone) receptors in the distal nephron, increasing sodium and water excretion while retaining potassium.', 'Weak diuretic with strong neurohormonal benefit in heart failure; antiandrogenic effects occur at higher doses.', 'Well absorbed orally, improved with food.', 'Highly protein bound.', 'Extensive hepatic metabolism to active metabolites including canrenone.', 'Renal and biliary excretion.', 'About 90% with food', 'About 1.4 hours (canrenone 16-22 hours)', 'Over 90%', NULL, NULL, '24-48 hours for full diuretic effect', '2-3 days after stopping', ARRAY['Heart failure with reduced ejection fraction', 'Resistant hypertension', 'Ascites and oedema in cirrhosis', 'Primary hyperaldosteronism']::text[], ARRAY['Hyperkalaemia', 'Addison disease', 'Severe renal impairment', 'Anuria']::text[], ARRAY['Hyperkalaemia is the main danger, especially with ACE inhibitors or ARBs', 'Check potassium and creatinine within 1-2 weeks of starting', 'Gynaecomastia can occur']::text[], NULL, ARRAY['Hyperkalaemia', 'Gynaecomastia', 'Breast tenderness', 'Menstrual irregularity']::text[], ARRAY['Severe hyperkalaemia with arrhythmia', 'Acute kidney injury', 'Metabolic acidosis']::text[], ARRAY['ACE inhibitors and ARBs', 'Potassium supplements', 'NSAIDs', 'Trimethoprim', 'Digoxin']::text[], NULL, ARRAY['Serum potassium and creatinine', 'Blood pressure', 'Weight']::text[], NULL, NULL, 'Antiandrogenic effects; usually avoided.', 'Metabolites appear in milk; alternatives preferred.', 'Specialist use in children.', 'High hyperkalaemia risk; monitor closely.', 'Avoid in significant renal impairment.', 'Used in cirrhotic ascites with careful monitoring.', ARRAY['Mortality benefit in heart failure', 'First-line diuretic in cirrhotic ascites']::text[], ARRAY['Hyperkalaemia', 'Gynaecomastia']::text[], ARRAY['Recheck potassium 1 week and 4 weeks after starting or increasing the dose']::text[], 'Spironolactone = "spares potassium, spares life in heart failure".', '-actone', 'speer-on-oh-LAK-tone', 'स्पी-रो-नो-लैक्-टोन', NULL, 'active', 'under_review', NULL, '1.0', '2026-08-19T05:55:43.559291+00:00', '2026-08-19T05:55:43.559291+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('810cdf75-4a9b-41c0-9d5d-e483064a9699', 'warfarin', 'Warfarin', 'Warfarin', 'Warfarin', 'Warfarin sodium', NULL, 'An oral vitamin K antagonist anticoagulant requiring INR monitoring.', 'Blood Thinners', ARRAY['1 mg', '2 mg', '3 mg', '5 mg']::text[], ARRAY['Tablet']::text[], ARRAY['Oral']::text[], 'Inhibits vitamin K epoxide reductase, reducing synthesis of clotting factors II, VII, IX and X and proteins C and S.', 'Anticoagulant effect develops over 48-72 hours as existing clotting factors are cleared.', 'Rapid and complete oral absorption.', 'Highly protein bound; small volume of distribution.', 'Hepatic metabolism, mainly via CYP2C9; VKORC1 and CYP2C9 genotype affect dose.', 'Renal excretion of metabolites.', 'Approximately 100%', 'About 36-42 hours', 'Around 99%', NULL, NULL, 'Anticoagulant effect in 48-72 hours', '2-5 days after stopping', ARRAY['Deep vein thrombosis and pulmonary embolism', 'Atrial fibrillation stroke prevention', 'Mechanical heart valves', 'Recurrent thromboembolism']::text[], ARRAY['Pregnancy (except mechanical valves under specialist care)', 'Active major bleeding', 'Severe uncontrolled hypertension', 'Non-adherence to INR monitoring']::text[], ARRAY['Narrow therapeutic index — regular INR monitoring is essential', 'Huge number of drug and food interactions', 'Keep vitamin K intake in the diet consistent rather than avoiding greens entirely']::text[], NULL, ARRAY['Bruising', 'Minor bleeding', 'Nausea']::text[], ARRAY['Major haemorrhage', 'Intracranial bleeding', 'Skin necrosis in early therapy', 'Purple toe syndrome']::text[], ARRAY['Antibiotics, especially fluoroquinolones and macrolides', 'NSAIDs and aspirin', 'Amiodarone', 'Antifungal azoles', 'Green leafy vegetables']::text[], NULL, ARRAY['INR at regular intervals', 'Signs of bleeding', 'Haemoglobin']::text[], NULL, NULL, 'Teratogenic — contraindicated except in specific valve cases under specialist supervision.', 'Considered compatible with breastfeeding.', 'Specialist use in children.', 'Higher bleeding risk; use lower starting doses.', 'Monitor INR more closely in renal impairment.', 'Avoid in significant liver disease.', ARRAY['Reversible with vitamin K', 'Long experience and low cost', 'Suitable for mechanical valves']::text[], ARRAY['INR monitoring burden', 'Extensive interactions', 'Bleeding risk']::text[], ARRAY['Any new medicine, including antibiotics, needs an INR check a few days later']::text[], 'Warfarin blocks 1972 factors: II, VII, IX, X.', '—', 'WAR-fa-rin', 'वार्-फ़ा-रिन', NULL, 'active', 'under_review', NULL, '1.0', '2026-08-19T05:58:50.17128+00:00', '2026-08-19T05:58:50.17128+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('f11bcb10-5fd5-486b-8c2e-5d5687139744', 'enoxaparin', 'Enoxaparin', 'Enoxaparin', 'Enoxaparin', 'Enoxaparin sodium', NULL, 'A low-molecular-weight heparin given by subcutaneous injection.', 'Blood Thinners', ARRAY['20 mg/0.2 mL', '40 mg/0.4 mL', '60 mg/0.6 mL']::text[], ARRAY['Prefilled syringe']::text[], ARRAY['Subcutaneous']::text[], 'Binds antithrombin III and preferentially accelerates inactivation of factor Xa relative to thrombin.', 'Predictable anticoagulation without routine monitoring in most patients.', 'Well absorbed subcutaneously.', 'Distributes in blood volume; does not cross the placenta.', 'Limited hepatic desulphation.', 'Mainly renal excretion.', 'About 92% subcutaneously', 'About 4-7 hours (longer in renal impairment)', 'Low', NULL, NULL, '3-5 hours to peak anti-Xa activity', '12-24 hours depending on dose', ARRAY['Venous thromboembolism treatment and prophylaxis', 'Acute coronary syndrome', 'Bridging anticoagulation', 'Thromboprophylaxis in pregnancy']::text[], ARRAY['Active major bleeding', 'History of heparin-induced thrombocytopenia', 'Severe thrombocytopenia']::text[], ARRAY['Dose reduction required when creatinine clearance is below 30 mL/min', 'Avoid neuraxial anaesthesia within the recommended time window', 'Monitor platelet count for heparin-induced thrombocytopenia']::text[], NULL, ARRAY['Injection-site bruising', 'Mild bleeding', 'Raised transaminases']::text[], ARRAY['Major haemorrhage', 'Heparin-induced thrombocytopenia', 'Spinal haematoma with neuraxial procedures']::text[], ARRAY['Antiplatelet agents', 'NSAIDs', 'Warfarin', 'Thrombolytics']::text[], NULL, ARRAY['Platelet count', 'Renal function', 'Anti-Xa levels in pregnancy, obesity or renal impairment']::text[], NULL, NULL, 'Preferred anticoagulant in pregnancy; does not cross the placenta.', 'Considered compatible with breastfeeding.', 'Weight-based dosing under specialist care.', 'Bleeding risk rises with age and renal decline.', 'Reduce dose if creatinine clearance is below 30 mL/min.', 'No routine adjustment.', ARRAY['No routine monitoring needed', 'Can be given at home', 'Safe in pregnancy']::text[], ARRAY['Injection route', 'Accumulates in renal impairment', 'Partial reversal only with protamine']::text[], ARRAY['Rotate injection sites and do not rub the site afterwards']::text[], 'LMWH = "Xa mainly" — predictable, so no routine INR.', '-parin', 'ee-nox-a-PAR-in', 'ई-नॉक्-सा-पै-रिन', NULL, 'active', 'under_review', NULL, '1.0', '2026-08-19T05:58:50.17128+00:00', '2026-08-19T05:58:50.17128+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('bcc95ac7-73b2-4c9f-83ce-6e2f83495600', 'simvastatin', 'Simvastatin', 'Simvastatin', 'Simvastatin', 'Simvastatin', NULL, 'A statin taken at night to lower LDL cholesterol.', 'Cholesterol', ARRAY['5 mg', '10 mg', '20 mg', '40 mg']::text[], ARRAY['Tablet']::text[], ARRAY['Oral']::text[], 'Competitively inhibits HMG-CoA reductase, the rate-limiting enzyme of hepatic cholesterol synthesis, upregulating LDL receptors.', 'Lowers LDL cholesterol and cardiovascular events; effect is greater with evening dosing because cholesterol synthesis peaks at night.', 'Well absorbed but with extensive first-pass metabolism.', 'Highly protein bound; hepatoselective.', 'Extensive hepatic metabolism via CYP3A4.', 'Mainly biliary and faecal excretion.', 'Under 5% systemically', 'About 2-3 hours', 'Around 95%', NULL, NULL, 'LDL reduction within 2 weeks', '24 hours', ARRAY['Primary hypercholesterolaemia', 'Cardiovascular risk reduction', 'Familial hypercholesterolaemia']::text[], ARRAY['Active liver disease', 'Pregnancy and breastfeeding', 'Concurrent strong CYP3A4 inhibitors']::text[], ARRAY['Do not exceed 20 mg daily with amlodipine or 40 mg with several other interacting drugs', 'Report unexplained muscle pain, tenderness or dark urine', 'Avoid grapefruit juice']::text[], NULL, ARRAY['Muscle aches', 'Headache', 'Constipation', 'Raised transaminases']::text[], ARRAY['Rhabdomyolysis', 'Hepatotoxicity', 'Immune-mediated necrotising myopathy (rare)']::text[], ARRAY['Clarithromycin and erythromycin', 'Azole antifungals', 'Amlodipine', 'Gemfibrozil', 'Grapefruit juice']::text[], NULL, ARRAY['Lipid profile', 'Liver enzymes at baseline', 'Creatine kinase if muscle symptoms occur']::text[], NULL, NULL, 'Contraindicated in pregnancy.', 'Contraindicated during breastfeeding.', 'Used in familial hypercholesterolaemia under specialist care.', 'Effective; start at lower doses.', 'Reduce dose in severe renal impairment.', 'Contraindicated in active liver disease.', ARRAY['Inexpensive', 'Strong outcome evidence']::text[], ARRAY['Many CYP3A4 interactions', 'Dose caps with common co-prescriptions']::text[], ARRAY['Take in the evening; atorvastatin and rosuvastatin can be taken at any time']::text[], '"-statin" → HMG-CoA reductase inhibitor; simvastatin is the interaction-prone one.', '-statin', 'SIM-va-stat-in', 'सिम्-वा-स्टै-टिन', NULL, 'active', 'under_review', NULL, '1.0', '2026-08-19T05:58:50.17128+00:00', '2026-08-19T05:58:50.17128+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('3c9c27a7-25b6-4d62-ab46-abfdb2bbf549', 'fenofibrate', 'Fenofibrate', 'Fenofibrate', 'Fenofibrate', 'Fenofibrate', NULL, 'A fibrate used mainly to lower triglycerides.', 'Cholesterol', ARRAY['145 mg', '160 mg', '200 mg']::text[], ARRAY['Tablet', 'Capsule']::text[], ARRAY['Oral']::text[], 'Activates PPAR-alpha, increasing lipoprotein lipase activity and fatty acid oxidation while reducing hepatic VLDL production.', 'Lowers triglycerides substantially, modestly raises HDL and lowers LDL.', 'Absorption improves with food for older formulations.', 'Highly protein bound.', 'Hydrolysed to fenofibric acid, then glucuronidated.', 'Mainly renal excretion.', 'Good with food', 'About 20 hours', 'About 99%', NULL, NULL, 'Lipid changes within 2-4 weeks', '24 hours', ARRAY['Severe hypertriglyceridaemia', 'Mixed dyslipidaemia', 'Prevention of pancreatitis from very high triglycerides']::text[], ARRAY['Severe renal impairment', 'Severe hepatic impairment', 'Gallbladder disease', 'Known photoallergy to fibrates']::text[], ARRAY['Myopathy risk increases when combined with a statin', 'Can raise serum creatinine without true renal injury', 'Gallstone risk']::text[], NULL, ARRAY['Dyspepsia', 'Raised transaminases', 'Muscle aches', 'Headache']::text[], ARRAY['Rhabdomyolysis', 'Hepatotoxicity', 'Gallstones', 'Pancreatitis']::text[], ARRAY['Statins', 'Warfarin', 'Ciclosporin', 'Bile acid sequestrants']::text[], NULL, ARRAY['Lipid profile', 'Liver enzymes', 'Renal function', 'Creatine kinase if muscle symptoms occur']::text[], NULL, NULL, 'Avoid unless clearly necessary.', 'Not recommended.', 'Not established in children.', 'Monitor renal function.', 'Reduce dose or avoid in renal impairment.', 'Avoid in severe hepatic impairment.', ARRAY['Strong triglyceride lowering', 'Once daily']::text[], ARRAY['Myopathy risk with statins', 'Creatinine rise can confuse monitoring']::text[], ARRAY['Lifestyle change and alcohol reduction matter as much as the drug in hypertriglyceridaemia']::text[], '"-fibrate" → fights triglycerides.', '-fibrate', 'fen-oh-FYE-brate', 'फ़े-नो-फ़ा-इ-ब्रेट', NULL, 'active', 'under_review', NULL, '1.0', '2026-08-19T05:58:50.17128+00:00', '2026-08-19T05:58:50.17128+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('d491dfeb-9da9-4c67-8a93-b52b0b46ca29', 'digoxin', 'Digoxin', 'Digoxin', 'Digoxin', 'Digoxin', NULL, 'A cardiac glycoside with a narrow therapeutic index.', 'Heart', ARRAY['0.0625 mg', '0.125 mg', '0.25 mg', '0.5 mg/2 mL injection']::text[], ARRAY['Tablet', 'Injection', 'Elixir']::text[], ARRAY['Oral', 'Intravenous']::text[], 'Inhibits the sodium-potassium ATPase pump, indirectly raising intracellular calcium and increasing contractility; increases vagal tone, slowing AV nodal conduction.', 'Positive inotropy with rate control in atrial fibrillation; no mortality benefit but reduces heart failure hospitalisation.', 'Well absorbed orally; absorption reduced by some foods and drugs.', 'Very large volume of distribution; binds skeletal muscle.', 'Minimal hepatic metabolism.', 'Mainly renal excretion of unchanged drug.', 'About 60-80% (tablets)', '36-48 hours with normal renal function', 'About 25%', NULL, NULL, '1-2 hours orally, 5-30 minutes IV', '3-4 days after stopping', ARRAY['Rate control in atrial fibrillation', 'Heart failure with reduced ejection fraction (symptom control)']::text[], ARRAY['Ventricular fibrillation', 'Complete heart block without a pacemaker', 'Hypertrophic obstructive cardiomyopathy', 'Wolff-Parkinson-White with atrial fibrillation']::text[], ARRAY['Toxicity is worsened by hypokalaemia, hypomagnesaemia and renal impairment', 'Nausea, visual halos and confusion suggest toxicity', 'Levels should be taken at least 6 hours after a dose']::text[], NULL, ARRAY['Nausea', 'Anorexia', 'Dizziness', 'Visual disturbance']::text[], ARRAY['Life-threatening arrhythmias', 'Complete heart block', 'Digoxin toxicity']::text[], ARRAY['Amiodarone', 'Verapamil', 'Diuretics causing hypokalaemia', 'Clarithromycin', 'Spironolactone']::text[], NULL, ARRAY['Serum digoxin level when toxicity is suspected', 'Potassium and magnesium', 'Renal function', 'Heart rate']::text[], NULL, NULL, 'Used when needed; considered relatively safe in pregnancy.', 'Considered compatible with breastfeeding.', 'Weight-based dosing under specialist care.', 'Reduce dose; toxicity is common and often missed.', 'Reduce dose substantially in renal impairment.', 'No routine adjustment.', ARRAY['Useful when atrial fibrillation coexists with heart failure', 'Inexpensive']::text[], ARRAY['Narrow therapeutic index', 'Multiple interactions', 'Toxicity presents non-specifically']::text[], ARRAY['Always correct potassium before blaming the heart rhythm on something else']::text[], 'Digoxin toxicity = "nausea, yellow-green vision, and a slow confused patient".', '—', 'di-JOX-in', 'डि-जॉक्-सिन', NULL, 'active', 'under_review', NULL, '1.0', '2026-08-19T05:58:50.17128+00:00', '2026-08-19T05:58:50.17128+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('a4ca74f5-1adc-432c-b433-86c3e21dbd6c', 'phenytoin', 'Phenytoin', 'Phenytoin', 'Phenytoin', 'Phenytoin sodium', NULL, 'A classic antiepileptic with non-linear pharmacokinetics.', 'Epilepsy', ARRAY['50 mg', '100 mg', '25 mg/mL suspension', '50 mg/mL injection']::text[], ARRAY['Capsule', 'Tablet', 'Suspension', 'Injection']::text[], ARRAY['Oral', 'Intravenous']::text[], 'Blocks voltage-gated sodium channels in their inactivated state, limiting repetitive neuronal firing.', 'Controls focal and generalised tonic-clonic seizures; zero-order kinetics mean small dose changes cause large level changes.', 'Slow and variable oral absorption; the suspension needs shaking.', 'Highly protein bound; free fraction rises in hypoalbuminaemia.', 'Hepatic metabolism via CYP2C9 and CYP2C19, saturable at therapeutic doses; potent enzyme inducer.', 'Renal excretion of metabolites.', 'Variable, formulation dependent', 'About 7-42 hours (dose dependent)', 'About 90%', NULL, NULL, 'Hours to days for steady state', '24 hours dosing interval', ARRAY['Focal and generalised tonic-clonic seizures', 'Status epilepticus (IV)', 'Seizure prophylaxis in neurosurgery']::text[], ARRAY['Sinus bradycardia or heart block (IV use)', 'Known hypersensitivity', 'Porphyria']::text[], ARRAY['Non-linear kinetics — increase doses in small steps', 'Gum overgrowth, hirsutism and coarse facial features with long-term use', 'Teratogenic; fetal hydantoin syndrome', 'Serious skin reactions, higher risk with HLA-B*1502']::text[], NULL, ARRAY['Gum hypertrophy', 'Nystagmus', 'Ataxia', 'Hirsutism', 'Rash']::text[], ARRAY['Stevens-Johnson syndrome', 'Hepatotoxicity', 'Blood dyscrasias', 'Cardiac arrhythmia with rapid IV infusion']::text[], ARRAY['Warfarin', 'Oral contraceptives', 'Isoniazid', 'Carbamazepine', 'Antacids']::text[], NULL, ARRAY['Serum phenytoin levels', 'Full blood count', 'Liver function', 'Gum health']::text[], NULL, NULL, 'Teratogenic; specialist pre-pregnancy planning with folic acid is essential.', 'Considered compatible; monitor the infant for drowsiness.', 'Weight-based dosing under specialist care.', 'Lower doses; free levels rise with low albumin.', 'Interpret levels with care in renal impairment.', 'Reduce dose in hepatic impairment.', ARRAY['Effective and inexpensive', 'Injectable form for status epilepticus']::text[], ARRAY['Non-linear kinetics', 'Cosmetic side effects', 'Major enzyme induction']::text[], ARRAY['Interpret levels alongside albumin; measure free phenytoin when albumin is low']::text[], 'Phenytoin = "gums grow, hair grows, levels jump".', '—', 'FEN-i-toyn', 'फ़े-नि-टॉ-इन', NULL, 'active', 'under_review', NULL, '1.0', '2026-08-19T05:58:50.17128+00:00', '2026-08-19T05:58:50.17128+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('22447a71-ca52-47d6-a91f-f42ea491b240', 'carbamazepine', 'Carbamazepine', 'Carbamazepine', 'Carbamazepine', 'Carbamazepine', NULL, 'An antiepileptic and first-line treatment for trigeminal neuralgia.', 'Epilepsy', ARRAY['100 mg', '200 mg', '400 mg CR']::text[], ARRAY['Tablet', 'Controlled-release tablet', 'Suspension']::text[], ARRAY['Oral']::text[], 'Blocks voltage-gated sodium channels, stabilising hyperexcitable neuronal membranes.', 'Controls focal seizures and neuropathic facial pain; induces its own metabolism (autoinduction).', 'Slow but fairly complete oral absorption.', 'Widely distributed; crosses the placenta.', 'Hepatic metabolism via CYP3A4 to an active epoxide; potent enzyme inducer.', 'Renal and faecal excretion.', 'About 75-85%', '25-65 hours initially, falling to 12-17 hours after autoinduction', 'About 75%', NULL, NULL, 'Days to weeks for full effect', '8-12 hours dosing interval', ARRAY['Focal seizures', 'Generalised tonic-clonic seizures', 'Trigeminal neuralgia', 'Bipolar disorder (specialist use)']::text[], ARRAY['AV conduction abnormalities', 'Bone marrow suppression', 'Concurrent MAO inhibitors', 'Acute porphyria']::text[], ARRAY['Screen for HLA-B*1502 in patients of South Asian or South-East Asian ancestry before starting', 'Hyponatraemia is common', 'Strong enzyme induction causes contraceptive failure']::text[], NULL, ARRAY['Dizziness', 'Drowsiness', 'Diplopia', 'Nausea', 'Hyponatraemia']::text[], ARRAY['Stevens-Johnson syndrome and toxic epidermal necrolysis', 'Aplastic anaemia and agranulocytosis', 'Hepatotoxicity']::text[], ARRAY['Oral contraceptives', 'Warfarin', 'Clarithromycin', 'Valproate', 'Other antiepileptics']::text[], NULL, ARRAY['Serum sodium', 'Full blood count', 'Liver function', 'Drug levels when indicated']::text[], NULL, NULL, 'Teratogenic risk; requires specialist planning with folic acid.', 'Considered compatible; monitor the infant.', 'Used in children with weight-based dosing.', 'Higher risk of hyponatraemia and ataxia.', 'No routine adjustment.', 'Caution in hepatic impairment.', ARRAY['Highly effective for trigeminal neuralgia', 'Long clinical experience']::text[], ARRAY['Enzyme induction', 'Hyponatraemia', 'Serious skin reactions']::text[], ARRAY['HLA-B*1502 screening matters particularly in Indian and South-East Asian populations']::text[], 'Carbamazepine → "Careful: skin, sodium and self-induction".', '-azepine', 'kar-ba-MAZ-e-peen', 'कार्-बा-मै-ज़े-पीन', NULL, 'active', 'under_review', NULL, '1.0', '2026-08-19T05:58:50.17128+00:00', '2026-08-19T05:58:50.17128+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('a60afaf2-38fb-402b-a338-839883f90b93', 'sodium-valproate', 'Sodium valproate', 'Sodium valproate (Valproic acid)', 'Valproate', 'Sodium valproate / valproic acid', NULL, 'A broad-spectrum antiepileptic that must be avoided in women of childbearing potential where possible.', 'Epilepsy', ARRAY['200 mg', '300 mg', '500 mg CR', '200 mg/5 mL syrup']::text[], ARRAY['Tablet', 'Controlled-release tablet', 'Syrup', 'Injection']::text[], ARRAY['Oral', 'Intravenous']::text[], 'Increases GABA availability, blocks voltage-gated sodium channels and modulates T-type calcium currents.', 'Broad-spectrum control of generalised, absence and myoclonic seizures; also mood stabilising.', 'Rapid and near-complete oral absorption.', 'Highly protein bound; saturable binding at higher levels.', 'Extensive hepatic metabolism including glucuronidation and beta-oxidation; enzyme inhibitor.', 'Renal excretion of metabolites.', 'Almost complete orally', '9-16 hours', 'About 90%', NULL, NULL, 'Days for seizure control', '12-24 hours dosing interval', ARRAY['Generalised tonic-clonic seizures', 'Absence seizures', 'Myoclonic seizures', 'Bipolar disorder', 'Migraine prophylaxis']::text[], ARRAY['Pregnancy for epilepsy unless no alternative, and never for migraine or bipolar disorder', 'Known mitochondrial disorders (POLG mutations)', 'Active liver disease', 'Urea cycle disorders']::text[], ARRAY['Highly teratogenic — pregnancy prevention programme conditions apply', 'Hepatotoxicity, particularly in children under 2 years', 'Hyperammonaemic encephalopathy can occur with normal liver enzymes']::text[], NULL, ARRAY['Nausea', 'Weight gain', 'Tremor', 'Hair loss', 'Drowsiness']::text[], ARRAY['Hepatic failure', 'Pancreatitis', 'Hyperammonaemic encephalopathy', 'Thrombocytopenia']::text[], ARRAY['Lamotrigine (raised levels and rash risk)', 'Carbapenems (loss of valproate effect)', 'Aspirin', 'Phenytoin']::text[], NULL, ARRAY['Liver function', 'Full blood count', 'Ammonia if confusion develops', 'Weight']::text[], NULL, NULL, 'Contraindicated in pregnancy except where no alternative exists for epilepsy under specialist care.', 'Considered compatible; monitor the infant.', 'Avoid under 2 years where possible due to hepatotoxicity.', 'Start low; monitor liver function and tremor.', 'No routine adjustment.', 'Contraindicated in significant liver disease.', ARRAY['Broad-spectrum efficacy', 'Effective in generalised epilepsies']::text[], ARRAY['Teratogenicity', 'Weight gain', 'Hepatic and pancreatic toxicity']::text[], ARRAY['Any woman of childbearing potential needs documented counselling and effective contraception']::text[], 'Valproate = "VALuable but never in pregnancy".', '—', 'val-PROE-ate', 'वैल्-प्रो-एट', NULL, 'active', 'under_review', NULL, '1.0', '2026-08-19T05:58:50.17128+00:00', '2026-08-19T05:58:50.17128+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('939c2d4b-0acb-4ab9-a40b-6855c6640b5d', 'levetiracetam', 'Levetiracetam', 'Levetiracetam', 'Levetiracetam', 'Levetiracetam', NULL, 'A modern antiepileptic with few drug interactions.', 'Epilepsy', ARRAY['250 mg', '500 mg', '750 mg', '100 mg/mL solution']::text[], ARRAY['Tablet', 'Oral solution', 'Injection']::text[], ARRAY['Oral', 'Intravenous']::text[], 'Binds synaptic vesicle protein SV2A, modulating neurotransmitter release; the exact anticonvulsant mechanism is not fully defined.', 'Broad-spectrum seizure control with rapid titration and minimal pharmacokinetic interactions.', 'Rapid and almost complete oral absorption.', 'Distributes close to total body water; minimal protein binding.', 'Mainly hydrolysed in blood; not dependent on cytochrome P450.', 'Predominantly renal excretion.', 'Approximately 100%', '6-8 hours', 'Under 10%', NULL, NULL, 'Within days', '12 hours dosing interval', ARRAY['Focal seizures', 'Generalised tonic-clonic seizures', 'Myoclonic seizures', 'Status epilepticus (IV)']::text[], ARRAY['Known hypersensitivity']::text[], ARRAY['Behavioural and mood changes including irritability and aggression are common', 'Dose reduction is needed in renal impairment', 'Do not stop abruptly']::text[], NULL, ARRAY['Drowsiness', 'Irritability', 'Fatigue', 'Headache']::text[], ARRAY['Severe behavioural disturbance', 'Suicidal ideation', 'Serious skin reactions (rare)']::text[], ARRAY['Few significant interactions', 'Carbamazepine (additive CNS effects)']::text[], NULL, ARRAY['Mood and behaviour', 'Renal function', 'Seizure frequency']::text[], NULL, NULL, 'Often preferred over valproate in women of childbearing potential; specialist supervision required.', 'Considered compatible; monitor the infant.', 'Used from infancy with weight-based dosing.', 'Reduce dose for renal decline.', 'Reduce dose in renal impairment.', 'No routine adjustment in mild to moderate impairment.', ARRAY['Minimal drug interactions', 'Rapid titration', 'IV and oral forms']::text[], ARRAY['Behavioural side effects', 'Renal dose adjustment needed']::text[], ARRAY['Ask specifically about irritability and mood at every review']::text[], 'Levetiracetam = "clean drug, cloudy mood".', '-racetam', 'lee-ve-tye-RA-se-tam', 'ले-वे-टा-इ-रै-से-टैम', NULL, 'active', 'under_review', NULL, '1.0', '2026-08-19T05:58:50.17128+00:00', '2026-08-19T05:58:50.17128+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('fbbcdc89-090f-45fb-9521-256bc6476bfe', 'diazepam', 'Diazepam', 'Diazepam', 'Diazepam', 'Diazepam', NULL, 'A long-acting benzodiazepine used for seizures, spasm and short-term anxiety.', 'Anxiety & Sleep', ARRAY['2 mg', '5 mg', '10 mg', '10 mg/2 mL injection']::text[], ARRAY['Tablet', 'Injection', 'Rectal solution']::text[], ARRAY['Oral', 'Intravenous', 'Rectal']::text[], 'Positive allosteric modulator at the GABA-A receptor, increasing the frequency of chloride channel opening and enhancing inhibition.', 'Anxiolytic, anticonvulsant, sedative and muscle relaxant effects.', 'Rapid oral absorption; erratic intramuscular absorption.', 'Highly lipophilic with rapid brain entry and redistribution.', 'Hepatic metabolism via CYP2C19 and CYP3A4 to active metabolites including desmethyldiazepam.', 'Renal excretion of metabolites.', 'Approximately 90% orally', '20-100 hours including active metabolites', 'About 98%', NULL, NULL, 'Within 15-60 minutes orally; minutes IV', 'Prolonged due to active metabolites', ARRAY['Status epilepticus and acute seizures', 'Acute severe anxiety', 'Alcohol withdrawal', 'Muscle spasm', 'Procedural sedation']::text[], ARRAY['Severe respiratory insufficiency', 'Sleep apnoea syndrome', 'Myasthenia gravis', 'Severe hepatic impairment']::text[], ARRAY['Dependence develops within weeks — limit to 2-4 weeks where possible', 'Serious respiratory depression when combined with opioids', 'Do not stop abruptly after regular use']::text[], NULL, ARRAY['Drowsiness', 'Ataxia', 'Confusion', 'Fatigue']::text[], ARRAY['Respiratory depression', 'Dependence and withdrawal seizures', 'Falls and fractures in the elderly']::text[], ARRAY['Opioids', 'Alcohol', 'CYP3A4 inhibitors', 'Other CNS depressants']::text[], NULL, ARRAY['Sedation level', 'Respiratory rate during IV use', 'Duration of therapy']::text[], NULL, NULL, 'Avoid, especially near term (floppy infant syndrome).', 'Accumulates in the infant; avoid repeated doses.', 'Used for acute seizures with weight-based dosing.', 'Very sensitive; high falls risk — avoid where possible.', 'No routine adjustment.', 'Reduce dose; avoid in severe impairment.', ARRAY['Rapid control of seizures and acute agitation', 'Multiple routes including rectal']::text[], ARRAY['Dependence', 'Long-acting metabolites accumulate in the elderly']::text[], ARRAY['Flumazenil reverses sedation but can precipitate seizures']::text[], '"-azepam" → benzodiazepine; long-acting diazepam lingers.', '-azepam', 'dye-AZ-e-pam', 'डा-इ-ऐ-ज़े-पैम', NULL, 'active', 'under_review', NULL, '1.0', '2026-08-19T05:58:50.17128+00:00', '2026-08-19T05:58:50.17128+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('cb35d764-2e3d-44b8-914d-f1ee91a2a9d5', 'amitriptyline', 'Amitriptyline', 'Amitriptyline', 'Amitriptyline', 'Amitriptyline hydrochloride', NULL, 'A tricyclic antidepressant used at low dose for neuropathic pain.', 'Mental Health', ARRAY['10 mg', '25 mg', '75 mg']::text[], ARRAY['Tablet']::text[], ARRAY['Oral']::text[], 'Inhibits reuptake of noradrenaline and serotonin; also blocks muscarinic, histamine H1 and alpha-1 adrenergic receptors.', 'Antidepressant at higher doses; analgesic and sleep-promoting at low doses.', 'Well absorbed orally with significant first-pass metabolism.', 'Highly lipophilic with a large volume of distribution.', 'Hepatic metabolism via CYP2D6 and CYP2C19 to nortriptyline.', 'Renal excretion of metabolites.', 'About 30-60%', '10-28 hours', 'Over 90%', NULL, NULL, 'Analgesic benefit in 1-2 weeks; antidepressant effect in 2-4 weeks', '24 hours', ARRAY['Neuropathic pain', 'Migraine prophylaxis', 'Depression', 'Nocturnal enuresis in children (specialist use)']::text[], ARRAY['Recent myocardial infarction', 'Arrhythmias and heart block', 'Concurrent MAO inhibitors', 'Severe hepatic impairment']::text[], ARRAY['Dangerous in overdose — cardiac arrhythmias and seizures', 'Marked anticholinergic effects', 'Start at a low dose at night']::text[], NULL, ARRAY['Dry mouth', 'Constipation', 'Drowsiness', 'Weight gain', 'Postural hypotension']::text[], ARRAY['Cardiac arrhythmias', 'Seizures', 'Urinary retention', 'Serotonin syndrome']::text[], ARRAY['MAO inhibitors', 'SSRIs', 'Tramadol', 'Anticholinergic drugs', 'QT-prolonging drugs']::text[], NULL, ARRAY['Mood and suicidal ideation early in therapy', 'Blood pressure', 'Anticholinergic effects']::text[], NULL, NULL, 'Use only if clearly needed.', 'Small amounts in milk; usually considered acceptable at low dose.', 'Specialist use only in children.', 'Avoid where possible — falls, confusion and retention.', 'Caution in renal impairment.', 'Reduce dose in hepatic impairment.', ARRAY['Effective in neuropathic pain at low doses', 'Helps sleep', 'Inexpensive']::text[], ARRAY['Anticholinergic burden', 'Dangerous in overdose']::text[], ARRAY['Pain doses (10-75 mg) are much lower than antidepressant doses']::text[], 'TCA = "Tri-C: Cardiac, Convulsions, aantiCholinergic" in overdose.', '-triptyline', 'a-mee-TRIP-ti-leen', 'ऐ-मि-ट्रिप्-टि-लीन', NULL, 'active', 'under_review', NULL, '1.0', '2026-08-19T05:58:50.17128+00:00', '2026-08-19T05:58:50.17128+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('4fc8f59f-56d1-4743-8ca5-d5f73c0b0766', 'fluoxetine', 'Fluoxetine', 'Fluoxetine', 'Fluoxetine', 'Fluoxetine hydrochloride', NULL, 'A long-acting SSRI antidepressant.', 'Mental Health', ARRAY['10 mg', '20 mg', '40 mg']::text[], ARRAY['Capsule', 'Tablet', 'Oral solution']::text[], ARRAY['Oral']::text[], 'Selectively inhibits presynaptic serotonin reuptake, increasing serotonin availability in the synapse.', 'Antidepressant and anxiolytic effect developing over 2-4 weeks; the long half-life reduces discontinuation symptoms.', 'Well absorbed orally; food does not affect absorption significantly.', 'Large volume of distribution; highly protein bound.', 'Hepatic metabolism via CYP2D6 to active norfluoxetine; potent CYP2D6 inhibitor.', 'Renal excretion of metabolites.', 'At least 60-80%', '4-6 days (norfluoxetine 4-16 days)', 'About 94%', NULL, NULL, '2-4 weeks for full effect', '24 hours; effects persist for weeks after stopping', ARRAY['Major depressive disorder', 'Obsessive-compulsive disorder', 'Bulimia nervosa', 'Panic disorder']::text[], ARRAY['Concurrent or recent MAO inhibitor use', 'Concurrent pimozide or thioridazine']::text[], ARRAY['Suicidal thoughts can increase in the first weeks, especially in young people', 'Serotonin syndrome risk with other serotonergic drugs', 'Hyponatraemia in the elderly']::text[], NULL, ARRAY['Nausea', 'Insomnia', 'Headache', 'Sexual dysfunction', 'Anxiety on starting']::text[], ARRAY['Serotonin syndrome', 'Hyponatraemia', 'QT prolongation at high doses', 'Increased bleeding risk with NSAIDs']::text[], ARRAY['MAO inhibitors', 'Tramadol and triptans', 'Warfarin and NSAIDs', 'Tamoxifen (CYP2D6 inhibition)']::text[], NULL, ARRAY['Mood and suicidal ideation', 'Serum sodium in the elderly', 'Weight']::text[], NULL, NULL, 'Used when benefit outweighs risk; specialist advice recommended.', 'Higher milk levels than sertraline; discuss alternatives.', 'Approved in children for depression under specialist care.', 'Watch for hyponatraemia and falls.', 'Caution in severe renal impairment.', 'Reduce dose or extend interval in hepatic impairment.', ARRAY['Long half-life forgives missed doses', 'Well studied in young people']::text[], ARRAY['Activating effects early on', 'Many CYP2D6 interactions']::text[], ARRAY['Review within 1-2 weeks of starting in young patients']::text[], '"Fluoxetine forgives" — the longest half-life among the SSRIs.', '-oxetine', 'floo-OX-e-teen', 'फ्लू-ऑक्-से-टीन', NULL, 'active', 'under_review', NULL, '1.0', '2026-08-19T05:58:50.17128+00:00', '2026-08-19T05:58:50.17128+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('40e883c2-cc1b-43db-953c-abe7f3eb3014', 'sertraline', 'Sertraline', 'Sertraline', 'Sertraline', 'Sertraline hydrochloride', NULL, 'A commonly used first-line SSRI.', 'Mental Health', ARRAY['25 mg', '50 mg', '100 mg']::text[], ARRAY['Tablet']::text[], ARRAY['Oral']::text[], 'Selectively inhibits presynaptic serotonin reuptake with minimal effect on noradrenaline and dopamine.', 'Antidepressant and anxiolytic effect over 2-4 weeks; relatively few pharmacokinetic interactions.', 'Slowly absorbed; food increases absorption.', 'Large volume of distribution; highly protein bound.', 'Extensive hepatic metabolism to the weakly active desmethylsertraline.', 'Renal and faecal excretion of metabolites.', 'Moderate; increased with food', 'About 26 hours', 'About 98%', NULL, NULL, '2-4 weeks for full effect', '24 hours', ARRAY['Major depressive disorder', 'Generalised anxiety and panic disorder', 'Post-traumatic stress disorder', 'Obsessive-compulsive disorder']::text[], ARRAY['Concurrent or recent MAO inhibitor use', 'Concurrent pimozide']::text[], ARRAY['Monitor for increased suicidal thinking in the first weeks', 'Do not stop abruptly — taper to avoid discontinuation symptoms', 'Serotonin syndrome risk with other serotonergic drugs']::text[], NULL, ARRAY['Nausea', 'Diarrhoea', 'Insomnia', 'Sexual dysfunction', 'Headache']::text[], ARRAY['Serotonin syndrome', 'Hyponatraemia', 'Bleeding risk with NSAIDs', 'QT prolongation (rare)']::text[], ARRAY['MAO inhibitors', 'NSAIDs and anticoagulants', 'Tramadol', 'Triptans']::text[], NULL, ARRAY['Mood and suicidal ideation', 'Serum sodium in the elderly', 'Response at 4-6 weeks']::text[], NULL, NULL, 'Often the preferred SSRI in pregnancy when treatment is needed.', 'Low milk levels; commonly preferred while breastfeeding.', 'Used for OCD in children under specialist care.', 'Preferred SSRI in many older patients; watch sodium.', 'No routine adjustment.', 'Reduce dose in hepatic impairment.', ARRAY['Few pharmacokinetic interactions', 'Preferred in pregnancy and breastfeeding', 'Good cardiac safety profile']::text[], ARRAY['GI upset early on', 'Sexual dysfunction']::text[], ARRAY['Take with food to reduce nausea and improve absorption']::text[], 'Sertraline = the "safe starter" SSRI.', '—', 'SER-tra-leen', 'सर्-ट्रा-लीन', NULL, 'active', 'under_review', NULL, '1.0', '2026-08-19T05:58:50.17128+00:00', '2026-08-19T05:58:50.17128+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('d212d7ec-f72a-413d-8467-60e9f709e8e1', 'allopurinol', 'Allopurinol', 'Allopurinol', 'Allopurinol', 'Allopurinol', NULL, 'A xanthine oxidase inhibitor used to prevent gout attacks.', 'Gout', ARRAY['100 mg', '300 mg']::text[], ARRAY['Tablet']::text[], ARRAY['Oral']::text[], 'Inhibits xanthine oxidase, reducing conversion of hypoxanthine and xanthine to uric acid.', 'Lowers serum urate over weeks; does not treat an acute attack and can trigger flares when started.', 'Well absorbed orally.', 'Distributes in body water; minimal protein binding.', 'Converted to the active metabolite oxypurinol.', 'Renal excretion of oxypurinol.', 'About 80%', '1-2 hours (oxypurinol 15-30 hours)', 'Negligible', NULL, NULL, 'Urate falls over 1-2 weeks', '24 hours', ARRAY['Chronic gout', 'Recurrent uric acid stones', 'Tumour lysis syndrome prophylaxis']::text[], ARRAY['Known hypersensitivity', 'Acute gout attack (do not start without anti-inflammatory cover)']::text[], ARRAY['Start low and titrate to target urate; cover with NSAID or colchicine for the first months', 'Stop immediately if a rash develops — allopurinol hypersensitivity syndrome can be fatal', 'HLA-B*5801 raises risk in some Asian populations']::text[], NULL, ARRAY['Rash', 'Nausea', 'Diarrhoea', 'Acute gout flare on initiation']::text[], ARRAY['Severe cutaneous adverse reactions', 'Hepatotoxicity', 'Bone marrow suppression']::text[], ARRAY['Azathioprine and mercaptopurine (serious toxicity)', 'Warfarin', 'Ampicillin (rash)', 'Thiazides']::text[], NULL, ARRAY['Serum urate (target usually below 6 mg/dL)', 'Renal function', 'Full blood count']::text[], NULL, NULL, 'Usually avoided; specialist advice needed.', 'Limited data; seek advice.', 'Used in tumour lysis prophylaxis in children.', 'Start at lower doses with renal decline.', 'Reduce starting dose in renal impairment.', 'Caution in hepatic impairment.', ARRAY['Prevents recurrent gout and tophi', 'Inexpensive']::text[], ARRAY['Flares on initiation', 'Rare but severe hypersensitivity']::text[], ARRAY['Never stop allopurinol during an acute flare if the patient is already established on it']::text[], 'Allopurinol = "prevention, not the fire brigade" for gout.', '—', 'al-oh-PURE-i-nol', 'ऐ-लो-प्यू-रि-नॉल', NULL, 'active', 'under_review', NULL, '1.0', '2026-08-19T05:58:50.17128+00:00', '2026-08-19T05:58:50.17128+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('b0e4f577-b3ef-4d4e-b7d1-70328d77aeef', 'ferrous-sulfate', 'Ferrous sulphate', 'Ferrous sulphate (Iron)', 'Ferrous sulphate', 'Ferrous sulphate (dried)', NULL, 'An oral iron salt used to treat and prevent iron deficiency anaemia.', 'Anaemia & Vitamins', ARRAY['200 mg (about 65 mg elemental iron)', '325 mg']::text[], ARRAY['Tablet', 'Syrup', 'Drops']::text[], ARRAY['Oral']::text[], 'Provides elemental iron for incorporation into haemoglobin, myoglobin and iron-dependent enzymes.', 'Reticulocyte response within a week and haemoglobin rise of about 1-2 g/dL over 3-4 weeks in true deficiency.', 'Absorbed in the duodenum; absorption improves on an empty stomach and with vitamin C, and falls with tea, calcium and antacids.', 'Bound to transferrin and stored as ferritin.', 'Iron is recycled rather than metabolised.', 'Losses occur mainly through shed cells and blood loss.', 'About 10-20% of an oral dose', 'Not applicable (body iron is recycled)', 'Bound to transferrin', NULL, NULL, 'Reticulocytosis in 5-10 days', 'Continue for 3 months after haemoglobin normalises', ARRAY['Iron deficiency anaemia', 'Iron supplementation in pregnancy', 'Prevention in high-risk groups']::text[], ARRAY['Haemochromatosis and iron overload', 'Anaemia not caused by iron deficiency', 'Repeated blood transfusion dependence']::text[], ARRAY['Overdose is a leading cause of poisoning deaths in young children — store out of reach', 'Blackened stools are expected and harmless', 'Do not take with tea, milk or calcium']::text[], NULL, ARRAY['Constipation', 'Nausea', 'Black stools', 'Metallic taste', 'Abdominal discomfort']::text[], ARRAY['Iron overdose in children', 'Severe GI intolerance']::text[], ARRAY['Levothyroxine', 'Tetracyclines and quinolones', 'Antacids and PPIs', 'Calcium supplements']::text[], NULL, ARRAY['Haemoglobin at 3-4 weeks', 'Ferritin after the course', 'Adherence and tolerance']::text[], NULL, NULL, 'Recommended in pregnancy as part of routine supplementation programmes.', 'Compatible with breastfeeding.', 'Weight-based dosing; a major poisoning hazard if a child takes adult tablets.', 'Constipation is common; consider alternate-day dosing.', 'Caution in renal anaemia — IV iron is often preferred.', 'No routine adjustment.', ARRAY['Very inexpensive', 'Effective in true iron deficiency']::text[], ARRAY['GI side effects reduce adherence', 'Absorption blocked by many foods and drugs']::text[], ARRAY['Alternate-day dosing can improve absorption and tolerance']::text[], 'Iron + vitamin C = better absorbed; iron + tea = wasted dose.', '—', 'FER-us SUL-fate', 'फ़े-रस् सल्-फ़ेट', NULL, 'active', 'under_review', NULL, '1.0', '2026-08-19T05:58:50.17128+00:00', '2026-08-19T05:58:50.17128+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('4beeeb8f-2dab-40e7-8503-6331fd35c7ff', 'folic-acid', 'Folic acid', 'Folic acid (Vitamin B9)', 'Folic acid', 'Folic acid', NULL, 'A B vitamin essential in pregnancy and in megaloblastic anaemia.', 'Anaemia & Vitamins', ARRAY['400 mcg', '1 mg', '5 mg']::text[], ARRAY['Tablet']::text[], ARRAY['Oral']::text[], 'Converted to tetrahydrofolate, a cofactor for single-carbon transfers required for DNA and amino acid synthesis.', 'Corrects megaloblastic anaemia and reduces the risk of neural tube defects when taken before conception.', 'Well absorbed from the proximal small intestine.', 'Stored in the liver; distributed to all tissues.', 'Reduced to active tetrahydrofolate in the liver.', 'Renal excretion of excess.', 'Approximately 100% for the synthetic form', 'Not clinically limiting', 'Moderate', NULL, NULL, 'Haematological response within days', 'Daily dosing', ARRAY['Prevention of neural tube defects', 'Megaloblastic anaemia due to folate deficiency', 'Supplementation with methotrexate', 'Haemolytic anaemia and chronic dialysis']::text[], ARRAY['Untreated vitamin B12 deficiency (as sole therapy)', 'Known hypersensitivity']::text[], ARRAY['Giving folate alone in B12 deficiency corrects the anaemia but allows neurological damage to progress', 'Higher doses (5 mg) are recommended for women with diabetes, epilepsy on antiepileptics, or a previous affected pregnancy']::text[], NULL, ARRAY['Nausea', 'Bloating', 'Bitter taste']::text[], ARRAY['Masking of B12 deficiency', 'Hypersensitivity (rare)']::text[], ARRAY['Methotrexate', 'Phenytoin', 'Sulfasalazine', 'Trimethoprim']::text[], NULL, ARRAY['Haemoglobin and blood film', 'Vitamin B12 level before treating megaloblastic anaemia']::text[], NULL, NULL, 'Recommended before conception and through the first trimester.', 'Compatible and often continued while breastfeeding.', 'Used in children with weight-appropriate dosing.', 'Check B12 before starting folate for anaemia.', 'Used in dialysis patients.', 'No routine adjustment.', ARRAY['Very inexpensive', 'Proven prevention of neural tube defects']::text[], ARRAY['Can mask B12 deficiency']::text[], ARRAY['Always check B12 before treating a macrocytic anaemia with folate alone']::text[], 'Folate before pregnancy → protects the spine.', '—', 'FOE-lik AS-id', 'फ़ो-लिक ऐ-सिड', NULL, 'active', 'under_review', NULL, '1.0', '2026-08-19T05:58:50.17128+00:00', '2026-08-19T05:58:50.17128+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('6aa596e4-fd12-428e-843f-e171faf9b84f', 'tamsulosin', 'Tamsulosin', 'Tamsulosin', 'Tamsulosin', 'Tamsulosin hydrochloride', NULL, 'A selective alpha-1A blocker used for benign prostatic hyperplasia.', 'Prostate & Urinary', ARRAY['0.2 mg', '0.4 mg']::text[], ARRAY['Modified-release capsule', 'Tablet']::text[], ARRAY['Oral']::text[], 'Selectively blocks alpha-1A adrenoceptors in prostatic and bladder neck smooth muscle, reducing outflow resistance.', 'Improves urinary flow and symptoms within days without significantly lowering blood pressure in most patients.', 'Well absorbed; food reduces absorption slightly.', 'Highly protein bound; small volume of distribution.', 'Hepatic metabolism via CYP3A4 and CYP2D6.', 'Mainly renal excretion of metabolites.', 'Over 90% fasting', '9-13 hours', 'About 99%', NULL, NULL, 'Within a few days', '24 hours', ARRAY['Lower urinary tract symptoms of benign prostatic hyperplasia', 'Medical expulsive therapy for distal ureteric stones']::text[], ARRAY['History of orthostatic hypotension', 'Known hypersensitivity']::text[], ARRAY['Tell the ophthalmologist before cataract surgery — intraoperative floppy iris syndrome', 'Take at the same time each day, after the same meal', 'Dizziness on standing is common at the start']::text[], NULL, ARRAY['Dizziness', 'Retrograde or reduced ejaculation', 'Headache', 'Nasal congestion']::text[], ARRAY['Syncope', 'Intraoperative floppy iris syndrome', 'Priapism (very rare)']::text[], ARRAY['PDE5 inhibitors such as sildenafil', 'Strong CYP3A4 inhibitors', 'Other alpha blockers', 'Antihypertensives']::text[], NULL, ARRAY['Symptom score', 'Postural blood pressure', 'Planned eye surgery']::text[], NULL, NULL, 'Not applicable — used in men.', 'Not applicable — used in men.', 'Not used in children.', 'Watch for postural hypotension and falls.', 'No routine adjustment in mild to moderate impairment.', 'Caution in severe hepatic impairment.', ARRAY['Rapid symptom relief in BPH', 'Minimal blood pressure effect at standard doses']::text[], ARRAY['Ejaculatory dysfunction', 'Floppy iris syndrome during cataract surgery']::text[], ARRAY['Alpha blockers relieve symptoms quickly; 5-alpha reductase inhibitors shrink the gland slowly']::text[], '"-osin" → alpha blocker for the prostate.', '-osin', 'tam-SOO-loe-sin', 'टैम्-सू-लो-सिन', NULL, 'active', 'under_review', NULL, '1.0', '2026-08-19T05:58:50.17128+00:00', '2026-08-19T05:58:50.17128+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('17d822a2-7cd4-42eb-a541-f5fe76b4cc55', 'meloxicam', 'Meloxicam', 'Meloxicam', 'Meloxicam', 'Meloxicam', NULL, 'Oxicam NSAID with relative COX-2 preference, used for osteoarthritis and rheumatoid arthritis.', 'Pain & Inflammation', ARRAY['7.5 mg', '15 mg']::text[], ARRAY['Tablet', 'Dispersible tablet', 'Injection']::text[], ARRAY['Oral', 'Intramuscular']::text[], 'Inhibits cyclo-oxygenase (relatively COX-2 preferential) reducing prostaglandin synthesis.', 'Analgesic, anti-inflammatory and antipyretic effects with once-daily dosing.', 'Well absorbed orally; peak in 5-6 hours.', 'Extensively distributed into synovial fluid.', 'Hepatic, mainly CYP2C9 with minor CYP3A4.', 'Metabolites excreted in urine and faeces.', 'About 89%', 'Approximately 20 hours', 'About 99%', NULL, NULL, 'Within hours', '24 hours (once daily)', ARRAY['Osteoarthritis', 'Rheumatoid arthritis', 'Ankylosing spondylitis']::text[], ARRAY['NSAID or aspirin hypersensitivity', 'Active peptic ulcer or GI bleeding', 'Severe heart failure', 'Third trimester of pregnancy']::text[], ARRAY['Gastrointestinal bleeding and perforation', 'Cardiovascular thrombotic events', 'Renal impairment with prolonged use']::text[], ARRAY['Use lowest effective dose for shortest duration', 'Caution with hypertension, dehydration or elderly patients']::text[], ARRAY['Dyspepsia', 'Nausea', 'Abdominal pain', 'Dizziness']::text[], ARRAY['GI bleeding', 'Acute kidney injury', 'Severe skin reactions']::text[], ARRAY['Anticoagulants', 'Other NSAIDs', 'ACE inhibitors and diuretics', 'Lithium and methotrexate']::text[], NULL, ARRAY['Renal function', 'Blood pressure', 'Haemoglobin in long-term use']::text[], NULL, NULL, 'Avoid, especially third trimester.', 'Not generally recommended; discuss with clinician.', 'Not routinely used in young children.', 'Increased GI and renal risk; use with caution.', 'Avoid in severe renal impairment.', 'Avoid in severe hepatic impairment.', ARRAY['Once-daily dosing', 'Relative COX-2 preference at low dose']::text[], ARRAY['Still carries NSAID GI and cardiovascular risk']::text[], ARRAY['Oxicam class NSAID', 'Long half-life allows once-daily use']::text[], '"-oxicam" → long-acting NSAIDs. Learning aid — exceptions exist.', '-oxicam', 'mel-OX-i-kam', 'मे-लॉक्-सी-कैम', '/mɛˈlɒksɪkæm/', 'active', 'verified', '2026-09-04', '3.0', '2026-09-04T05:57:04.600691+00:00', '2026-09-04T05:57:04.600691+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('6b418e37-bc28-49b0-8970-d919a6cbacb0', 'ketorolac', 'Ketorolac', 'Ketorolac', 'Ketorolac tromethamine', 'Tromethamine', NULL, 'Potent short-term NSAID analgesic used mainly for acute moderate to severe pain.', 'Pain & Inflammation', ARRAY['10 mg tablet', '30 mg/mL injection']::text[], ARRAY['Injection', 'Tablet', 'Eye drops']::text[], ARRAY['Intramuscular', 'Intravenous', 'Oral', 'Ophthalmic']::text[], 'Non-selective COX inhibition reducing prostaglandin-mediated pain and inflammation.', 'Analgesic potency approaching opioids for short-term acute pain, without opioid effects.', 'Rapid and complete after intramuscular injection.', 'Low volume of distribution; crosses into synovial fluid.', 'Hepatic glucuronidation and hydroxylation.', 'Mainly renal.', 'Almost 100% (IM)', 'About 5-6 hours', 'More than 99%', NULL, NULL, '30 minutes (IM)', '4-6 hours', ARRAY['Short-term management of acute moderate to severe pain', 'Postoperative pain', 'Ocular inflammation (eye drops)']::text[], ARRAY['Peptic ulcer or GI bleeding', 'Bleeding disorders', 'Severe renal impairment', 'Labour, delivery and breastfeeding']::text[], ARRAY['Total treatment must not exceed 5 days', 'High risk of GI bleeding and renal injury', 'Not for neuraxial administration']::text[], ARRAY['Ensure hydration', 'Avoid combining with other NSAIDs']::text[], ARRAY['Injection site pain', 'Nausea', 'Dyspepsia', 'Drowsiness']::text[], ARRAY['GI haemorrhage', 'Acute renal failure', 'Bronchospasm in NSAID-sensitive asthma']::text[], ARRAY['Anticoagulants', 'Other NSAIDs', 'Probenecid', 'ACE inhibitors']::text[], NULL, ARRAY['Renal function', 'Signs of GI bleeding']::text[], NULL, NULL, 'Avoid.', 'Contraindicated.', 'Restricted in children; specialist decision.', 'Reduce dose and duration.', 'Contraindicated in advanced renal impairment.', 'Use with caution.', ARRAY['Strong non-opioid analgesia for acute pain']::text[], ARRAY['Strict 5-day limit', 'Significant bleeding and renal risk']::text[], ARRAY['Short-course NSAID only', 'Never combine with other systemic NSAIDs']::text[], 'Ketorolac = "opioid-strength NSAID, five-day maximum". Learning aid — exceptions exist.', NULL, 'kee-TOR-oh-lak', 'की-टो-रो-लैक', '/kiːˈtɔːrəlæk/', 'active', 'verified', '2026-09-04', '3.0', '2026-09-04T05:57:04.600691+00:00', '2026-09-04T05:57:04.600691+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('55b66c74-eed6-45fd-93bb-eeff27f0e0db', 'indomethacin', 'Indomethacin', 'Indomethacin', 'Indomethacin', 'Indomethacin', NULL, 'Potent non-selective NSAID used in gout, inflammatory arthritis and patent ductus arteriosus.', 'Pain & Inflammation', ARRAY['25 mg', '50 mg', '75 mg SR']::text[], ARRAY['Capsule', 'Sustained-release capsule', 'Suppository', 'Injection']::text[], ARRAY['Oral', 'Rectal', 'Intravenous']::text[], 'Potent non-selective inhibition of COX-1 and COX-2.', 'Strong anti-inflammatory action; in neonates closes the ductus arteriosus by removing prostaglandin support.', 'Rapid and near complete oral absorption.', 'Crosses blood-brain barrier and placenta.', 'Hepatic; also enterohepatic recirculation.', 'Renal and biliary.', 'About 90%', 'Approximately 4.5 hours', 'About 99%', NULL, NULL, 'Within 1-2 hours', '4-6 hours (longer for SR)', ARRAY['Acute gout', 'Rheumatoid arthritis and ankylosing spondylitis', 'Patent ductus arteriosus in neonates (specialist use)']::text[], ARRAY['Active peptic ulcer', 'NSAID hypersensitivity', 'Severe renal or heart failure']::text[], ARRAY['High rate of CNS effects such as headache', 'Significant GI toxicity']::text[], ARRAY['Take with food', 'Avoid in patients with epilepsy or parkinsonism where possible']::text[], ARRAY['Frontal headache', 'Dizziness', 'Dyspepsia', 'Nausea']::text[], ARRAY['GI bleeding', 'Acute kidney injury', 'Confusion in elderly']::text[], ARRAY['Anticoagulants', 'Lithium', 'Diuretics and ACE inhibitors']::text[], NULL, ARRAY['Renal function', 'GI symptoms', 'CNS side effects']::text[], NULL, NULL, 'Avoid; contraindicated in third trimester.', 'Not recommended.', 'Neonatal use only under specialist supervision.', 'High CNS and GI risk; avoid where possible.', 'Avoid in significant impairment.', 'Use with caution.', ARRAY['Very potent anti-inflammatory action']::text[], ARRAY['Prominent headache and GI adverse effects']::text[], ARRAY['Classic gout NSAID', 'Also used for neonatal PDA closure']::text[], 'Indomethacin = "potent but heady" — headache is its signature. Learning aid — exceptions exist.', NULL, 'in-doh-METH-a-sin', 'इन्-डो-मेथ-ा-सिन', '/ˌɪndəˈmɛθəsɪn/', 'active', 'verified', '2026-09-04', '3.0', '2026-09-04T05:57:04.600691+00:00', '2026-09-04T05:57:04.600691+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('a5d5126f-c8f9-4e85-b0ba-bfae9edb0310', 'piroxicam', 'Piroxicam', 'Piroxicam', 'Piroxicam', 'Piroxicam', NULL, 'Long-acting oxicam NSAID used in chronic arthritic conditions.', 'Pain & Inflammation', ARRAY['10 mg', '20 mg']::text[], ARRAY['Capsule', 'Dispersible tablet', 'Gel', 'Injection']::text[], ARRAY['Oral', 'Topical', 'Intramuscular']::text[], 'Non-selective COX inhibition reducing prostaglandin synthesis.', 'Sustained anti-inflammatory effect permitting once-daily dosing.', 'Well absorbed orally.', 'Widely distributed; enters synovial fluid.', 'Hepatic, chiefly CYP2C9.', 'Renal, with some biliary elimination.', 'Nearly complete', 'About 50 hours', 'About 99%', NULL, NULL, '1-2 hours', '24 hours or longer', ARRAY['Osteoarthritis', 'Rheumatoid arthritis', 'Ankylosing spondylitis']::text[], ARRAY['Peptic ulcer disease', 'NSAID hypersensitivity', 'Severe heart, renal or hepatic failure']::text[], ARRAY['Higher GI and serious skin reaction risk than many NSAIDs', 'Not first-line NSAID']::text[], ARRAY['Consider gastroprotection', 'Review need regularly']::text[], ARRAY['Dyspepsia', 'Nausea', 'Oedema', 'Rash']::text[], ARRAY['GI bleeding', 'Stevens-Johnson syndrome', 'Acute kidney injury']::text[], ARRAY['Anticoagulants', 'Other NSAIDs', 'Lithium', 'Methotrexate']::text[], NULL, ARRAY['Renal function', 'GI symptoms', 'Skin reactions']::text[], NULL, NULL, 'Avoid.', 'Not recommended.', 'Not recommended in children.', 'Avoid; accumulates due to long half-life.', 'Avoid in significant impairment.', 'Avoid in severe impairment.', ARRAY['Once-daily dosing due to long half-life']::text[], ARRAY['Long half-life increases toxicity risk', 'Restricted as second-line in many guidelines']::text[], ARRAY['Oxicam NSAID with ~50 hour half-life']::text[], '"-oxicam" → oxicam family, long half-life. Learning aid — exceptions exist.', '-oxicam', 'peer-OX-i-kam', 'पी-रॉक्-सी-कैम', '/pɪˈrɒksɪkæm/', 'active', 'verified', '2026-09-04', '3.0', '2026-09-04T05:57:04.600691+00:00', '2026-09-04T05:57:04.600691+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('0e423589-aad0-44c3-a04f-04860c190e07', 'celecoxib', 'Celecoxib', 'Celecoxib', 'Celecoxib', 'Celecoxib', NULL, 'Selective COX-2 inhibitor NSAID with lower gastrointestinal ulcer risk than non-selective NSAIDs.', 'Pain & Inflammation', ARRAY['100 mg', '200 mg']::text[], ARRAY['Capsule']::text[], ARRAY['Oral']::text[], 'Selectively inhibits COX-2, reducing inflammatory prostaglandins while largely sparing COX-1 in gastric mucosa.', 'Anti-inflammatory and analgesic with less platelet inhibition than non-selective NSAIDs.', 'Peak plasma level in about 3 hours; food increases absorption.', 'Widely distributed.', 'Hepatic, mainly CYP2C9.', 'Metabolites in faeces and urine.', 'Not precisely established', 'About 11 hours', 'About 97%', NULL, NULL, 'Within hours', '12-24 hours', ARRAY['Osteoarthritis', 'Rheumatoid arthritis', 'Ankylosing spondylitis', 'Acute pain']::text[], ARRAY['Sulfonamide hypersensitivity', 'Ischaemic heart disease or stroke', 'Severe heart failure', 'Active GI bleeding']::text[], ARRAY['Cardiovascular thrombotic risk', 'Renal impairment risk']::text[], ARRAY['Use lowest effective dose', 'CYP2C9 poor metabolisers need lower doses']::text[], ARRAY['Dyspepsia', 'Diarrhoea', 'Peripheral oedema', 'Headache']::text[], ARRAY['Myocardial infarction or stroke', 'Serious skin reactions', 'Acute kidney injury']::text[], ARRAY['Warfarin', 'Fluconazole (raises celecoxib levels)', 'ACE inhibitors and diuretics']::text[], NULL, ARRAY['Blood pressure', 'Renal function', 'Cardiovascular symptoms']::text[], NULL, NULL, 'Avoid, particularly third trimester.', 'Not recommended.', 'Limited paediatric indications; specialist use.', 'Use with caution.', 'Avoid in severe impairment.', 'Reduce dose in moderate impairment; avoid if severe.', ARRAY['Lower GI ulcer risk than non-selective NSAIDs', 'Does not impair platelet function significantly']::text[], ARRAY['Cardiovascular risk', 'Sulfonamide-related hypersensitivity']::text[], ARRAY['"-coxib" identifies COX-2 selectivity', 'Avoid in established cardiovascular disease']::text[], '"-coxib" → COX-2 inhibitor: stomach-kinder, heart-cautious. Learning aid — exceptions exist.', '-coxib', 'sel-e-KOX-ib', 'से-ले-कॉक्-सिब', '/ˌsɛlɪˈkɒksɪb/', 'active', 'verified', '2026-09-04', '3.0', '2026-09-04T05:57:04.600691+00:00', '2026-09-04T05:57:04.600691+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('ae7e7a4d-743b-47b8-8766-2f71ca95b315', 'tapentadol', 'Tapentadol', 'Tapentadol', 'Tapentadol', 'Tapentadol hydrochloride', NULL, 'Centrally acting analgesic combining opioid agonism with noradrenaline reuptake inhibition.', 'Pain & Inflammation', ARRAY['50 mg', '75 mg', '100 mg']::text[], ARRAY['Tablet', 'Extended-release tablet']::text[], ARRAY['Oral']::text[], 'Mu-opioid receptor agonist and noradrenaline reuptake inhibitor.', 'Analgesia for nociceptive and neuropathic pain with dual mechanism.', 'Rapidly absorbed; extensive first-pass metabolism.', 'Volume of distribution about 540 L.', 'Mainly glucuronidation.', 'Renal, largely as conjugates.', 'About 32%', 'About 4 hours', 'About 20%', NULL, NULL, 'Within 1 hour', '4-6 hours (12 hours ER)', ARRAY['Moderate to severe acute pain', 'Chronic pain including diabetic neuropathic pain (ER)']::text[], ARRAY['Severe respiratory depression', 'Paralytic ileus', 'Use with or within 14 days of MAO inhibitors']::text[], ARRAY['Controlled substance with dependence and misuse potential', 'Respiratory depression', 'Serotonin syndrome risk with serotonergic drugs']::text[], ARRAY['Avoid alcohol', 'Taper on discontinuation']::text[], ARRAY['Nausea', 'Dizziness', 'Somnolence', 'Constipation']::text[], ARRAY['Respiratory depression', 'Seizures', 'Serotonin syndrome']::text[], ARRAY['MAO inhibitors', 'SSRIs and SNRIs', 'Benzodiazepines and other CNS depressants']::text[], NULL, ARRAY['Pain scores', 'Sedation and respiratory rate', 'Signs of misuse']::text[], NULL, NULL, 'Avoid unless clearly necessary.', 'Not recommended.', 'Not established in young children.', 'Start low; increased sedation risk.', 'Avoid in severe impairment.', 'Avoid in severe impairment.', ARRAY['Dual mechanism useful in mixed pain', 'Less constipation than classical opioids']::text[], ARRAY['Opioid dependence potential', 'Regulated prescribing requirements']::text[], ARRAY['Opioid plus noradrenergic action', 'Never combine with MAO inhibitors']::text[], 'Tapentadol = "tramadol''s cousin, noradrenaline not serotonin". Learning aid — exceptions exist.', NULL, 'ta-PEN-ta-dol', 'टै-पेन्-टा-डॉल', '/təˈpɛntədɒl/', 'active', 'verified', '2026-09-04', '3.0', '2026-09-04T05:57:04.600691+00:00', '2026-09-04T05:57:04.600691+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('20fdff34-b11f-4bee-a1d2-64ad2e577404', 'esomeprazole', 'Esomeprazole', 'Esomeprazole', 'Esomeprazole', 'Esomeprazole magnesium / sodium', NULL, 'S-isomer of omeprazole; a proton pump inhibitor for acid-related disorders.', 'Acidity & GERD', ARRAY['20 mg', '40 mg']::text[], ARRAY['Capsule', 'Tablet', 'Injection']::text[], ARRAY['Oral', 'Intravenous']::text[], 'Irreversibly inhibits the gastric H+/K+ ATPase proton pump in parietal cells.', 'Profound and prolonged suppression of gastric acid secretion.', 'Acid-labile; given as enteric-coated formulation, peak in 1-2 hours.', 'Volume of distribution about 16 L.', 'Hepatic via CYP2C19 and CYP3A4.', 'Mostly renal as metabolites.', 'About 64-90% with repeated dosing', 'About 1-1.5 hours', 'About 97%', NULL, NULL, 'Within 1 hour', 'Up to 24 hours (irreversible pump block)', ARRAY['Gastro-oesophageal reflux disease', 'Peptic ulcer disease', 'H. pylori eradication regimens', 'NSAID ulcer prophylaxis', 'Zollinger-Ellison syndrome']::text[], ARRAY['Hypersensitivity to substituted benzimidazoles', 'Co-administration with rilpivirine']::text[], ARRAY['Long-term use linked with hypomagnesaemia, B12 deficiency and fracture risk', 'May mask gastric malignancy']::text[], ARRAY['Take 30-60 minutes before food', 'Review need for long-term therapy']::text[], ARRAY['Headache', 'Diarrhoea', 'Abdominal pain', 'Nausea']::text[], ARRAY['Clostridioides difficile colitis', 'Hypomagnesaemia', 'Acute interstitial nephritis']::text[], ARRAY['Clopidogrel (reduced activation)', 'Atazanavir and rilpivirine', 'Methotrexate', 'Drugs needing gastric acid for absorption']::text[], NULL, ARRAY['Magnesium in long-term use', 'Vitamin B12 in prolonged therapy', 'Symptom response']::text[], NULL, NULL, 'Considered acceptable when needed; use clinical judgement.', 'Limited data; use if clearly needed.', 'Paediatric formulations exist for GERD.', 'No routine dose change.', 'No dose change usually needed.', 'Reduce dose in severe impairment.', ARRAY['Strong, reliable acid suppression', 'Once-daily dosing']::text[], ARRAY['Interactions via CYP2C19', 'Long-term use has nutritional risks']::text[], ARRAY['"-prazole" suffix marks proton pump inhibitors', 'Dose before the first meal of the day']::text[], '"-prazole" → proton pump inhibitor; take before food. Learning aid — exceptions exist.', '-prazole', 'es-oh-MEP-ra-zole', 'ए-सो-मे-प्रा-ज़ोल', '/ˌɛsoʊˈmɛprəzoʊl/', 'active', 'verified', '2026-09-04', '3.0', '2026-09-04T05:57:04.600691+00:00', '2026-09-04T05:57:04.600691+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('30117acd-9953-4f12-98e6-948143f0401e', 'itopride', 'Itopride', 'Itopride', 'Itopride', 'Itopride hydrochloride', NULL, 'Prokinetic agent used for functional dyspepsia and gastric motility disorders.', 'Gastrointestinal', ARRAY['50 mg', '150 mg SR']::text[], ARRAY['Tablet', 'Sustained-release capsule']::text[], ARRAY['Oral']::text[], 'Dopamine D2 receptor antagonism plus acetylcholinesterase inhibition, increasing gastric acetylcholine.', 'Enhances gastric motility and accelerates gastric emptying; also antiemetic.', 'Rapidly absorbed; peak in about 35 minutes.', 'Poor CNS penetration.', 'Hepatic via flavin-containing monooxygenase.', 'Mainly renal.', 'About 60%', 'About 6 hours', 'About 96%', NULL, NULL, 'Within 1 hour', '6-8 hours', ARRAY['Functional dyspepsia', 'Non-ulcer bloating, early satiety and nausea']::text[], ARRAY['GI haemorrhage, obstruction or perforation', 'Known hypersensitivity']::text[], ARRAY['Prolactin elevation possible', 'Discontinue if extrapyramidal symptoms occur']::text[], ARRAY['Take before meals', 'Review after symptom control']::text[], ARRAY['Diarrhoea', 'Abdominal pain', 'Headache', 'Dizziness']::text[], ARRAY['Extrapyramidal reactions (rare)', 'Hyperprolactinaemia']::text[], ARRAY['Anticholinergic drugs (reduce effect)', 'Other dopamine antagonists']::text[], NULL, ARRAY['Symptom improvement', 'Prolactin-related symptoms with long-term use']::text[], NULL, NULL, 'Avoid unless clearly necessary.', 'Not recommended.', 'Not established in children.', 'Use with caution.', 'Use with caution.', 'Use with caution.', ARRAY['Minimal CNS penetration compared with metoclopramide', 'Not significantly metabolised by CYP450']::text[], ARRAY['Limited long-term outcome data']::text[], ARRAY['Dual prokinetic mechanism', 'Taken before meals']::text[], 'Itopride = prokinetic that "pushes food along" with two mechanisms. Learning aid — exceptions exist.', NULL, 'eye-TOE-pride', 'आइ-टो-प्राइड', '/aɪˈtoʊpraɪd/', 'active', 'verified', '2026-09-04', '3.0', '2026-09-04T05:57:04.600691+00:00', '2026-09-04T05:57:04.600691+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('6ee7fe89-86af-46a9-b33b-e2ef33aaff12', 'bisacodyl', 'Bisacodyl', 'Bisacodyl', 'Bisacodyl', 'Bisacodyl', NULL, 'Stimulant laxative used for short-term constipation and bowel preparation.', 'Gastrointestinal', ARRAY['5 mg tablet', '10 mg suppository']::text[], ARRAY['Enteric-coated tablet', 'Suppository']::text[], ARRAY['Oral', 'Rectal']::text[], 'Stimulates colonic mucosal nerve endings, increasing peristalsis and reducing water absorption.', 'Produces a bowel movement typically 6-12 hours after an oral dose.', 'Minimal systemic absorption from the gut.', 'Acts locally in the colon.', 'Hydrolysed by intestinal and bacterial enzymes to the active metabolite.', 'Faeces, with a small amount in urine.', 'Minimal systemic', 'Not clinically relevant (local action)', 'Not applicable', NULL, NULL, '6-12 hours oral; 15-60 minutes rectal', 'Single evacuation', ARRAY['Short-term constipation', 'Bowel preparation before procedures']::text[], ARRAY['Intestinal obstruction', 'Acute abdominal conditions such as appendicitis', 'Severe dehydration']::text[], ARRAY['Chronic use can cause electrolyte disturbance and laxative dependence']::text[], ARRAY['Swallow enteric-coated tablets whole', 'Do not take within 1 hour of antacids or milk']::text[], ARRAY['Abdominal cramps', 'Diarrhoea', 'Nausea']::text[], ARRAY['Hypokalaemia with prolonged misuse', 'Dehydration']::text[], ARRAY['Antacids and milk (disrupt enteric coating)', 'Diuretics and corticosteroids (electrolyte loss)']::text[], NULL, ARRAY['Bowel habit', 'Electrolytes with prolonged use']::text[], NULL, NULL, 'Generally considered acceptable short-term; seek advice.', 'Minimal absorption; considered compatible.', 'Used in children with medical advice.', 'Watch fluid and electrolyte balance.', 'Caution with electrolyte disturbance.', 'No specific adjustment.', ARRAY['Predictable, inexpensive short-term relief']::text[], ARRAY['Cramping', 'Not suitable for long-term use']::text[], ARRAY['Stimulant laxative', 'Enteric coating must stay intact']::text[], 'Bisacodyl = "night-time tablet, morning result". Learning aid — exceptions exist.', NULL, 'bis-AK-oh-dil', 'बिस्-ऐ-को-डिल', '/bɪsˈækədɪl/', 'active', 'verified', '2026-09-04', '3.0', '2026-09-04T05:57:04.600691+00:00', '2026-09-04T05:57:04.600691+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('77bf323f-be74-48ad-abb3-8f0c9638aa40', 'mesalazine', 'Mesalazine', 'Mesalazine (5-ASA)', 'Mesalazine', '5-aminosalicylic acid', NULL, 'Aminosalicylate used for induction and maintenance of remission in ulcerative colitis.', 'Gastrointestinal', ARRAY['400 mg', '800 mg', '1.2 g']::text[], ARRAY['Delayed-release tablet', 'Sustained-release granules', 'Suppository', 'Enema']::text[], ARRAY['Oral', 'Rectal']::text[], 'Local anti-inflammatory action on colonic mucosa, inhibiting prostaglandin and leukotriene production and scavenging free radicals.', 'Reduces mucosal inflammation in inflammatory bowel disease.', 'Formulation dependent; designed for delivery to distal bowel.', 'Acts topically on gut mucosa.', 'Acetylated in gut mucosa and liver to N-acetyl-5-ASA.', 'Renal and faecal.', 'Formulation dependent', 'About 5-10 hours (acetyl metabolite)', 'About 43%', NULL, NULL, 'Days to weeks for clinical effect', 'Maintenance therapy', ARRAY['Ulcerative colitis (induction and maintenance)', 'Mild Crohn disease involving the colon']::text[], ARRAY['Salicylate hypersensitivity', 'Severe renal or hepatic impairment']::text[], ARRAY['Rare renal toxicity including interstitial nephritis', 'Mesalazine-induced acute intolerance syndrome may mimic a colitis flare']::text[], ARRAY['Maintain hydration', 'Do not crush modified-release forms']::text[], ARRAY['Headache', 'Nausea', 'Abdominal pain', 'Diarrhoea']::text[], ARRAY['Interstitial nephritis', 'Pancreatitis', 'Blood dyscrasias']::text[], ARRAY['Azathioprine and mercaptopurine (myelosuppression)', 'Nephrotoxic drugs such as NSAIDs']::text[], NULL, ARRAY['Renal function before and during treatment', 'Full blood count']::text[], NULL, NULL, 'Widely used in pregnancy when indicated; specialist guidance.', 'Small amounts in milk; usually acceptable with monitoring.', 'Used in children under specialist care.', 'Monitor renal function.', 'Avoid in significant impairment.', 'Caution in impairment.', ARRAY['Topical gut action with limited systemic exposure', 'Effective maintenance therapy in ulcerative colitis']::text[], ARRAY['High pill burden', 'Requires renal monitoring']::text[], ARRAY['First-line for mild to moderate ulcerative colitis', 'Rectal forms suit distal disease']::text[], '5-ASA = "aspirin''s cousin that stays in the colon". Learning aid — exceptions exist.', NULL, 'me-SAL-a-zeen', 'मे-सै-ला-ज़ीन', '/mɛˈsæləziːn/', 'active', 'verified', '2026-09-04', '3.0', '2026-09-04T05:57:04.600691+00:00', '2026-09-04T05:57:04.600691+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('ceb7c8e8-b8a5-43a8-b454-061c96eb491e', 'prochlorperazine', 'Prochlorperazine', 'Prochlorperazine', 'Prochlorperazine', 'Prochlorperazine maleate', NULL, 'Phenothiazine dopamine antagonist used for nausea, vomiting and vertigo.', 'Antiemetics', ARRAY['5 mg', '10 mg']::text[], ARRAY['Tablet', 'Buccal tablet', 'Injection']::text[], ARRAY['Oral', 'Buccal', 'Intramuscular']::text[], 'Blocks D2 dopamine receptors in the chemoreceptor trigger zone; also antihistaminic and anticholinergic.', 'Antiemetic, antivertigo and mild antipsychotic activity.', 'Absorbed orally with substantial first-pass metabolism.', 'Widely distributed; crosses blood-brain barrier.', 'Extensive hepatic metabolism.', 'Renal and biliary.', 'Low and variable orally', 'About 6-9 hours', 'More than 90%', NULL, NULL, '30-60 minutes oral', '3-4 hours', ARRAY['Nausea and vomiting', 'Vertigo including Meniere disease', 'Labyrinthine disorders']::text[], ARRAY['CNS depression or coma', 'Known phenothiazine hypersensitivity', 'Children under 2 years or under 10 kg']::text[], ARRAY['Extrapyramidal reactions including acute dystonia', 'QT prolongation', 'Neuroleptic malignant syndrome (rare)']::text[], ARRAY['Avoid alcohol', 'C