producers']::text[], ARRAY['Diarrhoea', 'Rash', 'Injection site reactions', 'Nausea']::text[], ARRAY['Anaphylaxis', 'C. difficile colitis', 'Neutropenia with prolonged use']::text[], ARRAY['Probenecid', 'Aminoglycosides (inactivation if mixed in the same line)', 'Methotrexate']::text[], NULL, ARRAY['Renal function', 'Full blood count in prolonged therapy', 'Clinical response']::text[], NULL, NULL, 'Considered acceptable when indicated.', 'Considered compatible.', 'Weight-based dosing in children.', 'Adjust for renal function.', 'Dose reduction required.', 'No routine adjustment.', ARRAY['Broad Gram-negative and anti-pseudomonal cover']::text[], ARRAY['Injection only', 'Broad-spectrum resistance pressure']::text[], ARRAY['Ureidopenicillin', 'Almost always used with tazobactam']::text[], 'Piperacillin = "big-gun penicillin for pseudomonas". Learning aid — exceptions exist.', '-cillin', 'pi-PER-a-sil-in', 'पि-पे-रा-सि-लिन', '/pɪˈpɛrəsɪlɪn/', 'active', 'verified', '2026-09-05', '3.0', '2026-09-05T22:19:27.659977+00:00', '2026-09-05T22:19:27.659977+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('a077f072-7c9c-4845-aa41-413ac22e0192', 'piperacillin-tazobactam', 'Piperacillin + Tazobactam', 'Piperacillin + Tazobactam', 'Piperacillin; Tazobactam', 'Piperacillin sodium + tazobactam sodium', NULL, 'Fixed-dose combination of a ureidopenicillin with a beta-lactamase inhibitor for severe infections.', 'Antibiotics', ARRAY['4.5 g (4 g + 0.5 g)', '2.25 g']::text[], ARRAY['Injection']::text[], ARRAY['Intravenous']::text[], 'Piperacillin inhibits cell wall synthesis while tazobactam protects it from bacterial beta-lactamases.', 'Broad bactericidal activity including Pseudomonas, Enterobacterales and anaerobes.', 'Parenteral administration only.', 'Good tissue and peritoneal penetration.', 'Minimal metabolism of both components.', 'Mainly renal.', 'Parenteral only', 'About 1 hour for both components', 'About 30%', NULL, NULL, 'Immediate', '6-8 hours', ARRAY['Severe hospital-acquired infections', 'Intra-abdominal sepsis', 'Complicated skin and soft tissue infection', 'Febrile neutropenia']::text[], ARRAY['Beta-lactam hypersensitivity']::text[], ARRAY['Anaphylaxis', 'Neurotoxicity if dose not adjusted in renal impairment', 'Possible added nephrotoxicity with vancomycin']::text[], ARRAY['Renal dose adjustment', 'De-escalate once cultures return']::text[], ARRAY['Diarrhoea', 'Rash', 'Nausea', 'Injection site reaction']::text[], ARRAY['C. difficile colitis', 'Anaphylaxis', 'Acute kidney injury', 'Thrombocytopenia']::text[], ARRAY['Vancomycin (nephrotoxicity)', 'Aminoglycosides', 'Methotrexate', 'Probenecid']::text[], NULL, ARRAY['Renal function', 'Full blood count', 'Clinical and microbiological response']::text[], NULL, NULL, 'Used in pregnancy when clearly indicated.', 'Considered compatible.', 'Weight-based paediatric dosing.', 'Renal dose adjustment often needed.', 'Reduce dose and frequency.', 'No routine adjustment.', ARRAY['Very broad empirical cover for severe sepsis']::text[], ARRAY['Reserved agent — resistance and cost concerns']::text[], ARRAY['Combination product: active drug plus enzyme inhibitor', 'Component ingredients tracked separately']::text[], 'Tazobactam = "the shield" protecting piperacillin from enzymes. Learning aid — exceptions exist.', NULL, 'pi-PER-a-sil-in taz-oh-BAK-tam', 'पि-पे-रा-सि-लिन टै-ज़ो-बैक्-टैम', NULL, 'active', 'verified', '2026-09-05', '3.0', '2026-09-05T22:19:27.659977+00:00', '2026-09-05T22:19:27.659977+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('3165ee6f-64d3-4df5-b456-c69aa0b5b807', 'cefpodoxime', 'Cefpodoxime', 'Cefpodoxime', 'Cefpodoxime proxetil', 'Proxetil ester', NULL, 'Oral third-generation cephalosporin for respiratory, urinary and skin infections.', 'Antibiotics', ARRAY['100 mg', '200 mg']::text[], ARRAY['Tablet', 'Oral suspension']::text[], ARRAY['Oral']::text[], 'Inhibits bacterial cell wall synthesis via penicillin-binding proteins; stable to many beta-lactamases.', 'Bactericidal against many Gram-positive and Gram-negative respiratory and urinary pathogens.', 'Prodrug absorbed and hydrolysed to active drug; food improves absorption.', 'Good tissue penetration including lung and tonsils.', 'Ester hydrolysis to active cefpodoxime.', 'Mainly renal.', 'About 50% with food', '2-3 hours', '22-33%', NULL, NULL, '1-2 hours', '12 hours', ARRAY['Community-acquired pneumonia and bronchitis', 'Acute otitis media and sinusitis', 'Uncomplicated urinary tract infection', 'Skin and soft tissue infection']::text[], ARRAY['Cephalosporin hypersensitivity', 'Severe penicillin anaphylaxis history']::text[], ARRAY['C. difficile colitis', 'Cross-reactivity with penicillin allergy']::text[], ARRAY['Take with food', 'Complete the course']::text[], ARRAY['Diarrhoea', 'Nausea', 'Abdominal pain', 'Rash']::text[], ARRAY['Anaphylaxis', 'C. difficile colitis', 'Stevens-Johnson syndrome (rare)']::text[], ARRAY['Antacids and H2 blockers (reduce absorption)', 'Probenecid']::text[], NULL, ARRAY['Clinical response', 'Renal function in impairment']::text[], NULL, NULL, 'Considered acceptable when indicated.', 'Considered compatible.', 'Common paediatric suspension.', 'Adjust for renal function.', 'Increase dosing interval in impairment.', 'No routine adjustment.', ARRAY['Oral third-generation cover', 'Twice-daily dosing']::text[], ARRAY['Absorption reduced by acid suppressants', 'Broad-spectrum resistance pressure']::text[], ARRAY['Oral 3rd-generation cephalosporin', 'Needs gastric acid and food for absorption']::text[], '"cef-" → cephalosporin; higher generation, wider Gram-negative reach. Learning aid — exceptions exist.', 'cef-', 'sef-poe-DOX-eem', 'सेफ़्-पो-डॉक्-सीम', '/ˌsɛfpoʊˈdɒksiːm/', 'active', 'verified', '2026-09-05', '3.0', '2026-09-05T22:19:27.659977+00:00', '2026-09-05T22:19:27.659977+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('08626be6-6b8a-472c-a75a-21478517ec16', 'cefoperazone', 'Cefoperazone', 'Cefoperazone', 'Cefoperazone', 'Sodium salt', NULL, 'Third-generation injectable cephalosporin with biliary excretion and anti-pseudomonal activity.', 'Antibiotics', ARRAY['1 g', '2 g']::text[], ARRAY['Injection']::text[], ARRAY['Intravenous', 'Intramuscular']::text[], 'Inhibits bacterial cell wall synthesis by binding penicillin-binding proteins.', 'Bactericidal with useful activity against Pseudomonas and Enterobacterales.', 'Parenteral only.', 'High biliary concentrations.', 'Minimal metabolism.', 'Predominantly biliary.', 'Parenteral only', 'About 2 hours', '82-93%', NULL, NULL, 'Immediate', '8-12 hours', ARRAY['Intra-abdominal and biliary tract infection', 'Respiratory tract infection', 'Septicaemia']::text[], ARRAY['Cephalosporin hypersensitivity']::text[], ARRAY['Hypoprothrombinaemia and bleeding risk (N-methylthiotetrazole side chain)', 'Disulfiram-like reaction with alcohol']::text[], ARRAY['Consider vitamin K in prolonged therapy', 'Avoid alcohol during and shortly after treatment']::text[], ARRAY['Diarrhoea', 'Rash', 'Injection site pain']::text[], ARRAY['Bleeding due to hypoprothrombinaemia', 'C. difficile colitis', 'Anaphylaxis']::text[], ARRAY['Warfarin and anticoagulants', 'Alcohol', 'Aminoglycosides']::text[], NULL, ARRAY['Prothrombin time', 'Clinical response', 'Liver function']::text[], NULL, NULL, 'Use when clearly indicated.', 'Considered compatible.', 'Weight-based paediatric dosing.', 'Monitor for bleeding.', 'Minimal adjustment (biliary excretion).', 'Reduce dose in significant impairment.', ARRAY['Useful in biliary infections', 'Retains activity in renal impairment']::text[], ARRAY['Bleeding risk', 'Alcohol interaction']::text[], ARRAY['Biliary-excreted cephalosporin', 'Watch prothrombin time']::text[], 'Cefoperazone = "bile route + bleeding risk". Learning aid — exceptions exist.', 'cef-', 'sef-oh-PER-a-zone', 'सेफ़्-ओ-पे-रा-ज़ोन', NULL, 'active', 'verified', '2026-09-05', '3.0', '2026-09-05T22:19:27.659977+00:00', '2026-09-05T22:19:27.659977+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('f8984cac-406e-419c-b287-0e4ce26ddefa', 'cefoperazone-sulbactam', 'Cefoperazone + Sulbactam', 'Cefoperazone + Sulbactam', 'Cefoperazone; Sulbactam', 'Cefoperazone sodium + sulbactam sodium', NULL, 'Combination of a third-generation cephalosporin with a beta-lactamase inhibitor, widely used in India for hospital infections.', 'Antibiotics', ARRAY['1.5 g', '3 g']::text[], ARRAY['Injection']::text[], ARRAY['Intravenous', 'Intramuscular']::text[], 'Cefoperazone inhibits cell wall synthesis while sulbactam inactivates many bacterial beta-lactamases and adds activity against Acinetobacter.', 'Broad bactericidal activity including many resistant Gram-negative organisms.', 'Parenteral only.', 'Good biliary and tissue penetration.', 'Minimal metabolism.', 'Cefoperazone mainly biliary; sulbactam mainly renal.', 'Parenteral only', 'About 1-2 hours', 'High for cefoperazone', NULL, NULL, 'Immediate', '8-12 hours', ARRAY['Hospital-acquired pneumonia', 'Intra-abdominal and biliary sepsis', 'Complicated urinary and skin infections']::text[], ARRAY['Beta-lactam hypersensitivity']::text[], ARRAY['Bleeding due to hypoprothrombinaemia', 'Disulfiram-like reaction with alcohol', 'Reserved antibiotic — use with stewardship']::text[], ARRAY['Monitor coagulation in prolonged use', 'Adjust sulbactam dose in renal impairment']::text[], ARRAY['Diarrhoea', 'Rash', 'Injection site reaction']::text[], ARRAY['Coagulopathy and bleeding', 'C. difficile colitis', 'Anaphylaxis']::text[], ARRAY['Anticoagulants', 'Alcohol', 'Aminoglycosides']::text[], NULL, ARRAY['Prothrombin time', 'Renal and liver function', 'Culture-guided de-escalation']::text[], NULL, NULL, 'Use when clearly indicated.', 'Considered compatible.', 'Weight-based dosing under specialist care.', 'Monitor bleeding risk.', 'Reduce sulbactam component in impairment.', 'Reduce dose in severe impairment.', ARRAY['Broad hospital-grade cover including Acinetobacter']::text[], ARRAY['Reserved agent', 'Coagulation monitoring needed']::text[], ARRAY['Combination product: cephalosporin plus enzyme inhibitor', 'Components stored and tracked separately']::text[], 'Sulbactam = shield; cefoperazone = sword. Learning aid — exceptions exist.', NULL, 'sef-oh-PER-a-zone sul-BAK-tam', 'सेफ़्-ओ-पे-रा-ज़ोन सल्-बैक्-टैम', NULL, 'active', 'verified', '2026-09-05', '3.0', '2026-09-05T22:19:27.659977+00:00', '2026-09-05T22:19:27.659977+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('e33baf2d-da2d-4c4c-9487-52b82140d141', 'meropenem', 'Meropenem', 'Meropenem', 'Meropenem', 'Meropenem trihydrate', NULL, 'Broad-spectrum carbapenem antibiotic for severe and multidrug-resistant infections.', 'Antibiotics', ARRAY['500 mg', '1 g']::text[], ARRAY['Injection']::text[], ARRAY['Intravenous']::text[], 'Inhibits cell wall synthesis by binding penicillin-binding proteins; highly stable to most beta-lactamases.', 'Very broad bactericidal activity including ESBL-producing Gram-negatives and anaerobes.', 'Parenteral only.', 'Penetrates most tissues including cerebrospinal fluid when meninges are inflamed.', 'Hydrolysed to an inactive metabolite.', 'Mainly renal.', 'Parenteral only', 'About 1 hour', 'About 2%', NULL, NULL, 'Immediate', '8 hours', ARRAY['Severe hospital-acquired infections', 'Bacterial meningitis', 'Febrile neutropenia', 'Complicated intra-abdominal infection']::text[], ARRAY['Carbapenem hypersensitivity', 'Severe beta-lactam anaphylaxis']::text[], ARRAY['Seizure risk, lower than imipenem', 'Reserved antibiotic — stewardship essential']::text[], ARRAY['Adjust dose in renal impairment', 'De-escalate when cultures allow']::text[], ARRAY['Diarrhoea', 'Nausea', 'Rash', 'Injection site inflammation']::text[], ARRAY['Seizures', 'C. difficile colitis', 'Anaphylaxis', 'Thrombocytopenia']::text[], ARRAY['Valproate (levels fall sharply — avoid)', 'Probenecid']::text[], NULL, ARRAY['Renal function', 'Full blood count', 'Seizure activity']::text[], NULL, NULL, 'Used when clearly indicated.', 'Considered compatible.', 'Approved in children including meningitis dosing.', 'Adjust for renal function.', 'Dose reduction required.', 'No routine adjustment.', ARRAY['Extremely broad spectrum', 'CSF penetration allows meningitis use']::text[], ARRAY['Last-line agent — resistance risk', 'Reduces valproate levels']::text[], ARRAY['"-penem" identifies carbapenems', 'Never co-prescribe with valproate']::text[], '"-penem" → carbapenem, the broad-spectrum reserve. Learning aid — exceptions exist.', '-penem', 'mer-oh-PEN-em', 'मे-रो-पे-नेम', '/ˌmɛroʊˈpɛnɛm/', 'active', 'verified', '2026-09-05', '3.0', '2026-09-05T22:19:27.659977+00:00', '2026-09-05T22:19:27.659977+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('4a15f267-13f7-44a1-b890-292182a64caf', 'imipenem-cilastatin', 'Imipenem + Cilastatin', 'Imipenem + Cilastatin', 'Imipenem; Cilastatin', 'Imipenem monohydrate + cilastatin sodium', NULL, 'Carbapenem combined with a renal dehydropeptidase inhibitor that protects the antibiotic in the kidney.', 'Antibiotics', ARRAY['500 mg + 500 mg']::text[], ARRAY['Injection']::text[], ARRAY['Intravenous']::text[], 'Imipenem inhibits cell wall synthesis; cilastatin blocks renal dehydropeptidase-1 preventing imipenem breakdown.', 'Broad bactericidal activity against Gram-positive, Gram-negative and anaerobic organisms.', 'Parenteral only.', 'Wide tissue distribution; poor CSF penetration relative to meropenem.', 'Imipenem degraded by renal dehydropeptidase without cilastatin.', 'Mainly renal.', 'Parenteral only', 'About 1 hour', 'About 20%', NULL, NULL, 'Immediate', '6-8 hours', ARRAY['Severe polymicrobial infections', 'Intra-abdominal sepsis', 'Complicated urinary tract infection']::text[], ARRAY['Carbapenem hypersensitivity', 'Not recommended for meningitis']::text[], ARRAY['Higher seizure risk than meropenem', 'Reserved antibiotic']::text[], ARRAY['Adjust for renal function', 'Avoid in CNS infection']::text[], ARRAY['Nausea', 'Vomiting', 'Diarrhoea', 'Injection site reaction']::text[], ARRAY['Seizures', 'C. difficile colitis', 'Anaphylaxis']::text[], ARRAY['Valproate (avoid)', 'Ganciclovir (seizure risk)', 'Probenecid']::text[], NULL, ARRAY['Renal function', 'Neurological status']::text[], NULL, NULL, 'Use only when clearly indicated.', 'Considered compatible.', 'Used under specialist supervision.', 'Reduce dose; seizure risk higher.', 'Dose reduction required.', 'No routine adjustment.', ARRAY['Very broad spectrum']::text[], ARRAY['Seizure risk', 'Not suitable for meningitis']::text[], ARRAY['Cilastatin has no antibacterial action of its own', 'Combination product with two tracked ingredients']::text[], 'Cilastatin = "kidney bodyguard" for imipenem. Learning aid — exceptions exist.', '-penem', 'i-mi-PEN-em sye-la-STAT-in', 'इ-मि-पे-नेम साइ-ला-स्टै-टिन', NULL, 'active', 'verified', '2026-09-05', '3.0', '2026-09-05T22:19:27.659977+00:00', '2026-09-05T22:19:27.659977+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('17851265-fa80-4cb6-9d4a-6a3ca38ac3c2', 'erythromycin', 'Erythromycin', 'Erythromycin', 'Erythromycin', 'Stearate / estolate / ethylsuccinate', NULL, 'First macrolide antibiotic, used for respiratory, skin and atypical infections and as a prokinetic.', 'Antibiotics', ARRAY['250 mg', '500 mg']::text[], ARRAY['Tablet', 'Oral suspension', 'Injection', 'Topical gel']::text[], ARRAY['Oral', 'Intravenous', 'Topical']::text[], 'Binds the bacterial 50S ribosomal subunit, blocking translocation and protein synthesis.', 'Bacteriostatic against Gram-positive cocci, atypical organisms and Bordetella pertussis; also a motilin agonist.', 'Acid-labile; salt forms improve absorption.', 'Wide tissue distribution; poor CSF penetration.', 'Hepatic via CYP3A4.', 'Mainly biliary.', 'Variable, 30-65%', '1.5-2 hours', '70-90%', NULL, NULL, '1-2 hours', '6-8 hours', ARRAY['Respiratory tract infections', 'Pertussis', 'Chlamydial infection', 'Penicillin-allergic streptococcal infection', 'Gastroparesis (off-label prokinetic use)']::text[], ARRAY['Macrolide hypersensitivity', 'Concurrent ergot alkaloids or terfenadine', 'Congenital QT prolongation']::text[], ARRAY['QT prolongation', 'Potent CYP3A4 inhibition causing many interactions', 'Cholestatic hepatitis with the estolate salt']::text[], ARRAY['Take with food if GI upset occurs', 'Review interacting medicines before prescribing']::text[], ARRAY['Abdominal cramps', 'Nausea', 'Vomiting', 'Diarrhoea']::text[], ARRAY['QT prolongation and arrhythmia', 'Cholestatic jaundice', 'Infantile hypertrophic pyloric stenosis']::text[], ARRAY['Statins (myopathy)', 'Warfarin', 'Carbamazepine and theophylline', 'Other QT-prolonging drugs']::text[], NULL, ARRAY['Liver function in prolonged use', 'ECG where QT risk exists']::text[], NULL, NULL, 'Generally acceptable; avoid the estolate salt.', 'Considered compatible.', 'Used in children; pyloric stenosis risk in neonates.', 'QT and interaction risk higher.', 'Minor adjustment in severe impairment.', 'Avoid in significant impairment.', ARRAY['Alternative for penicillin allergy', 'Useful against atypical pathogens']::text[], ARRAY['Marked GI upset', 'Extensive drug interactions']::text[], ARRAY['Prototype macrolide', 'Strong CYP3A4 inhibitor']::text[], '"-thromycin" → macrolide; macrolides meddle with CYP3A4. Learning aid — exceptions exist.', '-thromycin', 'e-rith-roe-MYE-sin', 'ए-रिथ्-रो-माइ-सिन', '/ɪˌrɪθroʊˈmaɪsɪn/', 'active', 'verified', '2026-09-05', '3.0', '2026-09-05T22:19:27.659977+00:00', '2026-09-05T22:19:27.659977+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('3c68710a-6fa9-4457-9f18-45e30196b1dd', 'clindamycin', 'Clindamycin', 'Clindamycin', 'Clindamycin', 'Hydrochloride / phosphate', NULL, 'Lincosamide antibiotic active against Gram-positive cocci and anaerobes.', 'Antibiotics', ARRAY['150 mg', '300 mg', '600 mg injection']::text[], ARRAY['Capsule', 'Injection', 'Topical solution', 'Vaginal cream']::text[], ARRAY['Oral', 'Intravenous', 'Topical', 'Vaginal']::text[], 'Binds the 50S ribosomal subunit inhibiting bacterial protein synthesis.', 'Bacteriostatic, bactericidal at high concentrations; suppresses toxin production in streptococcal and staphylococcal infection.', 'Well absorbed orally, unaffected by food.', 'Excellent bone and abscess penetration; poor CSF entry.', 'Hepatic.', 'Biliary and renal as metabolites.', 'About 90%', '2-3 hours', 'About 90%', NULL, NULL, 'Within 1 hour', '6-8 hours', ARRAY['Anaerobic infections', 'Skin and soft tissue infections including MRSA in some settings', 'Bone and joint infection', 'Toxic shock syndrome as adjunct', 'Acne (topical)']::text[], ARRAY['Lincosamide hypersensitivity', 'History of antibiotic-associated colitis']::text[], ARRAY['High risk of Clostridioides difficile colitis', 'Oesophageal irritation if taken without water']::text[], ARRAY['Take with a full glass of water', 'Stop if severe diarrhoea develops']::text[], ARRAY['Diarrhoea', 'Nausea', 'Metallic taste', 'Rash']::text[], ARRAY['C. difficile colitis', 'Severe skin reactions', 'Hepatotoxicity']::text[], ARRAY['Neuromuscular blocking agents', 'Erythromycin (antagonism)']::text[], NULL, ARRAY['Bowel habit', 'Liver function in prolonged therapy']::text[], NULL, NULL, 'Considered acceptable when indicated.', 'Considered compatible with monitoring.', 'Weight-based dosing used in children.', 'Higher C. difficile risk.', 'No routine adjustment.', 'Reduce dose in severe impairment.', ARRAY['Excellent anaerobic and bone penetration', 'Reduces bacterial toxin production']::text[], ARRAY['Highest C. difficile colitis association']::text[], ARRAY['Lincosamide class', 'Diarrhoea must always be taken seriously']::text[], 'Clindamycin = "great for anaerobes, watch the colon". Learning aid — exceptions exist.', NULL, 'klin-da-MYE-sin', 'क्लिन्-डा-माइ-सिन', '/ˌklɪndəˈmaɪsɪn/', 'active', 'verified', '2026-09-05', '3.0', '2026-09-05T22:19:27.659977+00:00', '2026-09-05T22:19:27.659977+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('9c1c69d5-2c73-44e4-9b95-4557b03dcd0c', 'linezolid', 'Linezolid', 'Linezolid', 'Linezolid', 'Linezolid', NULL, 'Oxazolidinone antibiotic active against resistant Gram-positive organisms including MRSA and VRE.', 'Antibiotics', ARRAY['600 mg']::text[], ARRAY['Tablet', 'Injection', 'Oral suspension']::text[], ARRAY['Oral', 'Intravenous']::text[], 'Binds the 23S component of the 50S ribosomal subunit, preventing formation of the initiation complex.', 'Bacteriostatic against staphylococci and enterococci; bactericidal against streptococci.', 'Rapid and complete oral absorption.', 'Widely distributed including lung tissue.', 'Non-enzymatic oxidation, not CYP-mediated.', 'Renal and faecal.', 'About 100%', '5-7 hours', 'About 31%', NULL, NULL, '1-2 hours', '12 hours', ARRAY['MRSA pneumonia and skin infection', 'Vancomycin-resistant enterococcal infection', 'Complicated skin and soft tissue infection']::text[], ARRAY['Hypersensitivity', 'Concurrent MAO inhibitors']::text[], ARRAY['Myelosuppression with courses beyond two weeks', 'Serotonin syndrome with serotonergic drugs', 'Optic and peripheral neuropathy with prolonged use']::text[], ARRAY['Limit courses to 28 days where possible', 'Restrict tyramine-rich foods']::text[], ARRAY['Nausea', 'Diarrhoea', 'Headache', 'Taste disturbance']::text[], ARRAY['Thrombocytopenia and anaemia', 'Serotonin syndrome', 'Lactic acidosis', 'Optic neuropathy']::text[], ARRAY['SSRIs and SNRIs', 'MAO inhibitors', 'Sympathomimetics', 'Tyramine-rich foods']::text[], NULL, ARRAY['Weekly full blood count', 'Visual symptoms', 'Serotonergic symptoms']::text[], NULL, NULL, 'Use only if clearly needed.', 'Limited data; caution.', 'Approved in children with weight-based dosing.', 'Monitor blood counts closely.', 'No adjustment; metabolites accumulate.', 'No adjustment in mild to moderate impairment.', ARRAY['Excellent oral bioavailability allows IV-to-oral switch', 'Active against MRSA and VRE']::text[], ARRAY['Myelosuppression', 'Serotonin syndrome risk', 'Cost']::text[], ARRAY['Oxazolidinone class', 'Weekly blood counts during therapy']::text[], '"-zolid" → oxazolidinone; watch platelets and serotonin. Learning aid — exceptions exist.', '-zolid', 'li-NEZ-oh-lid', 'लि-ने-ज़ो-लिड', '/lɪˈnɛzəlɪd/', 'active', 'verified', '2026-09-05', '3.0', '2026-09-05T22:19:27.659977+00:00', '2026-09-05T22:19:27.659977+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('59f5d1c6-37c9-4760-8df7-bfa0973e62ca', 'amikacin', 'Amikacin', 'Amikacin', 'Amikacin', 'Sulfate', NULL, 'Aminoglycoside antibiotic used for serious Gram-negative infections resistant to gentamicin.', 'Antibiotics', ARRAY['100 mg', '500 mg']::text[], ARRAY['Injection']::text[], ARRAY['Intravenous', 'Intramuscular']::text[], 'Binds the 30S ribosomal subunit causing misreading of mRNA and bacterial death.', 'Concentration-dependent bactericidal activity with post-antibiotic effect.', 'Not absorbed orally.', 'Distributes into extracellular fluid; poor CSF penetration.', 'Not metabolised.', 'Renal, unchanged.', 'Parenteral only', '2-3 hours with normal renal function', 'Less than 10%', NULL, NULL, 'Immediate', '24 hours with once-daily dosing', ARRAY['Serious Gram-negative sepsis', 'Complicated urinary tract infection', 'Multidrug-resistant tuberculosis (second-line)']::text[], ARRAY['Aminoglycoside hypersensitivity', 'Myasthenia gravis']::text[], ARRAY['Nephrotoxicity', 'Irreversible ototoxicity and vestibular damage', 'Neuromuscular blockade']::text[], ARRAY['Once-daily dosing where appropriate', 'Monitor levels and renal function']::text[], ARRAY['Nausea', 'Injection site reaction', 'Transient rise in creatinine']::text[], ARRAY['Acute kidney injury', 'Hearing loss', 'Vestibular toxicity']::text[], ARRAY['Loop diuretics', 'Vancomycin and amphotericin B', 'Neuromuscular blockers']::text[], NULL, ARRAY['Peak and trough levels', 'Renal function', 'Audiometry in prolonged therapy']::text[], NULL, NULL, 'Avoid; risk of fetal ototoxicity.', 'Small amounts in milk; usually acceptable.', 'Weight-based dosing with level monitoring.', 'Higher toxicity risk; adjust dose.', 'Major dose adjustment required.', 'No adjustment.', ARRAY['Retains activity where gentamicin resistance exists']::text[], ARRAY['Ototoxic and nephrotoxic', 'Requires level monitoring']::text[], ARRAY['Aminoglycoside class', 'Once-daily dosing reduces toxicity']::text[], 'Aminoglycosides = "kidneys and ears at risk". Learning aid — exceptions exist.', '-micin / -mycin', 'am-i-KAY-sin', 'ऐ-मि-के-सिन', '/ˌæmɪˈkeɪsɪn/', 'active', 'verified', '2026-09-05', '3.0', '2026-09-05T22:19:27.659977+00:00', '2026-09-05T22:19:27.659977+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('ffbfb2b1-062f-42a0-a535-632bb48873a3', 'fosfomycin', 'Fosfomycin', 'Fosfomycin', 'Fosfomycin', 'Trometamol / calcium', NULL, 'Single-dose oral antibiotic for uncomplicated urinary tract infection.', 'Antibiotics', ARRAY['3 g sachet']::text[], ARRAY['Sachet (granules)', 'Injection']::text[], ARRAY['Oral', 'Intravenous']::text[], 'Inhibits MurA enzyme, blocking the first step of bacterial cell wall synthesis.', 'Bactericidal with high urinary concentrations sustained for 24-48 hours after a single dose.', 'Rapid oral absorption; food delays it.', 'Concentrates in urine; limited tissue distribution orally.', 'Not metabolised.', 'Renal, unchanged.', 'About 34-41%', 'About 5.7 hours', 'Negligible', NULL, NULL, '2-4 hours in urine', 'Urinary levels persist 24-48 hours', ARRAY['Uncomplicated lower urinary tract infection', 'Selected multidrug-resistant urinary infections']::text[], ARRAY['Hypersensitivity', 'Severe renal impairment']::text[], ARRAY['Not suitable for pyelonephritis or systemic infection when given orally']::text[], ARRAY['Take on an empty stomach, ideally at bedtime after voiding']::text[], ARRAY['Diarrhoea', 'Nausea', 'Headache', 'Vaginitis']::text[], ARRAY['C. difficile colitis (rare)', 'Angioedema (rare)']::text[], ARRAY['Metoclopramide (reduces absorption)']::text[], NULL, ARRAY['Symptom resolution', 'Urine culture where indicated']::text[], NULL, NULL, 'Considered acceptable for uncomplicated cystitis.', 'Considered compatible.', 'Not routinely used in young children.', 'Convenient single dose.', 'Avoid if creatinine clearance below 10 mL/min.', 'No adjustment.', ARRAY['Single-dose therapy improves adherence', 'Active against many resistant urinary pathogens']::text[], ARRAY['Only for lower urinary tract infection when given orally']::text[], ARRAY['Unique cell wall mechanism', 'Single 3 g sachet cures most uncomplicated cystitis']::text[], 'Fosfomycin = "one sachet for simple cystitis". Learning aid — exceptions exist.', NULL, 'fos-foe-MYE-sin', 'फ़ॉस्-फ़ो-माइ-सिन', '/ˌfɒsfoʊˈmaɪsɪn/', 'active', 'verified', '2026-09-05', '3.0', '2026-09-05T22:19:27.659977+00:00', '2026-09-05T22:19:27.659977+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('74fe6e36-9a45-46e9-aa40-ba031c47ab07', 'vancomycin', 'Vancomycin', 'Vancomycin', 'Vancomycin', 'Hydrochloride', NULL, 'Glycopeptide antibiotic for serious Gram-positive infections including MRSA.', 'Antibiotics', ARRAY['500 mg', '1 g', '125 mg capsule']::text[], ARRAY['Injection', 'Capsule']::text[], ARRAY['Intravenous', 'Oral (for C. difficile)']::text[], 'Binds D-alanyl-D-alanine termini of cell wall precursors, blocking peptidoglycan polymerisation.', 'Bactericidal against Gram-positive organisms; oral form acts locally in the gut only.', 'Negligible oral absorption; intravenous route for systemic infection.', 'Distributes into most tissues; variable CSF penetration.', 'Minimal metabolism.', 'Renal (intravenous); faecal (oral).', 'Negligible systemic absorption when given orally', '4-6 hours in normal renal function', 'About 55%', NULL, NULL, 'Immediate (intravenous)', '8-12 hours', ARRAY['MRSA bacteraemia and endocarditis', 'Severe Gram-positive infection in beta-lactam allergy', 'Oral therapy for Clostridioides difficile colitis']::text[], ARRAY['Hypersensitivity to vancomycin']::text[], ARRAY['Nephrotoxicity, especially with piperacillin-tazobactam or aminoglycosides', 'Infusion reaction (vancomycin flushing syndrome) with rapid infusion', 'Ototoxicity at high levels']::text[], ARRAY['Infuse over at least 60 minutes', 'Use trough or AUC-guided dosing']::text[], ARRAY['Phlebitis', 'Flushing with rapid infusion', 'Nausea']::text[], ARRAY['Acute kidney injury', 'Ototoxicity', 'Neutropenia', 'DRESS syndrome']::text[], ARRAY['Aminoglycosides', 'Piperacillin-tazobactam', 'Loop diuretics']::text[], NULL, ARRAY['Serum vancomycin levels', 'Renal function', 'Hearing symptoms']::text[], NULL, NULL, 'Used when clearly indicated.', 'Poor oral absorption by the infant; generally acceptable.', 'Weight-based dosing with level monitoring.', 'Reduce dose; renal risk higher.', 'Major dose adjustment required.', 'No routine adjustment.', ARRAY['Reliable MRSA cover', 'Oral form is first-line for severe C. difficile']::text[], ARRAY['Requires therapeutic drug monitoring', 'Nephrotoxicity']::text[], ARRAY['Glycopeptide antibiotic', 'Oral and intravenous forms treat completely different problems']::text[], 'Vancomycin = "IV for MRSA, oral only for the gut". Learning aid — exceptions exist.', NULL, 'van-koe-MYE-sin', 'वैन्-को-माइ-सिन', '/ˌvænkoʊˈmaɪsɪn/', 'active', 'verified', '2026-09-05', '3.0', '2026-09-05T22:19:27.659977+00:00', '2026-09-06T05:53:30.629874+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('be0ea179-0450-499b-a99c-2fa6c25970f8', 'itraconazole', 'Itraconazole', 'Itraconazole', 'Itraconazole', 'Itraconazole', NULL, 'Triazole antifungal used for dermatophyte, nail and systemic fungal infections.', 'Antifungals', ARRAY['100 mg', '200 mg']::text[], ARRAY['Capsule', 'Oral solution']::text[], ARRAY['Oral']::text[], 'Inhibits fungal lanosterol 14-alpha-demethylase, blocking ergosterol synthesis.', 'Fungistatic against dermatophytes, Candida and Aspergillus; accumulates in keratin.', 'Capsules need gastric acid and food; solution absorbs better fasting.', 'Highly lipophilic; concentrates in skin and nails.', 'Hepatic CYP3A4 to hydroxy-itraconazole.', 'Faecal and renal as metabolites.', 'About 55% with food', 'About 21 hours (longer with chronic dosing)', 'About 99.8%', NULL, NULL, 'Days to weeks', 'Persists in nails for months', ARRAY['Onychomycosis', 'Dermatophytosis and tinea', 'Oropharyngeal and vulvovaginal candidiasis', 'Aspergillosis (specialist use)']::text[], ARRAY['Heart failure', 'Concurrent ergot alkaloids, pimozide or quinidine', 'Pregnancy for onychomycosis']::text[], ARRAY['Negative inotropic effect and heart failure risk', 'Hepatotoxicity', 'Potent CYP3A4 inhibition with many interactions']::text[], ARRAY['Take capsules with an acidic drink and food', 'Review all concomitant drugs']::text[], ARRAY['Nausea', 'Abdominal pain', 'Headache', 'Rash']::text[], ARRAY['Hepatotoxicity', 'Congestive heart failure', 'QT prolongation with interacting drugs']::text[], ARRAY['Statins', 'Rifampicin (reduces levels)', 'Antacids and PPIs (reduce absorption)', 'Warfarin']::text[], NULL, ARRAY['Liver function during prolonged therapy', 'Cardiac symptoms']::text[], NULL, NULL, 'Avoid; contraindicated for nail infection.', 'Not recommended.', 'Limited paediatric data.', 'Cardiac caution.', 'No routine adjustment; avoid IV form in impairment.', 'Avoid in significant impairment.', ARRAY['Concentrates in keratin allowing pulse therapy']::text[], ARRAY['Extensive drug interactions', 'Cardiac and liver risks']::text[], ARRAY['Azole antifungal', 'Absorption depends on stomach acid']::text[], '"-azole" → antifungal that blocks ergosterol. Learning aid — exceptions exist.', '-azole', 'it-ra-KON-a-zole', 'इट्-रा-को-ना-ज़ोल', '/ˌɪtrəˈkɒnəzoʊl/', 'active', 'verified', '2026-09-06', '3.0', '2026-09-06T05:55:52.501981+00:00', '2026-09-06T05:55:52.501981+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('982e2d87-c214-479e-b93c-9cae57eb651d', 'ketoconazole', 'Ketoconazole', 'Ketoconazole', 'Ketoconazole', 'Ketoconazole', NULL, 'Imidazole antifungal now used mainly topically because of systemic hepatotoxicity.', 'Antifungals', ARRAY['2% shampoo', '2% cream', '200 mg tablet']::text[], ARRAY['Shampoo', 'Cream', 'Tablet (restricted)']::text[], ARRAY['Topical', 'Oral (restricted)']::text[], 'Inhibits fungal cytochrome P450 14-alpha-demethylase, reducing ergosterol synthesis.', 'Fungistatic against dermatophytes and Malassezia; oral form also suppresses steroid synthesis.', 'Topical absorption minimal; oral absorption needs gastric acid.', 'Widely distributed after oral use; poor CSF penetration.', 'Extensive hepatic metabolism.', 'Mainly biliary.', 'Minimal topically', 'About 8 hours (oral)', 'About 99%', NULL, NULL, 'Days for skin conditions', 'Depends on formulation', ARRAY['Seborrhoeic dermatitis and dandruff', 'Pityriasis versicolor', 'Tinea infections (topical)']::text[], ARRAY['Hepatic disease for oral use', 'Concurrent QT-prolonging drugs', 'Known hypersensitivity']::text[], ARRAY['Oral use restricted due to severe hepatotoxicity and adrenal suppression', 'Avoid systemic use where alternatives exist']::text[], ARRAY['Prefer topical therapy', 'Avoid alcohol with oral use']::text[], ARRAY['Local irritation', 'Dry skin', 'Scalp itching']::text[], ARRAY['Hepatotoxicity (oral)', 'Adrenal insufficiency (oral)', 'QT prolongation']::text[], ARRAY['Statins', 'Warfarin', 'Antacids and PPIs', 'Cisapride and pimozide']::text[], NULL, ARRAY['Liver function if used orally', 'Skin response']::text[], NULL, NULL, 'Topical use generally acceptable; avoid oral.', 'Topical use acceptable away from the breast.', 'Topical use common in children.', 'Prefer topical.', 'No adjustment topically.', 'Oral use contraindicated in liver disease.', ARRAY['Effective, inexpensive topical antifungal']::text[], ARRAY['Systemic form largely withdrawn due to liver toxicity']::text[], ARRAY['Imidazole antifungal', 'Modern practice is topical use']::text[], 'Ketoconazole = "shampoo yes, tablets rarely". Learning aid — exceptions exist.', '-azole', 'kee-toe-KON-a-zole', 'की-टो-को-ना-ज़ोल', '/ˌkiːtoʊˈkɒnəzoʊl/', 'active', 'verified', '2026-09-06', '3.0', '2026-09-06T05:55:52.501981+00:00', '2026-09-06T05:55:52.501981+00:00') ON CONFLICT (slug) DO NOTHING;
