longed oral therapy']::text[], ARRAY['Gastrointestinal upset', 'Rash', 'Headache', 'Taste disturbance']::text[], ARRAY['Hepatic failure', 'Stevens-Johnson syndrome', 'Blood dyscrasias']::text[], ARRAY['Rifampicin (reduces levels)', 'Cimetidine (raises levels)', 'CYP2D6 substrates such as tricyclics']::text[], NULL, ARRAY['Liver function before and during oral therapy', 'Full blood count in long courses']::text[], NULL, NULL, 'Avoid oral therapy unless essential.', 'Not recommended orally.', 'Weight-based oral dosing used for tinea capitis.', 'Check liver and renal function.', 'Avoid oral use if creatinine clearance below 50 mL/min.', 'Contraindicated in active liver disease.', ARRAY['Fungicidal and highly effective for nail infection', 'Short courses relative to nail growth']::text[], ARRAY['Liver monitoring needed', 'Taste disturbance']::text[], ARRAY['Allylamine antifungal', 'First-line for dermatophyte onychomycosis']::text[], '"-afine" → allylamine; blocks squalene epoxidase. Learning aid — exceptions exist.', '-afine', 'TER-bin-a-feen', 'टर्-बि-ना-फ़ीन', '/ˈtɜːrbɪnəfiːn/', 'active', 'verified', '2026-09-06', '3.0', '2026-09-06T05:55:52.501981+00:00', '2026-09-06T05:55:52.501981+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('0a37664d-e63a-46eb-9c11-e449c9167df0', 'clotrimazole', 'Clotrimazole', 'Clotrimazole', 'Clotrimazole', 'Clotrimazole', NULL, 'Topical imidazole antifungal for skin, vaginal and oral candidal infections.', 'Antifungals', ARRAY['1% cream', '100 mg pessary', '500 mg pessary']::text[], ARRAY['Cream', 'Vaginal pessary', 'Lozenge', 'Solution']::text[], ARRAY['Topical', 'Vaginal', 'Oromucosal']::text[], 'Inhibits ergosterol synthesis, damaging the fungal cell membrane.', 'Fungistatic to fungicidal locally against Candida and dermatophytes.', 'Minimal systemic absorption from skin or vagina.', 'Remains at the site of application.', 'Any absorbed drug is metabolised hepatically.', 'Biliary.', 'Negligible systemically', 'Not clinically relevant topically', 'Not applicable', NULL, NULL, 'Days', 'Duration of treatment course', ARRAY['Vulvovaginal candidiasis', 'Tinea infections of skin', 'Oral candidiasis (lozenge)', 'Napkin candidiasis']::text[], ARRAY['Hypersensitivity to imidazoles']::text[], ARRAY['Vaginal preparations can weaken latex condoms and diaphragms']::text[], ARRAY['Complete the full course', 'Treat sexual partners if symptomatic']::text[], ARRAY['Local burning or itching', 'Erythema']::text[], ARRAY['Severe local hypersensitivity (rare)']::text[], ARRAY['Tacrolimus and sirolimus with oral lozenges (rare systemic effect)']::text[], NULL, ARRAY['Local response']::text[], NULL, NULL, 'Topical and vaginal use widely considered acceptable.', 'Considered compatible.', 'Used in infants for candidal napkin rash.', 'No adjustment.', 'No adjustment.', 'No adjustment.', ARRAY['Very low systemic exposure', 'Available without prescription in many settings']::text[], ARRAY['Only treats local infection', 'Multiple daily applications']::text[], ARRAY['Topical azole antifungal', 'Weakens latex barrier contraceptives']::text[], '"-azole" cream = local antifungal only. Learning aid — exceptions exist.', '-azole', 'kloe-TRIM-a-zole', 'क्लो-ट्रि-मा-ज़ोल', '/kloʊˈtrɪməzoʊl/', 'active', 'verified', '2026-09-06', '3.0', '2026-09-06T05:55:52.501981+00:00', '2026-09-06T05:55:52.501981+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('efc3ea75-bc50-43c8-a1ea-db3d0c35cd50', 'miconazole', 'Miconazole', 'Miconazole', 'Miconazole', 'Nitrate', NULL, 'Imidazole antifungal used topically and as an oral gel for candidiasis.', 'Antifungals', ARRAY['2% cream', '2% oral gel']::text[], ARRAY['Cream', 'Oral gel', 'Vaginal pessary', 'Powder']::text[], ARRAY['Topical', 'Oromucosal', 'Vaginal']::text[], 'Inhibits fungal 14-alpha-demethylase, blocking ergosterol synthesis.', 'Local antifungal action with additional activity against some Gram-positive bacteria.', 'Minimal absorption from skin; some absorption from the oral gel.', 'Acts locally.', 'Hepatic for absorbed drug.', 'Faecal and renal.', 'Negligible topically', 'About 24 hours for absorbed drug', 'About 90%', NULL, NULL, 'Days', 'Duration of course', ARRAY['Oral and oesophageal candidiasis (gel)', 'Vaginal candidiasis', 'Tinea and cutaneous candidiasis']::text[], ARRAY['Hypersensitivity', 'Oral gel in infants under 4 months (choking risk)']::text[], ARRAY['Oral gel can raise warfarin effect significantly', 'Choking risk if gel is applied at the back of the throat in infants']::text[], ARRAY['Apply after meals for oral gel', 'Avoid latex contact for vaginal forms']::text[], ARRAY['Local irritation', 'Altered taste with oral gel', 'Nausea']::text[], ARRAY['Bleeding when combined with warfarin', 'Severe hypersensitivity']::text[], ARRAY['Warfarin', 'Sulfonylureas', 'Phenytoin']::text[], NULL, ARRAY['INR if used with warfarin', 'Local response']::text[], NULL, NULL, 'Topical and vaginal use generally acceptable.', 'Considered compatible.', 'Oral gel not for infants under 4 months.', 'Watch warfarin interaction.', 'No adjustment.', 'No adjustment.', ARRAY['Effective for oral candidiasis', 'Broad local activity']::text[], ARRAY['Clinically important warfarin interaction']::text[], ARRAY['Topical azole', 'Even the oral gel interacts with warfarin']::text[], 'Miconazole gel + warfarin = bleeding risk. Learning aid — exceptions exist.', '-azole', 'mi-KON-a-zole', 'मि-को-ना-ज़ोल', '/mɪˈkɒnəzoʊl/', 'active', 'verified', '2026-09-06', '3.0', '2026-09-06T05:55:52.501981+00:00', '2026-09-06T05:55:52.501981+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('4297bdfd-93ef-4dfd-966f-4729a7acddbc', 'amphotericin-b', 'Amphotericin B', 'Amphotericin B', 'Amphotericin B', 'Deoxycholate / liposomal', NULL, 'Polyene antifungal for severe systemic fungal infections and visceral leishmaniasis.', 'Antifungals', ARRAY['50 mg vial']::text[], ARRAY['Injection', 'Liposomal injection']::text[], ARRAY['Intravenous']::text[], 'Binds ergosterol in fungal membranes forming pores that cause leakage of cell contents.', 'Fungicidal against a wide range of yeasts and moulds.', 'Not absorbed orally; given intravenously.', 'Extensively bound to tissues; poor CSF penetration.', 'Poorly characterised; slow tissue release.', 'Slow renal and biliary elimination.', 'Parenteral only', 'About 15 days terminal (conventional)', 'More than 90%', NULL, NULL, 'Hours', 'Prolonged tissue retention', ARRAY['Invasive candidiasis and aspergillosis', 'Cryptococcal meningitis', 'Mucormycosis', 'Visceral leishmaniasis (kala-azar)']::text[], ARRAY['Hypersensitivity to amphotericin']::text[], ARRAY['Dose-limiting nephrotoxicity', 'Severe infusion reactions with fever and rigors', 'Hypokalaemia and hypomagnesaemia']::text[], ARRAY['Pre-hydrate with saline', 'Liposomal formulations reduce toxicity']::text[], ARRAY['Fever and chills during infusion', 'Nausea', 'Hypokalaemia', 'Phlebitis']::text[], ARRAY['Acute kidney injury', 'Severe electrolyte disturbance', 'Cardiac arrhythmia', 'Anaemia']::text[], ARRAY['Aminoglycosides and ciclosporin (nephrotoxicity)', 'Digoxin (via hypokalaemia)', 'Corticosteroids']::text[], NULL, ARRAY['Renal function', 'Serum potassium and magnesium', 'Full blood count']::text[], NULL, NULL, 'Considered acceptable for life-threatening infection.', 'Limited data; use if essential.', 'Used in children including kala-azar therapy.', 'Higher nephrotoxicity risk.', 'Dose and formulation adjustments needed.', 'No routine adjustment.', ARRAY['Broadest antifungal spectrum', 'Liposomal form far better tolerated']::text[], ARRAY['Nephrotoxicity and infusion reactions', 'Cost of liposomal form']::text[], ARRAY['Polyene antifungal binding ergosterol', 'Electrolytes must be watched daily']::text[], 'Amphotericin = "ampho-terrible" for the kidneys. Learning aid — exceptions exist.', NULL, 'am-foe-TER-i-sin bee', 'ऐम्-फ़ो-टे-रि-सिन बी', '/ˌæmfəˈtɛrɪsɪn/', 'active', 'verified', '2026-09-06', '3.0', '2026-09-06T05:55:52.501981+00:00', '2026-09-06T05:55:52.501981+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('18d57ceb-47b8-4139-8748-d60be302e492', 'valacyclovir', 'Valacyclovir', 'Valacyclovir', 'Valacyclovir', 'Hydrochloride', NULL, 'Oral prodrug of aciclovir with better bioavailability, used for herpes and varicella zoster infections.', 'Antivirals', ARRAY['500 mg', '1000 mg']::text[], ARRAY['Tablet']::text[], ARRAY['Oral']::text[], 'Converted to aciclovir, which after viral thymidine kinase phosphorylation inhibits viral DNA polymerase.', 'Selective antiviral activity against herpes simplex and varicella zoster viruses.', 'Rapidly absorbed and converted to aciclovir.', 'Distributes widely including into CSF.', 'Hepatic first-pass conversion to aciclovir.', 'Renal.', 'About 55% as aciclovir', 'About 2.5-3.5 hours (aciclovir)', '13-18%', NULL, NULL, 'Within hours', '8-12 hours', ARRAY['Herpes labialis and genital herpes', 'Herpes zoster (shingles)', 'Suppression of recurrent genital herpes']::text[], ARRAY['Hypersensitivity to valacyclovir or aciclovir']::text[], ARRAY['Thrombotic thrombocytopenic purpura at very high doses in immunocompromised patients', 'Neurotoxicity in renal impairment']::text[], ARRAY['Maintain hydration', 'Start treatment as early as possible in zoster']::text[], ARRAY['Headache', 'Nausea', 'Abdominal pain', 'Dizziness']::text[], ARRAY['Acute kidney injury', 'Neuropsychiatric effects', 'Thrombotic microangiopathy (rare)']::text[], ARRAY['Probenecid and cimetidine (raise levels)', 'Nephrotoxic drugs']::text[], NULL, ARRAY['Renal function', 'Neurological symptoms in impaired renal function']::text[], NULL, NULL, 'Considered acceptable when indicated.', 'Considered compatible.', 'Approved for chickenpox and herpes in children.', 'Reduce dose for renal function.', 'Dose reduction required.', 'No routine adjustment.', ARRAY['Far better oral bioavailability than aciclovir', 'Fewer daily doses']::text[], ARRAY['Requires renal dose adjustment', 'Cost above aciclovir']::text[], ARRAY['Prodrug of aciclovir', 'Early start improves zoster outcomes']::text[], 'Valacyclovir = aciclovir with a "delivery van" attached. Learning aid — exceptions exist.', '-cyclovir', 'val-ay-SYE-kloe-veer', 'वैल्-ए-साइ-क्लो-वीर', '/ˌvæləˈsaɪkloʊvɪər/', 'active', 'verified', '2026-09-06', '3.0', '2026-09-06T05:55:52.501981+00:00', '2026-09-06T05:55:52.501981+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('f095a855-61cb-4814-b4cd-ff0ad3b219eb', 'tenofovir', 'Tenofovir', 'Tenofovir', 'Tenofovir disoproxil fumarate / alafenamide', 'Disoproxil fumarate / alafenamide', NULL, 'Nucleotide reverse transcriptase inhibitor used in HIV and chronic hepatitis B.', 'Antivirals', ARRAY['300 mg (TDF)', '25 mg (TAF)']::text[], ARRAY['Tablet']::text[], ARRAY['Oral']::text[], 'Prodrug converted to tenofovir diphosphate, which inhibits HIV reverse transcriptase and hepatitis B polymerase by chain termination.', 'Sustained viral suppression with a high barrier to resistance for hepatitis B.', 'Oral absorption improved with food (TDF).', 'Low protein binding; wide distribution.', 'Hydrolysis to tenofovir then intracellular phosphorylation.', 'Renal by filtration and active tubular secretion.', 'About 25% (TDF)', 'About 17 hours (plasma)', 'Less than 7%', NULL, NULL, 'Weeks for viral suppression', '24 hours (once daily)', ARRAY['HIV-1 infection as part of combination therapy', 'Chronic hepatitis B', 'HIV pre-exposure prophylaxis (in combination)']::text[], ARRAY['Hypersensitivity', 'Use alone for HIV (must be combined)']::text[], ARRAY['Renal tubular injury and Fanconi syndrome with TDF', 'Reduction in bone mineral density', 'Severe hepatitis B flare if stopped abruptly']::text[], ARRAY['Test hepatitis B status before HIV therapy', 'Do not stop abruptly in hepatitis B']::text[], ARRAY['Nausea', 'Diarrhoea', 'Headache', 'Fatigue']::text[], ARRAY['Acute kidney injury', 'Lactic acidosis', 'Hepatitis flare on discontinuation']::text[], ARRAY['NSAIDs and other nephrotoxic drugs', 'Didanosine', 'Rifampicin (with TAF)']::text[], NULL, ARRAY['Renal function and urine protein', 'Bone health in long-term use', 'Viral load']::text[], NULL, NULL, 'Widely used in pregnancy for HIV and hepatitis B.', 'Recommended regimens exist; follow guidelines.', 'Weight-based dosing available.', 'Monitor renal function.', 'Dose interval adjustment for TDF.', 'No routine adjustment.', ARRAY['Once-daily dosing', 'High resistance barrier in hepatitis B']::text[], ARRAY['Renal and bone effects with the disoproxil form']::text[], ARRAY['Backbone agent in HIV therapy', 'Never stop suddenly in hepatitis B']::text[], 'TDF = kidneys and bones; TAF = gentler at lower dose. Learning aid — exceptions exist.', NULL, 'te-NOF-oh-veer', 'टे-नो-फ़ो-वीर', '/tɛˈnɒfoʊvɪər/', 'active', 'verified', '2026-09-06', '3.0', '2026-09-06T05:55:52.501981+00:00', '2026-09-06T05:55:52.501981+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('072bdcd8-500b-45bb-aea1-b461170ddab4', 'entecavir', 'Entecavir', 'Entecavir', 'Entecavir', 'Entecavir monohydrate', NULL, 'Nucleoside analogue used for chronic hepatitis B with a high barrier to resistance.', 'Antivirals', ARRAY['0.5 mg', '1 mg']::text[], ARRAY['Tablet', 'Oral solution']::text[], ARRAY['Oral']::text[], 'Phosphorylated intracellularly to inhibit hepatitis B polymerase priming, reverse transcription and DNA synthesis.', 'Potent suppression of hepatitis B viral replication.', 'Well absorbed on an empty stomach; food reduces absorption.', 'Widely distributed.', 'Minimal hepatic metabolism.', 'Mainly renal.', 'Approaching 100% fasting', '128-149 hours (intracellular effect)', 'About 13%', NULL, NULL, 'Weeks for viral suppression', '24 hours', ARRAY['Chronic hepatitis B with active viral replication', 'Compensated and decompensated hepatitis B liver disease']::text[], ARRAY['Hypersensitivity']::text[], ARRAY['Severe hepatitis flare after stopping', 'Lactic acidosis and hepatomegaly with steatosis', 'Resistance risk if used in lamivudine-resistant disease at standard dose']::text[], ARRAY['Take on an empty stomach', 'Do not stop without specialist advice']::text[], ARRAY['Headache', 'Fatigue', 'Dizziness', 'Nausea']::text[], ARRAY['Severe post-treatment hepatitis flare', 'Lactic acidosis']::text[], ARRAY['Drugs reducing renal function', 'Ribavirin (theoretical)']::text[], NULL, ARRAY['Hepatitis B DNA level', 'Liver function', 'Renal function']::text[], NULL, NULL, 'Limited data; specialist decision.', 'Not recommended.', 'Approved from 2 years of age.', 'Adjust for renal function.', 'Dose reduction required.', 'No adjustment needed.', ARRAY['High potency with a high resistance barrier', 'Once-daily dosing']::text[], ARRAY['Must be taken fasting', 'Long-term therapy usually required']::text[], ARRAY['First-line oral hepatitis B therapy', 'Empty-stomach dosing matters']::text[], 'Entecavir = "empty stomach, hepatitis B". Learning aid — exceptions exist.', NULL, 'en-TEK-a-veer', 'एन्-टे-का-वीर', '/ɛnˈtɛkəvɪər/', 'active', 'verified', '2026-09-06', '3.0', '2026-09-06T05:55:52.501981+00:00', '2026-09-06T05:55:52.501981+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('b09161f9-0a5e-4b8c-8228-c4560040552c', 'secnidazole', 'Secnidazole', 'Secnidazole', 'Secnidazole', 'Secnidazole', NULL, 'Long-acting nitroimidazole given as a single dose for amoebiasis, giardiasis and bacterial vaginosis.', 'Antiparasitics', ARRAY['500 mg', '1 g', '2 g']::text[], ARRAY['Tablet', 'Oral granules', 'Suspension']::text[], ARRAY['Oral']::text[], 'Reduced within anaerobic organisms to reactive intermediates that damage microbial DNA.', 'Amoebicidal, giardicidal and active against anaerobic bacteria; long half-life allows single-dose therapy.', 'Rapid and near complete oral absorption.', 'Widely distributed in tissue.', 'Hepatic.', 'Mainly renal.', 'Nearly complete', '17-29 hours', 'About 15%', NULL, NULL, 'Within hours', 'Single dose covers several days', ARRAY['Intestinal amoebiasis', 'Giardiasis', 'Bacterial vaginosis', 'Trichomoniasis']::text[], ARRAY['Nitroimidazole hypersensitivity', 'First trimester of pregnancy', 'Blood dyscrasias']::text[], ARRAY['Disulfiram-like reaction with alcohol', 'Neurological effects with prolonged use']::text[], ARRAY['Avoid alcohol during and for 48 hours after treatment', 'Treat sexual partners in trichomoniasis']::text[], ARRAY['Metallic taste', 'Nausea', 'Abdominal pain', 'Headache']::text[], ARRAY['Peripheral neuropathy', 'Seizures (rare)', 'Severe hypersensitivity']::text[], ARRAY['Alcohol', 'Warfarin', 'Lithium', 'Phenobarbital']::text[], NULL, ARRAY['Symptom resolution', 'Neurological symptoms in repeat courses']::text[], NULL, NULL, 'Avoid in the first trimester.', 'Suspend breastfeeding briefly after a single dose per local guidance.', 'Weight-based single dose used in children.', 'No routine adjustment.', 'Caution in severe impairment.', 'Reduce dose in impairment.', ARRAY['Single-dose therapy improves adherence']::text[], ARRAY['Alcohol interaction', 'Metallic taste']::text[], ARRAY['Nitroimidazole family with metronidazole and tinidazole', 'Longest half-life of the group']::text[], 'Metronidazole → tinidazole → secnidazole = longer and longer action. Learning aid — exceptions exist.', '-nidazole', 'sek-NID-a-zole', 'सेक्-नि-डा-ज़ोल', '/sɛkˈnɪdəzoʊl/', 'active', 'verified', '2026-09-06', '3.0', '2026-09-06T05:55:52.501981+00:00', '2026-09-06T05:55:52.501981+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('e249008e-f1bf-4cec-98e2-a107096801f9', 'mebendazole', 'Mebendazole', 'Mebendazole', 'Mebendazole', 'Mebendazole', NULL, 'Benzimidazole anthelmintic used for common intestinal worm infections.', 'Antiparasitics', ARRAY['100 mg', '500 mg']::text[], ARRAY['Chewable tablet', 'Suspension']::text[], ARRAY['Oral']::text[], 'Binds parasite beta-tubulin, blocking microtubule formation and glucose uptake in the worm.', 'Kills intestinal nematodes slowly by depleting their energy stores.', 'Poorly absorbed from the gut, which supports local action.', 'Limited systemic distribution.', 'Extensive first-pass hepatic metabolism.', 'Mainly faecal.', 'About 2-10%', '2.5-5.5 hours', 'About 95%', NULL, NULL, 'Days', 'Course of 1-3 days', ARRAY['Threadworm (pinworm)', 'Roundworm, hookworm and whipworm infection', 'Mixed intestinal helminth infection']::text[], ARRAY['Hypersensitivity', 'First trimester of pregnancy (relative)']::text[], ARRAY['High-dose prolonged use may cause bone marrow suppression', 'Rare severe skin reactions']::text[], ARRAY['Treat all household members for threadworm', 'Reinforce hand hygiene']::text[], ARRAY['Abdominal pain', 'Diarrhoea', 'Nausea']::text[], ARRAY['Agranulocytosis with high-dose therapy', 'Stevens-Johnson syndrome (rare)']::text[], ARRAY['Metronidazole (rare severe skin reactions)', 'Cimetidine (raises levels)', 'Phenytoin and carbamazepine (lower levels)']::text[], NULL, ARRAY['Symptom resolution', 'Full blood count with high-dose therapy']::text[], NULL, NULL, 'Avoid in the first trimester; used in mass programmes later.', 'Considered compatible.', 'Widely used from 1-2 years of age.', 'No routine adjustment.', 'No adjustment.', 'Caution in impairment.', ARRAY['Broad anthelmintic cover with a simple course', 'Very low systemic absorption']::text[], ARRAY['Reinfection common without hygiene measures']::text[], ARRAY['Benzimidazole anthelmintic', 'Repeat dose after 2 weeks for threadworm']::text[], 'Benzimidazoles = "worms starve of glucose". Learning aid — exceptions exist.', '-bendazole', 'me-BEN-da-zole', 'मे-बेन्-डा-ज़ोल', '/mɛˈbɛndəzoʊl/', 'active', 'verified', '2026-09-06', '3.0', '2026-09-06T05:55:52.501981+00:00', '2026-09-06T05:55:52.501981+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('eb9f7891-28cf-4362-938d-48d4ff052568', 'nitazoxanide', 'Nitazoxanide', 'Nitazoxanide', 'Nitazoxanide', 'Nitazoxanide', NULL, 'Thiazolide antiparasitic used for giardiasis, cryptosporidiosis and some infectious diarrhoeas.', 'Antiparasitics', ARRAY['200 mg', '500 mg']::text[], ARRAY['Tablet', 'Oral suspension']::text[], ARRAY['Oral']::text[], 'Interferes with the pyruvate-ferredoxin oxidoreductase enzyme-dependent electron transfer essential to anaerobic energy metabolism.', 'Active against protozoa, some helminths and certain enteric viruses and bacteria.', 'Absorbed and rapidly hydrolysed to tizoxanide; food increases absorption.', 'Tizoxanide distributes into plasma and gut.', 'Hydrolysis then glucuronidation.', 'Urine, bile and faeces.', 'Food-dependent', 'About 1-1.6 hours (tizoxanide)', 'More than 99%', NULL, NULL, 'Within hours', 'Twice-daily dosing', ARRAY['Giardiasis', 'Cryptosporidiosis', 'Amoebiasis', 'Selected infectious diarrhoea']::text[], ARRAY['Hypersensitivity']::text[], ARRAY['Urine may appear bright yellow-green (harmless)']::text[], ARRAY['Take with food', 'Complete the 3-day course']::text[], ARRAY['Abdominal pain', 'Diarrhoea', 'Nausea', 'Headache']::text[], ARRAY['Severe hypersensitivity (rare)']::text[], ARRAY['Highly protein-bound drugs such as warfarin (theoretical displacement)']::text[], NULL, ARRAY['Symptom resolution', 'Stool studies if symptoms persist']::text[], NULL, NULL, 'Limited data; use if clearly needed.', 'Limited data.', 'Paediatric suspension widely used.', 'No routine adjustment.', 'Caution; limited data.', 'Caution; limited data.', ARRAY['Effective in cryptosporidiosis where options are few', 'Well tolerated']::text[], ARRAY['Limited data in some populations', 'Cost']::text[], ARRAY['Thiazolide antiparasitic', 'Always take with food']::text[], 'Nitazoxanide = "food-friendly, broad anti-parasite". Learning aid — exceptions exist.', NULL, 'nye-ta-ZOX-a-nide', 'नाइ-टा-ज़ॉक्-सा-नाइड', '/ˌnaɪtəˈzɒksənaɪd/', 'active', 'verified', '2026-09-06', '3.0', '2026-09-06T05:55:52.501981+00:00', '2026-09-06T05:55:52.501981+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('880a410a-9de1-4d0c-adfe-6c0e61004f13', 'permethrin', 'Permethrin', 'Permethrin', 'Permethrin', 'Permethrin', NULL, 'Topical pyrethroid scabicide and pediculicide.', 'Antiparasitics', ARRAY['5% cream', '1% lotion']::text[], ARRAY['Cream', 'Lotion']::text[], ARRAY['Topical']::text[], 'Disrupts sodium channel function in parasite nerve membranes, causing paralysis and death.', 'Kills Sarcoptes scabiei and head lice on contact.', 'Minimal absorption through intact skin (less than 2%).', 'Remains largely in the skin.', 'Rapidly hydrolysed by skin and liver esterases.', 'Renal as metabolites.', 'Less than 2%', 'Not clinically relevant topically', 'Not applicable', NULL, NULL, 'Hours', 'Single application, repeat after 7 days', ARRAY['Scabies', 'Head lice', 'Pubic lice']::text[], ARRAY['Hypersensitivity to pyrethroids or chrysanthemums']::text[], ARRAY['Itching may persist for 2-4 weeks after successful treatment', 'Treat all close contacts simultaneously']::text[], ARRAY['Apply to whole body from neck down in adults', 'Wash bedding and clothes in hot water']::text[], ARRAY['Burning or stinging', 'Itching', 'Mild erythema']::text[], ARRAY['Severe hypersensitivity (rare)']::text[], ARRAY['No clinically significant systemic interactions']::text[], NULL, ARRAY['Resolution of burrows and itching', 'Treatment of household contacts']::text[], NULL, NULL, 'Considered the preferred scabies treatment in pregnancy.', 'Considered compatible; clean the breast before feeding.', 'Used from 2 months of age with medical advice.', 'Apply carefully including scalp in the elderly.', 'No adjustment.', 'No adjustment.', ARRAY['First-line scabies treatment', 'Very low systemic exposure']::text[], ARRAY['Requires whole-body application and contact treatment']::text[], ARRAY['Topical scabicide', 'Post-scabies itch is not treatment failure']::text[], 'Permethrin = "neck down, repeat in a week". Learning aid — exceptions exist.', NULL, 'per-METH-rin', 'पर्-मेथ्-रिन', '/pərˈmɛθrɪn/', 'active', 'verified', '2026-09-06', '3.0', '2026-09-06T05:55:52.501981+00:00', '2026-09-06T05:55:52.501981+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('62fd0fd0-b3ad-49da-9102-8aaa8b03214a', 'vildagliptin', 'Vildagliptin', 'Vildagliptin', 'Vildagliptin', 'Vildagliptin', NULL, 'DPP-4 inhibitor used in type 2 diabetes, commonly combined with metformin.', 'Diabetes', ARRAY['50 mg']::text[], ARRAY['Tablet']::text[], ARRAY['Oral']::text[], 'Inhibits dipeptidyl peptidase-4, prolonging incretin (GLP-1 and GIP) activity.', 'Glucose-dependent increase in insulin and reduction in glucagon; weight neutral with low hypoglycaemia risk alone.', 'Rapidly absorbed; food has little effect.', 'Volume of distribution about 71 L.', 'Mainly hydrolysis, largely non-CYP.', 'Renal as metabolites and parent drug.', 'About 85%', 'About 3 hours', 'About 9.3%', NULL, NULL, 'Within hours', '12 hours (twice-daily dosing)', ARRAY['Type 2 diabetes mellitus as monotherapy or combination therapy']::text[], ARRAY['Hypersensitivity', 'Severe hepatic impairment or raised transaminases']::text[], ARRAY['Rare hepatic dysfunction — check liver function before and during therapy', 'Pancreatitis reported']::text[], ARRAY['Not for type 1 diabetes or ketoacidosis', 'Reduce sulfonylurea dose when combined']::text[], ARRAY['Headache', 'Dizziness', 'Nasopharyngitis', 'Nausea']::text[], ARRAY['Hepatitis', 'Acute pancreatitis', 'Angioedema (especially with ACE inhibitors)']::text[], ARRAY['Sulfonylureas and insulin (hypoglycaemia)', 'ACE inhibitors (angioedema risk)']::text[], NULL, ARRAY['HbA1c', 'Liver function tests', 'Renal function']::text[], NULL, NULL, 'Not recommended; insulin preferred.', 'Not recommended.', 'Not established in children.', 'Adjust for renal function.', 'Reduce dose to once daily in moderate to severe impairment.', 'Avoid in hepatic impairment.', ARRAY['Weight neutral', 'Low hypoglycaemia risk as monotherapy']::text[], ARRAY['Twice-daily dosing', 'Requires liver monitoring']::text[], ARRAY['"-gliptin" identifies DPP-4 inhibitors', 'Check liver function before starting']::text[], '"-gliptin" → DPP-4 inhibitor, incretin booster. Learning aid — exceptions exist.', '-gliptin', 'vil-da-GLIP-tin', 'विल्-डा-ग्लिप्-टिन', '/ˌvɪldəˈɡlɪptɪn/', 'active', 'verified', '2026-09-06', '3.0', '2026-09-06T05:58:19.512078+00:00', '2026-09-06T05:58:19.512078+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('e3c4cb38-1f8c-45f6-a109-0993b8fda912', 'linagliptin', 'Linagliptin', 'Linagliptin', 'Linagliptin', 'Linagliptin', NULL, 'DPP-4 inhibitor notable for elimination that is largely independent of the kidneys.', 'Diabetes', ARRAY['5 mg']::text[], ARRAY['Tablet']::text[], ARRAY['Oral']::text[], 'Selective, reversible inhibition of dipeptidyl peptidase-4, increasing active incretin levels.', 'Glucose-dependent insulin release and glucagon suppression; weight neutral.', 'Absorbed with peak at 1.5 hours; food has minimal effect.', 'Extensive tissue binding.', 'Minimal metabolism.', 'Predominantly biliary and faecal.', 'About 30%', 'Effective half-life about 12 hours (terminal much longer)', 'Concentration dependent, high', NULL, NULL, 'Within hours', '24 hours', ARRAY['Type 2 diabetes mellitus alone or with other agents']::text[], ARRAY['Hypersensitivity', 'Type 1 diabetes and ketoacidosis']::text[], ARRAY['Pancreatitis reported', 'Bullous pemphigoid reported with DPP-4 inhibitors']::text[], ARRAY['Reduce sulfonylurea or insulin dose when combined']::text[], ARRAY['Nasopharyngitis', 'Headache', 'Cough']::text[], ARRAY['Acute pancreatitis', 'Angioedema', 'Bullous pemphigoid']::text[], ARRAY['Rifampicin (reduces effect)', 'Sulfonylureas and insulin']::text[], NULL, ARRAY['HbA1c', 'Symptoms of pancreatitis']::text[], NULL, NULL, 'Not recommended; insulin preferred.', 'Not recommended.', 'Not established in children.', 'No dose adjustment needed.', 'No dose adjustment needed — a key advantage.', 'No dose adjustment needed.', ARRAY['No dose change in renal impairment', 'Once-daily fixed dose']::text[], ARRAY['Modest HbA1c reduction', 'Cost']::text[], ARRAY['Only DPP-4 inhibitor needing no renal dose adjustment']::text[], 'Linagliptin = "liver route" so kidneys need no adjustment. Learning aid — exceptions exist.', '-gliptin', 'lin-a-GLIP-tin', 'लि-ना-ग्लिप्-टिन', '/ˌlɪnəˈɡlɪptɪn/', 'active', 'verified', '2026-09-06', '3.0', '2026-09-06T05:58:19.512078+00:00', '2026-09-06T05:58:19.512078+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('78b34290-5a0a-4d2a-a27f-c3c1f79edc9b', 'empagliflozin', 'Empagliflozin', 'Empagliflozin', 'Empagliflozin', 'Empagliflozin', NULL, 'SGLT2 inhibitor with proven cardiovascular and kidney benefits.', 'Diabetes', ARRAY['10 mg', '25 mg']::text[], ARRAY['Tablet']::text[], ARRAY['Oral']::text[], 'Blocks sodium-glucose co-transporter 2 in the proximal renal tubule, increasing urinary glucose excretion.', 'Lowers glucose independently of insulin; reduces weight, blood pressure, heart failure hospitalisation and kidney disease progression.', 'Rapidly absorbed; food has little clinical effect.', 'Volume of distribution about 74 L.', 'Mainly glucuronidation.', 'Urine and faeces.', 'Not formally established in humans', 'About 12.4 hours', 'About 86%', NULL, NULL, 'Within hours', '24 hours', ARRAY['Type 2 diabetes mellitus', 'Heart failure with reduced or preserved ejection fraction', 'Chronic kidney disease']::text[], ARRAY['Type 1 diabetes (risk of ketoacidosis)', 'Hypersensitivity', 'Dialysis']::text[], ARRAY['Euglycaemic diabetic ketoacidosis', 'Genital mycotic infection', 'Rare Fournier gangrene', 'Volume depletion']::text[], ARRAY['Withhold during acute illness, fasting or before surgery', 'Advise good genital hygiene']::text[], ARRAY['Genital fungal infection', 'Increased urination', 'Urinary tract infection', 'Thirst']::text[], ARRAY['Diabetic ketoacidosis with near-normal glucose', 'Severe urinary infection', 'Fournier gangrene']::text[], ARRAY['Diuretics (volume depletion)', 'Insulin and sulfonylureas (hypoglycaemia)']::text[], NULL, ARRAY['Renal function', 'Volume status', 'Ketones during illness']::text[], NULL, NULL, 'Not recommended.', 'Not recommended.', 'Not established in children.', 'Watch volume depletion.', 'Efficacy for glucose falls at low eGFR; cardiorenal benefit persists per guidelines.', 'No adjustment in mild to moderate impairment.', ARRAY['Cardiovascular and kidney protection', 'Weight and blood pressure reduction']::text[], ARRAY['Genital infections', 'Ketoacidosis risk in illness']::text[], ARRAY['"-gliflozin" identifies SGLT2 inhibitors', 'Sick-day rules must be taught']::text[], '"-flozin" → flush glucose out in urine. Learning aid — exceptions exist.', '-gliflozin', 'em-pa-gli-FLOH-zin', 'एम्-पा-ग्लि-फ़्लो-ज़िन', '/ˌɛmpəɡlɪˈfloʊzɪn/', 'active', 'verified', '2026-09-06', '3.0', '2026-09-06T05:58:19.512078+00:00', '2026-09-06T05:58:19.512078+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('038d25d0-7e35-4559-97f4-ac7851e753a5', 'canagliflozin', 'Canagliflozin', 'Canagliflozin', 'Canagliflozin', 'Canagliflozin', NULL, 'SGLT2 inhibitor with kidney-protective evidence in diabetic nephropathy.', 'Diabetes', ARRAY['100 mg', '300 mg']::text[], ARRAY['Tablet']::text[], ARRAY['Oral']::text[], 'Inhibits SGLT2 in the proximal tubule, reducing glucose reabsorption; also weak SGLT1 inhibition in the gut at higher doses.', 'Lowers blood glucose, weight and blood pressure; slows progression of diabetic kidney disease.', 'Absorbed with peak in 1-2 hours; take before the first meal.', 'Volume of distribution about 119 L.', 'Mainly O-glucuronidation.', 'Faecal and renal.', 'About 65%', '10.6-13.1 hours', 'About 99%', NULL, NULL, 'Within hours', '24 hours', ARRAY['Type 2 diabetes mellitus', 'Diabetic kidney disease with albuminuria']::text[], ARRAY['Type 1 diabetes', 'Severe renal impairment for glucose lowering', 'Hypersensitivity']::text[], ARRAY['Euglycaemic ketoacidosis', 'Volume depletion and hypotension', 'Genital mycotic infection']::text[], ARRAY['Take before the first meal of the day', 'Foot care advice and sick-day rules']::text[], ARRAY['Genital fungal infection', 'Increased urination', 'Thirst', 'Constipation']::text[], ARRAY['Diabetic ketoacidosis', 'Acute kidney injury with volume depletion', 'Fournier gangrene']::text[], ARRAY['Diuretics', 'Digoxin', 'Rifampicin (reduces levels)', 'Insulin and sulfonylureas']::text[], NULL, ARRAY['Renal function', 'Volume status', 'Foot examination']::text[], NULL, NULL, 'Not recommended.', 'Not recommended.', 'Not established in children.', 'Volume depletion risk higher.', 'Dose limited by eGFR for glucose control.', 'Avoid in severe impairment.', ARRAY['Kidney protection in diabetic nephropathy', 'Weight reduction']::text[], ARRAY['Genital infections', 'Volume depletion']::text[], ARRAY['SGLT2 inhibitor taken before breakfast']::text[], '"-flozin" family = sugar out through urine. Learning aid — exceptions exist.', '-gliflozin', 'kan-a-gli-FLOH-zin', 'कै-ना-ग्लि-फ़्लो-ज़िन', '/ˌkænəɡlɪˈfloʊzɪn/', 'active', 'verified', '2026-09-06', '3.0', '2026-09-06T05:58:19.512078+00:00', '2026-09-06T05:58:19.512078+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('0fb339b8-3a6e-4c6f-b731-ce69e16d7ef9', 'repaglinide', 'Repaglinide', 'Repaglinide', 'Repaglinide', 'Repaglinide', NULL, 'Short-acting meglitinide insulin secretagogue taken with meals.', 'Diabetes', ARRAY['0.5 mg', '1 mg', '2 mg']::text[], ARRAY['Tablet']::text[], ARRAY['Oral']::text[], 'Closes ATP-sensitive potassium channels in pancreatic beta cells at a site distinct from sulfonylureas, triggering insulin release.', 'Rapid, short-lived insulin secretion targeting post-meal glucose rises.', 'Rapidly absorbed; peak within 1 hour.', 'Volume of distribution about 31 L.', 'Hepatic via CYP2C8 and CYP3A4.', 'Mainly biliary and faecal.', 'About 56%', 'About 1 hour', 'More than 98%', NULL, NULL, 'Within 30 minutes', '4-6 hours', ARRAY['Type 2 diabetes mellitus, especially with irregular meal patterns']::text[], ARRAY['Type 1 diabetes and ketoacidosis', 'Severe hepatic impairment', 'Concurrent gemfibrozil']::text[], ARRAY['Hypoglycaemia if a meal is missed', 'Gemfibrozil markedly raises levels']::text[], ARRAY['Take shortly before each meal and skip the dose if the meal is skipped']::text[], ARRAY['Hypoglycaemia', 'Weight gain', 'Upper respiratory infection']::text[], ARRAY['Severe hypoglycaemia', 'Hepatic dysfunction (rare)']::text[], ARRAY['Gemfibrozil (contraindicated)', 'Clarithromycin and ketoconazole', 'Rifampicin', 'Beta blockers (mask hypoglycaemia)']::text[], NULL, ARRAY['Blood glucose', 'HbA1c', 'Weight']::text[], NULL, NULL, 'Not recommended; insulin preferred.', 'Not recommended.', 'Not established in children.', 'Start at a low dose.', 'Use with caution in severe impairment.', 'Avoid in severe impairment.', ARRAY['Flexible meal-based dosing', 'Lower risk of prolonged hypoglycaemia than sulfonylureas']::text[], ARRAY['Multiple daily doses', 'Weight gain']::text[], ARRAY['"-glinide" marks meglitinides', 'No meal means no dose']::text[], '"No meal, no meglitinide." Learning aid — exceptions exist.', '-glinide', 're-PAG-li-nide', 'रे-पैग्-लि-नाइड', '/rɪˈpæɡlɪnaɪd/', 'active', 'verified', '2026-09-06', '3.0', '2026-09-06T05:58:19.512078+00:00', '2026-09-06T05:58:19.512078+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('ba596823-fe4a-4e4b-b7a4-223a6e01a75a', 'acarbose', 'Acarbose', 'Acarbose', 'Acarbose', 'Acarbose', NULL, 'Alpha-glucosidase inhibitor that blunts post-meal glucose rises.', 'Diabetes', ARRAY['25 mg', '50 mg', '100 mg']::text[], ARRAY['Tablet']::text[], ARRAY['Oral']::text[], 'Competitively inhibits intestinal alpha-glucosidase enzymes, slowing carbohydrate digestion and absorption.', 'Reduces postprandial glucose peaks without stimulating insulin secretion.', 'Minimal systemic absorption of active drug.', 'Acts within the gut lumen.', 'Degraded by intestinal bacteria and enzymes.', 'Faecal, with a small absorbed fraction renally excreted.', 'Less than 2% systemically', 'About 2 hours (absorbed fraction)', 'Low', NULL, NULL, 'With the meal', 'Duration of digestion', ARRAY['Type 2 diabetes mellitus, particularly postprandial hyperglycaemia']::text[], ARRAY['Inflammatory bowel disease', 'Intestinal obstruction or chronic malabsorption', 'Severe renal impairment', 'Cirrhosis']::text[], ARRAY['Hypoglycaemia with sulfonylureas must be treated with glucose, not sucrose', 'Raised liver enzymes at high doses']::text[], ARRAY['Chew with the first mouthful of food', 'Start low to limit flatulence']::text[], ARRAY['Flatulence', 'Abdominal distension', 'Diarrhoea']::text[], ARRAY['Raised transaminases', 'Rare hepatitis', 'Ileus (rare)']::text[], ARRAY['Sulfonylureas and insulin', 'Digestive enzyme preparations (reduce effect)', 'Digoxin']::text[], NULL, ARRAY['HbA1c and post-meal glucose', 'Liver enzymes at high doses']::text[], NULL, NULL, 'Not recommended.', 'Not recommended.', 'Not established in children.', 'Well tolerated but GI effects limit use.', 'Avoid if creatinine clearance below 25 mL/min.', 'Avoid in cirrhosis.', ARRAY['No hypoglycaemia when used alone', 'Weight neutral']::text[], ARRAY['Prominent flatulence', 'Modest HbA1c effect']::text[], ARRAY['Works in the gut, not the bloodstream', 'Treat hypoglycaemia with glucose, not table sugar']::text[], 'Acarbose = "sugar stays in the gut" — use glucose for hypos. Learning aid — exceptions exist.', NULL, 'AY-kar-bose', 'ए-कार्-बोस', '/ˈeɪkɑːrboʊs/', 'active', 'verified', '2026-09-06', '3.0', '2026-09-06T05:58:19.512078+00:00', '2026-09-06T05:58:19.512078+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('aedd50dd-ca7d-45c6-b349-541e0120c65a', 'insulin-glargine', 'Insulin glargine', 'Insulin Glargine', 'Insulin glargine', 'Recombinant human insulin analogue', NULL, 'Long-acting basal insulin analogue providing near peakless 24-hour coverage.', 'Diabetes', ARRAY['100 units/mL', '300 units/mL']::text[], ARRAY['Prefilled pen', 'Vial', 'Cartridge']::text[], ARRAY['Subcutaneous']::text[], 'Binds insulin receptors; the modified molecule precipitates at physiological pH forming a subcutaneous depot with slow release.', 'Steady basal insulin action controlling fasting glucose with little peak.', 'Slow, prolonged absorption from the subcutaneous depot.', 'Distributes as endogenous insulin does.', 'Partially processed to active metabolites at the injection site.', 'Metabolised; minimal renal excretion of intact hormone.', 'Not applicable (subcutaneous)', 'Effect lasts about 24 hours', 'Not applicable', NULL, NULL, '1-2 hours', 'Approximately 24 hours', ARRAY['Type 1 diabetes mellitus as basal insulin', 'Type 2 diabetes requiring insulin']::text[], ARRAY['Hypoglycaemia', 'Hypersensitivity to the product']::text[], ARRAY['Never give intravenously', 'Do not mix in the same syringe with other insulins', 'Concentration strengths must not be confused']::text[], ARRAY['Rotate injection sites', 'Adjust dose for illness, exercise and fasting']::text[], ARRAY['Hypoglycaemia', 'Injection site reactions', 'Lipohypertrophy', 'Weight gain']::text[], ARRAY['Severe hypoglycaemia', 'Hypokalaemia', 'Severe allergic reactions']::text[], ARRAY['Beta blockers (mask hypoglycaemia)', 'Corticosteroids (raise glucose)', 'Alcohol', 'Other glucose-lowering drugs']::text[], NULL, ARRAY['Fasting blood glucose', 'HbA1c', 'Injection sites', 'Hypoglycaemia episodes']::text[], NULL, NULL, 'Insulin is the preferred glucose-lowering therapy in pregnancy.', 'Compatible; dose may need reduction.', 'Used in children with appropriate dosing.', 'Aim for less strict targets to limit hypoglycaemia.', 'Insulin requirement may fall; monitor closely.', 'Insulin requirement may fall.', ARRAY['Once-daily, largely peakless basal cover', 'Lower nocturnal hypoglycaemia than NPH']::text[], ARRAY['Injection required', 'Cannot be mixed with other insulins']::text[], ARRAY['Basal insulin analogue', 'Different strengths are not interchangeable unit-for-unit by volume']::text[], 'Glargine = "glass-smooth basal line". Learning aid — exceptions exist.', NULL, 'IN-su-lin GLAR-jeen', 'इन्-सु-लिन ग्लार्-जीन', NULL, 'active', 'verified', '2026-09-06', '3.0', '2026-09-06T05:58:19.512078+00:00', '2026-09-06T05:58:19.512078+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('4dd39f33-3b2f-40f0-8acb-d4359a74af21', 'lisinopril', 'Lisinopril', 'Lisinopril', 'Lisinopril', 'Lisinopril dihydrate', NULL, 'Long-acting ACE inhibitor for hypertension, heart failure and post-infarction care.', 'Cardiovascular', ARRAY['2.5 mg', '5 mg', '10 mg', '20 mg']::text[], ARRAY['Tablet']::text[], ARRAY['Oral']::text[], 'Inhibits angiotensin-converting enzyme, reducing angiotensin II and aldosterone and increasing bradykinin.', 'Lowers blood pressure and afterload; provides renal protection in proteinuric kidney disease.', 'Absorbed slowly; food does not affect absorption.', 'Does not require hepatic activation (not a prodrug).', 'Not metabolised.', 'Renal, unchanged.', 'About 25%', 'About 12 hours (effective)', 'Minimal', NULL, NULL, 'About 1 hour', '24 hours', ARRAY['Hypertension', 'Heart failure with reduced ejection fraction', 'After myocardial infarction', 'Diabetic nephropathy']::text[], ARRAY['Pregnancy', 'History of ACE inhibitor angioedema', 'Bilateral renal artery stenosis', 'Concurrent aliskiren in diabetes']::text[], ARRAY['Angioedema', 'Hyperkalaemia', 'Acute kidney injury with volume depletion or NSAIDs']::text[], ARRAY['Check renal function and potassium 1-2 weeks after starting or increasing the dose']::text[], ARRAY['Dry cough', 'Dizziness', 'Headache', 'Fatigue']::text[], ARRAY['Angioedema', 'Severe hyperkalaemia', 'Acute kidney injury']::text[], ARRAY['Potassium supplements and potassium-sparing diuretics', 'NSAIDs', 'Lithium', 'ARBs and aliskiren']::text[], NULL, ARRAY['Blood pressure', 'Serum creatinine and potassium']::text[], NULL, NULL, 'Contraindicated.', 'Alternatives preferred.', 'Used in children for hypertension under specialist care.', 'Start low; postural hypotension risk.', 'Reduce dose; monitor closely.', 'No routine adjustment.', ARRAY['Once-daily dosing', 'Not dependent on hepatic activation']::text[], ARRAY['Dry cough', 'Renal and potassium monitoring needed']::text[], ARRAY['"-pril" identifies ACE inhibitors', 'Cough is the classic reason for switching to an ARB']::text[], '"-pril" → ACE inhibitor; cough and potassium rise. Learning aid — exceptions exist.', '-pril', 'lye-SIN-oh-pril', 'लाइ-सि-नो-प्रिल', '/laɪˈsɪnoʊprɪl/', 'active', 'verified', '2026-09-06', '3.0', '2026-09-06T05:58:19.512078+00:00', '2026-09-06T05:58:19.512078+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('050e4a8c-3704-420e-a417-f8f81a43ae8e', 'olmesartan', 'Olmesartan', 'Olmesartan', 'Olmesartan medoxomil', 'Medoxomil', NULL, 'Angiotensin II receptor blocker used for hypertension.', 'Cardiovascular', ARRAY['10 mg', '20 mg', '40 mg']::text[], ARRAY['Tablet']::text[], ARRAY['Oral']::text[], 'Selectively blocks the angiotensin II type 1 receptor, preventing vasoconstriction and aldosterone release.', 'Sustained 24-hour blood pressure reduction without the cough of ACE inhibitors.', 'Prodrug hydrolysed during absorption to active olmesartan.', 'Volume of distribution about 17 L.', 'No further significant metabolism after activation.', 'Biliary and renal.', 'About 26%', '10-15 hours', 'More than 99%', NULL, NULL, '1-2 hours', '24 hours', ARRAY['Hypertension', 'Blood pressure control in patients intolerant of ACE inhibitors']::text[], ARRAY['Pregnancy', 'Biliary obstruction', 'Concurrent aliskiren in diabetes']::text[], ARRAY['Hyperkalaemia', 'Rare sprue-like enteropathy with chronic diarrhoea and weight loss', 'Acute kidney injury with volume depletion']::text[], ARRAY['Monitor renal function and potassium after initiation']::text[], ARRAY['Dizziness', 'Headache', 'Fatigue']::text[], ARRAY['Angioedema (rare)', 'Severe hyperkalaemia', 'Sprue-like enteropathy']::text[], ARRAY['NSAIDs', 'Potassium-sparing diuretics', 'Lithium', 'ACE inhibitors']::text[], NULL, ARRAY['Blood pressure', 'Creatinine and potassium']::text[], NULL, NULL, 'Contraindicated.', 'Not recommended.', 'Approved from 6 years in some regions.', 'Start at a lower dose.', 'Caution in severe impairment.', 'No routine adjustment.', ARRAY['No cough compared with ACE inhibitors', 'Once-daily control']::text[], ARRAY['Rare enteropathy', 'Same fetal risk as ACE inhibitors']::text[], ARRAY['"-sartan" identifies ARBs', 'Never use in pregnancy']::text[], '"-sartan" → ARB; blocks the receptor, no cough. Learning aid — exceptions exist.', '-sartan', 'ol-me-SAR-tan', 'ओल्-मे-सार्-टैन', '/ˌɒlmɪˈsɑːrtən/', 'active', 'verified', '2026-09-06', '3.0', '2026-09-06T05:58:19.512078+00:00', '2026-09-06T05:58:19.512078+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('77b2c98d-a5f5-4557-bb6e-c351433be904', 'bisoprolol', 'Bisoprolol', 'Bisoprolol', 'Bisoprolol fumarate', 'Fumarate', NULL, 'Cardioselective beta blocker used in hypertension, angina and heart failure.', 'Cardiovascular', ARRAY['2.5 mg', '5 mg', '10 mg']::text[], ARRAY['Tablet']::text[], ARRAY['Oral']::text[], 'Selectively blocks beta-1 adrenergic receptors, reducing heart rate, contractility and renin release.', 'Lowers blood pressure and myocardial oxygen demand; improves survival in chronic heart failure.', 'Well absorbed with little first-pass effect.', 'Volume of distribution about 3.5 L/kg.', 'About half metabolised hepatically.', 'Renal and hepatic in roughly equal parts.', 'About 90%', '10-12 hours', 'About 30%', NULL, NULL, '1-2 hours', '24 hours', ARRAY['Hypertension', 'Stable angina', 'Chronic heart failure (with careful titration)']::text[], ARRAY['Severe bradycardia or heart block', 'Decompensated heart failure', 'Severe asthma', 'Cardiogenic shock']::text[], ARRAY['Never stop abruptly — rebound angina and arrhythmia', 'May mask hypoglycaemia symptoms']::text[], ARRAY['Start low and titrate slowly in heart failure']::text[], ARRAY['Fatigue', 'Bradycardia', 'Cold extremities', 'Dizziness']::text[], ARRAY['Severe bradycardia or heart block', 'Bronchospasm', 'Worsening heart failure during rapid titration']::text[], ARRAY['Verapamil and diltiazem', 'Other rate-limiting drugs', 'Insulin and sulfonylureas', 'Clonidine (rebound risk)']::text[], NULL, ARRAY['Heart rate', 'Blood pressure', 'Heart failure symptoms']::text[], NULL, NULL, 'Used when necessary with monitoring.', 'Considered compatible with monitoring of the infant.', 'Limited paediatric data.', 'Start low; bradycardia risk.', 'Reduce dose in severe impairment.', 'Reduce dose in severe impairment.', ARRAY['Highly beta-1 selective', 'Survival benefit in heart failure']::text[], ARRAY['Fatigue', 'Cannot be stopped abruptly']::text[], ARRAY['"-olol" marks beta blockers', 'One of the four heart failure beta blockers']::text[], '"-olol" → beta blocker; never stop suddenly. Learning aid — exceptions exist.', '-olol', 'bis-OH-proe-lol', 'बिस्-ओ-प्रो-लॉल', '/bɪˈsoʊproʊlɒl/', 'active', 'verified', '2026-09-06', '3.0', '2026-09-06T05:58:19.512078+00:00', '2026-09-06T05:58:19.512078+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('dfae7bf2-4f7a-49c3-9778-3c99cb61eec9', 'diltiazem', 'Diltiazem', 'Diltiazem', 'Diltiazem', 'Hydrochloride', NULL, 'Non-dihydropyridine calcium channel blocker for angina, hypertension and rate control.', 'Cardiovascular', ARRAY['30 mg', '60 mg', '90 mg SR']::text[], ARRAY['Tablet', 'Sustained-release capsule', 'Injection']::text[], ARRAY['Oral', 'Intravenous']::text[], 'Blocks L-type calcium channels in cardiac and vascular smooth muscle, slowing AV nodal conduction and causing vasodilation.', 'Reduces heart rate, contractility and blood pressure; relieves coronary vasospasm.', 'Well absorbed with extensive first-pass metabolism.', 'Volume of distribution about 3-13 L/kg.', 'Hepatic via CYP3A4; also a CYP3A4 inhibitor.', 'Renal and biliary as metabolites.', 'About 40%', '3-4.5 hours (longer for SR)', '70-80%', NULL, NULL, '30-60 minutes oral', '6-8 hours (24 hours for SR)', ARRAY['Stable and vasospastic angina', 'Hypertension', 'Rate control in atrial fibrillation', 'Supraventricular tachycardia (intravenous)']::text[], ARRAY['Severe bradycardia or second/third degree heart block', 'Sick sinus syndrome without a pacemaker', 'Systolic heart failure', 'Severe hypotension']::text[], ARRAY['Do not combine with intravenous beta blockers', 'Bradycardia and heart block risk', 'CYP3A4 inhibition raises other drug levels']::text[], ARRAY['Do not crush modified-release forms', 'Monitor pulse']::text[], ARRAY['Ankle oedema', 'Headache', 'Bradycardia', 'Constipation']::text[], ARRAY['Complete heart block', 'Severe hypotension', 'Worsening heart failure', 'Hepatotoxicity (rare)']::text[], ARRAY['Beta blockers', 'Statins (especially simvastatin)', 'Digoxin', 'Ciclosporin and carbamazepine']::text[], NULL, ARRAY['Heart rate and rhythm', 'Blood pressure', 'Liver function occasionally']::text[], NULL, NULL, 'Use only if clearly needed.', 'Small amounts in milk; caution.', 'Limited paediatric use.', 'Start at lower doses.', 'No major adjustment.', 'Reduce dose in impairment.', ARRAY['Rate control plus antianginal action', 'Useful when beta blockers are contraindicated in asthma']::text[], ARRAY['Negative inotropy', 'Multiple CYP3A4 interactions']::text[], ARRAY['Non-dihydropyridine calcium blocker', 'Avoid combining with beta blockers for rate control']::text[], 'Diltiazem and verapamil = "heart-slowing" calcium blockers. Learning aid — exceptions exist.', NULL, 'dil-TYE-a-zem', 'डिल्-टाइ-आ-ज़ेम', '/dɪlˈtaɪəzɛm/', 'active', 'verified', '2026-09-06', '3.0', '2026-09-06T05:58:19.512078+00:00', '2026-09-06T05:58:19.512078+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('fff45d4f-bb1f-4881-8bc6-6e8e7a2f4e11', 'verapamil', 'Verapamil', 'Verapamil', 'Verapamil', 'Hydrochloride', NULL, 'Non-dihydropyridine calcium channel blocker with the strongest cardiac depressant effect of the class.', 'Cardiovascular', ARRAY['40 mg', '80 mg', '120 mg SR']::text[], ARRAY['Tablet', 'Sustained-release tablet', 'Injection']::text[], ARRAY['Oral', 'Intravenous']::text[], 'Blocks L-type calcium channels, markedly slowing AV nodal conduction and reducing contractility.', 'Rate control, antianginal and antihypertensive effects.', 'Well absorbed but extensive first-pass metabolism.', 'Volume of distribution about 3-5 L/kg.', 'Hepatic via CYP3A4; potent CYP3A4 and P-glycoprotein inhibitor.', 'Mainly renal as metabolites.', 'About 20-35%', '3-7 hours', 'About 90%', NULL, NULL, '1-2 hours oral; minutes intravenous', '6-8 hours', ARRAY['Supraventricular tachycardia', 'Rate control in atrial fibrillation', 'Angina', 'Hypertension', 'Cluster headache prophylaxis']::text[], ARRAY['Systolic heart failure', 'Second or third degree heart block', 'Wolff-Parkinson-White with atrial fibrillation', 'Concurrent intravenous beta blockade']::text[], ARRAY['Severe bradycardia and asystole risk with intravenous use plus beta blockers', 'Marked constipation', 'Raises digoxin levels']::text[], ARRAY['Do not crush sustained-release tablets', 'Advise fluid and fibre for constipation']::text[], ARRAY['Constipation', 'Headache', 'Ankle oedema', 'Dizziness']::text[], ARRAY['Complete heart block', 'Severe hypotension', 'Acute heart failure']::text[], ARRAY['Beta blockers', 'Digoxin', 'Simvastatin', 'Ciclosporin', 'Grapefruit juice']::text[], NULL, ARRAY['ECG and heart rate', 'Blood pressure', 'Digoxin level if co-prescribed']::text[], NULL, NULL, 'Use only if clearly needed.', 'Considered compatible.', 'Specialist use in children.', 'Start low; constipation and bradycardia risk.', 'Caution; reduce dose in severe impairment.', 'Reduce dose substantially.', ARRAY['Effective rate control and antianginal action']::text[], ARRAY['Constipation', 'Contraindicated in systolic heart failure']::text[], ARRAY['Most cardiodepressant calcium channel blocker', 'Constipation is the classic side effect']::text[], 'Verapamil = "very constipating" calcium blocker. Learning aid — exceptions exist.', NULL, 'ver-AP-a-mil', 'वे-रै-पा-मिल', '/vəˈræpəmɪl/', 'active', 'verified', '2026-09-06', '3.0', '2026-09-06T05:58:19.512078+00:00', '2026-09-06T05:58:19.512078+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('82a37825-a5bf-4037-b809-d194a9512baf', 'chlorthalidone', 'Chlorthalidone', 'Chlorthalidone', 'Chlorthalidone', 'Chlorthalidone', NULL, 'Thiazide-like diuretic with a long duration of action used for hypertension.', 'Cardiovascular', ARRAY['6.25 mg', '12.5 mg', '25 mg']::text[], ARRAY['Tablet']::text[], ARRAY['Oral']::text[], 'Inhibits sodium-chloride reabsorption in the distal convoluted tubule, promoting sodium and water loss.', 'Sustained blood pressure reduction with proven cardiovascular outcome benefit.', 'Well absorbed; slow onset.', 'Concentrates in red blood cells.', 'Limited metabolism.', 'Mainly renal.', 'About 65%', '40-60 hours', 'About 75%', NULL, NULL, '2-3 hours', 'Up to 48-72 hours', ARRAY['Hypertension', 'Oedema', 'Prevention of calcium-containing kidney stones']::text[], ARRAY['Anuria', 'Severe hyponatraemia or hypokalaemia', 'Sulfonamide hypersensitivity']::text[], ARRAY['Electrolyte disturbance, especially hyponatraemia and hypokalaemia', 'Hyperuricaemia may precipitate gout', 'Raises blood glucose']::text[], ARRAY['Check electrolytes 2-4 weeks after starting', 'Take in the morning']::text[], ARRAY['Increased urination', 'Dizziness', 'Hypokalaemia', 'Muscle cramps']::text[], ARRAY['Severe hyponatraemia', 'Severe hypokalaemia and arrhythmia', 'Acute gout', 'Pancreatitis (rare)']::text[], ARRAY['Lithium', 'Digoxin (via hypokalaemia)', 'NSAIDs', 'Other antihypertensives']::text[], NULL, ARRAY['Sodium, potassium and renal function', 'Blood pressure', 'Uric acid and glucose']::text[], NULL, NULL, 'Not first choice; use only if necessary.', 'May suppress lactation; caution.', 'Rarely used in children.', 'Higher hyponatraemia risk; use low doses.', 'Ineffective at low eGFR.', 'Caution in impairment.', ARRAY['Longer acting and more potent than hydrochlorothiazide', 'Strong outcome evidence']::text[], ARRAY['Greater electrolyte disturbance risk']::text[], ARRAY['Thiazide-like diuretic', 'Low doses give most of the benefit']::text[], 'Chlorthalidone = "long-acting thiazide-like" — check the sodium. Learning aid — exceptions exist.', NULL, 'klor-THAL-i-done', 'क्लोर्-थै-लि-डोन', '/klɔːrˈθælɪdoʊn/', 'active', 'verified', '2026-09-06', '3.0', '2026-09-06T05:58:19.512078+00:00', '2026-09-06T05:58:19.512078+00:00') ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.medicines (id, slug, generic_name, display_name, active_ingredient, salt, synonyms, description, category, strengths, dosage_forms, routes, mechanism_of_action, pharmacodynamics, absorption, distribution, metabolism, excretion, bioavailability, half_life, protein_binding, volume_of_distribution, clearance, onset, duration, indications, contraindications, warnings, precautions, common_adverse_effects, serious_adverse_effects, drug_interactions, food_interactions, monitoring, storage, patient_counselling, pregnancy, lactation, pediatric, geriatric, renal, hepatic, advantages, disadvantages, key_points, memory_trick, key_suffix, pronunciation_en, pronunciation_hi, pronunciation_ipa, status, verification_status, last_verified, data_version, created_at, updated_at) VALUES ('d161904e-030f-450c-995d-6c336c01d6d0', 'torsemide', 'Torsemide', 'Torsemide (Torasemide)', 'Torsemide', 'Torsemide', NULL, 'Loop diuretic with more predictable absorption and longer action than furosemide.', 'Cardiovascular', ARRAY['5 mg', '10 mg', '20 mg']::text[], ARRAY['Tablet', 'Injection']::text[], ARRAY['Oral', 'Intravenous']::text[], 'Inhibits the Na-K-2Cl co-transporter in the thick ascending limb of the loop of Henle.', 'Potent diuresis with reliable oral bioavailability; also mild antihypertensive effect.', 'Rapid, near complete absorption largely unaffected by food or oedema.', 'Volume of distribution about 12-15 L.', 'Hepatic via CYP2C9 (about 80%).', 'Renal and hepatic.', 'About 80-90%', '3-4 hours', 'More than 99%', NULL, NULL, 'About 1 hour', '6-8 hours', ARRAY['Oedema in heart failure', 'Oedema in renal or hepatic disease', 'Hypertension']::text[], ARRAY['Anuria', 'Severe electrolyte depletion', 'Hepatic coma', 'Sulfonylurea hypersensitivity (caution)']::text[], ARRAY['Electrolyte depletion and dehydration', 'Ototoxicity with rapid high-dose intravenous use']::text[], ARRAY['Monitor weight and electrolytes', 'Take in the morning to avoid nocturia']::text[], ARRAY['Increased urination', 'Dizziness', 'Headache', 'Hypokalaemia']::text[], ARRAY['Severe dehydration', 'Hypokalaemia with arrhythmia', 'Ototoxicity', 'Acute kidney injury']::text[], ARRAY['NSAIDs', 'Aminoglycosides', 'Digoxin', 'Lithium']::text[], NULL, ARRAY['Weight and fluid balance', 'Electrolytes and renal function', 'Blood pressure']::text[], NULL, NULL, 'Use only if clearly needed.', 'Limited data; may suppress lactation.', 'Limited paediatric data.', 'Monitor for dehydration and falls.', 'Higher doses often needed; monitor closely.', 'Caution in cirrhosis.', ARRAY['More predictable absorption than furosemide', 'Longer duration reduces dosing frequency']::text[], ARRAY['Electrolyte disturbance', 'Requires monitoring']::text[], ARRAY['Loop diuretic', 'Bioavailability is more reliable than furosemide in heart failure']::text[], 'Loop diuretics = "torrential urine, check potassium". Learning aid — exceptions exist.', NULL, 'TOR-se-mide', 'टोर्-से-माइड', '/ˈtɔːrsəmaɪd/', 'active', 'verified', '2026-09-06', '3.0', '2026-09-06T05:58:19.512078+00:00', '2026-09-06T05:58:19.512078+00:00') ON CONFLICT (slug) DO NOTHING;
