INSERT INTO public.suffix_patterns (id, suffix, meaning, class_hint, examples, note) VALUES ('a2fb8e6e-309f-4dbc-a2d1-f10c3eb79431', '-setron', '5-HT3 antagonist antiemetics', 'Antiemetics', ARRAY['Ondansetron', 'Granisetron']::text[], 'Memory aid only; exceptions exist.') ON CONFLICT (suffix) DO NOTHING;
