INSERT INTO public.suffix_patterns (id, suffix, meaning, class_hint, examples, note) VALUES ('70c76ebd-f33a-426d-a8aa-3ad2fabf8e3a', '-thromycin', 'Macrolide antibiotics', 'Macrolides', ARRAY['Azithromycin', 'Clarithromycin']::text[], 'Memory aid only; exceptions exist.') ON CONFLICT (suffix) DO NOTHING;
