INSERT INTO public.suffix_patterns (id, suffix, meaning, class_hint, examples, note) VALUES ('5b375472-6b98-454f-8572-4ee51f58874e', '-gliptin', 'DPP-4 inhibitor', 'DPP-4 Inhibitors', ARRAY['Sitagliptin']::text[], 'Weight neutral, low hypoglycaemia risk alone.') ON CONFLICT (suffix) DO NOTHING;
INSERT INTO public.suffix_patterns (id, suffix, meaning, class_hint, examples, note) VALUES ('79e5123f-a5ff-4f2f-ba14-9231d03e7780', '-gliflozin', 'SGLT2 inhibitor', 'SGLT2 Inhibitors', ARRAY['Dapagliflozin']::text[], 'Genital infections and sick-day rules matter.') ON CONFLICT (suffix) DO NOTHING;
INSERT INTO public.suffix_patterns (id, suffix, meaning, class_hint, examples, note) VALUES ('d5d6449e-d479-443a-9f0a-22edd3025ad8', '-glitazone', 'Thiazolidinedione', 'Thiazolidinediones', ARRAY['Pioglitazone']::text[], 'Fluid retention and heart failure risk.') ON CONFLICT (suffix) DO NOTHING;
INSERT INTO public.suffix_patterns (id, suffix, meaning, class_hint, examples, note) VALUES ('c0aa5c3f-f1bb-47d1-a105-924e75b82b54', '-lukast', 'Leukotriene receptor antagonist', 'Leukotriene Antagonists', ARRAY['Montelukast']::text[], 'Not for acute attacks; watch mood changes.') ON CONFLICT (suffix) DO NOTHING;
INSERT INTO public.suffix_patterns (id, suffix, meaning, class_hint, examples, note) VALUES ('2d602cd6-80cc-488f-a308-dd772df063f7', '-azepam', 'Benzodiazepine', 'Benzodiazepines', ARRAY['Diazepam', 'Alprazolam']::text[], 'Dependence with prolonged use.') ON CONFLICT (suffix) DO NOTHING;
INSERT INTO public.suffix_patterns (id, suffix, meaning, class_hint, examples, note) VALUES ('7fa2fbb2-ea47-4a23-8fa1-56e9b817b866', '-bendazole', 'Benzimidazole anthelmintic', 'Anthelmintics', ARRAY['Albendazole', 'Mebendazole']::text[], 'Single-dose therapy for many gut worms.') ON CONFLICT (suffix) DO NOTHING;
INSERT INTO public.suffix_patterns (id, suffix, meaning, class_hint, examples, note) VALUES ('fec5df95-1fa4-4a8b-bd3a-1c5f7540e254', '-vir', 'Antiviral agent', 'Antivirals', ARRAY['Aciclovir', 'Oseltamivir']::text[], 'Start early for best benefit.') ON CONFLICT (suffix) DO NOTHING;
INSERT INTO public.suffix_patterns (id, suffix, meaning, class_hint, examples, note) VALUES ('fd3acafa-b89a-4769-8dd4-c3b5857df72d', '-parin', 'Heparin anticoagulant', 'Anticoagulants', ARRAY['Enoxaparin']::text[], 'Mainly anti-factor Xa activity.') ON CONFLICT (suffix) DO NOTHING;
INSERT INTO public.suffix_patterns (id, suffix, meaning, class_hint, examples, note) VALUES ('81ef0889-3a74-4410-a1ec-0aa0f21af826', '-fibrate', 'Fibrate lipid-lowering agent', 'Fibrates', ARRAY['Fenofibrate']::text[], 'Mainly lowers triglycerides.') ON CONFLICT (suffix) DO NOTHING;
INSERT INTO public.suffix_patterns (id, suffix, meaning, class_hint, examples, note) VALUES ('fd433cb5-0caa-4abc-b935-fea56b1245d1', '-osin', 'Alpha-1 blocker', 'Alpha Blockers', ARRAY['Tamsulosin']::text[], 'Postural hypotension and floppy iris syndrome.') ON CONFLICT (suffix) DO NOTHING;
INSERT INTO public.mnemonics (id, title, content, explanation, medicine_id, class_id, created_at) VALUES ('993cea61-7e25-4605-94ba-eec83c1d1848', 'ARBs end in -sartan', 'Losartan, Valsartan, Telmisartan, Candesartan, Olmesartan', 'All block the angiotensin II AT1 receptor.', NULL, '2b9f5d41-c4c5-41fb-b9cb-67c2bf49e4d5', '2026-08-18T16:52:03.908289+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mnemonics (id, title, content, explanation, medicine_id, class_id, created_at) VALUES ('e7e41b24-a0ed-4d0b-a900-5ff7c3a0ef94', 'PPIs end in -prazole', 'Omeprazole, Pantoprazole, Rabeprazole, Esomeprazole', 'All irreversibly block the gastric proton pump.', NULL, '92696c93-07f2-4898-94a5-d5391b2488d0', '2026-08-18T16:52:03.908289+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mnemonics (id, title, content, explanation, medicine_id, class_id, created_at) VALUES ('4087b7ba-d8b4-46ec-93e7-3e001a55b198', 'Statins end in -statin', 'Atorvastatin, Rosuvastatin, Simvastatin', 'All inhibit HMG-CoA reductase.', NULL, '940bcacf-0a74-43b0-96ad-4df302caf186', '2026-08-18T16:52:03.908289+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.mnemonics (id, title, content, explanation, medicine_id, class_id, created_at) VALUES ('7ac0c53d-c4bb-4228-ba64-7459953f6144', 'CCBs end in -dipine', 'Amlodipine, Nifedipine, Felodipine', 'Dihydropyridine calcium channel blockers; ankle oedema is the clue.', NULL, 'c4291a4a-b504-4870-8ffa-2aab6ee7f374', '2026-08-18T16:52:03.908289+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, question, answer, topic, difficulty, medicine_id, class_id, created_at) VALUES ('f73ac887-90a2-4b63-bd70-7ec160a20000', 'What is the antidote for paracetamol overdose?', 'N-acetylcysteine', 'Emergency', 'easy', 'fefb6ce8-d380-407e-af03-709d3fe462d8', NULL, '2026-08-18T16:52:03.165523+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, question, answer, topic, difficulty, medicine_id, class_id, created_at) VALUES ('3ed7dfe5-e00d-4d60-b347-8576766b6f97', 'What does clavulanic acid add to amoxicillin?', 'Beta-lactamase inhibition, protecting amoxicillin from breakdown', 'Mechanism', 'easy', 'd643f589-932f-4e10-9ba9-62ecc9dbc960', NULL, '2026-08-18T16:52:03.165523+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, question, answer, topic, difficulty, medicine_id, class_id, created_at) VALUES ('b13ecb2d-c0c5-49cc-95e4-7c204aa162f7', 'Why is doxycycline avoided in pregnancy and young children?', 'Risk of tooth discolouration and effects on developing bone', 'Safety', 'easy', 'e9a6149a-ec37-446c-a5e8-42131445c225', NULL, '2026-08-18T16:52:03.165523+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, question, answer, topic, difficulty, medicine_id, class_id, created_at) VALUES ('42a7e934-19b9-4ecf-b47a-bb3da19cfa8d', 'What must be strictly avoided with metronidazole?', 'Alcohol, due to a disulfiram-like reaction', 'Safety', 'easy', 'b71dfafe-8abe-4cf8-ac40-7162b69890e4', NULL, '2026-08-18T16:52:03.165523+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, question, answer, topic, difficulty, medicine_id, class_id, created_at) VALUES ('42fd2e4d-6e04-4804-a56a-dded286c19cb', 'What is the main mechanism of omeprazole?', 'Irreversible inhibition of the gastric H+/K+-ATPase (proton pump)', 'Mechanism', 'easy', '74ef0987-9f92-49c9-8645-fbb4599876ed', NULL, '2026-08-18T16:52:03.165523+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, question, answer, topic, difficulty, medicine_id, class_id, created_at) VALUES ('0bf7bfc0-f214-42b7-9cce-bebcc4e1ab85', 'Why is ondansetron used cautiously in cardiac patients?', 'It can prolong the QT interval', 'Safety', 'medium', '4d6b410b-0c2c-4044-bb74-3e034f0c685a', NULL, '2026-08-18T16:52:03.165523+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, question, answer, topic, difficulty, medicine_id, class_id, created_at) VALUES ('ec04b3cf-e610-4282-bf7f-18b9c16c293d', 'What is the mechanism of salbutamol?', 'Beta-2 adrenoceptor agonism relaxing bronchial smooth muscle', 'Mechanism', 'easy', '1b863c01-ed09-4f6f-b66d-3aab15cc6552', NULL, '2026-08-18T16:52:03.165523+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, question, answer, topic, difficulty, medicine_id, class_id, created_at) VALUES ('1c5bb549-8793-4300-9b31-03e834bf1c3c', 'How is metformin eliminated?', 'Excreted unchanged by the kidneys; it is not metabolised', 'ADME', 'medium', '9b9c4665-37b7-4d8f-829d-bfc0a0ed183a', NULL, '2026-08-18T16:52:03.165523+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, question, answer, topic, difficulty, medicine_id, class_id, created_at) VALUES ('9abf65f5-3280-4807-98bd-3607c549dd39', 'What is the classic dose-related adverse effect of amlodipine?', 'Ankle oedema', 'Adverse Effects', 'easy', 'e3aa7b24-c39c-4af2-ae98-8c50729fa971', NULL, '2026-08-18T16:52:03.165523+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, question, answer, topic, difficulty, medicine_id, class_id, created_at) VALUES ('91dd157e-f51e-4394-8de7-84791c4a96c6', 'Which class does losartan belong to?', 'ARB — Angiotensin II receptor blocker', 'Drug Classes', 'easy', 'f0eae62e-dd32-4c3c-9413-7b86dcb24f5d', NULL, '2026-08-18T16:52:03.165523+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, question, answer, topic, difficulty, medicine_id, class_id, created_at) VALUES ('494f1bac-9b8b-4ee7-a381-8d0f59bdcbad', 'Which ARB has the longest half-life?', 'Telmisartan, about 24 hours', 'Pharmacokinetics', 'medium', '97ee4bde-7a9d-43a7-9286-0bcab5809e2b', NULL, '2026-08-18T16:52:03.165523+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, question, answer, topic, difficulty, medicine_id, class_id, created_at) VALUES ('9f955fe4-896a-4bec-8422-bd1c44ecdd57', 'When should levothyroxine be taken?', 'On an empty stomach, 30-60 minutes before breakfast', 'Counselling', 'easy', 'bf45cfb8-eeaf-4df1-bbea-a751e72c3bcd', NULL, '2026-08-18T16:52:03.165523+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, question, answer, topic, difficulty, medicine_id, class_id, created_at) VALUES ('fda3ebb1-c57a-497d-ba9e-a283016d1c47', 'Which electrolyte must be monitored with furosemide?', 'Potassium (hypokalaemia risk)', 'Monitoring', 'easy', 'ac5fbe3d-07b5-4768-bc11-60a4b530fd25', NULL, '2026-08-18T16:52:03.165523+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, question, answer, topic, difficulty, medicine_id, class_id, created_at) VALUES ('d8bdc773-794c-46ab-92b7-fc5978425a1a', 'How long does the antiplatelet effect of aspirin last?', '7-10 days, the lifespan of the platelet, because COX-1 inhibition is irreversible', 'Pharmacodynamics', 'medium', '956bb130-891a-48c7-98ca-260b286d84c4', NULL, '2026-08-18T16:52:03.165523+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, question, answer, topic, difficulty, medicine_id, class_id, created_at) VALUES ('fce6d0c9-427a-4084-a4ab-9c9adeb606a2', 'Which enzyme activates clopidogrel?', 'CYP2C19 in the liver', 'ADME', 'medium', 'bb0c1209-dd6b-4496-903c-3d3b11d21667', NULL, '2026-08-18T16:52:03.165523+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, question, answer, topic, difficulty, medicine_id, class_id, created_at) VALUES ('dbdd4c53-0dd8-446a-bf65-8a9f20fd7b33', 'What does ADME stand for?', 'Absorption, Distribution, Metabolism, Excretion', 'ADME', 'easy', NULL, NULL, '2026-08-18T16:52:03.4139+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, question, answer, topic, difficulty, medicine_id, class_id, created_at) VALUES ('62eb0d9a-1a7c-4c61-b2ca-0576e5527cf4', 'Define bioavailability.', 'The fraction of an administered dose that reaches the systemic circulation unchanged', 'Pharmacokinetics', 'easy', NULL, NULL, '2026-08-18T16:52:03.4139+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, question, answer, topic, difficulty, medicine_id, class_id, created_at) VALUES ('d1e66b72-b673-4d7d-bce3-4fda7a5b3342', 'Define half-life.', 'The time taken for the plasma concentration of a drug to fall by half', 'Pharmacokinetics', 'easy', NULL, NULL, '2026-08-18T16:52:03.4139+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, question, answer, topic, difficulty, medicine_id, class_id, created_at) VALUES ('8160cba0-41e7-4602-ae01-34898af2f9be', 'What does the suffix -prazole indicate?', 'Proton pump inhibitor', 'Suffixes', 'easy', NULL, NULL, '2026-08-18T16:52:03.4139+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, question, answer, topic, difficulty, medicine_id, class_id, created_at) VALUES ('89fd7e2b-c75d-4dc8-9008-9f496114c454', 'What does the suffix -pril indicate?', 'ACE inhibitor', 'Suffixes', 'easy', NULL, NULL, '2026-08-18T16:52:03.4139+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.flashcards (id, question, answer, topic, difficulty, medicine_id, class_id, created_at) VALUES ('eb0f43ea-2cb4-4006-98f5-13f66268dc4d', 'Pharmacokinetics vs pharmacodynamics?', 'Pharmacokinetics is what the body does to the drug; pharmacodynamics is what the drug does to the body', 'Concepts', 'easy', NULL, NULL, '2026-08-18T16:52:03.4139+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quiz_questions (id, question, question_type, options, correct_answer, explanation, topic, difficulty, medicine_id, created_at) VALUES ('6320918f-8d6c-42da-8475-e7b0d49ec36e', 'Losartan belongs to which drug class?', 'mcq', ARRAY['ACE inhibitor', 'ARB', 'Beta blocker', 'Calcium channel blocker']::text[], 'ARB', 'Losartan blocks the angiotensin II AT1 receptor. The -sartan suffix is a memory aid for ARBs.', 'Drug Classes', 'easy', NULL, '2026-08-18T16:52:03.660955+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quiz_questions (id, question, question_type, options, correct_answer, explanation, topic, difficulty, medicine_id, created_at) VALUES ('468c6ca7-7299-41af-a656-163744cbdd93', 'Which medicine is the usual first-line oral therapy in type 2 diabetes?', 'mcq', ARRAY['Glimepiride', 'Metformin', 'Insulin glargine', 'Amlodipine']::text[], 'Metformin', 'Metformin is weight neutral, does not intrinsically cause hypoglycaemia and has strong long-term evidence.', 'Pharmacology', 'easy', NULL, '2026-08-18T16:52:03.660955+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quiz_questions (id, question, question_type, options, correct_answer, explanation, topic, difficulty, medicine_id, created_at) VALUES ('b279e5d7-2805-4188-be08-cf92037cb871', 'The antidote for paracetamol overdose is:', 'mcq', ARRAY['Naloxone', 'Flumazenil', 'N-acetylcysteine', 'Atropine']::text[], 'N-acetylcysteine', 'N-acetylcysteine replenishes glutathione, which detoxifies the reactive metabolite NAPQI.', 'Emergency', 'easy', NULL, '2026-08-18T16:52:03.660955+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quiz_questions (id, question, question_type, options, correct_answer, explanation, topic, difficulty, medicine_id, created_at) VALUES ('f2a13514-f3cf-47af-aaeb-56366d4151f0', 'Which suffix usually indicates a proton pump inhibitor?', 'mcq', ARRAY['-sartan', '-prazole', '-olol', '-statin']::text[], '-prazole', 'Omeprazole, pantoprazole and rabeprazole are proton pump inhibitors.', 'Medical Terms', 'easy', NULL, '2026-08-18T16:52:03.660955+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quiz_questions (id, question, question_type, options, correct_answer, explanation, topic, difficulty, medicine_id, created_at) VALUES ('d822f37b-b52a-439d-8179-f448e842c01b', 'Metformin is mainly eliminated by:', 'mcq', ARRAY['Hepatic metabolism', 'Renal excretion unchanged', 'Biliary excretion after conjugation', 'Exhalation']::text[], 'Renal excretion unchanged', 'Metformin is not metabolised; renal impairment therefore raises the risk of accumulation.', 'ADME', 'medium', NULL, '2026-08-18T16:52:03.660955+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quiz_questions (id, question, question_type, options, correct_answer, explanation, topic, difficulty, medicine_id, created_at) VALUES ('496cc099-6342-40fb-8abb-01687dd0ee44', 'Which adverse effect is characteristic of amlodipine?', 'mcq', ARRAY['Dry cough', 'Ankle oedema', 'Hyperkalaemia', 'Bradycardia']::text[], 'Ankle oedema', 'Dihydropyridine calcium channel blockers cause dose-related peripheral oedema.', 'Pharmacology', 'easy', NULL, '2026-08-18T16:52:03.660955+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quiz_questions (id, question, question_type, options, correct_answer, explanation, topic, difficulty, medicine_id, created_at) VALUES ('d6e3f232-e52e-4fdf-8fab-bd0de61703ed', 'Doxycycline should generally be avoided in:', 'mcq', ARRAY['Adults with pneumonia', 'Pregnancy', 'Acne', 'Rickettsial infection']::text[], 'Pregnancy', 'Tetracyclines affect developing teeth and bone.', 'Pharmacology', 'easy', NULL, '2026-08-18T16:52:03.660955+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quiz_questions (id, question, question_type, options, correct_answer, explanation, topic, difficulty, medicine_id, created_at) VALUES ('28cc6d59-099a-46e2-979a-974a97a847b7', 'Aspirin''s antiplatelet effect lasts about:', 'mcq', ARRAY['4 hours', '24 hours', '7-10 days', '30 days']::text[], '7-10 days', 'COX-1 inhibition in platelets is irreversible, so the effect lasts the platelet lifespan.', 'Pharmacodynamics', 'medium', NULL, '2026-08-18T16:52:03.660955+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quiz_questions (id, question, question_type, options, correct_answer, explanation, topic, difficulty, medicine_id, created_at) VALUES ('75859b92-94a7-4eaa-a505-31a51b611fe2', 'Which PPI is usually preferred alongside clopidogrel?', 'mcq', ARRAY['Omeprazole', 'Esomeprazole', 'Pantoprazole', 'Lansoprazole']::text[], 'Pantoprazole', 'Pantoprazole has less CYP2C19 inhibition, so it interferes less with clopidogrel activation.', 'Interactions', 'hard', NULL, '2026-08-18T16:52:03.660955+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quiz_questions (id, question, question_type, options, correct_answer, explanation, topic, difficulty, medicine_id, created_at) VALUES ('179d2300-0765-4b48-8378-0cc97b3c5ac1', 'Bioavailability refers to:', 'mcq', ARRAY['How fast a drug is excreted', 'The fraction of the dose reaching systemic circulation unchanged', 'The volume the drug distributes into', 'The strength of receptor binding']::text[], 'The fraction of the dose reaching systemic circulation unchanged', 'It is a key absorption parameter within ADME.', 'ADME', 'easy', NULL, '2026-08-18T16:52:03.660955+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quiz_questions (id, question, question_type, options, correct_answer, explanation, topic, difficulty, medicine_id, created_at) VALUES ('31960b97-b2e0-4f21-84e9-566f8c54d6f6', 'Metronidazole must not be taken with:', 'mcq', ARRAY['Milk', 'Alcohol', 'Vitamin C', 'Paracetamol']::text[], 'Alcohol', 'A disulfiram-like reaction can occur with flushing, nausea and vomiting.', 'Safety', 'easy', NULL, '2026-08-18T16:52:03.660955+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quiz_questions (id, question, question_type, options, correct_answer, explanation, topic, difficulty, medicine_id, created_at) VALUES ('b664b9d4-32f6-48e6-b0ad-8e648cc139dd', 'Pharmacodynamics is best described as:', 'mcq', ARRAY['What the body does to the drug', 'What the drug does to the body', 'How a drug is manufactured', 'How a drug is stored']::text[], 'What the drug does to the body', 'Pharmacokinetics is the reverse: what the body does to the drug.', 'Concepts', 'easy', NULL, '2026-08-18T16:52:03.660955+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quiz_questions (id, question, question_type, options, correct_answer, explanation, topic, difficulty, medicine_id, created_at) VALUES ('9d091507-17a8-4ce8-8cb4-e626a37af8bd', 'Salbutamol acts on which receptor?', 'mcq', ARRAY['Beta-1', 'Beta-2', 'Alpha-1', 'Muscarinic']::text[], 'Beta-2', 'Beta-2 agonism relaxes bronchial smooth muscle.', 'Mechanism', 'easy', NULL, '2026-08-18T16:52:03.660955+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quiz_questions (id, question, question_type, options, correct_answer, explanation, topic, difficulty, medicine_id, created_at) VALUES ('e87e1fa4-32ea-43d0-af25-d0e2ae111ce1', 'Levothyroxine is best taken:', 'mcq', ARRAY['With breakfast', 'On an empty stomach before breakfast', 'With calcium tablets', 'At bedtime with milk']::text[], 'On an empty stomach before breakfast', 'Food, calcium and iron reduce absorption.', 'Counselling', 'easy', NULL, '2026-08-18T16:52:03.660955+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quiz_questions (id, question, question_type, options, correct_answer, explanation, topic, difficulty, medicine_id, created_at) VALUES ('8ab5b911-356d-4287-b893-5fbc6282aa4d', 'Which class does azithromycin belong to?', 'mcq', ARRAY['Beta-lactam', 'Macrolide', 'Tetracycline', 'Fluoroquinolone']::text[], 'Macrolide', 'Azithromycin binds the 50S ribosomal subunit.', 'Drug Classes', 'easy', NULL, '2026-08-18T16:52:03.660955+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quiz_questions (id, question, question_type, options, correct_answer, explanation, topic, difficulty, medicine_id, created_at) VALUES ('def2918f-8f39-414a-ba01-d43d02289047', 'Furosemide acts on which part of the nephron?', 'mcq', ARRAY['Proximal tubule', 'Thick ascending limb of the loop of Henle', 'Distal convoluted tubule', 'Collecting duct']::text[], 'Thick ascending limb of the loop of Henle', 'It inhibits the Na-K-2Cl co-transporter there.', 'Pharmacology', 'medium', NULL, '2026-08-18T16:52:03.660955+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quiz_questions (id, question, question_type, options, correct_answer, explanation, topic, difficulty, medicine_id, created_at) VALUES ('0766fcab-8c31-4572-a763-fe7fab38af1c', 'Statins inhibit which enzyme?', 'mcq', ARRAY['HMG-CoA reductase', 'Cyclo-oxygenase', 'ACE', 'Xanthine oxidase']::text[], 'HMG-CoA reductase', 'This is the rate-limiting step of hepatic cholesterol synthesis.', 'Mechanism', 'easy', NULL, '2026-08-18T16:52:03.660955+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quiz_questions (id, question, question_type, options, correct_answer, explanation, topic, difficulty, medicine_id, created_at) VALUES ('2149d599-07b2-412d-90ec-ea3ed0d83d1b', 'Ondansetron blocks which receptor?', 'mcq', ARRAY['Dopamine D2', 'Histamine H1', 'Serotonin 5-HT3', 'Muscarinic M1']::text[], 'Serotonin 5-HT3', 'It acts on vagal afferents and the chemoreceptor trigger zone.', 'Mechanism', 'medium', NULL, '2026-08-18T16:52:03.660955+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quiz_questions (id, question, question_type, options, correct_answer, explanation, topic, difficulty, medicine_id, created_at) VALUES ('320c0a8e-ca3d-4926-b625-6ea2d1f0c967', 'ACE inhibitors commonly cause which distinctive adverse effect?', 'mcq', ARRAY['Ankle oedema', 'Dry cough', 'Hair loss', 'Tinnitus']::text[], 'Dry cough', 'Bradykinin accumulation is the usual explanation; ARBs avoid this.', 'Pharmacology', 'easy', NULL, '2026-08-18T16:52:03.660955+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.quiz_questions (id, question, question_type, options, correct_answer, explanation, topic, difficulty, medicine_id, created_at) VALUES ('48afdf99-fbee-4761-9b58-164fef0991d9', 'Which statement about drug-name suffixes is correct?', 'true_false', ARRAY['True', 'False']::text[], 'False', 'Suffixes are memory aids only; exceptions exist and the actual record must always be checked. (Statement: suffixes are absolute classification rules.)', 'Medical Terms', 'easy', NULL, '2026-08-18T16:52:03.660955+00:00') ON CONFLICT (id) DO NOTHING;
INSERT INTO public.drug_interactions (id, medicine_a_id, medicine_b_id, severity, description, mechanism, clinical_significance, professional_consideration, reference_id, verified) VALUES ('472cc434-35e4-4cbd-aa30-f075136e4af0', '956bb130-891a-48c7-98ca-260b286d84c4', 'cdfddd11-5b2b-42e1-ad39-ba09eeecf21b', 'moderate', 'Ibuprofen can reduce the cardioprotective antiplatelet effect of low-dose aspirin.', 'Competition for the COX-1 acetylation site on platelets.', 'May reduce cardiovascular protection when used regularly together.', 'Where both are needed, timing separation or an alternative analgesic is often considered.', NULL, TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.drug_interactions (id, medicine_a_id, medicine_b_id, severity, description, mechanism, clinical_significance, professional_consideration, reference_id, verified) VALUES ('ed1d20e7-11e9-4d8e-b53f-66c41af42455', 'bb0c1209-dd6b-4496-903c-3d3b11d21667', '74ef0987-9f92-49c9-8645-fbb4599876ed', 'major', 'Omeprazole reduces conversion of clopidogrel to its active metabolite.', 'CYP2C19 inhibition by omeprazole.', 'Reduced antiplatelet effect with possible increased thrombotic risk.', 'Pantoprazole is commonly preferred when a PPI is required with clopidogrel.', NULL, TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.drug_interactions (id, medicine_a_id, medicine_b_id, severity, description, mechanism, clinical_significance, professional_consideration, reference_id, verified) VALUES ('5473b778-77c8-40e1-a90e-2d467ad7e4eb', '9b9c4665-37b7-4d8f-829d-bfc0a0ed183a', 'ac5fbe3d-07b5-4768-bc11-60a4b530fd25', 'moderate', 'Diuretic-induced dehydration can precipitate metformin accumulation.', 'Reduced renal clearance of metformin during volume depletion.', 'Increased risk of lactic acidosis in dehydration or acute illness.', 'Renal function monitoring and sick-day guidance are standard practice.', NULL, TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.drug_interactions (id, medicine_a_id, medicine_b_id, severity, description, mechanism, clinical_significance, professional_consideration, reference_id, verified) VALUES ('39d57ba6-3519-4879-a28c-a5327eb50d95', 'f0eae62e-dd32-4c3c-9413-7b86dcb24f5d', 'cdfddd11-5b2b-42e1-ad39-ba09eeecf21b', 'moderate', 'NSAIDs can reduce the antihypertensive effect of ARBs and impair renal function.', 'Prostaglandin inhibition reduces renal perfusion and sodium excretion.', 'Blood pressure rise and risk of acute kidney injury, especially with a diuretic.', 'Renal function and blood pressure monitoring are advised.', NULL, TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.drug_interactions (id, medicine_a_id, medicine_b_id, severity, description, mechanism, clinical_significance, professional_consideration, reference_id, verified) VALUES ('8e9556f6-3f61-401e-aa06-46903bf5bf25', 'bf45cfb8-eeaf-4df1-bbea-a751e72c3bcd', '74ef0987-9f92-49c9-8645-fbb4599876ed', 'moderate', 'Reduced gastric acidity can decrease levothyroxine absorption.', 'Higher gastric pH reduces dissolution and absorption.', 'Possible rise in TSH and reduced control of hypothyroidism.', 'TSH monitoring after starting or stopping the PPI is advised.', NULL, TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.drug_interactions (id, medicine_a_id, medicine_b_id, severity, description, mechanism, clinical_significance, professional_consideration, reference_id, verified) VALUES ('7a8c345b-eada-40df-b660-6e4c45e4a7e5', '4a842194-44d2-4153-abe9-8540a8d5f61c', '18227fbe-9276-4d36-abac-ae6a2ca962d2', 'moderate', 'Macrolides may increase statin exposure and myopathy risk.', 'Inhibition of CYP3A4 and transporter-mediated clearance.', 'Increased risk of muscle symptoms and rarely rhabdomyolysis.', 'Muscle symptom review during concurrent therapy is advised.', NULL, TRUE) ON CONFLICT (id) DO NOTHING;
INSERT INTO public.drug_interactions (id, medicine_a_id, medicine_b_id, severity, description, mechanism, clinical_significance, professional_consideration, reference_id, verified) VALUES ('4786519e-8edc-4037-9ea2-3f0aa43034ae', '956bb130-891a-48c7-98ca-260b286d84c4', 'bb0c1209-dd6b-4496-903c-3d3b11d21667', 'moderate', 'Combined antiplatelet therapy increases bleeding risk.', 'Additive inhibition of platelet function by two different pathways.', 'Higher bleeding risk; the combination is nonetheless indicated in specific cardiac situations.', 'Duration of dual therapy is determined by the treating specialist.', NULL, TRUE) ON CONFLICT (id) DO NOTHING;
